package com.whylag;

import com.whylag.core.Icon;
import com.whylag.core.Level;
import java.awt.image.BufferedImage;
import java.util.function.Function;
import net.runelite.client.util.ImageUtil;

/**
 * The game badge's eight pictures (contract P2.7): 24 x 24, one per cause and state, {@code badge-<icon>-<state>.png}
 * with icon {@code world}, {@code line}, {@code pc}, {@code unknown} ({@link Icon#file()}) and state
 * {@code warn} or {@code bad}. They are our own pixel art, made by {@code docs/handoff/lab/tools/whylag_icons.py} from
 * set A of {@code game-icons.js} and committed under {@code src/main/resources/com/whylag/}; nothing is downloaded.
 * The status shape of the state is already in each file's bottom right corner, and every icon but the globe is
 * tinted by the state.
 *
 * <p>All eight are loaded ONCE, in the constructor ({@code WhyLagPlugin.startUp}), with
 * {@link ImageUtil#loadImageResource}; {@link #get} only looks one up, so the overlay's {@code render} never loads
 * a picture (T20). OK and NO_DATA have no picture: those states draw a status shape alone.
 *
 * <p>Choice: fileName answers null where there is no file: Icon.NONE, OK, NO_DATA, or a null argument.
 * <p>Choice: a file that fails to load stays null, so get answers null and the painter draws the status shape.
 * <p>Choice: a package-private constructor takes the loader, so a test can count the eight loads.
 */
public final class BadgeIcons
{
	/** The two states that have a picture, in the order of the {@code pictures} slots. */
	private static final Level[] STATES = {Level.WARN, Level.BAD};

	/** One slot per icon and state: {@code icon.ordinal() * 2 + (BAD ? 1 : 0)}; NONE's two stay null. */
	private final BufferedImage[] pictures = new BufferedImage[Icon.values().length * STATES.length];

	/** Loads the eight pictures from this class's package with {@link ImageUtil#loadImageResource}. */
	public BadgeIcons()
	{
		this(name -> ImageUtil.loadImageResource(BadgeIcons.class, name));
	}

	/** Loads the eight pictures with {@code loader}, each file once; a load that throws leaves its slot null. */
	BadgeIcons(Function<String, BufferedImage> loader)
	{
		for (Icon icon : Icon.values())
		{
			for (Level level : STATES)
			{
				final String name = fileName(icon, level);
				if (name == null)
				{
					continue;
				}
				try
				{
					pictures[slot(icon, level)] = loader.apply(name);
				}
				catch (RuntimeException e)
				{
					pictures[slot(icon, level)] = null;
				}
			}
		}
	}

	/**
	 * The 24 x 24 picture of a cause in a state, the same object on every call; null for {@link Icon#NONE}, for OK
	 * and NO_DATA (a shape alone), for a null, and for a file that did not load.
	 */
	public BufferedImage get(Icon icon, Level level)
	{
		return fileName(icon, level) == null ? null : pictures[slot(icon, level)];
	}

	/**
	 * The file of a cause in a state, "badge-world-bad.png"; null when there is none: {@link Icon#NONE}, the levels
	 * OK and NO_DATA, or a null argument.
	 */
	public static String fileName(Icon icon, Level level)
	{
		if (icon == null || icon == Icon.NONE || (level != Level.WARN && level != Level.BAD))
		{
			return null;
		}
		return "badge-" + icon.file() + "-" + (level == Level.WARN ? "warn" : "bad") + ".png";
	}

	private static int slot(Icon icon, Level level)
	{
		return icon.ordinal() * STATES.length + (level == Level.BAD ? 1 : 0);
	}
}

package com.whylag;

import com.whylag.core.BadgeView;
import com.whylag.core.Level;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

/**
 * The game badge of the two styles WITHOUT words ({@code ICON}, {@code SHAPE_ONLY}) as a real RuneLite infobox
 * (addendum D of the contract): it sits in the infobox row with everyone else's, so no other plugin's infobox is
 * drawn over it, and the player moves, flips and detaches it with RuneLite's own menu entries (RuneLite adds them).
 * The two styles with words stay {@link BadgeOverlay}. Like the overlay it measures nothing: it shows the
 * {@link BadgeView} that its supplier answers, and holds no {@code Client}, reads no config and calls no
 * {@code LagSource}.
 *
 * <p>RuneLite calls {@link #render} once in every frame, on the client thread, BEFORE it reads the picture, so the
 * lazy repaint lives there. {@code render} reads the supplier ONCE. When the view is not the object it painted last
 * (by identity) it asks the painter for {@link BadgePainter#bare} (no box: RuneLite draws its own background and
 * centres a picture smaller than the infobox), hands it to {@link #setImage} and to
 * {@link InfoBoxManager#updateInfoBoxImage} (which makes the scaled picture that RuneLite draws), and keeps the
 * tooltip: {@code tip1} in the colour of line 1, {@code </br>} and {@code tip2} ({@link BadgeOverlay#tooltipText}),
 * "" when {@code tip1} is "". While the view is the same object it builds no picture, no string and makes no manager
 * call (T18). It answers true only while it has a picture, so a hidden view, a null view and a view of a word style
 * take no room in the row.
 *
 * <p>There are no words in an infobox of ours: {@link #getText} answers "". {@link #getTextColor} answers line 1's
 * colour for the last view's level, which RuneLite uses for nothing while the text is "". It has no priority
 * ({@code InfoBoxPriority.NONE}) and no menu entries of ours.
 *
 * <p>Choice: it paints through a Function (the public constructor passes {@code painter::bare}), so a test counts
 * paints, as {@link BadgeOverlay} does.
 * <p>Choice: the tooltip is kept in the inherited {@code tooltip} field ({@link #setTooltip}), so RuneLite's own
 * {@code getTooltip} answers it.
 * <p>Choice: a paint that throws keeps nothing and is tried again; RuneLite catches it, logs it once and skips the
 * frame.
 * <p>Choice: a null style reads as ICON, which has no words, as the painter reads it.
 */
public final class BadgeInfoBox extends InfoBox
{
	private final Supplier<BadgeView> view;
	private final Function<BadgeView, BufferedImage> painter;
	private final InfoBoxManager manager;

	/** The view painted last; null before the first render. */
	private BadgeView painted;
	/** Its level, for the colour of {@link #getTextColor}; null before the first render. */
	private Level level;

	public BadgeInfoBox(Plugin plugin, Supplier<BadgeView> view, BadgePainter painter, InfoBoxManager manager)
	{
		this(plugin, view, painter::bare, manager);
	}

	BadgeInfoBox(Plugin plugin, Supplier<BadgeView> view, Function<BadgeView, BufferedImage> painter,
		InfoBoxManager manager)
	{
		super(null, plugin);
		this.view = view;
		this.painter = painter;
		this.manager = manager;
	}

	/**
	 * True when this view is the infobox's: visible, and of a style without words. A hidden view, and a view of a
	 * word style (the overlay's), are not. {@link BadgeOverlay} asks the same question, so exactly one of the two
	 * shows a visible view.
	 */
	static boolean handles(BadgeView v)
	{
		return v != null && v.visible && (v.style == null || !v.style.words());
	}

	@Override
	public boolean render()
	{
		final BadgeView v = view.get();
		if (v != painted)
		{
			final BufferedImage next = handles(v) ? painter.apply(v) : null;
			setImage(next);
			if (next != null)
			{
				manager.updateInfoBoxImage(this);
			}
			setTooltip(next == null || v.tip1.isEmpty() ? "" : BadgeOverlay.tooltipText(v));
			level = v == null ? null : v.level;
			painted = v;
		}
		return getImage() != null;
	}

	/** "": the styles of this infobox show no words. */
	@Override
	public String getText()
	{
		return "";
	}

	/** Line 1's colour for the last view's level ({@code NO_DATA}'s before the first view). */
	@Override
	public Color getTextColor()
	{
		return BadgePainter.lineOneColour(level);
	}
}

package com.whylag;

import com.whylag.core.BadgeView;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

/**
 * The game badge on the game screen (contract P2.5): one small overlay, top left by default, movable with Alt + drag
 * like every overlay (RuneLite remembers its place by this class's name). It measures nothing: it draws the
 * {@link BadgeView} that its supplier answers ({@code BadgeModel.view()}, one volatile read), and holds no
 * {@code Client}, reads no config and no ring, and calls no {@code LagSource}.
 *
 * <p>It draws only the two styles WITH words ({@code ICON_AND_WORDS}, {@code SHAPE_AND_WORDS}). A visible view of a
 * style without words ({@code ICON}, {@code SHAPE_ONLY}) is {@link BadgeInfoBox}'s (addendum D): here it is treated
 * as hidden, so the overlay and the infobox never both show.
 *
 * <p>{@link #render} reads the supplier ONCE. When the view is not the object it painted last (by identity), it
 * asks the painter for the new picture and makes its {@link Dimension} and its {@link Tooltip} once; then it draws
 * the kept picture at (0, 0) and answers the kept {@code Dimension}. While the view is the same object it builds no
 * string, no image, no {@code Dimension} and no {@code Tooltip} (T18). No picture (a hidden view): it answers null,
 * so RuneLite gives it no bounds, no hover and no drag.
 *
 * <p>{@link #onMouseOver}, which RuneLite calls in every frame the mouse is inside the badge, adds the kept tooltip:
 * {@code tip1} in the colour of line 1 for the view's level ({@link BadgePainter#lineOneColour}), then, when
 * {@code tip2} is not "", {@code </br>} and {@code tip2}. With {@code tip1} "" there is no tooltip. Both methods run
 * on the client thread, so the kept fields are plain.
 *
 * <p>Choice: it paints through a Function (the public constructor passes painter::paint), so a test counts paints.
 * <p>Choice: a null view is drawn as nothing, like HIDDEN; a paint that throws keeps nothing and is tried again.
 * <p>Choice: the painter is not asked for a view that {@link BadgeInfoBox#handles} owns; the rule lives in one place.
 */
public final class BadgeOverlay extends Overlay
{
	private final Supplier<BadgeView> view;
	private final Function<BadgeView, BufferedImage> painter;
	private final TooltipManager tooltips;

	/** The view painted last; null before the first render. */
	private BadgeView painted;
	/** Its picture, its size and its tooltip; null when it has none. */
	private BufferedImage image;
	private Dimension size;
	private Tooltip tooltip;

	public BadgeOverlay(Supplier<BadgeView> view, BadgePainter painter, TooltipManager tooltips)
	{
		this(view, painter::paint, tooltips);
	}

	BadgeOverlay(Supplier<BadgeView> view, Function<BadgeView, BufferedImage> painter, TooltipManager tooltips)
	{
		this.view = view;
		this.painter = painter;
		this.tooltips = tooltips;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final BadgeView v = view.get();
		if (v != painted)
		{
			final BufferedImage next = v == null || BadgeInfoBox.handles(v) ? null : painter.apply(v);
			image = next;
			size = next == null ? null : new Dimension(next.getWidth(), next.getHeight());
			tooltip = next == null || v.tip1.isEmpty() ? null : new Tooltip(tooltipText(v));
			painted = v;
		}
		if (image == null)
		{
			return null;
		}
		graphics.drawImage(image, 0, 0, null);
		return size;
	}

	@Override
	public void onMouseOver()
	{
		if (tooltip != null)
		{
			tooltips.add(tooltip);
		}
	}

	/** {@code tip1} in line 1's colour, then {@code </br>} and {@code tip2} when that is not "". */
	static String tooltipText(BadgeView v)
	{
		final String first = ColorUtil.wrapWithColorTag(v.tip1, BadgePainter.lineOneColour(v.level));
		return v.tip2.isEmpty() ? first : first + "</br>" + v.tip2;
	}
}

package com.whylag;

import com.whylag.core.BadgeStyle;
import com.whylag.core.BadgeView;
import com.whylag.core.Level;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;

/**
 * The picture of one game badge (contract P2.3, P2.4): ONE {@code TYPE_INT_ARGB} image that holds the whole badge,
 * box included, made once per view; the overlay keeps it and draws it every frame (T18). Pure Java2D: the one
 * RuneLite call is {@link FontManager#getRunescapeFont()}, the badge's face at its native 16 px.
 *
 * <p><b>The box</b>, in RuneLite's overlay colours and painted by our own code (RuneLite's
 * {@code BackgroundComponent} makes two colours on every call): the ground 70,61,50 alpha 156 over the whole
 * rectangle, a 1 px outer frame 56,48,40 alpha 218, and a 1 px inner frame 84,73,60 alpha 218 one pixel inside it.
 *
 * <p><b>The picture</b> is a 24 x 24 icon of {@link BadgeIcons} (the style shows icons, the view has one and its
 * level is WARN or BAD; the status shape is already in the file's corner), else the 14 x 14 status shape of the
 * level: a 12 x 12 shape with a 1 px black edge, pixel for pixel the rule of picture 22's page ({@code inside}).
 *
 * <p><b>The words</b> (styles that show words): RuneScape regular at 16 px, anti-aliasing off, each line drawn
 * twice, black one pixel down and right, then in its colour; line 1 in the level's colour (red TEXT is always
 * 255,90,90, never the shape's 230,30,30), line 2 white. A line is 17 px high with its baseline 13 px under its
 * top; a line that is "" is not drawn and takes no room.
 *
 * <p><b>Sizes</b> ({@code pw}, {@code ph} the picture's, {@code n} the lines drawn, {@code tw} the widest line):
 * ICON and SHAPE_ONLY are {@code pw + 8} by {@code ph + 8} with the picture at (4, 4); the two word styles are
 * {@code 5 + pw + 5 + tw + 7} by {@code 8 + max(ph, 17 n)}, the picture at x 5 centred in the height (but a 14 px
 * shape beside two lines at y 5, beside line 1), the block of lines at x {@code 5 + pw + 5} centred in the height.
 * The widest badge is 117 x 42 with an icon and 107 x 42 with a shape ("Disconnected", 76 px).
 *
 * <p><b>Dimmed</b>: the picture and the words at half strength ({@code AlphaComposite.SrcOver.derive(0.5f)}); the
 * box is not.
 *
 * <p><b>Bare</b> ({@link #bare}, addendum D): the picture of the two styles without words, WITHOUT the box, for the
 * RuneLite infobox ({@code BadgeInfoBox}), which draws its own background and centres a smaller picture in it.
 *
 * <p>Choice: the frames are drawn OVER the ground (SrcOver), as BackgroundComponent does: RuneLite's own box.
 * <p>Choice: the ground is WRITTEN (Src), exactly 70,61,50 alpha 156; SrcOver on a clear image rounds a step off.
 * <p>Choice: a half pixel of centring rounds down: the 14 px shape beside ONE line sits at y 5, as beside two.
 * <p>Choice: the four shapes are made once, in the constructor; text is measured in the hints it is drawn with.
 * <p>Choice: a picture that BadgeIcons does not have (a file that did not load) is drawn as the status shape.
 * <p>Choice: a null style, level or icon reads as ICON, NO_DATA, NONE; no line to draw keeps the formula at 0.
 */
public final class BadgePainter
{
	/** The box's ground (RuneLite's {@code ComponentConstants.STANDARD_BACKGROUND_COLOR}). */
	private static final Color GROUND = new Color(70, 61, 50, 156);
	/** The outer frame: the ground's colour times 0.8, its alpha times 1.4, as {@code BackgroundComponent}. */
	private static final Color FRAME_OUTER = new Color(56, 48, 40, 218);
	/** The inner frame, one pixel inside the outer: the ground's colour times 1.2, its alpha times 1.4. */
	private static final Color FRAME_INNER = new Color(84, 73, 60, 218);
	/** The edge of every status shape, and the shadow of every line. */
	private static final Color BLACK = new Color(0, 0, 0);
	/** Line 2, whose side it is. */
	private static final Color LINE_TWO = new Color(255, 255, 255);

	/** The status shape's colour, by {@link Level} ordinal: OK, WARN, BAD, NO_DATA. */
	private static final Color[] SHAPE = {
		new Color(55, 240, 70), new Color(230, 150, 30), new Color(230, 30, 30), new Color(150, 150, 150)};
	/** Line 1's colour, and the tooltip's first line, by {@link Level} ordinal. Red text is never stock red. */
	private static final Color[] LINE_ONE = {
		new Color(55, 240, 70), new Color(240, 160, 40), new Color(255, 90, 90), new Color(170, 170, 170)};

	/** The status shape: 12 x 12 and a 1 px edge all round. */
	private static final int SHAPE_PX = 14;
	/** The shape's own side, without its edge. */
	private static final int SHAPE_INSIDE = 12;
	/** Where the picture sits in ICON and SHAPE_ONLY; the box is the picture and twice this. */
	private static final int PICTURE_ONLY_PAD = 4;
	/** The word styles: the picture's x, the gap before the words, the room after them, top and bottom together. */
	private static final int WORDS_LEFT = 5, WORDS_GAP = 5, WORDS_RIGHT = 7, WORDS_HEIGHT_PAD = 8;
	/** The bare picture's status shape is the 14 px shape doubled: each pixel becomes this many by this many. */
	private static final int BARE_SHAPE_SCALE = 2;
	/** The y of a 14 px shape beside two lines: beside line 1. */
	private static final int SHAPE_BESIDE_TWO_Y = 5;
	/** A line's height, and its baseline under its top. */
	private static final int LINE_PX = 17, BASELINE = 13;

	private final BadgeIcons icons;
	private final Font font;
	private final FontMetrics metrics;
	/** The four status shapes, by {@link Level} ordinal. */
	private final BufferedImage[] shapes = new BufferedImage[Level.values().length];

	public BadgePainter(BadgeIcons icons)
	{
		this.icons = icons;
		this.font = FontManager.getRunescapeFont();
		final BufferedImage scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = scratch.createGraphics();
		try
		{
			pixelHints(g);
			this.metrics = g.getFontMetrics(font);
		}
		finally
		{
			g.dispose();
		}
		for (Level level : Level.values())
		{
			shapes[level.ordinal()] = shape(level);
		}
	}

	/** The whole badge, box included, as a new image; null when the view is not visible. */
	public BufferedImage paint(BadgeView v)
	{
		if (v == null || !v.visible)
		{
			return null;
		}
		final BadgeStyle style = v.style == null ? BadgeStyle.ICON : v.style;
		final Level level = v.level == null ? Level.NO_DATA : v.level;

		BufferedImage picture = null;
		if (style.icon() && (level == Level.WARN || level == Level.BAD))
		{
			picture = icons.get(v.icon, level);
		}
		final boolean shape = picture == null;
		if (shape)
		{
			picture = shapes[level.ordinal()];
		}
		final int pw = picture.getWidth();
		final int ph = picture.getHeight();

		final String[] lines = new String[2];
		final Color[] colours = new Color[2];
		int n = 0;
		int tw = 0;
		if (style.words())
		{
			if (!v.line1.isEmpty())
			{
				lines[n] = v.line1;
				colours[n++] = lineOneColour(level);
			}
			if (!v.line2.isEmpty())
			{
				lines[n] = v.line2;
				colours[n++] = LINE_TWO;
			}
			for (int i = 0; i < n; i++)
			{
				tw = Math.max(tw, metrics.stringWidth(lines[i]));
			}
		}

		final int width;
		final int height;
		final int px;
		final int py;
		if (style.words())
		{
			width = WORDS_LEFT + pw + WORDS_GAP + tw + WORDS_RIGHT;
			height = WORDS_HEIGHT_PAD + Math.max(ph, LINE_PX * n);
			px = WORDS_LEFT;
			py = shape && n == 2 ? SHAPE_BESIDE_TWO_Y : (height - ph) / 2;
		}
		else
		{
			width = pw + 2 * PICTURE_ONLY_PAD;
			height = ph + 2 * PICTURE_ONLY_PAD;
			px = PICTURE_ONLY_PAD;
			py = PICTURE_ONLY_PAD;
		}

		final BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		try
		{
			pixelHints(g);
			g.setComposite(AlphaComposite.Src);
			g.setColor(GROUND);
			g.fillRect(0, 0, width, height);
			g.setComposite(AlphaComposite.SrcOver);
			g.setColor(FRAME_OUTER);
			g.drawRect(0, 0, width - 1, height - 1);
			g.setColor(FRAME_INNER);
			g.drawRect(1, 1, width - 3, height - 3);

			if (v.dimmed)
			{
				g.setComposite(AlphaComposite.SrcOver.derive(0.5f));
			}
			g.drawImage(picture, px, py, null);

			if (n > 0)
			{
				g.setFont(font);
				final int x = px + pw + WORDS_GAP;
				final int top = (height - LINE_PX * n) / 2;
				for (int i = 0; i < n; i++)
				{
					final int baseline = top + LINE_PX * i + BASELINE;
					g.setColor(BLACK);
					g.drawString(lines[i], x + 1, baseline + 1);
					g.setColor(colours[i]);
					g.drawString(lines[i], x, baseline);
				}
			}
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	/**
	 * The badge's picture WITHOUT the box, for the infobox (addendum D): the 24 x 24 icon file as it is when the style
	 * shows icons, the view has one and its level is WARN or BAD; else the status shape doubled to 28 x 28 by
	 * nearest neighbour (each pixel of the 14 px shape becomes 2 x 2), so it holds its own in a 35 px infobox.
	 * Dimmed: every pixel at half strength, as {@link #paint} does the picture. A new image on every call; null when
	 * the view is null or not visible. The words of a word style are not part of it.
	 *
	 * <p>Choice: the pictures are copied pixel by pixel ({@code getRGB} / {@code setRGB}), so no blend can move one.
	 * <p>Choice: a null style, level or icon reads as ICON, NO_DATA, NONE, as {@link #paint} reads them.
	 */
	public BufferedImage bare(BadgeView v)
	{
		if (v == null || !v.visible)
		{
			return null;
		}
		final BadgeStyle style = v.style == null ? BadgeStyle.ICON : v.style;
		final Level level = v.level == null ? Level.NO_DATA : v.level;

		BufferedImage picture = null;
		if (style.icon() && (level == Level.WARN || level == Level.BAD))
		{
			picture = icons.get(v.icon, level);
		}
		final int scale = picture == null ? BARE_SHAPE_SCALE : 1;
		if (picture == null)
		{
			picture = shapes[level.ordinal()];
		}
		final int w = picture.getWidth() * scale;
		final int h = picture.getHeight() * scale;
		final BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				out.setRGB(x, y, picture.getRGB(x / scale, y / scale));
			}
		}
		if (!v.dimmed)
		{
			return out;
		}
		final BufferedImage half = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = half.createGraphics();
		try
		{
			g.setComposite(AlphaComposite.SrcOver.derive(0.5f));
			g.drawImage(out, 0, 0, null);
		}
		finally
		{
			g.dispose();
		}
		return half;
	}

	/**
	 * Line 1's colour for a level, which the tooltip's first line takes too: OK 55,240,70; WARN 240,160,40; BAD
	 * 255,90,90; NO_DATA 170,170,170 (a null is NO_DATA's).
	 */
	static Color lineOneColour(Level level)
	{
		return LINE_ONE[(level == null ? Level.NO_DATA : level).ordinal()];
	}

	/** The status shape's colour for a level: OK 55,240,70; WARN 230,150,30; BAD 230,30,30; NO_DATA 150,150,150. */
	static Color shapeColour(Level level)
	{
		return SHAPE[(level == null ? Level.NO_DATA : level).ordinal()];
	}

	/**
	 * The rule of picture 22's page: for x, y in 0 .. 11, with r2 = (x + 0.5 - 6)^2 + (y + 0.5 - 6)^2, a pixel is
	 * inside when OK: r2 &lt;= 36; NO_DATA: r2 &lt;= 36 and r2 &gt; 9 (a ring); WARN: |x + 0.5 - 6| &lt;= (y + 1) / 2
	 * (a triangle, point up); BAD: always (a square). Outside 0 .. 11 nothing is inside.
	 */
	private static boolean inside(Level level, int x, int y)
	{
		if (x < 0 || y < 0 || x >= SHAPE_INSIDE || y >= SHAPE_INSIDE)
		{
			return false;
		}
		final double dx = x + 0.5 - 6;
		final double dy = y + 0.5 - 6;
		final double r2 = dx * dx + dy * dy;
		switch (level)
		{
			case OK:
				return r2 <= 36;
			case NO_DATA:
				return r2 <= 36 && r2 > 9;
			case WARN:
				return Math.abs(dx) <= (y + 1) / 2.0;
			default:
				return true;
		}
	}

	/**
	 * One status shape, 14 x 14: an inside pixel at (x + 1, y + 1) in the level's colour; a pixel that is not inside
	 * but has an inside pixel left, right, above or under it, black; every other pixel clear.
	 */
	private static BufferedImage shape(Level level)
	{
		final BufferedImage img = new BufferedImage(SHAPE_PX, SHAPE_PX, BufferedImage.TYPE_INT_ARGB);
		final int colour = shapeColour(level).getRGB();
		final int black = BLACK.getRGB();
		for (int y = -1; y <= SHAPE_INSIDE; y++)
		{
			for (int x = -1; x <= SHAPE_INSIDE; x++)
			{
				if (inside(level, x, y))
				{
					img.setRGB(x + 1, y + 1, colour);
				}
				else if (inside(level, x - 1, y) || inside(level, x + 1, y) || inside(level, x, y - 1)
					|| inside(level, x, y + 1))
				{
					img.setRGB(x + 1, y + 1, black);
				}
			}
		}
		return img;
	}

	/** Pixel fonts and pixel shapes: no anti-aliasing of either, no fractional metrics. */
	private static void pixelHints(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
	}
}

package com.whylag;

import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * The badge's one game message per lag (contract P2.6): "[Why Lag] World lag - not you (14 s). Ticks 1,240 ms, ping
 * 41 ms." {@code BadgeModel} makes the words; this class only QUEUES them, as a {@link ChatMessageType#CONSOLE}
 * message whose RuneLite-formatted text is the line as given, with no tag and no colour of its own. Nothing is typed
 * into the chat input and nothing is sent to the server (T21). {@link ChatMessageManager#queue} adds to a concurrent
 * queue that the client thread empties, so {@link #send} may be called on any thread (the sampler thread calls it).
 *
 * <p>Choice: a null or empty text is not queued: RuneLite would fail on it later, on the client thread.
 * <p>Choice: a line that cannot be queued is dropped without a log: the badge's classes import no logger.
 */
public final class ChatLine
{
	private final ChatMessageManager chat;

	public ChatLine(ChatMessageManager chat)
	{
		this.chat = chat;
	}

	/** Queues the line as one CONSOLE game message; any thread; never throws. */
	public void send(String text)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		try
		{
			chat.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(text)
				.build());
		}
		catch (RuntimeException e)
		{
			// never throws: this lag's line is lost, the next one is tried as usual
		}
	}
}

package com.whylag;

import com.whylag.core.NoData;

/**
 * One reading of the game's socket (contract 3.11): {@link ConnectionProbe#read} fills it on the sampler thread and
 * the plugin hands its four fields to the engine. Mutable and reused: one instance for the plugin's life.
 *
 * <p>With {@code conn} {@link NoData#NONE} the three numbers are the socket's own: the round trip time in
 * MICROseconds, and the cumulative sent and re-sent counters (bytes on Windows, segments elsewhere, contract 3.2).
 * Any other {@code conn} says why there is no data (contract 3.10: "conn says why there is no data"), and then the
 * three numbers are -1.
 *
 * <p>Choice: a new sample holds no data yet: the three numbers -1 and {@code conn} STALE, never null.
 */
public final class ConnSample
{
	/** Round trip time in microseconds, as {@code TCPInfo.getRTT()} answers it; -1 = no data. */
	public long rttMicros = -1;
	/** Cumulative sent (bytes on Windows, segments elsewhere); -1 = no data. */
	public long sent = -1;
	/** Cumulative re-sent, in the same unit; -1 = no data. */
	public long resent = -1;
	/** {@link NoData#NONE} when the numbers are the socket's; else why there are none. Never null. */
	public NoData conn = NoData.STALE;
}

package com.whylag;

import com.whylag.core.NoData;
import java.io.FileDescriptor;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.client.plugins.worldhopper.ping.TCPInfo;

/**
 * Reads the game socket's round trip time and its sent and re-sent counters, once a second on the sampler thread
 * (contract 3.11, 7 L7). Read-only: it sends no packet and never calls {@code Ping.ping}. The plugin builds it as
 * {@code new ConnectionProbe(client::getSocketFD, Ping::getTCPInfo)}; tests hand in fakes.
 *
 * <p>The outcomes, in the order they are tested (the Ping cell's words are contract 5.2's):
 * <ul>
 * <li>not logged in: {@link NoData#NOT_LOGGED_IN}, and the socket is not asked;</li>
 * <li>no socket (a null descriptor): {@link NoData#NOT_CONNECTED};</li>
 * <li>no {@code TCPInfo} (Ping answers null on this system), or a {@code LinkageError} anywhere:
 * {@link NoData#UNSUPPORTED}, "Not on this PC";</li>
 * <li>any other exception, a {@code RuntimeException} above all (without {@code --add-opens} Ping cannot read the
 * socket's descriptor and throws one on JDK 17): {@link NoData#ERROR}, "Could not read it";</li>
 * <li>else {@link NoData#NONE} with the socket's three numbers.</li>
 * </ul>
 * It never throws (T13).
 *
 * <p>Choice: a read without data sets the three numbers to -1, so no number of an earlier read is handed on.
 * <p>Choice: the three getters are all read before the sample is written, so a throw leaves no half-written reading.
 * <p>Choice: the numbers are passed on as the socket gives them; making them per-second values is the engine's work.
 * <p>Choice: a null sample is ignored (nothing to fill), which keeps the promise never to throw.
 */
public final class ConnectionProbe
{
	/** A number with no data. */
	private static final long NO_DATA = -1;

	private final Supplier<FileDescriptor> socket;
	private final Function<FileDescriptor, TCPInfo> info;

	/**
	 * @param socket the game's socket, {@code client::getSocketFD}; null while there is none
	 * @param info   the TCP numbers of a socket, {@code Ping::getTCPInfo}; null where the system has none
	 */
	public ConnectionProbe(Supplier<FileDescriptor> socket, Function<FileDescriptor, TCPInfo> info)
	{
		this.socket = socket;
		this.info = info;
	}

	/**
	 * One reading into {@code out}. {@code loggedIn} is the plugin's volatile in-game flag, written on the client
	 * thread (contract 7, L9): this runs on the sampler thread and never reads the game state itself. Never throws.
	 */
	public void read(boolean loggedIn, ConnSample out)
	{
		if (out == null)
		{
			return;
		}
		if (!loggedIn)
		{
			noData(out, NoData.NOT_LOGGED_IN);
			return;
		}
		try
		{
			final FileDescriptor fd = socket.get();
			if (fd == null)
			{
				noData(out, NoData.NOT_CONNECTED);
				return;
			}
			final TCPInfo tcp = info.apply(fd);
			if (tcp == null)
			{
				noData(out, NoData.UNSUPPORTED);
				return;
			}
			final long rtt = tcp.getRTT();
			final long sent = tcp.getTransmitted();
			final long resent = tcp.getRetransmitted();
			out.rttMicros = rtt;
			out.sent = sent;
			out.resent = resent;
			out.conn = NoData.NONE;
		}
		catch (LinkageError e)
		{
			noData(out, NoData.UNSUPPORTED);
		}
		catch (Exception e)
		{
			noData(out, NoData.ERROR);
		}
	}

	private static void noData(ConnSample out, NoData why)
	{
		out.rttMicros = NO_DATA;
		out.sent = NO_DATA;
		out.resent = NO_DATA;
		out.conn = why;
	}
}

