package com.whylag.core;

/**
 * The big two-line answer of every cause and every card state (contract 3.6): the ONE source of those words. The
 * panel's answer card, the game badge, the badge's tooltip and the chat line all print it, so they can never
 * disagree. Immutable; every instance is a constant of this class, and {@link #of(Verdict)} and {@link #of(Cause)}
 * answer one of them and allocate nothing, so a caller may compare answers by identity.
 *
 * <p>{@code line1} is the cause, or the state, and is never ""; {@code line2} says whose side it is, "" when the
 * answer has one line; {@code icon} is the badge's picture ({@link Icon#NONE}: the status shape alone);
 * {@code oneLine} is {@code line1 + " - " + line2} with the FIRST letter of {@code line2} in lower case ("World lag -
 * not you", "Low FPS - your PC", "Client froze - your PC"), or {@code line1} alone when {@code line2} is "". The
 * LEVEL is not part of the answer: it is the verdict's, so W1 (an event, BAD) and W1c (a condition, WARN) share one
 * pair and differ by their shape.
 *
 * <table>
 * <caption>The answers of the wave-one causes and the three card states</caption>
 * <tr><th>Cause (rule)</th><th>Line 1</th><th>Line 2</th><th>Icon</th></tr>
 * <tr><td>ALL_CLEAR (V2)</td><td>Smooth</td><td>-</td><td>NONE</td></tr>
 * <tr><td>SLOW_WORLD (W1, W1c)</td><td>World lag</td><td>Not you</td><td>WORLD</td></tr>
 * <tr><td>PING_JUMPY (N2)</td><td>Ping lag</td><td>Your internet</td><td>LINE</td></tr>
 * <tr><td>PING_HIGH (N1)</td><td>High ping</td><td>Your internet</td><td>LINE</td></tr>
 * <tr><td>UPLOAD_LOSS (N3)</td><td>Packet loss</td><td>Line or world</td><td>LINE</td></tr>
 * <tr><td>DISCONNECT (D1)</td><td>Disconnected</td><td>Line or world</td><td>LINE</td></tr>
 * <tr><td>DELIVERY_GAP (N6)</td><td>No ticks</td><td>Line or world</td><td>UNKNOWN</td></tr>
 * <tr><td>SLOW_DRAWING (F2)</td><td>Low FPS</td><td>Your PC</td><td>PC</td></tr>
 * <tr><td>FRAME_CAP (F1)</td><td>FPS capped</td><td>Your setting</td><td>PC</td></tr>
 * <tr><td>CLIENT_BUSY (S3)</td><td>Client froze</td><td>Your PC</td><td>PC</td></tr>
 * <tr><td>MAP_LOAD (S1)</td><td>Map loading</td><td>Just the map</td><td>PC</td></tr>
 * <tr><td>NOT_SURE (X)</td><td>Lag</td><td>Can't tell why</td><td>UNKNOWN</td></tr>
 * <tr><td>WARMING_UP, headline {@link #HEAD_MEASURING}</td><td>Measuring</td><td>-</td><td>NONE</td></tr>
 * <tr><td>WARMING_UP, headline {@link #HEAD_NOT_LOGGED_IN}</td><td>Not logged in</td><td>-</td><td>NONE</td></tr>
 * <tr><td>WARMING_UP, headline {@link #HEAD_WAITING}</td><td>Waiting</td><td>-</td><td>NONE</td></tr>
 * </table>
 *
 * <p>A cause that is NOT in wave one answers its GROUP's pair, so {@code of} never fails: CONNECTION "Ping lag" /
 * "Your internet"; FRAME_RATE "Low FPS" / "Your PC"; WORLD "World lag" / "Not you"; UNSURE "Lag" / "Can't tell
 * why"; NONE "Smooth" - the same constants as the wave-one causes of those pairs.
 *
 * <p><b>Every line fits</b> (measured on 2026-09-29 with {@code FontMetrics} on the fonts of {@code client} 1.12.37,
 * text anti-aliasing off): in RuneScape Bold at 32 px the widest is "Can't tell why", 178 px, the card's whole big
 * line; at 16 px in RuneScape regular, the badge's face, "Disconnected", 76 px. No line is longer than 14
 * characters, and every one is plain ASCII ({@code AnswerTest}). Three lines of the user's pictures are changed on
 * purpose (contract 10.3): a disconnect, lost packets and a delivery gap say "Line or world", because the client
 * cannot tell which end failed.
 *
 * <p>Choice (1.0.0, the Hub's rule): a stall of the client is ONE answer, "Client froze" / "Your PC". The plugin
 * no longer reads the game thread's busy share, so it cannot tell a client that was working from one that was
 * kept waiting, and "A plugin?" and "An overlay?" were guesses from that share.
 */
public final class Answer
{
	/** The headline of the card state "Not logged in" (contract 5.1). The verdict engine writes it FROM HERE. */
	public static final String HEAD_NOT_LOGGED_IN = "Not logged in";
	/** The headline of the card's warm-up state (contract 5.1); also {@code NoData.WARMING_UP}'s word. */
	public static final String HEAD_MEASURING = "Still measuring";
	/** The headline of the card state "Waiting for the game": frames stopped while logged in (contract 5.1). */
	public static final String HEAD_WAITING = "Waiting for the game";

	/** All is well: V2, and the pair of the group NONE. */
	public static final Answer SMOOTH = new Answer("Smooth", "", Icon.NONE);
	/** Warming up, a null verdict, and a WARMING_UP verdict whose headline is neither of the other two states'. */
	public static final Answer MEASURING = new Answer("Measuring", "", Icon.NONE);
	/** Not logged in. */
	public static final Answer NOT_LOGGED_IN = new Answer("Not logged in", "", Icon.NONE);
	/** Frames stopped while logged in: waiting for the game. */
	public static final Answer WAITING = new Answer("Waiting", "", Icon.NONE);

	private static final Answer WORLD_LAG = new Answer("World lag", "Not you", Icon.WORLD);
	private static final Answer PING_LAG = new Answer("Ping lag", "Your internet", Icon.LINE);
	private static final Answer HIGH_PING = new Answer("High ping", "Your internet", Icon.LINE);
	private static final Answer PACKET_LOSS = new Answer("Packet loss", "Line or world", Icon.LINE);
	private static final Answer DISCONNECTED = new Answer("Disconnected", "Line or world", Icon.LINE);
	private static final Answer NO_TICKS = new Answer("No ticks", "Line or world", Icon.UNKNOWN);
	private static final Answer LOW_FPS = new Answer("Low FPS", "Your PC", Icon.PC);
	private static final Answer FPS_CAPPED = new Answer("FPS capped", "Your setting", Icon.PC);
	private static final Answer CLIENT_FROZE = new Answer("Client froze", "Your PC", Icon.PC);
	private static final Answer MAP_LOADING = new Answer("Map loading", "Just the map", Icon.PC);
	private static final Answer LAG = new Answer("Lag", "Can't tell why", Icon.UNKNOWN);

	/** The answer of every cause, by ordinal; built once, after the constants above. */
	private static final Answer[] BY_CAUSE = byCause();

	/** The cause, or the state; never "". */
	public final String line1;
	/** Whose side it is; "" = the answer has one line. */
	public final String line2;
	/** The badge's picture; {@link Icon#NONE} = the status shape alone. */
	public final Icon icon;
	/** "World lag - not you": line 2's first letter in lower case; {@code line1} alone when {@code line2} is "". */
	public final String oneLine;

	private Answer(String line1, String line2, Icon icon)
	{
		this.line1 = line1;
		this.line2 = line2;
		this.icon = icon;
		this.oneLine = line2.isEmpty()
			? line1
			: line1 + " - " + Character.toLowerCase(line2.charAt(0)) + line2.substring(1);
	}

	/**
	 * The answer of a verdict; never null, allocates nothing. A null verdict answers {@link #MEASURING}. A verdict
	 * whose cause is {@link Cause#WARMING_UP} is told apart by its headline: {@link #HEAD_NOT_LOGGED_IN} answers
	 * {@link #NOT_LOGGED_IN}, {@link #HEAD_WAITING} answers {@link #WAITING}, anything else {@link #MEASURING}. Every
	 * other verdict answers {@link #of(Cause)} of its cause.
	 */
	public static Answer of(Verdict v)
	{
		if (v == null)
		{
			return MEASURING;
		}
		if (v.cause == Cause.WARMING_UP)
		{
			if (HEAD_NOT_LOGGED_IN.equals(v.headline))
			{
				return NOT_LOGGED_IN;
			}
			if (HEAD_WAITING.equals(v.headline))
			{
				return WAITING;
			}
			return MEASURING;
		}
		return of(v.cause);
	}

	/**
	 * The answer of a cause, by the table in the class notes; never null, allocates nothing. A cause outside wave one
	 * answers its group's pair. {@link Cause#WARMING_UP}, which has no headline here, answers {@link #MEASURING}, as
	 * a WARMING_UP verdict with neither state's headline does; a null cause answers {@link #MEASURING} too.
	 */
	public static Answer of(Cause c)
	{
		return c == null ? MEASURING : BY_CAUSE[c.ordinal()];
	}

	private static Answer[] byCause()
	{
		final Cause[] causes = Cause.values();
		final Answer[] out = new Answer[causes.length];
		for (Cause c : causes)
		{
			out[c.ordinal()] = c.inWaveOne() ? ofWaveOne(c) : ofGroup(c.group());
		}
		return out;
	}

	private static Answer ofWaveOne(Cause c)
	{
		switch (c)
		{
			case ALL_CLEAR:
				return SMOOTH;
			case SLOW_WORLD:
				return WORLD_LAG;
			case PING_JUMPY:
				return PING_LAG;
			case PING_HIGH:
				return HIGH_PING;
			case UPLOAD_LOSS:
				return PACKET_LOSS;
			case DISCONNECT:
				return DISCONNECTED;
			case DELIVERY_GAP:
				return NO_TICKS;
			case SLOW_DRAWING:
				return LOW_FPS;
			case FRAME_CAP:
				return FPS_CAPPED;
			case CLIENT_BUSY:
				return CLIENT_FROZE;
			case MAP_LOAD:
				return MAP_LOADING;
			case NOT_SURE:
				return LAG;
			case WARMING_UP:
				return MEASURING;
			default:
				return ofGroup(c.group());
		}
	}

	/** The pair of a group, for a cause outside wave one. */
	private static Answer ofGroup(Group g)
	{
		switch (g)
		{
			case CONNECTION:
				return PING_LAG;
			case FRAME_RATE:
				return LOW_FPS;
			case WORLD:
				return WORLD_LAG;
			case UNSURE:
				return LAG;
			default:
				return SMOOTH;
		}
	}
}

package com.whylag.core;

/**
 * The game badge's state machine and its chat line (contract P2.2, P2.6; lot L10). Pure: it reads no clock, no ring
 * and no config. {@code WhyLagPlugin} calls {@link #update} once a step on the sampler thread, after
 * {@code LagEngine.step}, with the card's verdict, the open event with its provisional verdict (contract 3.6), the
 * session's newest closed event, the newest complete second ({@code Session.lastSec}) and the four settings of "Game
 * screen", and then takes the chat line ({@link #takeChatLine}). The overlay reads {@link #view()} inside
 * {@code render}: one volatile read, no allocation, any thread.
 *
 * <p>It keeps four things between calls: the view it answered last, the id of the last closed event it saw, the
 * {@code lastSec} of the last chat line it made, and the line waiting to be taken. {@code update} and
 * {@code takeChatLine} run on the sampler thread only; the view alone is shared, through one volatile field.
 *
 * <p><b>The view.</b> {@code update} first handles the chat line, then picks the view: the FIRST rule that holds
 * wins. {@code e} is the open event when there is one, else the last closed one, and {@code q = max(0, lastSec -
 * e.endSec)} counts the quiet seconds since its last trigger second.
 * <table>
 * <caption>The six rules (contract P2.2)</caption>
 * <tr><th>#</th><th>When</th><th>The view</th></tr>
 * <tr><td>1</td><td>{@code show} is false</td><td>{@link BadgeView#HIDDEN}</td></tr>
 * <tr><td>2</td><td>no card, or its answer is {@link Answer#NOT_LOGGED_IN}</td><td>HIDDEN</td></tr>
 * <tr><td>3</td><td>{@code e} exists and {@code q <= BADGE_HOLD_S}</td><td>a lag: the answer of its verdict at the
 * verdict's level ("Lag", BAD, while it has none); dimmed unless it is going on, {@code e.open && q <= 1}</td></tr>
 * <tr><td>4</td><td>the card's level is NO_DATA ("Measuring", "Waiting")</td><td>"When smooth: Hide": HIDDEN;
 * else the hollow ring: NO_DATA, no icon, the card's answer</td></tr>
 * <tr><td>5</td><td>the card is all clear (V2), or still holds a past lag ({@code eventId >= 0})</td><td>"When
 * smooth: Hide": HIDDEN; else smooth: the green circle, {@link Answer#SMOOTH}</td></tr>
 * <tr><td>6</td><td>anything else: a condition (F1, N1, F2, W1c)</td><td>slow: the card's answer at the card's
 * level, not dimmed, drawn whatever "When smooth" says</td></tr>
 * </table>
 * A hidden view is always {@link BadgeView#HIDDEN} itself, whatever the style; every visible view carries the style
 * as given and both lines of its answer (the painter leaves out what the style does not show). {@code update}
 * answers the view it answered last, the same OBJECT, while the new one is {@link BadgeView#sameAs} it (contract 4,
 * T19), so the overlay paints a view once.
 *
 * <p><b>The tooltip's two lines</b>: a lag, the answer's one line and the event's numbers; slow, the answer's one
 * line and the card's proof; smooth on V2, "Smooth. " and the card's proof, and no second line; smooth on a past
 * lag, "Smooth." and "Last lag: " with the one line of the card's answer; the ring, the card's headline and proof;
 * HIDDEN, neither.
 *
 * <p><b>An event's numbers</b>, by the answer's icon, each through {@link Fmt#thousands}: WORLD "Ticks 1,240 ms,
 * ping 41 ms" ({@code worstTickGapMs}, {@code rttMs}); LINE "Ping 310 ms, ticks 1,240 ms" ({@code rttMaxMs},
 * {@code worstTickGapMs}); PC "Worst frame 480 ms, 50 fps" ({@code worstFrameMs}, {@code fps}); UNKNOWN "Ticks
 * 1,240 ms, worst frame 170 ms" ({@code worstTickGapMs}, {@code worstFrameMs}). The tick is the WORST gap, never the
 * mean. A part with no number is left out and what remains starts with a capital ("Ping 41 ms"); with both parts
 * out the numbers are "".
 *
 * <p><b>The chat line</b> (contract P2.6). The last closed event is NEW when its id is not the one seen last (none
 * at first); a new one is marked as seen at once, whatever follows. It gets a line only when {@code chat} is on and
 * no line was made in the last {@link Thresholds#CHAT_GAP_S} seconds; otherwise it never gets one, so a bad minute
 * cannot flood the chat. The line is "[Why Lag] ", the one line of its answer, " (14 s).", then a space, its numbers
 * and "." when it has numbers: "[Why Lag] World lag - not you (14 s). Ticks 1,240 ms, ping 41 ms." An open event
 * never makes a line, and the view's rules never hold one back.
 *
 * <p>Choice: the 1 of rule 3's {@code q <= 1} is {@code GOING_ON_S} here, not a Thresholds entry: it only dims.
 * <p>Choice: an event's number below 0 is left out as -1 is (every LagEvent number is -1 for none); 0 prints.
 * <p>Choice: an answer whose icon is NONE has no numbers, "": P2.2's table of numbers has no row for it.
 * <p>Choice: an event with no verdict is "Lag - can't tell why" in the chat line as in rule 3, never "Measuring".
 * <p>Choice: every update replaces the waiting line with its own, null when it made none (P2.6: the last update's).
 * <p>Choice: the ring (rule 4) carries both lines of the card's answer, as every visible view; line 2 is "" there.
 * <p>Choice: the numbers are printed whole, never clamped: the tooltip and the chat line have no fixed width.
 */
public final class BadgeModel
{
	/** "No closed event seen yet": an event's id is 0 or more and never reused (contract 3.4, "The id"). */
	private static final long NONE_SEEN = -1;
	/** "No chat line made yet". */
	private static final long NO_LINE = Long.MIN_VALUE;
	/**
	 * A lag is going on while its last trigger second is at most this many seconds behind the newest second, so the
	 * badge dims from the second quiet second (contract P2.2, rule 3: {@code e.open && q <= 1}).
	 */
	private static final int GOING_ON_S = 1;
	private static final String CHAT_START = "[Why Lag] ";
	private static final String LAST_LAG = "Last lag: ";

	/** The view answered last; {@link BadgeView#HIDDEN} before the first update. Written on the sampler thread. */
	private volatile BadgeView view = BadgeView.HIDDEN;
	/** The id of the last closed event seen; {@link #NONE_SEEN} = none. Sampler thread only. */
	private long seenId = NONE_SEEN;
	/** The {@code lastSec} of the last chat line made; {@link #NO_LINE} = none. Sampler thread only. */
	private long lineSec = NO_LINE;
	/** The line the last update made, waiting to be taken; null = none. Sampler thread only. */
	private String line;

	public BadgeModel()
	{
	}

	/**
	 * One step, on the sampler thread, after {@code LagEngine.step}: handles the chat line first (contract P2.6),
	 * then picks the view by the six rules of the class notes and publishes it for {@link #view()}.
	 *
	 * @param card the card's verdict, {@code LagSource.verdict()}; null answers HIDDEN
	 * @param open the open event with its provisional verdict, {@code LagSource.openEvent()}; null = none open
	 * @param lastClosed the session's newest closed event, {@code session().events.last()}; null = none
	 * @param lastSec the newest complete second, {@code session().lastSec(nowSec)}
	 * @param show the setting "Show on game screen"
	 * @param style the setting "Style"; every visible view carries it as given
	 * @param whenSmooth the setting "When smooth": HIDE hides smooth and measuring, never a lag or a condition
	 * @param chat the setting "Chat line on a lag"
	 * @return the view now: the SAME object as last time while nothing it shows changed
	 */
	public BadgeView update(Verdict card, LagEvent open, LagEvent lastClosed, long lastSec, boolean show,
		BadgeStyle style, WhenSmooth whenSmooth, boolean chat)
	{
		line = chatLine(lastClosed, lastSec, chat);
		final BadgeView next = pick(card, open, lastClosed, lastSec, show, style, whenSmooth);
		final BadgeView shown = view;
		if (next.sameAs(shown))
		{
			return shown;
		}
		view = next;
		return next;
	}

	/** What the badge shows now: one volatile read, no allocation, any thread. HIDDEN before the first update. */
	public BadgeView view()
	{
		return view;
	}

	/** The line the last {@link #update} made, handed out ONCE; null = none. Sampler thread only. */
	public String takeChatLine()
	{
		final String taken = line;
		line = null;
		return taken;
	}

	/** P2.6: the line for {@code closed} when it is new, the setting is on and the chat gap is over; else null. */
	private String chatLine(LagEvent closed, long lastSec, boolean chat)
	{
		if (closed == null || closed.id == seenId)
		{
			return null;
		}
		seenId = closed.id;
		if (!chat || (lineSec != NO_LINE && lastSec - lineSec < Thresholds.CHAT_GAP_S))
		{
			return null;
		}
		lineSec = lastSec;
		final Answer answer = answerOf(closed);
		final String numbers = numbers(closed, answer.icon);
		final String text = CHAT_START + answer.oneLine + " (" + closed.lengthS() + " s).";
		return numbers.isEmpty() ? text : text + " " + numbers + ".";
	}

	/** P2.2: the first of the six rules that holds. */
	private static BadgeView pick(Verdict card, LagEvent open, LagEvent lastClosed, long lastSec, boolean show,
		BadgeStyle style, WhenSmooth whenSmooth)
	{
		if (!show || card == null || Answer.of(card) == Answer.NOT_LOGGED_IN)
		{
			return BadgeView.HIDDEN;
		}
		final LagEvent e = open != null ? open : lastClosed;
		if (e != null)
		{
			final long q = Math.max(0, lastSec - e.endSec);
			if (q <= Thresholds.BADGE_HOLD_S)
			{
				return lag(e, q, style);
			}
		}
		final boolean hide = whenSmooth == WhenSmooth.HIDE;
		if (card.level == Level.NO_DATA)
		{
			if (hide)
			{
				return BadgeView.HIDDEN;
			}
			final Answer answer = Answer.of(card);
			return new BadgeView(true, style, Level.NO_DATA, Icon.NONE, false, answer.line1, answer.line2,
				card.headline, card.proof);
		}
		if (card.cause == Cause.ALL_CLEAR || card.eventId >= 0)
		{
			if (hide)
			{
				return BadgeView.HIDDEN;
			}
			final Answer smooth = Answer.SMOOTH;
			return card.cause == Cause.ALL_CLEAR
				? new BadgeView(true, style, Level.OK, Icon.NONE, false, smooth.line1, smooth.line2,
					smooth.line1 + ". " + card.proof, "")
				: new BadgeView(true, style, Level.OK, Icon.NONE, false, smooth.line1, smooth.line2,
					smooth.line1 + ".", LAST_LAG + Answer.of(card).oneLine);
		}
		final Answer answer = Answer.of(card);
		return new BadgeView(true, style, card.level, answer.icon, false, answer.line1, answer.line2,
			answer.oneLine, card.proof);
	}

	/** Rule 3: a lag, going on or within its hold. */
	private static BadgeView lag(LagEvent e, long q, BadgeStyle style)
	{
		final Answer answer = answerOf(e);
		final Level level = e.verdict == null ? Level.BAD : e.verdict.level;
		final boolean goingOn = e.open && q <= GOING_ON_S;
		return new BadgeView(true, style, level, answer.icon, !goingOn, answer.line1, answer.line2,
			answer.oneLine, numbers(e, answer.icon));
	}

	/** The answer of an event: its verdict's, and "Lag" / "Can't tell why" while it has none (P2.2, rule 3). */
	private static Answer answerOf(LagEvent e)
	{
		return e.verdict == null ? Answer.of(Cause.NOT_SURE) : Answer.of(e.verdict);
	}

	/** The event's numbers by the answer's icon (P2.2); "" with no number, and for an answer with no icon. */
	private static String numbers(LagEvent e, Icon icon)
	{
		switch (icon)
		{
			case WORLD:
				return join(part("Ticks ", e.worstTickGapMs, " ms"), part("ping ", e.rttMs, " ms"));
			case LINE:
				return join(part("Ping ", e.rttMaxMs, " ms"), part("ticks ", e.worstTickGapMs, " ms"));
			case PC:
				return join(part("Worst frame ", e.worstFrameMs, " ms"), part("", e.fps, " fps"));
			case UNKNOWN:
				return join(part("Ticks ", e.worstTickGapMs, " ms"), part("worst frame ", e.worstFrameMs, " ms"));
			default:
				return "";
		}
	}

	/** One part of the numbers, in its place in the sentence; "" when the number is missing (below 0). */
	private static String part(String word, int number, String unit)
	{
		return number < 0 ? "" : word + Fmt.thousands(number) + unit;
	}

	/** Both parts, or the one that remains with a capital, or "". */
	private static String join(String first, String second)
	{
		if (first.isEmpty())
		{
			return second.isEmpty() ? "" : Character.toUpperCase(second.charAt(0)) + second.substring(1);
		}
		return second.isEmpty() ? first : first + ", " + second;
	}
}

package com.whylag.core;

/**
 * The four settings of the game badge as the panel's gear menu ticks them (1.0.1, lot C): whether the badge shows,
 * its {@link BadgeStyle}, its {@link WhenSmooth} choice and whether a lag sends a chat line. Immutable. The plugin
 * reads them from its config on the sampler thread, where the badge reads them too, and attaches them to the
 * snapshot, so the menu ticks what is stored and the Swing thread never reads the config.
 *
 * <p>Choice: a null style or a null when-smooth choice is kept as the config's own default ({@link BadgeStyle#ICON},
 * {@link WhenSmooth#SHOW}), so a config that answers nothing still gives a menu that can be drawn.
 */
public final class BadgeSettings
{
	/** The config's own defaults: show on, {@link BadgeStyle#ICON}, {@link WhenSmooth#SHOW}, chat line on. */
	public static final BadgeSettings DEFAULTS = new BadgeSettings(true, BadgeStyle.ICON, WhenSmooth.SHOW, true);

	public final boolean show;
	public final BadgeStyle style;
	public final WhenSmooth whenSmooth;
	public final boolean chatLine;

	/** The four settings as given; a null style or when-smooth choice is kept as the config's own default. */
	public BadgeSettings(boolean show, BadgeStyle style, WhenSmooth whenSmooth, boolean chatLine)
	{
		this.show = show;
		this.style = style == null ? BadgeStyle.ICON : style;
		this.whenSmooth = whenSmooth == null ? WhenSmooth.SHOW : whenSmooth;
		this.chatLine = chatLine;
	}
}

package com.whylag.core;

/**
 * How the game badge draws its answer (contract 3.2, P2.3): the setting "Style" of the section "Game screen"
 * ({@code WhyLagConfig.badgeStyle}, default {@link #ICON}).
 *
 * <p><b>The constant NAMES are frozen at first release.</b> RuneLite's {@code ConfigManager} stores an enum setting
 * by {@code name()} and reads it back with {@code Enum.valueOf}, so renaming a constant silently resets every user's
 * choice ({@code WhyLagConfigTest.theStoredEnumNamesArePinned}). {@link #toString()} is the name the settings list
 * shows, and may change.
 */
public enum BadgeStyle
{
	/** The cause's icon with its status shape in the corner; a shape alone while smooth or measuring. No words. */
	ICON("Icon", true, false),
	/** The icon, and the answer's two lines beside it. */
	ICON_AND_WORDS("Icon and words", true, true),
	/** The status shape, and the answer's two lines beside it. Never an icon. */
	SHAPE_AND_WORDS("Shape and words", false, true),
	/** The status shape alone, in every state; the tooltip tells the causes apart. */
	SHAPE_ONLY("Shape only", false, false);

	private final String label;
	private final boolean icon;
	private final boolean words;

	BadgeStyle(String label, boolean icon, boolean words)
	{
		this.label = label;
		this.icon = icon;
		this.words = words;
	}

	/** The name in the settings list: "Icon", "Icon and words", "Shape and words", "Shape only". */
	@Override
	public String toString()
	{
		return label;
	}

	/** True when the style draws the cause's icon: {@link #ICON} and {@link #ICON_AND_WORDS}. */
	public boolean icon()
	{
		return icon;
	}

	/** True when the style draws the answer's words: {@link #ICON_AND_WORDS} and {@link #SHAPE_AND_WORDS}. */
	public boolean words()
	{
		return words;
	}
}

package com.whylag.core;

/**
 * What the game badge shows, immutable (contract 3.8, P2): built by the badge's state machine on the sampler thread,
 * read by the overlay inside {@code render} on the client thread through one volatile read. The overlay paints it
 * and holds no rule of its own.
 *
 * <p>{@code visible} false: the overlay draws nothing and has no tooltip. A hidden view is always {@link #HIDDEN}
 * itself (contract P2.2): the state machine builds no other view with {@code visible} false, so a reader may compare
 * by identity. {@code style} is the setting as given in every VISIBLE view (HIDDEN's is ICON, whatever the setting);
 * the painter leaves out what the style does not show. {@code level} is the status shape and the icon's state;
 * {@code icon} the cause's picture ({@link Icon#NONE}: the shape alone); {@code dimmed} true once the lag is over,
 * while the hold of {@link Thresholds#BADGE_HOLD_S} runs. {@code line1} and {@code line2} are the answer's two lines
 * ({@link Answer}), {@code tip1} and {@code tip2} the tooltip's two lines; "" = none, and a null text is kept as "".
 *
 * <p>The state machine answers the SAME object while nothing the badge shows changed ({@link #sameAs}), so the
 * overlay repaints only a new view (contract 4, T18 and T19).
 */
public final class BadgeView
{
	/**
	 * Nothing to show: not visible, style ICON, level NO_DATA, icon NONE, not dimmed, every text "". The ONE hidden
	 * view: the state machine answers this object in every hidden case, whatever the style setting (contract P2.2).
	 */
	public static final BadgeView HIDDEN = new BadgeView(false, BadgeStyle.ICON, Level.NO_DATA, Icon.NONE, false,
		"", "", "", "");

	/** False: the overlay draws nothing and has no tooltip. */
	public final boolean visible;
	public final BadgeStyle style;
	/** The status shape, and the icon's state. */
	public final Level level;
	/** The cause's picture; {@link Icon#NONE} = the shape alone. */
	public final Icon icon;
	/** The lag is over; the hold of {@link Thresholds#BADGE_HOLD_S} runs. */
	public final boolean dimmed;
	/** The answer's two lines; "" = none. */
	public final String line1, line2;
	/** The tooltip's two lines; "" = none. */
	public final String tip1, tip2;

	public BadgeView(boolean visible, BadgeStyle style, Level level, Icon icon, boolean dimmed, String line1,
		String line2, String tip1, String tip2)
	{
		this.visible = visible;
		this.style = style;
		this.level = level;
		this.icon = icon;
		this.dimmed = dimmed;
		this.line1 = line1 == null ? "" : line1;
		this.line2 = line2 == null ? "" : line2;
		this.tip1 = tip1 == null ? "" : tip1;
		this.tip2 = tip2 == null ? "" : tip2;
	}

	/** True when {@code o} shows the same badge: every field is equal. */
	public boolean sameAs(BadgeView o)
	{
		return o != null
			&& visible == o.visible
			&& style == o.style
			&& level == o.level
			&& icon == o.icon
			&& dimmed == o.dimmed
			&& line1.equals(o.line1)
			&& line2.equals(o.line2)
			&& tip1.equals(o.tip1)
			&& tip2.equals(o.tip2);
	}
}

package com.whylag.core;

/**
 * What sets the frame cap in force (contract 3.2, 3.7). {@link #selfSet()}: the player chose it, so a frame rate
 * held at it is no lag (F1). {@link #waits()}: the renderer paces frames by WAITING for it, so a gap of a couple of
 * cap intervals can be pacing rather than a stall (S4's exclude).
 */
public enum CapSource
{
	NONE("", false, false),
	CLIENT_50("the client", false, false),
	FPS_CONTROL("FPS Control", true, true),
	FPS_CONTROL_UNFOCUSED("FPS Control (unfocused)", true, true),
	GPU_TARGET("GPU: FPS target", true, true),
	GPU_VSYNC("GPU: V-Sync", true, true),
	HD_TARGET("117 HD: FPS target", true, true),
	HD_VSYNC("117 HD: V-Sync", true, true);

	private final String label;
	private final boolean selfSet;
	private final boolean waits;

	CapSource(String label, boolean selfSet, boolean waits)
	{
		this.label = label;
		this.selfSet = selfSet;
		this.waits = waits;
	}

	/** The words F1's proof and the report print ("Set by FPS Control."); "" for {@link #NONE}. */
	public String label()
	{
		return label;
	}

	/** True when the player set this cap. */
	public boolean selfSet()
	{
		return selfSet;
	}

	/** True when frames are paced by waiting for this cap. */
	public boolean waits()
	{
		return waits;
	}
}

package com.whylag.core;

/**
 * Every cause of the build plan, by its id (contract 3.2). {@link #shortName()} is the phrase the X verdict names
 * ("It was a client stall or lost packets."). Only the causes of wave one's twelve rules, plus
 * {@link #WARMING_UP}, answer {@link #inWaveOne()}: the rest are named so their ids stay fixed, and no wave-one
 * rule gives them.
 *
 * <p>Choice (1.0.0, the Hub's rule): the memory causes (G1, G2, G3), the client-waiting cause (S4, which read the
 * game thread's busy share to tell waiting from working) and the other-program cause (S5, which read the whole PC's
 * CPU) are gone with the readings they stood on; S3 is the one client-stall cause and judges by the frame gap alone.
 *
 * <p>{@link #WARMING_UP} is the one wave-one cause that no rule gives: it is the cause of each of the three states
 * of the card that are not verdicts (contract 5.1) - "Not logged in", "Still measuring" and "Waiting for the game" -
 * each with the confidence {@link Confidence#CANT_TELL} and the level {@link Level#NO_DATA}. They differ by their
 * headline.
 *
 * <p>{@link #DELIVERY_GAP} (N6) is new with skeptic C2: a delivery gap whose cause is unknown. {@link #TICKS_STOPPED}
 * (D3) has no rule in wave one; N6 covers its trace.
 */
public enum Cause
{
	MAP_LOAD("S1", Group.FRAME_RATE, "map loading"),
	EVENT_STALL("S2", Group.FRAME_RATE, "a plugin"),
	CLIENT_BUSY("S3", Group.FRAME_RATE, "a client stall"),
	FRAME_CAP("F1", Group.FRAME_RATE, "a frame cap"),
	SLOW_DRAWING("F2", Group.FRAME_RATE, "slow drawing"),
	CROWD("F3", Group.FRAME_RATE, "this place"),
	SCALES_BADLY("F4", Group.FRAME_RATE, "this place"),
	PING_HIGH("N1", Group.CONNECTION, "high ping"),
	PING_JUMPY("N2", Group.CONNECTION, "your connection"),
	UPLOAD_LOSS("N3", Group.CONNECTION, "lost packets"),
	PERIODIC_SPIKE("N4", Group.CONNECTION, "a ping spike"),
	MAC_WIFI("N5", Group.CONNECTION, "Wi-Fi"),
	DELIVERY_GAP("N6", Group.UNSURE, "your line or the server"),
	SLOW_WORLD("W1", Group.WORLD, "the world"),
	WORLD_ONLY("W2", Group.WORLD, "the world"),
	ROUTE("W3", Group.WORLD, "the route"),
	YOUR_LINE("W4", Group.CONNECTION, "your line"),
	DISCONNECT("D1", Group.CONNECTION, "a disconnect"),
	WEEKLY_UPDATE("D2", Group.WORLD, "the weekly update"),
	TICKS_STOPPED("D3", Group.UNSURE, "your line or the server"),
	VSYNC_HINT("V1", Group.NONE, "V-Sync"),
	ALL_CLEAR("V2", Group.NONE, ""),
	NOT_SURE("X", Group.UNSURE, ""),
	WARMING_UP("-", Group.NONE, "");

	private final String id;
	private final Group group;
	private final String shortName;

	Cause(String id, Group group, String shortName)
	{
		this.id = id;
		this.group = group;
		this.shortName = shortName;
	}

	/** The plan's id: "S3", "N6", "X", "-". */
	public String id()
	{
		return id;
	}

	/** What an event with this cause is counted under. */
	public Group group()
	{
		return group;
	}

	/** The phrase the X verdict uses for this cause; "" where X never names it. */
	public String shortName()
	{
		return shortName;
	}

	/**
	 * True for exactly thirteen causes: those of the twelve rules of section 6 (D1, S1, N3, N2, W1 - whose
	 * condition form W1c reuses it - S3, N6, F1, N1, F2, V2, X) and {@link #WARMING_UP}.
	 */
	public boolean inWaveOne()
	{
		switch (this)
		{
			case DISCONNECT:
			case MAP_LOAD:
			case UPLOAD_LOSS:
			case PING_JUMPY:
			case SLOW_WORLD:
			case CLIENT_BUSY:
			case DELIVERY_GAP:
			case FRAME_CAP:
			case PING_HIGH:
			case SLOW_DRAWING:
			case ALL_CLEAR:
			case NOT_SURE:
			case WARMING_UP:
				return true;
			default:
				return false;
		}
	}
}

package com.whylag.core;

/**
 * One of the three small cells of the panel of picture 18 (contract 3.8, 5.2), as data: the panel paints it and
 * holds no rule of its own; {@link Cells} makes the three. Immutable; a null text is kept as "".
 *
 * <p>{@code name} is "FPS", "Tick" or "Ping"; {@code value} the big number, "50", "1,240", "41", or "-" for no
 * data; {@code unit} the small line under it, "fps", "ms", "ms", or "" for none; {@code level} the shape beside
 * the name; {@code culprit} marks the cell of a selected event's cause (a coloured edge and ground); {@code tip} is
 * the tooltip, what the old tile said in full.
 */
public final class Cell
{
	public final Lane lane;
	/** "FPS", "Tick", "Ping". */
	public final String name;
	/** "50", "1,240", "41"; "-" = no data. */
	public final String value;
	/** "fps", "ms", "ms"; "" = none. */
	public final String unit;
	/** The shape beside the name. */
	public final Level level;
	/** The cell of a selected event's cause: coloured edge and ground (contract 5.2). */
	public final boolean culprit;
	/** The tooltip: what the old tile said in full. */
	public final String tip;

	public Cell(Lane lane, String name, String value, String unit, Level level, boolean culprit, String tip)
	{
		this.lane = lane;
		this.name = name == null ? "" : name;
		this.value = value == null ? "" : value;
		this.unit = unit == null ? "" : unit;
		this.level = level;
		this.culprit = culprit;
		this.tip = tip == null ? "" : tip;
	}
}

package com.whylag.core;

/**
 * The three small cells of the panel (contract 3.8, 5.2): the three tiles, as picture 18 draws them, each a third
 * of the panel's width. Pure and static. The tiles stay DATA (the lane values and the report read them); this class
 * turns them into what the panel paints, so the snapshot builder builds nothing new and the panel holds no cell
 * rule.
 *
 * <p><b>{@link #now}</b>, with no event selected, reads the snapshot's three tiles:
 * <table>
 * <caption>The cells of now</caption>
 * <tr><th>Cell</th><th>Value</th><th>Unit</th><th>Level</th><th>Tip</th></tr>
 * <tr><td>FPS</td><td>the number of the Frame rate tile's value</td><td>fps</td><td>the tile's</td>
 * <td>"Frame rate: 50 fps, worst 35 ms"</td></tr>
 * <tr><td>Tick</td><td>the number of the Server ticks tile's value: the window's mean gap</td><td>ms</td>
 * <td>the tile's</td><td>"Ticks: 600 ms, &plusmn;13 ms"</td></tr>
 * <tr><td>Ping</td><td>the number of the Ping tile's value</td><td>ms</td><td>the tile's</td>
 * <td>"Ping: 41 ms, was 39 ms"</td></tr>
 * </table>
 *
 * <p><b>{@link #of}</b>, for ONE selected event, reads {@link EventView#tiles} of it, by the same rules, with one
 * difference: the Tick cell shows the event's WORST tick ({@code worstTickGapMs}, "1,240"; -1: "-") at
 * {@code Levels.tick(worstCorrectedTickMs)}, and its tip is "Ticks: worst 1,240 ms, mean 952 ms", a part at -1
 * left out. The ticks lane beside the graph keeps the mean: the cell answers "how bad did it get".
 *
 * <p><b>The rules.</b>
 * <ul>
 * <li>"The number of a value" is the text before its LAST space, read as a whole number with the commas taken out,
 * held in 0 .. 9,999 and printed through {@link Fmt#thousands}: "1,240 ms" gives "1,240", 12,400 gives "9,999".</li>
 * <li>A tile whose value is "-" gives the value "-", the unit "" and the level NO_DATA, and its reason goes in the
 * tip: "Ping: Nothing sent", "Frame rate: Not logged in". A cell has no room for it, so the reason is never
 * painted in it.</li>
 * <li>A tip is {@link Lane#label()}, ": ", the tile's value, then ", " and its small line unless that is "". With no
 * data it is the label, ": " and the reason.</li>
 * <li>No cell of {@link #now} is a culprit. In {@link #of} the culprit is the cell of {@code e.group().lane()}; a
 * "Not sure" event (the group UNSURE, which has no lane) marks none. The culprit's level is the event's verdict's
 * (BAD while it has none), whatever its own number says, so its edge, its ground and its shape agree.</li>
 * </ul>
 *
 * <p>Choice: a tile value with no number to read (never made) is a dash at NO_DATA; its tip keeps the tile's words.
 * <p>Choice: a dash with no reason (an event's field at -1) has the tip "label: -": "Frame rate: -", "Ticks: -".
 * <p>Choice: a tip prints the true number: a worst tick of 12,400 ms is "9,999" in the cell, "worst 12,400" in its tip.
 */
public final class Cells
{
	/** The largest number a tile's cell prints, and the largest worst tick: "9,999" (contract 5.2). */
	private static final int MAX_NUMBER = 9999;
	/** No number could be read from a tile's value. */
	private static final int NO_NUMBER = -1;
	private static final String DASH = "-";

	private Cells()
	{
	}

	/**
	 * The three cells with no event selected, in {@link Lane} order; none is a culprit. Each follows its tile.
	 */
	public static Cell[] now(PanelSnapshot s)
	{
		final Tile[] t = s.tiles;
		return new Cell[] {
			tileCell(Lane.FRAME_RATE, "FPS", tile(t, Lane.FRAME_RATE), "fps"),
			tileCell(Lane.TICKS, "Tick", tile(t, Lane.TICKS), "ms"),
			tileCell(Lane.PING, "Ping", tile(t, Lane.PING), "ms")};
	}

	/** The three cells of ONE event (a selected row), in {@link Lane} order, its culprit marked. */
	public static Cell[] of(LagEvent e)
	{
		final Tile[] t = EventView.tiles(e);
		final Cell[] out = {
			tileCell(Lane.FRAME_RATE, "FPS", t[0], "fps"),
			worstTickCell(e),
			tileCell(Lane.PING, "Ping", t[2], "ms")};
		final Lane culprit = e.group().lane();
		if (culprit != null)
		{
			final Cell c = out[culprit.ordinal()];
			final Level level = e.verdict == null ? Level.BAD : e.verdict.level;
			out[culprit.ordinal()] = new Cell(c.lane, c.name, c.value, c.unit, level, true, c.tip);
		}
		return out;
	}

	/** A cell of one tile: the number of its value, or a dash with the reason in the tip. */
	private static Cell tileCell(Lane lane, String name, Tile t, String unit)
	{
		final String tip;
		if (DASH.equals(t.value))
		{
			tip = lane.label() + ": " + (t.sub.isEmpty() ? DASH : t.sub);
		}
		else
		{
			tip = lane.label() + ": " + t.value + (t.sub.isEmpty() ? "" : ", " + t.sub);
		}
		final int n = DASH.equals(t.value) ? NO_NUMBER : numberOf(t.value);
		if (n == NO_NUMBER)
		{
			return new Cell(lane, name, DASH, "", Level.NO_DATA, false, tip);
		}
		return new Cell(lane, name, Fmt.thousands(n), unit, t.level, false, tip);
	}

	/** An event's Tick cell: its WORST tick, at the level of its largest corrected deviation. */
	private static Cell worstTickCell(LagEvent e)
	{
		final StringBuilder tip = new StringBuilder(Lane.TICKS.label()).append(": ");
		if (e.worstTickGapMs >= 0)
		{
			tip.append("worst ").append(Fmt.thousands(e.worstTickGapMs)).append(" ms");
		}
		if (e.meanTickGapMs >= 0)
		{
			tip.append(e.worstTickGapMs >= 0 ? ", " : "").append("mean ").append(Fmt.thousands(e.meanTickGapMs))
				.append(" ms");
		}
		if (e.worstTickGapMs < 0 && e.meanTickGapMs < 0)
		{
			tip.append(DASH);
		}
		if (e.worstTickGapMs < 0)
		{
			return new Cell(Lane.TICKS, "Tick", DASH, "", Level.NO_DATA, false, tip.toString());
		}
		return new Cell(Lane.TICKS, "Tick", Fmt.thousands(Math.min(e.worstTickGapMs, MAX_NUMBER)), "ms",
			Levels.tick(e.worstCorrectedTickMs), false, tip.toString());
	}

	/** The tile of that lane, or a dash with no reason when the snapshot has none there. */
	private static Tile tile(Tile[] tiles, Lane lane)
	{
		final int i = lane.ordinal();
		if (tiles == null || i >= tiles.length || tiles[i] == null)
		{
			return new Tile(lane, Level.NO_DATA, DASH, "", NoData.NONE);
		}
		return tiles[i];
	}

	/**
	 * The number of a tile's value (contract 5.2): the text before its LAST space, read as a whole number with the
	 * commas taken out, held in 0 .. {@link #MAX_NUMBER}; {@link #NO_NUMBER} when that text holds no number.
	 */
	private static int numberOf(String value)
	{
		final int space = value.lastIndexOf(' ');
		final int end = space < 0 ? value.length() : space;
		long n = 0;
		boolean digits = false;
		boolean negative = false;
		for (int i = 0; i < end; i++)
		{
			final char c = value.charAt(i);
			if (c == ',')
			{
				continue;
			}
			if (c == '-' && i == 0)
			{
				negative = true;
				continue;
			}
			if (c < '0' || c > '9')
			{
				return NO_NUMBER;
			}
			digits = true;
			n = Math.min(n * 10 + (c - '0'), MAX_NUMBER + 1L);
		}
		if (!digits)
		{
			return NO_NUMBER;
		}
		return negative ? 0 : (int) Math.min(n, MAX_NUMBER);
	}
}

package com.whylag.core;

import java.time.ZoneId;

/**
 * Everything the ten checks need to know, immutable once built (1.0.1, lot B): one set of plain numbers, flags
 * and words, read in ONE step of the sampler thread, so a check is a pure function of it ({@link Checks#run}) and a
 * test feeds it any state it likes. Nothing here is a name, a hash, a host, an address or a path: the world
 * NUMBER, the client's and Java's versions and the system's name are the most personal words it holds.
 *
 * <p><b>Who reads what.</b> {@link Builder#session} reads the rings and the event clocks of the session - the frame
 * and tick columns the client thread writes, the host columns the sampler writes - and is called on the sampler
 * thread only, the thread that owns every ring ({@code MinuteLine.of} and {@code SnapshotBuilder} do the same). The
 * plugin sets the rest by hand, from the fields it already keeps: the settings, the badge, the last step's timings
 * and the clock watch. The Swing thread never reads a ring and never builds one of these.
 *
 * <p>A fact with no value is -1 (or 0 for a count, "" for a word, false for a flag): every check then says "no data"
 * in its own words and none reads a ring itself.
 *
 * <p>
 * Choice: the frame rate and the frames of the last {@value #FRAMES_S} s come from the newest COMPLETE seconds, as
 * every "newest second" in the plugin does, and both read 0 when no frame has been drawn for certainly longer than
 * {@link Thresholds#NO_FRAMES_MS} ({@link Session#framesStopped}): the frame columns stop moving when the client
 * stops drawing, so the last second the ring holds is an old one, and reading it would pass a frozen client.
 * <br>
 * Choice: the last tick's age, the ticks of the last {@value #TICKS_S} s and their mean gap come from the CLOCK, not
 * from the newest second, so a world that stopped sending ticks reads as a growing age. The mean leaves out the
 * gaps of masked ticks (a login, a hop, a load) and any gap of 0 or less, a tick with no tick before it.
 * <br>
 * Choice: the ping state is the newest complete second's own {@link SecondRing#conn}: {@link Ping#READING} is a
 * fresh round trip time, {@link Ping#UNSUPPORTED}, {@link Ping#ERROR} and {@link Ping#STALE} are the probe's three
 * other answers, and every other reason (not logged in, not connected, still measuring) is {@link Ping#NONE}.
 * <br>
 * Choice: {@link #capKnown} is false for an unread renderer and for a V-Sync cap whose refresh rate could not be
 * read; "no cap" of an unlocked renderer is a known state, and the report already says "cap none" for it.
 */
public final class CheckFacts
{
	/** The state of the ping probe as a check sees it. */
	public enum Ping
	{
		/** A fresh round trip time was read. */
		READING,
		/** The game's socket or the TCP reading is not offered on this PC or by this client. */
		UNSUPPORTED,
		/** The probe tried and failed. */
		ERROR,
		/** Nothing has been sent lately, so the reading is old. */
		STALE,
		/** No reading and no reason of the three: not logged in, not connected, or still measuring. */
		NONE
	}

	/** The seconds the frame count looks back over. */
	public static final int FRAMES_S = 2;
	/** The seconds the tick count looks back over. */
	public static final int TICKS_S = 10;

	private static final long MS_PER_SECOND = 1000L;
	private static final ZoneId UTC = ZoneId.of("UTC");
	private static final String VSYNC_ON = "ON";
	private static final String VSYNC_ADAPTIVE = "ADAPTIVE";

	/** True when the newest complete second is in-game. */
	public final boolean loggedIn;
	/** That second's world; 0 = none known. */
	public final int world;
	/** Frames drawn in the last {@value #FRAMES_S} complete seconds; -1 = no second; 0 when frames have stopped. */
	public final int framesLast2s;
	/** Frames in the newest complete second; -1 = none; 0 when frames have stopped. */
	public final int fps;
	/** Milliseconds since the newest tick arrived; -1 = none yet. */
	public final long lastTickAgoMs;
	/** Ticks that arrived in the last {@value #TICKS_S} s. */
	public final int ticksLast10s;
	/** Their mean gap in ms, masked ticks left out; -1 = none to average. */
	public final int meanGapMs;
	public final Ping pingState;
	/** The newest second's round trip time in ms; -1 = none. */
	public final int rttMs;
	/** How old that reading is, in seconds; -1 = unknown. */
	public final int pingAgeS;
	/** Milliseconds since the last sampler step started; -1 = no step yet. */
	public final long lastStepAgoMs;
	/** What the last step's host and step calls took, in microseconds; -1 = not timed yet. */
	public final long stepCostUs;
	public final Renderer renderer;
	public final boolean capKnown;
	/** The infobox and the overlay are both registered with the client. */
	public final boolean badgeRegistered;
	/** The "Show" setting of the badge. */
	public final boolean badgeShow;
	/** "" = unknown. */
	public final String clientVersion;
	/** {@code java.version}; "" = unknown. */
	public final String javaVersion;
	/** {@code os.name}; "" = unknown. */
	public final String os;
	/** How far back the wall clock last jumped, in whole seconds; 0 = never. */
	public final int clockJumpedBackS;
	/** The wall time of that jump; 0 = never. */
	public final long clockJumpAtWallMs;
	/** The zone the clocks are written in; never null. */
	public final ZoneId zone;
	/** Seconds since the current login; 0 when not logged in. */
	public final long loggedInS;
	/** The card's state now; never null. */
	public final Answer cardState;

	private CheckFacts(Builder b)
	{
		loggedIn = b.loggedIn;
		world = b.world;
		framesLast2s = b.framesLast2s;
		fps = b.fps;
		lastTickAgoMs = b.lastTickAgoMs;
		ticksLast10s = b.ticksLast10s;
		meanGapMs = b.meanGapMs;
		pingState = b.pingState == null ? Ping.NONE : b.pingState;
		rttMs = b.rttMs;
		pingAgeS = b.pingAgeS;
		lastStepAgoMs = b.lastStepAgoMs;
		stepCostUs = b.stepCostUs;
		renderer = b.renderer == null ? Renderer.UNKNOWN : b.renderer;
		capKnown = b.capKnown;
		badgeRegistered = b.badgeRegistered;
		badgeShow = b.badgeShow;
		clientVersion = b.clientVersion == null ? "" : b.clientVersion;
		javaVersion = b.javaVersion == null ? "" : b.javaVersion;
		os = b.os == null ? "" : b.os;
		clockJumpedBackS = b.clockJumpedBackS;
		clockJumpAtWallMs = b.clockJumpAtWallMs;
		zone = b.zone == null ? UTC : b.zone;
		loggedInS = b.loggedInS;
		cardState = b.cardState == null ? Answer.MEASURING : b.cardState;
	}

	/**
	 * True when the settings hold a cap reading a verdict can use: the renderer is read, and a V-Sync cap has a
	 * refresh rate to stand on.
	 */
	public static boolean capKnown(SettingsView v)
	{
		if (v == null || v.renderer == Renderer.UNKNOWN)
		{
			return false;
		}
		final boolean ownCap = v.renderer == Renderer.GPU || v.renderer == Renderer.HD;
		final boolean vsync = VSYNC_ON.equals(v.vsyncMode) || VSYNC_ADAPTIVE.equals(v.vsyncMode);
		return !(ownCap && v.unlockFps && vsync && v.refreshHz <= 0);
	}

	/**
	 * The facts being gathered: every field starts as "nothing known" and {@link #build} freezes them. Not thread
	 * safe and not kept: the sampler thread makes one, fills it and builds.
	 */
	public static final class Builder
	{
		public boolean loggedIn;
		public int world;
		public int framesLast2s = -1;
		public int fps = -1;
		public long lastTickAgoMs = -1;
		public int ticksLast10s;
		public int meanGapMs = -1;
		public Ping pingState = Ping.NONE;
		public int rttMs = -1;
		public int pingAgeS = -1;
		public long lastStepAgoMs = -1;
		public long stepCostUs = -1;
		public Renderer renderer = Renderer.UNKNOWN;
		public boolean capKnown;
		public boolean badgeRegistered;
		public boolean badgeShow;
		public String clientVersion = "";
		public String javaVersion = "";
		public String os = "";
		public int clockJumpedBackS;
		public long clockJumpAtWallMs;
		public ZoneId zone = UTC;
		public long loggedInS;
		public Answer cardState = Answer.MEASURING;

		/** The settings' two facts: the renderer and whether the cap is known. */
		public Builder settings(SettingsView v)
		{
			renderer = v == null ? Renderer.UNKNOWN : v.renderer;
			capKnown = capKnown(v);
			return this;
		}

		/**
		 * The facts of the session at {@code nanos}: login, world, frames, ticks, ping and the time since the login.
		 * Sampler thread only; never throws for a session with no data.
		 *
		 * @param s     the session to read
		 * @param nanos the sampler's clock now, {@code System.nanoTime()} in a client
		 */
		public Builder session(Session s, long nanos)
		{
			final long nowSec = s.secOf(nanos);
			final long nowMs = s.msOf(nanos);
			final SecondRing r = s.seconds;
			final long last = s.lastSec(nowSec);
			readNewest(r, last);
			readFrames(s, r, last, nowSec);
			readTicks(s.ticks, nowMs);
			readPing(r, last);
			final long since = s.loggedInSinceSec();
			loggedInS = loggedIn && since != Session.NEVER ? Math.max(0, nowSec - since) : 0;
			return this;
		}

		/** Login, world and the newest second's frame rate. */
		private void readNewest(SecondRing r, long last)
		{
			loggedIn = false;
			world = 0;
			fps = -1;
			if (last < 0 || !r.valid(last))
			{
				return;
			}
			final int flags = r.flags(last);
			final int w = r.world(last);
			final int f = r.frames(last);
			if (!r.valid(last))
			{
				return;
			}
			loggedIn = !Flags.has(flags, Flags.NOT_LOGGED_IN);
			world = loggedIn ? Math.max(0, w) : 0;
			fps = Math.max(0, f);
		}

		/** The frames of the last {@value CheckFacts#FRAMES_S} complete seconds; 0 while the client has stopped drawing. */
		private void readFrames(Session s, SecondRing r, long last, long nowSec)
		{
			framesLast2s = -1;
			if (s.framesStopped(nowSec))
			{
				framesLast2s = 0;
				fps = 0;
				return;
			}
			int sum = 0;
			boolean any = false;
			for (long k = last; k > last - FRAMES_S && k >= 0; k--)
			{
				if (!r.valid(k))
				{
					continue;
				}
				final int frames = r.frames(k);
				if (r.valid(k))
				{
					any = true;
					sum += Math.max(0, frames);
				}
			}
			framesLast2s = any ? sum : -1;
		}

		/** The newest tick's age, and the count and mean gap of the ticks of the last {@value CheckFacts#TICKS_S} s. */
		private void readTicks(TickRing t, long nowMs)
		{
			lastTickAgoMs = -1;
			ticksLast10s = 0;
			meanGapMs = -1;
			final long head = t.head();
			final long from = nowMs - TICKS_S * MS_PER_SECOND;
			long gapSum = 0;
			int gaps = 0;
			for (long seq = head; seq >= 0; seq--)
			{
				if (!t.valid(seq))
				{
					break;
				}
				final long at = t.atMs(seq);
				final int gap = t.gapMs(seq);
				final int flags = t.flags(seq);
				if (!t.valid(seq))
				{
					break;
				}
				if (seq == head)
				{
					lastTickAgoMs = Math.max(0, nowMs - at);
				}
				if (at < from)
				{
					break;   // ticks arrive in order: this one and every older one is outside the window
				}
				ticksLast10s++;
				if (gap > 0 && !Flags.masked(flags))
				{
					gapSum += gap;
					gaps++;
				}
			}
			meanGapMs = gaps == 0 ? -1 : (int) ((gapSum + gaps / 2) / gaps);
		}

		/** The newest second's ping. */
		private void readPing(SecondRing r, long last)
		{
			pingState = Ping.NONE;
			rttMs = -1;
			pingAgeS = -1;
			if (last < 0 || !r.valid(last))
			{
				return;
			}
			final NoData conn = r.conn(last);
			final int rtt = r.rttMs(last);
			final int age = r.rttAgeS(last);
			if (r.valid(last))
			{
				pingState = pingOf(conn);
				rttMs = rtt;
				pingAgeS = age;
			}
		}

		private static Ping pingOf(NoData conn)
		{
			switch (conn)
			{
				case NONE:
					return Ping.READING;
				case UNSUPPORTED:
					return Ping.UNSUPPORTED;
				case ERROR:
					return Ping.ERROR;
				case STALE:
					return Ping.STALE;
				default:
					return Ping.NONE;
			}
		}

		/** The immutable facts. */
		public CheckFacts build()
		{
			return new CheckFacts(this);
		}
	}
}

package com.whylag.core;

/**
 * The answer of one check (1.0.1, lot B): its id ({@code C4}), its name ({@code Ping readable}), whether it passed
 * and one line of detail. Immutable; {@link Checks#run} makes ten of them and the report prints each as
 * {@link #line()}.
 *
 * <p>The detail of a PASS is what was found ({@code 41 ms, 1 s old}); the detail of a FAIL is the plain words of what
 * is wrong, which {@link Checks#verdict} puts first, so a detail starts in lower case and means a sentence.
 *
 * <p>Choice: a check that could not run for a stated reason (not logged in) is a
 * PASS whose detail says so, never a FAIL: a FAIL means the plugin itself is short of something it needs.
 * <br>
 * Choice: a null text is kept as "".
 */
public final class CheckResult
{
	/** {@code C1} to {@code C10}. */
	public final String id;
	/** {@code Ping readable}. */
	public final String name;
	public final boolean pass;
	/** One line, no line break. */
	public final String detail;

	public CheckResult(String id, String name, boolean pass, String detail)
	{
		this.id = id == null ? "" : id;
		this.name = name == null ? "" : name;
		this.pass = pass;
		this.detail = detail == null ? "" : detail;
	}

	/** The report's line: {@code PASS  C4 Ping readable  41 ms, 1 s old}; the detail is left off when it is "". */
	public String line()
	{
		final String head = (pass ? "PASS" : "FAIL") + "  " + id + " " + name;
		return detail.isEmpty() ? head : head + "  " + detail;
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The ten checks of "Troubleshoot..." (1.0.1, lots B and C), each a pure function of the {@link CheckFacts} the
 * sampler thread gathered, and the plain-words verdict made of their answers. Nothing here reads a ring, a clock or
 * the game, so a test feeds every check a state that passes and a state that fails.
 *
 * <table>
 * <caption>The ten checks, in the order they are run and listed</caption>
 * <tr><th>Id</th><th>Name</th><th>Passes when</th></tr>
 * <tr><td>C1</td><td>Logged in</td><td>a world is known and the newest second is in-game</td></tr>
 * <tr><td>C2</td><td>Frames arrive</td><td>frames were counted in the last 2 s, at 1 to 1,000 a second</td></tr>
 * <tr><td>C3</td><td>Ticks arrive</td><td>the last tick is under 1.2 s old, 5 or more came in 10 s, their mean gap is
 * 500 to 700 ms</td></tr>
 * <tr><td>C4</td><td>Ping readable</td><td>a fresh round trip time was read from the game's own socket</td></tr>
 * <tr><td>C5</td><td>The sampler runs</td>
 * <td>the last step started under 2 s ago and its work took under 2 ms</td></tr>
 * <tr><td>C6</td><td>Settings read</td><td>the renderer and the cap are known</td></tr>
 * <tr><td>C7</td><td>The badge is up</td><td>it is registered with the client; hidden by the setting passes
 * (a note)</td></tr>
 * <tr><td>C8</td><td>Client fits</td><td>RuneLite 1.13.0 or newer, Java 11 or newer, the system named</td></tr>
 * <tr><td>C9</td><td>Clock sane</td><td>the wall clock never jumped back</td></tr>
 * <tr><td>C10</td><td>Not stuck measuring</td><td>logged in for over 60 s means the card left Measuring</td></tr>
 * </table>
 *
 * <p>Choice (1.0.0, the Hub's rule): the memory and CPU checks (C5 and C6 of the twelve) went with the readings
 * they stood on, and the rest kept their order, renumbered; the verdict still names the first check that fails.
 *
 * <p>
 * Choice: a check that cannot apply because nobody is logged in (C3, C4, C10) PASSES with "not logged in, not
 * checked": C1 already fails and is the verdict, and three more FAILs would only repeat it.
 * <br>
 * Choice: the detail of a FAIL is the plain-words sentence, in lower case, short enough to fit the panel's verdict
 * line once its first letter is raised ({@link #verdict}); the longer story is in the report's other lines.
 * <br>
 * Choice: a reading no check can rule on (the step not timed yet, a client version this class cannot parse) is left
 * out of that check: it neither fails nor counts as found.
 * <br>
 * Choice: a ping is fresh when it is at most {@link Thresholds#RTT_STALE_S} s old, as the rings and every tile
 * count it, not "under" it.
 * <br>
 * Choice: the verdict is the detail of the FIRST failing check, in the order above, with its first letter raised,
 * and no full stop; when every check passes it is {@value #ALL_GOOD}.
 * <br>
 * Choice: the verdict passes {@link Diagnostics#scrub}, as every line of the report does, because the panel shows it
 * without going through the report; no word a check prints is a path today, and this keeps it so.
 */
public final class Checks
{
	/** The verdict when every check passes. */
	public static final String ALL_GOOD = "Everything is being measured.";

	/** The fewest ticks in the last 10 s. */
	static final int MIN_TICKS = 5;
	/** The mean tick gap must lie in this range, in ms. */
	static final int GAP_LOW_MS = 500, GAP_HIGH_MS = 700;
	/** The frame rate must lie in this range. */
	static final int FPS_LOW = 1, FPS_HIGH = 1000;
	/** The last step must have started no longer ago than this, in ms. */
	static final long STEP_STALE_MS = 2000;
	/** The last step's work must have taken less than this, in microseconds. */
	static final long STEP_COST_US = 2000;
	/** The oldest RuneLite this plugin was built for: 1.13.0. */
	static final int MIN_CLIENT_MAJOR = 1, MIN_CLIENT_MINOR = 13;
	private static final String MIN_CLIENT = "1.13.0";
	/** The oldest Java this plugin runs on. */
	static final int MIN_JAVA = 11;
	/** Logged in for longer than this, the card must have left Measuring. */
	static final long MEASURING_S = 60;

	private static final long MS_PER_SECOND = 1000L;
	private static final long US_PER_MS = 1000L;
	private static final String NOT_LOGGED_IN = "not logged in, not checked";
	private static final Pattern NUMBERS = Pattern.compile("^(\\d+)(?:\\.(\\d+))?");

	private Checks()
	{
	}

	/** The ten results of {@code f}, C1 first. */
	public static List<CheckResult> run(CheckFacts f)
	{
		final List<CheckResult> out = new ArrayList<>(10);
		out.add(loggedIn(f));
		out.add(frames(f));
		out.add(ticks(f));
		out.add(ping(f));
		out.add(sampler(f));
		out.add(settings(f));
		out.add(badge(f));
		out.add(client(f));
		out.add(clock(f));
		out.add(measuring(f));
		return out;
	}

	/**
	 * The plain-words verdict: the detail of the first failing result with its first letter raised, else
	 * {@value #ALL_GOOD}.
	 */
	public static String verdict(List<CheckResult> results)
	{
		for (CheckResult r : results)
		{
			if (!r.pass)
			{
				return Diagnostics.scrub(raise(r.detail));
			}
		}
		return ALL_GOOD;
	}

	/**
	 * The note the diagnostics keep of a run: {@code tests run: 9 pass, 1 fail: C4 Ping readable}; the failures are
	 * listed by id and name, comma separated; a run with none ends at the count.
	 */
	public static String summary(List<CheckResult> results)
	{
		int pass = 0;
		final StringBuilder failed = new StringBuilder();
		for (CheckResult r : results)
		{
			if (r.pass)
			{
				pass++;
			}
			else
			{
				failed.append(failed.length() == 0 ? ": " : ", ").append(r.id).append(' ').append(r.name);
			}
		}
		return "tests run: " + pass + " pass, " + (results.size() - pass) + " fail" + failed;
	}

	/**
	 * The report's {@code Verdict} and {@code Checks} sections, for {@code ReportText.of(s, checks)}: the verdict
	 * line, a blank line, {@code Checks:} with one line per result, and a blank line; each line ended with a new
	 * line.
	 */
	public static String section(List<CheckResult> results)
	{
		final StringBuilder b = new StringBuilder(1024);
		b.append("Verdict: ").append(verdict(results)).append("\n\nChecks:\n");
		for (CheckResult r : results)
		{
			b.append(r.line()).append('\n');
		}
		return b.append('\n').toString();
	}

	// ------------------------------------------------------------------ the ten

	private static CheckResult loggedIn(CheckFacts f)
	{
		if (!f.loggedIn)
		{
			return result(1, "Logged in", false, "not logged in: nothing is measured yet");
		}
		if (f.world <= 0)
		{
			return result(1, "Logged in", false, "logged in, but the world is not known yet");
		}
		return result(1, "Logged in", true, "world " + Fmt.thousands(f.world));
	}

	private static CheckResult frames(CheckFacts f)
	{
		if (f.framesLast2s <= 0)
		{
			return result(2, "Frames arrive", false, "no frames counted for " + CheckFacts.FRAMES_S + " s");
		}
		if (f.fps < FPS_LOW || f.fps > FPS_HIGH)
		{
			return result(2, "Frames arrive", false, "the frame rate reads " + Fmt.thousands(f.fps));
		}
		return result(2, "Frames arrive", true, Fmt.thousands(f.fps) + " fps, " + Fmt.thousands(f.framesLast2s)
			+ " frames in " + CheckFacts.FRAMES_S + " s");
	}

	private static CheckResult ticks(CheckFacts f)
	{
		if (!f.loggedIn)
		{
			return result(3, "Ticks arrive", true, NOT_LOGGED_IN);
		}
		if (f.lastTickAgoMs < 0)
		{
			return result(3, "Ticks arrive", false, "no tick has arrived yet");
		}
		if (f.lastTickAgoMs >= Thresholds.NO_TICK_MS)
		{
			return result(3, "Ticks arrive", false, "no ticks for " + seconds(f.lastTickAgoMs) + " s");
		}
		if (f.ticksLast10s < MIN_TICKS)
		{
			return result(3, "Ticks arrive", false, "only " + f.ticksLast10s + " ticks in " + CheckFacts.TICKS_S
				+ " s");
		}
		if (f.meanGapMs >= 0 && (f.meanGapMs < GAP_LOW_MS || f.meanGapMs > GAP_HIGH_MS))
		{
			return result(3, "Ticks arrive", false, "ticks average " + Fmt.thousands(f.meanGapMs) + " ms");
		}
		return result(3, "Ticks arrive", true, Fmt.thousands(f.ticksLast10s) + " in " + CheckFacts.TICKS_S
			+ " s, last " + Fmt.thousands((int) Math.min(Integer.MAX_VALUE, f.lastTickAgoMs)) + " ms ago"
			+ (f.meanGapMs >= 0 ? ", mean gap " + Fmt.thousands(f.meanGapMs) + " ms" : ""));
	}

	private static CheckResult ping(CheckFacts f)
	{
		if (!f.loggedIn)
		{
			return result(4, "Ping readable", true, NOT_LOGGED_IN);
		}
		switch (f.pingState)
		{
			case UNSUPPORTED:
				return result(4, "Ping readable", false, "ping cannot be read on this PC");
			case ERROR:
				return result(4, "Ping readable", false, "ping cannot be read from this client");
			case STALE:
				return result(4, "Ping readable", false, "ping is stale: nothing sent lately");
			case READING:
				if (f.rttMs < 0)
				{
					return result(4, "Ping readable", false, "no ping reading yet");
				}
				if (f.pingAgeS > Thresholds.RTT_STALE_S)
				{
					return result(4, "Ping readable", false, "ping reading is " + f.pingAgeS + " s old");
				}
				return result(4, "Ping readable", true, Fmt.thousands(f.rttMs) + " ms"
					+ (f.pingAgeS >= 0 ? ", " + f.pingAgeS + " s old" : ""));
			default:
				return result(4, "Ping readable", false, "no ping reading yet");
		}
	}

	private static CheckResult sampler(CheckFacts f)
	{
		if (f.lastStepAgoMs > STEP_STALE_MS)
		{
			return result(5, "The sampler runs", false, "the sampler has not run for " + seconds(f.lastStepAgoMs)
				+ " s");
		}
		if (f.stepCostUs >= STEP_COST_US)
		{
			return result(5, "The sampler runs", false, "sampler steps are slow: "
				+ millis(f.stepCostUs) + " ms");
		}
		if (f.lastStepAgoMs < 0)
		{
			return result(5, "The sampler runs", true, "no step yet, the plugin has just started");
		}
		return result(5, "The sampler runs", true, "last step " + Fmt.thousands((int) f.lastStepAgoMs) + " ms ago"
			+ (f.stepCostUs >= 0 ? ", work " + Fmt.thousands((int) Math.min(Integer.MAX_VALUE, f.stepCostUs))
				+ " us" : ""));
	}

	private static CheckResult settings(CheckFacts f)
	{
		final List<String> missing = new ArrayList<>(2);
		if (f.renderer == Renderer.UNKNOWN)
		{
			missing.add("renderer");
		}
		if (!f.capKnown)
		{
			missing.add("cap");
		}
		if (!missing.isEmpty())
		{
			return result(6, "Settings read", false, "settings not read: " + String.join(", ", missing));
		}
		return result(6, "Settings read", true, "renderer " + f.renderer.label() + ", cap known");
	}

	private static CheckResult badge(CheckFacts f)
	{
		if (!f.badgeShow)
		{
			return result(7, "The badge is up", true, "hidden by setting");
		}
		if (!f.badgeRegistered)
		{
			return result(7, "The badge is up", false, "the badge is not registered with the client");
		}
		return result(7, "The badge is up", true, "registered, Show is on");
	}

	private static CheckResult client(CheckFacts f)
	{
		if (f.os.isEmpty())
		{
			return result(8, "Client fits", false, "the operating system is not named");
		}
		final int[] version = numbers(f.clientVersion);
		if (version != null && (version[0] < MIN_CLIENT_MAJOR
			|| version[0] == MIN_CLIENT_MAJOR && version[1] < MIN_CLIENT_MINOR))
		{
			return result(8, "Client fits", false, "client " + f.clientVersion + " is older than " + MIN_CLIENT);
		}
		final int java = javaMajor(f.javaVersion);
		if (java >= 0 && java < MIN_JAVA)
		{
			return result(8, "Client fits", false, "Java " + f.javaVersion + " is older than " + MIN_JAVA);
		}
		return result(8, "Client fits", true, "client " + (f.clientVersion.isEmpty() ? "unknown" : f.clientVersion)
			+ ", Java " + (f.javaVersion.isEmpty() ? "unknown" : f.javaVersion) + ", " + f.os);
	}

	private static CheckResult clock(CheckFacts f)
	{
		if (f.clockJumpedBackS > 0)
		{
			return result(9, "Clock sane", false, "the clock jumped back " + Fmt.thousands(f.clockJumpedBackS)
				+ " s" + (f.clockJumpAtWallMs > 0 ? " at " + Fmt.clock(f.clockJumpAtWallMs, f.zone) : ""));
		}
		return result(9, "Clock sane", true, "never went back, zone " + f.zone.getId());
	}

	private static CheckResult measuring(CheckFacts f)
	{
		if (!f.loggedIn)
		{
			return result(10, "Not stuck measuring", true, NOT_LOGGED_IN);
		}
		if (f.loggedInS > MEASURING_S && f.cardState == Answer.MEASURING)
		{
			return result(10, "Not stuck measuring", false, "measuring for " + Fmt.thousands((int) Math.min(
				Integer.MAX_VALUE, f.loggedInS)) + " s: no readings arrive");
		}
		return result(10, "Not stuck measuring", true, "card: " + f.cardState.oneLine);
	}

	// ------------------------------------------------------------------ helpers

	private static CheckResult result(int n, String name, boolean pass, String detail)
	{
		return new CheckResult("C" + n, name, pass, detail);
	}

	/** Whole seconds of a span in ms, rounded to the nearest, at least 1. */
	private static int seconds(long ms)
	{
		return (int) Math.max(1, Math.min(Integer.MAX_VALUE, (ms + MS_PER_SECOND / 2) / MS_PER_SECOND));
	}

	/** Microseconds as milliseconds with one decimal, rounded down: 2,350 is "2.3". */
	private static String millis(long us)
	{
		final long tenths = Math.max(0, us) * 10 / US_PER_MS;
		return (tenths / 10) + "." + (tenths % 10);
	}

	/** {@code text} with its first letter in upper case. */
	private static String raise(String text)
	{
		return text.isEmpty() ? text : text.substring(0, 1).toUpperCase(Locale.ROOT) + text.substring(1);
	}

	/** The first two numbers of a version such as {@code 1.13.0} or {@code 1.13.1-SNAPSHOT}; null when it has none. */
	private static int[] numbers(String version)
	{
		final Matcher m = NUMBERS.matcher(version);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return new int[] {Integer.parseInt(m.group(1)), m.group(2) == null ? 0 : Integer.parseInt(m.group(2))};
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** The major number of a Java version: {@code 17.0.18} is 17, {@code 1.8.0_352} is 8; -1 when it cannot be read. */
	private static int javaMajor(String version)
	{
		final int[] n = numbers(version);
		if (n == null)
		{
			return -1;
		}
		return n[0] == 1 ? n[1] : n[0];
	}
}

package com.whylag.core;

/**
 * How sure a verdict is (contract 3.2, 6.3). Strongest first: the ORDINAL grows as confidence falls, which is what
 * {@link #lower()} and {@link #weaker(Confidence, Confidence)} rely on.
 */
public enum Confidence
{
	SURE("Sure"),
	LIKELY("Likely"),
	HINT("Hint"),
	CANT_TELL("Can't tell");

	private final String word;

	Confidence(String word)
	{
		this.word = word;
	}

	/** The word the card and the report print: "Sure", "Likely", "Hint", "Can't tell". */
	public String word()
	{
		return word;
	}

	/** One step weaker; {@link #CANT_TELL} stays {@link #CANT_TELL}. */
	public Confidence lower()
	{
		switch (this)
		{
			case SURE:
				return LIKELY;
			case LIKELY:
				return HINT;
			default:
				return CANT_TELL;
		}
	}

	/** The weaker of the two, for a ceiling laid over a score; two equal ones answer {@code a}. */
	public static Confidence weaker(Confidence a, Confidence b)
	{
		return b.ordinal() > a.ordinal() ? b : a;
	}
}

package com.whylag.core;

/**
 * Finds lag events in the rings (contract 3.9, 6.1, 6.2). Called on the sampler thread only.
 *
 * <p>It alone adds to and resets the three usuals of the {@link Session}; it never touches {@link EventLog} (the
 * engine writes that, from the listener).
 *
 * <p><b>The id.</b> It numbers the events it opens 0, 1, 2 ... in the order they open, from one counter of its own
 * that nothing restarts (not a hop, a world change, a login or a lost connection); a new detector starts again at
 * 0. An event keeps its id from
 * {@link DetectorListener#opened} through every {@link #open()} to {@link DetectorListener#closed}, and no id is
 * reused (contract 3.4, "The id").
 */
public interface Detector
{
	/** Reads every second up to and including {@code throughSec}, telling {@code out} of each event opened or closed. */
	void advance(Session s, long throughSec, SettingsView settings, DetectorListener out);

	/** The open event, or null. It keeps the id that {@link DetectorListener#opened} was handed. */
	LagEvent open();

	/** True when no trigger fired in {@code sec} (asked after {@link #advance} has read it). */
	boolean quiet(long sec);
}

package com.whylag.core;

/**
 * What the detector tells the engine (contract 3.4), on the sampler thread. The engine answers {@code opened} with
 * {@link EventLog#add} and {@code closed} with {@link EventLog#replace} once the verdict is attached.
 */
public interface DetectorListener
{
	void opened(LagEvent e);

	void closed(LagEvent e);
}

package com.whylag.core;

import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * A short memory of what the plugin has been doing, for one purpose: the report's last three sections are made from
 * it, and a player pastes the report into a bug post. It exists because the plugin's log lines are few and a
 * player's client log is rarely to hand; a report that says "ping: could not read it" at 21:47:02 saves a round of
 * questions. Pure: the clock comes in as a parameter ({@code wallMs}) and the zone at construction, so every stamp
 * in a test is a known one.
 *
 * <p><b>What it holds.</b> A ring of the last {@value #NOTES} notes, each stamped {@code hh:mm:ss} in the zone and
 * printed {@code hh:mm:ss  text}; the warning keys raised this session with how often ({@link #warnOnce}), which is
 * also what keeps the client log to one WARN line per kind of trouble; and the last {@value #ERRORS} DISTINCT errors
 * (the class and the message), each with its first {@value #FRAMES} stack frames and how many times it came.
 * <b>What it never holds:</b> a player name, an account hash, a host, an address or a file path. The first four are a
 * rule for the CALLERS, who hand it states, counts and times only - the plugin never reads a name or a hash, so there
 * is none to hand over; the class cannot tell a name from any other word. The path rule is kept here as well: every
 * text that comes in passes {@link #scrub}, because an exception message from the disk is very often the path
 * itself, and a path holds the Windows user name.
 *
 * <p>Thread-safe: the sampler thread writes and the report reads. Every method is one short critical section, so
 * none of them can hold the other up.
 *
 * <p>
 * Choice: a line break in a text becomes a space, so a note, a warning and an error message stay one line each.
 * <br>
 * Choice: a repeat of an error only bumps its count; it keeps its place and its first time, so the ring drops the
 * error that came FIRST, not the one that came last.
 * <br>
 * Choice: two errors are the same when their class and their SCRUBBED message are equal, so one failing path that
 * differs in its folder only is one error counted, not ten.
 * <br>
 * Choice: {@link #text()} prints the errors oldest first, as it prints the notes, so the report reads as one timeline.
 * <br>
 * Choice: {@link #warnOnce} keeps the text of the FIRST time a key was raised and prints it after the count.
 * <br>
 * Choice: a section with nothing in it prints "(none)", never a bare heading.
 */
public final class Diagnostics
{
	/** The most notes kept; the oldest goes when a new one arrives. */
	public static final int NOTES = 200;
	/** The most distinct errors kept; the one that came first goes when an eleventh arrives. */
	public static final int ERRORS = 10;
	/** The most stack frames kept of an error. */
	public static final int FRAMES = 3;
	/** What a section with nothing in it prints. */
	public static final String NONE = "(none)";
	/** What a scrubbed path prints. */
	public static final String PATH = "<path>";

	/** A Windows path: a drive, then directories (which may hold spaces) and a last component (which may not). */
	private static final Pattern WINDOWS_PATH = Pattern.compile(
		"\\b[A-Za-z]:[\\\\/](?:[^\\\\/:\"'<>|\\r\\n]+[\\\\/])*[^\\s\\\\/:\"'<>|,;)\\]]*");
	/** A network path: two backslashes and whatever follows up to a space. */
	private static final Pattern UNC_PATH = Pattern.compile("\\\\\\\\[^\\s\"'<>|,;)\\]]+");
	/** The three home roots of the systems the client runs on: everything after the root is the path. */
	private static final Pattern HOME_PATH = Pattern.compile("(?i)(?<![\\w:.~-])/(?:home|Users|tmp)/[^\\r\\n]*");
	/** What is left of a path that lost its drive: {@code Users\}, and any run of characters after it. */
	private static final Pattern USERS_REST = Pattern.compile("(?i)Users[\\\\/][^\\r\\n]*");
	/** A Unix path of at least two components, not the tail of a URL or of a word such as "and/or". */
	private static final Pattern UNIX_PATH = Pattern.compile(
		"(?<![\\w/:.~-])/(?:[^/\\s\"'<>|:]+/)+[^\\s/\"'<>|:,;)\\]]*");

	/** One warning key: how often it was raised and the text of the first time. */
	private static final class Warning
	{
		final String text;
		int count = 1;

		Warning(String text)
		{
			this.text = text;
		}
	}

	/** One kept error: when it first came, its class and message, its first frames, and how often it came. */
	private static final class Err
	{
		final String time;
		final String type;
		final String message;
		final List<String> frames;
		int count = 1;

		Err(String time, String type, String message, List<String> frames)
		{
			this.time = time;
			this.type = type;
			this.message = message;
			this.frames = frames;
		}
	}

	private final ZoneId zone;
	private final Object lock = new Object();
	private final Deque<String> notes = new ArrayDeque<>();
	/** Warning key to its record, in the order first raised. */
	private final Map<String, Warning> warnings = new LinkedHashMap<>();
	/** Distinct errors by class and message, first seen first. */
	private final Map<String, Err> errors = new LinkedHashMap<>();

	/** @param zone the zone the notes' times are written in */
	public Diagnostics(ZoneId zone)
	{
		this.zone = zone;
	}

	/**
	 * Adds one note, stamped {@code hh:mm:ss} in the zone. The oldest is dropped once there are {@value #NOTES}.
	 *
	 * @param wallMs the wall clock, in epoch milliseconds
	 */
	public void note(long wallMs, String text)
	{
		final String line = Fmt.clockSeconds(wallMs, zone) + "  " + clean(text);
		synchronized (lock)
		{
			notes.addLast(line);
			while (notes.size() > NOTES)
			{
				notes.removeFirst();
			}
		}
	}

	/**
	 * Whether {@code key} is being raised for the FIRST time this session: true once, false ever after. Every call
	 * counts, so the report shows how often each kind of trouble came back. The plugin logs at WARN only when this
	 * answers true.
	 *
	 * @param key  a short kind of trouble, such as {@code step: IllegalStateException} - no names, no hashes
	 * @param text what it was, kept from the first time
	 */
	public boolean warnOnce(String key, String text)
	{
		final String k = clean(key);
		synchronized (lock)
		{
			final Warning before = warnings.get(k);
			if (before != null)
			{
				before.count++;
				return false;
			}
			warnings.put(k, new Warning(clean(text)));
			return true;
		}
	}

	/** How often {@code key} was raised this session; 0 when it never was. */
	public int warningCount(String key)
	{
		synchronized (lock)
		{
			final Warning w = warnings.get(clean(key));
			return w == null ? 0 : w.count;
		}
	}

	/**
	 * Keeps {@code t}: its class, its message and its first {@value #FRAMES} stack frames. The last {@value #ERRORS}
	 * DISTINCT errors are kept, distinct by class and message; the same error again only counts up.
	 *
	 * @param wallMs the wall clock, in epoch milliseconds
	 */
	public void error(long wallMs, Throwable t)
	{
		final String message = clean(t.getMessage());
		final String type = kind(t);
		final String key = type + ": " + message;
		final StackTraceElement[] trace = t.getStackTrace();
		final List<String> frames = new ArrayList<>();
		for (int i = 0; i < trace.length && i < FRAMES; i++)
		{
			frames.add(clean(trace[i].toString()));
		}
		final String time = Fmt.clockSeconds(wallMs, zone);
		synchronized (lock)
		{
			final Err before = errors.get(key);
			if (before != null)
			{
				before.count++;
				return;
			}
			errors.put(key, new Err(time, type, message, frames));
			while (errors.size() > ERRORS)
			{
				final Iterator<String> oldest = errors.keySet().iterator();
				oldest.next();
				oldest.remove();
			}
		}
	}

	/**
	 * The kind of a throwable: its class name, read as the text of {@code toString()} up to the first ':' (a message
	 * may hold more colons, a class name never does). The plugin keys its one warning per kind by it.
	 */
	public static String kind(Throwable t)
	{
		final String text = String.valueOf(t);
		final int colon = text.indexOf(':');
		return colon < 0 ? text : text.substring(0, colon);
	}

	/**
	 * The three sections, each a heading and its lines, a blank line between them, every line ended with a new
	 * line: {@code Notes} (oldest first, {@code hh:mm:ss  text}), {@code Warnings} ({@code key  3 times  text}) and
	 * {@code Errors} ({@code hh:mm:ss  class: message}, its count when above 1, and its frames, one under the other).
	 * A section with nothing in it says {@value #NONE}.
	 */
	public String text()
	{
		final StringBuilder out = new StringBuilder(2048);
		synchronized (lock)
		{
			out.append("Notes\n");
			if (notes.isEmpty())
			{
				out.append(NONE).append('\n');
			}
			for (String line : notes)
			{
				out.append(line).append('\n');
			}
			out.append("\nWarnings\n");
			if (warnings.isEmpty())
			{
				out.append(NONE).append('\n');
			}
			for (Map.Entry<String, Warning> e : warnings.entrySet())
			{
				final Warning w = e.getValue();
				out.append(e.getKey()).append("  ").append(w.count).append(w.count == 1 ? " time" : " times");
				if (!w.text.isEmpty())
				{
					out.append("  ").append(w.text);
				}
				out.append('\n');
			}
			out.append("\nErrors\n");
			if (errors.isEmpty())
			{
				out.append(NONE).append('\n');
			}
			for (Err e : errors.values())
			{
				out.append(e.time).append("  ").append(e.type);
				if (!e.message.isEmpty())
				{
					out.append(": ").append(e.message);
				}
				if (e.count > 1)
				{
					out.append("  (").append(e.count).append(" times)");
				}
				out.append('\n');
				for (String frame : e.frames)
				{
					out.append("    at ").append(frame).append('\n');
				}
			}
		}
		return out.toString();
	}

	/** The text of a diagnostics log with nothing in it: the three headings and {@value #NONE} under each. */
	public static String empty()
	{
		return new Diagnostics(ZoneOffset.UTC).text();
	}

	/**
	 * {@code text} with every file path in it replaced by {@code <path>}: a Windows path ({@code X:\...}, the folders
	 * of it may hold spaces), a network path, anything from {@code /home/}, {@code /Users/} or {@code /tmp/} to the
	 * end of the line, anything from {@code Users\} to the end of the line, and a Unix path of two components or
	 * more. A URL and a word such as "and/or" are left alone. An exception from the disk names the file it failed on,
	 * and a file lives under the player's home folder, which is named after them.
	 */
	public static String scrub(String text)
	{
		if (text == null || text.isEmpty())
		{
			return "";
		}
		String out = WINDOWS_PATH.matcher(text).replaceAll(PATH);
		out = UNC_PATH.matcher(out).replaceAll(PATH);
		out = HOME_PATH.matcher(out).replaceAll(PATH);
		out = USERS_REST.matcher(out).replaceAll(PATH);
		return UNIX_PATH.matcher(out).replaceAll(PATH);
	}

	/** One line with no path in it: a line break becomes a space and {@link #scrub} runs. */
	private static String clean(String text)
	{
		return text == null ? "" : scrub(text.replace("\r\n", " ").replace('\n', ' ').replace('\r', ' '));
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * The session's events, oldest first, at most {@code capacity} of them (contract 3.4). Every method is
 * synchronized.
 *
 * <p><b>One writer.</b> The engine alone writes it: {@link #add} when the detector opens an event, {@link #replace}
 * when it closes (with its verdict attached). An open event is held with {@code open == true}, and every reader of
 * CLOSED events - {@link #between}, {@link #last}, {@link #sessionTotal}, {@link #sessionCount} - skips it.
 *
 * <p><b>The session counts outlive the cap.</b> When the log is full the oldest event is dropped, but it stays
 * counted: the counts are of every closed event this session, by its {@link LagEvent#group()}.
 */
public final class EventLog
{
	private final LagEvent[] held;
	private final int[] counts = new int[Group.values().length];
	/** Index in {@link #held} of the oldest held event. */
	private int first;
	private int size;
	private int total;

	/**
	 * @param capacity events held, at least 1
	 */
	public EventLog(int capacity)
	{
		if (capacity < 1)
		{
			throw new IllegalArgumentException("an event log needs room for one event, got " + capacity);
		}
		held = new LagEvent[capacity];
	}

	/** Appends {@code e}, dropping the oldest when full (its count is kept). A closed {@code e} is counted. */
	public synchronized void add(LagEvent e)
	{
		Objects.requireNonNull(e, "event");
		if (size == held.length)
		{
			held[first] = null;
			first = (first + 1) % held.length;
			size--;
		}
		held[(first + size) % held.length] = e;
		size++;
		count(e, 1);
	}

	/**
	 * Swaps the held event with {@code e}'s id for {@code e}, and re-counts: the old one's group loses it if it was
	 * closed, {@code e}'s group gains it if {@code e} is closed.
	 *
	 * @return false when no held event has that id (nothing changes)
	 */
	public synchronized boolean replace(LagEvent e)
	{
		Objects.requireNonNull(e, "event");
		for (int k = size - 1; k >= 0; k--)
		{
			final int i = (first + k) % held.length;
			if (held[i].id == e.id)
			{
				count(held[i], -1);
				held[i] = e;
				count(e, 1);
				return true;
			}
		}
		return false;
	}

	/** Events held, open ones included. */
	public synchronized int size()
	{
		return size;
	}

	/** The {@code i}-th event held; 0 is the oldest. */
	public synchronized LagEvent get(int i)
	{
		if (i < 0 || i >= size)
		{
			throw new IndexOutOfBoundsException("event " + i + " of " + size);
		}
		return held[(first + i) % held.length];
	}

	/** The held event with this id, or null. */
	public synchronized LagEvent byId(long id)
	{
		for (int k = size - 1; k >= 0; k--)
		{
			final LagEvent e = held[(first + k) % held.length];
			if (e.id == id)
			{
				return e;
			}
		}
		return null;
	}

	/** Every held event, open ones included, oldest first; unmodifiable. */
	public synchronized List<LagEvent> copy()
	{
		final List<LagEvent> out = new ArrayList<>(size);
		for (int k = 0; k < size; k++)
		{
			out.add(held[(first + k) % held.length]);
		}
		return Collections.unmodifiableList(out);
	}

	/** The CLOSED events overlapping {@code fromSec .. toSec} (both included), oldest first; unmodifiable. */
	public synchronized List<LagEvent> between(long fromSec, long toSec)
	{
		final List<LagEvent> out = new ArrayList<>();
		for (int k = 0; k < size; k++)
		{
			final LagEvent e = held[(first + k) % held.length];
			if (!e.open && e.startSec <= toSec && e.endSec >= fromSec)
			{
				out.add(e);
			}
		}
		return Collections.unmodifiableList(out);
	}

	/** Closed events this session, dropped ones included. */
	public synchronized int sessionTotal()
	{
		return total;
	}

	/** Closed events this session counted under {@code g}, dropped ones included. */
	public synchronized int sessionCount(Group g)
	{
		return counts[g.ordinal()];
	}

	/** The newest CLOSED event, or null. */
	public synchronized LagEvent last()
	{
		for (int k = size - 1; k >= 0; k--)
		{
			final LagEvent e = held[(first + k) % held.length];
			if (!e.open)
			{
				return e;
			}
		}
		return null;
	}

	private void count(LagEvent e, int step)
	{
		if (!e.open)
		{
			total += step;
			counts[e.group().ordinal()] += step;
		}
	}
}

package com.whylag.core;

/**
 * ONE event as the three tiles and the three lane values (contract 3.8, 5.2, 5.3): what the panel draws in place
 * of "now" while a list row is selected. Pure and static; it reads the event's own numbers only.
 *
 * <table>
 * <caption>The tiles of a selected event</caption>
 * <tr><th>Tile</th><th>Value</th><th>Sub</th><th>Level</th></tr>
 * <tr><td>Frame rate</td><td>"50 fps" = fps</td><td>"worst 34 ms" = worstFrameMs</td>
 * <td>{@code Levels.fps(fps, 0, false)}: no cap is known for a past event</td></tr>
 * <tr><td>Server ticks</td><td>"952 ms" = meanTickGapMs</td><td>"worst 1,240" = worstTickGapMs</td>
 * <td>{@code Levels.tick(worstCorrectedTickMs)}</td></tr>
 * <tr><td>Ping</td><td>"41 ms" = rttMs</td><td>"was 41 ms" = rttBeforeMs; -1: ""</td>
 * <td>{@code Levels.ping(rttMs)}</td></tr>
 * </table>
 *
 * <p>A value field at -1 gives the value "-", the level NO_DATA and the sub "" (its {@code noData} is
 * {@link NoData#NONE}: an event has no reason to print). A sub field at -1 gives "".
 *
 * <p><b>The lanes.</b> The lane values and levels are the tiles' values and levels, so the tiles and the lanes
 * always show the same numbers.
 */
public final class EventView
{
	private static final int LANES = Lane.values().length;

	private EventView()
	{
	}

	/** Three tiles ({@link Lane#TILES}), in {@link Lane} order. */
	public static Tile[] tiles(LagEvent e)
	{
		return new Tile[] {frameRate(e), ticks(e), ping(e)};
	}

	/** Three values, in {@link Lane} order: "50 fps", "952 ms", "41 ms"; "-" = no data. */
	public static String[] laneValues(LagEvent e)
	{
		final Tile[] tiles = tiles(e);
		final String[] out = new String[LANES];
		for (int i = 0; i < tiles.length; i++)
		{
			out[i] = tiles[i].value;
		}
		return out;
	}

	/** Three levels, in {@link Lane} order: the tiles' levels. */
	public static Level[] laneLevels(LagEvent e)
	{
		final Tile[] tiles = tiles(e);
		final Level[] out = new Level[LANES];
		for (int i = 0; i < tiles.length; i++)
		{
			out[i] = tiles[i].level;
		}
		return out;
	}

	private static Tile frameRate(LagEvent e)
	{
		if (e.fps < 0)
		{
			return dash(Lane.FRAME_RATE);
		}
		final String sub = e.worstFrameMs < 0 ? "" : "worst " + Fmt.thousands(e.worstFrameMs) + " ms";
		return new Tile(Lane.FRAME_RATE, Levels.fps(e.fps, 0, false), Fmt.thousands(e.fps) + " fps", sub,
			NoData.NONE);
	}

	private static Tile ticks(LagEvent e)
	{
		if (e.meanTickGapMs < 0)
		{
			return dash(Lane.TICKS);
		}
		final String sub = e.worstTickGapMs < 0 ? "" : "worst " + Fmt.thousands(e.worstTickGapMs);
		return new Tile(Lane.TICKS, Levels.tick(e.worstCorrectedTickMs), Fmt.thousands(e.meanTickGapMs) + " ms",
			sub, NoData.NONE);
	}

	private static Tile ping(LagEvent e)
	{
		if (e.rttMs < 0)
		{
			return dash(Lane.PING);
		}
		final String sub = e.rttBeforeMs < 0 ? "" : "was " + Fmt.thousands(e.rttBeforeMs) + " ms";
		return new Tile(Lane.PING, Levels.ping(e.rttMs), Fmt.thousands(e.rttMs) + " ms", sub, NoData.NONE);
	}

	private static Tile dash(Lane lane)
	{
		return new Tile(lane, Level.NO_DATA, "-", "", NoData.NONE);
	}
}

package com.whylag.core;

/**
 * What the rules of contract 6.3 judge: the signals of ONE event's span, or of the window (the last
 * {@link Thresholds#WINDOW_S} seconds) for a condition. Built by {@link EvidenceBuilder} from the rings; read by
 * {@link Rules} and {@link Words}. A plain carrier: every field is public and set once by its builder.
 *
 * <p><b>No data.</b> An int of -1 means "no data". The two spike signals have three answers, {@link #YES},
 * {@link #NO} and {@link #NO_DATA}: they have no data when there is no fresh RTT to judge or no usual, whatever the
 * event's trigger bit says (contract 6.3). A need on a signal with no data fails; an exclude or a support on one is
 * skipped and lowers the rule's ceiling one step ({@link Rule}).
 *
 * <p>Choice: a fresh {@code Evidence} holds "no data" in every field (ints -1, counts 0, booleans false, the two
 * spikes {@link #NO_DATA}), so a builder that finds no readable second leaves a record on which no rule scores.
 * <p>Choice: {@code sent} and {@code resent} are held at {@link Integer#MAX_VALUE} when their sum is larger.
 * <p>Choice: beside the fields that contract 6.3 lists, the evidence carries four that only the words and one
 * condition need: {@link #event} (which kind it is), {@link #first} (X's words), {@link #capLabel} (F1's words) and
 * {@link #eventInWindow} (W1c's need "no event open or closed in the window").
 */
public final class Evidence
{
	/** The three answers of a signal that may have no data. */
	public static final int NO_DATA = -1, NO = 0, YES = 1;

	/** True for an event's evidence, false for a condition's (the window). */
	public boolean event;
	/** The event's first trigger (X's words); null for a condition. */
	public Trigger first;

	/** A second of the span (or an unmasked second of the window) carries the DISCONNECT flag. */
	public boolean disconnect;
	/** D1: the FIRST second of the span with the DISCONNECT flag; -1 = none. */
	public long disconnectSec = -1;
	/** D1: the second of the newest tick before the end of {@link #disconnectSec}, masked or not; -1 = none. */
	public long lastTickSec = -1;

	/** The worst frame's length; -1 = no second to read. */
	public int frameGapMs = -1;
	/** {@code settings.frameGapLimitMs(f)}, f the focus of the second judged (contract 3.7); -1 = no second. */
	public int frameLimitMs = -1;
	/** Events: the summed loading time of every LOADING run with a second in startSec - 1 .. endSec. */
	public int loadMs;
	/** Events: the LOADING runs of the last {@link Thresholds#LOADS_LOOK_S} seconds, back from the event's end. */
	public int loads;
	/** The cap in force in the second judged; 0 = none known. */
	public int capFps;
	/** {@code 1000 / capFps}; 0 = no cap. */
	public int capIntervalMs;
	/** The cap was set by the player (FPS Control, a renderer's target or V-Sync). */
	public boolean capSelfSet;
	/** The cap paces frames by waiting. */
	public boolean capWaits;
	/** Who set the cap, as F1's words print it; "" = none. */
	public String capLabel = "";

	/** The median frames a second; -1 = no second. */
	public int fps = -1;
	/** Conditions: slow seconds in a row up to the newest second. */
	public int lowFpsS;
	/** Conditions: the median rate of the slow run; -1 when {@link #lowFpsS} is 0. */
	public int lowFps = -1;
	/** Conditions: capped seconds in a row up to the newest second. */
	public int capHeldS;
	/** {@code ceil(1000 / fps)}; 1000 when fps is 0; -1 when fps is -1. */
	public int frameMedianMs = -1;
	/** {@code frameGapMs < FRAME_CLEAN_MS}; false with no frame data. */
	public boolean framesClean;

	/** A second of the span (or window) has a fresh RTT. */
	public boolean rttKnown;
	/** Median, lowest and highest fresh RTT; -1 = none. */
	public int rtt = -1, rttMin = -1, rttMax = -1;
	/** Events: the usual as it stood when the event opened. Conditions: this world's usual now. -1 = none. */
	public int rttUsual = -1;
	/** {@link #YES}, {@link #NO} or {@link #NO_DATA}. */
	public int rttSpike = NO_DATA;

	/** Events: sent and re-sent units over the span and {@link Thresholds#RESENT_LOOK_S} either side. */
	public int sent, resent;
	/** Events: the RESENT trigger fired. */
	public boolean resentCounts;
	/** Events: the NO_TICK trigger fired - a real stop of {@link Thresholds#NO_TICK_MS} or more (N6 needs it). */
	public boolean noTick;
	/** Events: {@code resent x 1000 / sent}, at most 1000, 0 when nothing was sent. */
	public int resentPm;

	/** Events: the span's ticks, and those off by TICK_OFF_MS or more, late and early. */
	public int ticks, tickLate, tickEarly;
	/** Events: the median of gap - frame time over the span's ticks; -1 = none. */
	public int tickMedianMs = -1;
	/** Events: the longest gap of the span's ticks; -1 = none. */
	public int tickWorstMs = -1;
	/** Events: the longest stretch with no tick inside the span; -1 = no tick at all before its end. */
	public int noTickMs = -1;
	/** Events, X's words: how far off the ticks ran; -1 = nothing to say. */
	public int tickOffMs = -1;
	/** Conditions: the median RAW gap of the window's ticks; -1 = none. */
	public int tickWindowMedianMs = -1;
	/** Conditions: the number of the window's ticks. */
	public int ticksInWindow;
	/** Conditions: an event, open or closed, overlaps the window; an open one reaches the newest second. */
	public boolean eventInWindow;

	/** Events: the event's length in seconds; 0 for a condition. */
	public int durationS;
	/** Events: the world of the first second. Conditions: the newest second's. 0 = none. */
	public int world;

	/** D1: median and highest fresh RTT of the D1_LOOK_S seconds that end at {@link #lastTickSec}; -1 = none. */
	public int beforeRtt = -1, beforeRttMax = -1;
	/** D1: the spike line on {@link #beforeRttMax} against {@link #rttUsual}; three answers. */
	public int beforeRttSpike = NO_DATA;
	/** D1: the re-sent share of those seconds, per mille; -1 = no second to read. */
	public int beforeResentPm = -1;
}

package com.whylag.core;

import java.util.Arrays;

/**
 * Reads the rings into an {@link Evidence} (contract 6.3): over an event's span, {@code startSec .. endSec}, or
 * over the window, the last {@link Thresholds#WINDOW_S} seconds up to the newest complete second, for a condition.
 * Pure: it writes nothing, and the same rings give the same evidence. Sampler thread.
 *
 * <p>From the {@link LagEvent} it judges, {@link #forEvent} reads the span, the trigger bits ({@code RESENT} is
 * {@code resentCounts}, {@code RTT_SPIKE} the spike), {@code first}, {@code rttBeforeMs} (the usual) and, only when
 * the span's first second can no longer be read, {@code world}. It never reads {@code open}: an open event is judged
 * as if it closed now. {@link #forCondition} reads, of each event in the log, its span and its {@code open} flag, for
 * W1c's need "no event open or closed in the window": the log keeps an OPEN event as {@code opened} handed it in
 * until {@code closed} replaces it (contract 3.4, 3.6), so its logged {@code endSec} is its first trigger second and
 * does not move while it stays open; an open event is taken as reaching the newest second.
 *
 * <p>An EVENT reads every second of its span, masked or not. A CONDITION leaves out the seconds that
 * {@link Flags#masked(int)} names for EVERY field, its {@code disconnect} included (contract 6.3, "Which seconds a
 * condition reads"), and its ticks are those without {@code LOGIN_MASK}. Every read of a ring is re-checked with
 * {@code valid}; a second or a tick that is no longer readable counts for nothing.
 *
 * <p>Choice: every median is taken by sorting a copy, the LOWER middle of an even count, as {@code Usual.median()}.
 * <p>Choice: a {@code frames} column of -1 counts as 0 frames; a tick's {@code frameMs} of -1 as 0 ms.
 * <p>Choice: {@code tickMedianMs} (gap less frame time) is held at 0 or more, and {@code tickOffMs}, when either of
 * its two sources exists, is held at 0 or more.
 * <p>Choice: with no readable second in the span or the window, every field keeps its "no data" start value
 * (the cap fields included), so no rule scores.
 * <p>Choice: {@code beforeResentPm} is -1 when there is no last tick or none of the look seconds is readable.
 */
public final class EvidenceBuilder
{
	private static final int MS_PER_SECOND = 1000;
	private static final int PER_MILLE = 1000;
	private static final int PERCENT = 100;

	private EvidenceBuilder()
	{
	}

	/** The evidence of one event, open or closed, over its span. */
	public static Evidence forEvent(Session s, LagEvent e, SettingsView settings)
	{
		final Evidence v = new Evidence();
		v.event = true;
		v.first = e.first;
		v.durationS = e.lengthS();
		v.rttUsual = e.rttBeforeMs < 0 ? -1 : e.rttBeforeMs;
		v.resentCounts = e.has(Trigger.RESENT);
		v.noTick = e.has(Trigger.NO_TICK);
		v.world = worldOf(s.seconds, e.startSec, e.world);

		seconds(v, s, settings, e.startSec, e.endSec, false);
		v.rttSpike = !v.rttKnown || v.rttUsual < 0 ? Evidence.NO_DATA
			: e.has(Trigger.RTT_SPIKE) ? Evidence.YES : Evidence.NO;
		ticks(v, s.ticks, s.msOfSec(e.startSec), s.msOfSec(e.endSec + 1), false);
		loads(v, s.seconds, e.startSec, e.endSec);
		resends(v, s.seconds, e.startSec - Thresholds.RESENT_LOOK_S, e.endSec + Thresholds.RESENT_LOOK_S);
		beforeTheDisconnect(v, s);
		return v;
	}

	/** The evidence of the window that ends with the newest complete second, {@code s.lastSec(nowSec)}. */
	public static Evidence forCondition(Session s, long nowSec, SettingsView settings)
	{
		final Evidence v = new Evidence();
		final long last = s.lastSec(nowSec);
		if (last < 0)
		{
			return v;
		}
		final long first = Math.max(last - Thresholds.WINDOW_S + 1, s.seconds.tail());
		v.world = worldOf(s.seconds, last, 0);
		v.rttUsual = s.rttUsual.median();

		seconds(v, s, settings, first, last, true);
		v.rttSpike = !v.rttKnown || v.rttUsual < 0 ? Evidence.NO_DATA : spikeLine(v.rttMax, v.rttUsual);
		ticks(v, s.ticks, s.msOfSec(last - Thresholds.WINDOW_S + 1), s.msOfSec(last + 1), true);
		runs(v, s.seconds, settings, first, last);
		v.eventInWindow = eventIn(s.events, first, last);
		return v;
	}

	/** The spike line of contract 6.2 on one RTT against a usual, both known. */
	static int spikeLine(int rttMs, int usualMs)
	{
		return rttMs >= (long) usualMs * Thresholds.RTT_SPIKE_PCT / PERCENT
			&& rttMs >= usualMs + Thresholds.RTT_SPIKE_ADD_MS ? Evidence.YES : Evidence.NO;
	}

	/** The median of the first {@code n} values: of an even count the LOWER middle one; -1 when n is 0. */
	static int median(int[] values, int n)
	{
		if (n <= 0)
		{
			return -1;
		}
		final int[] sorted = Arrays.copyOf(values, n);
		Arrays.sort(sorted);
		return sorted[(n - 1) / 2];
	}

	// ------------------------------------------------------------------ the seconds

	private static void seconds(Evidence v, Session s, SettingsView settings, long from, long to,
		boolean condition)
	{
		final SecondRing r = s.seconds;
		final long lo = Math.max(from, r.tail());
		final long hi = Math.min(to, r.head());
		final int room = hi >= lo ? (int) (hi - lo + 1) : 0;
		final int[] rates = new int[room];
		final int[] rtts = new int[room];
		int nRates = 0;
		int nRtts = 0;
		int worstMs = Integer.MIN_VALUE;
		boolean worstFocused = false;
		for (long sec = lo; sec <= hi; sec++)
		{
			final int flags = r.flags(sec);
			final int frames = r.frames(sec);
			final int worst = r.worstFrameMs(sec);
			final int rtt = r.rttMs(sec);
			final int age = r.rttAgeS(sec);
			if (!r.valid(sec))
			{
				continue;
			}
			// A condition leaves a masked second out of every field, its disconnect included (6.3).
			if (condition && Flags.masked(flags))
			{
				continue;
			}
			if (Flags.has(flags, Flags.DISCONNECT))
			{
				v.disconnect = true;
				if (v.disconnectSec < 0)
				{
					v.disconnectSec = sec;
				}
			}
			rates[nRates++] = Math.max(0, frames);
			// Strictly larger: of several seconds with the same worst frame, the EARLIEST stays.
			if (worst > worstMs)
			{
				worstMs = worst;
				worstFocused = Flags.has(flags, Flags.FOCUSED);
			}
			if (fresh(rtt, age))
			{
				rtts[nRtts++] = rtt;
			}
		}
		if (nRates == 0)
		{
			return;
		}

		v.frameGapMs = Math.max(0, worstMs);
		v.framesClean = v.frameGapMs < Thresholds.FRAME_CLEAN_MS;
		v.fps = median(rates, nRates);
		v.frameMedianMs = v.fps == 0 ? MS_PER_SECOND : (MS_PER_SECOND + v.fps - 1) / v.fps;

		// The focus of the ONE second judged (contract 3.7): an event's worst frame's, a condition's newest.
		final boolean focused = condition ? Flags.has(r.flags(to), Flags.FOCUSED) : worstFocused;
		final CapSource source = settings.capSource(focused);
		v.frameLimitMs = settings.frameGapLimitMs(focused);
		v.capFps = settings.capFps(focused);
		v.capIntervalMs = settings.capIntervalMs(focused);
		v.capSelfSet = source.selfSet();
		v.capWaits = source.waits();
		v.capLabel = source.label();

		if (nRtts > 0)
		{
			v.rttKnown = true;
			v.rtt = median(rtts, nRtts);
			int min = Integer.MAX_VALUE;
			int max = -1;
			for (int i = 0; i < nRtts; i++)
			{
				min = Math.min(min, rtts[i]);
				max = Math.max(max, rtts[i]);
			}
			v.rttMin = min;
			v.rttMax = max;
		}
	}

	private static boolean fresh(int rttMs, int ageS)
	{
		return rttMs >= 0 && ageS >= 0 && ageS <= Thresholds.RTT_STALE_S;
	}

	private static int worldOf(SecondRing r, long sec, int otherwise)
	{
		if (!r.valid(sec))
		{
			return otherwise;
		}
		final int world = r.world(sec);
		return r.valid(sec) && world >= 0 ? world : otherwise;
	}

	// ------------------------------------------------------------------ the runs (conditions F1 and F2)

	private static void runs(Evidence v, SecondRing r, SettingsView settings, long first, long last)
	{
		if (last < first)
		{
			return;
		}
		final int[] rates = new int[(int) (last - first + 1)];
		int n = 0;
		boolean capped = false;
		for (long sec = last; sec >= first; sec--)
		{
			final int flags = r.flags(sec);
			final int frames = Math.max(0, r.frames(sec));
			if (!r.valid(sec))
			{
				break;
			}
			if (Flags.masked(flags) || Flags.has(flags, Flags.NO_FRAMES))
			{
				continue;
			}
			if (frames >= Thresholds.FPS_WARN)
			{
				break;
			}
			final boolean focused = Flags.has(flags, Flags.FOCUSED);
			final boolean isCapped = settings.capSource(focused).selfSet()
				&& Math.abs(frames - settings.capFps(focused)) <= Thresholds.CAP_MATCH_FPS;
			if (n == 0)
			{
				capped = isCapped;
			}
			else if (isCapped != capped)
			{
				break;
			}
			rates[n++] = frames;
		}
		if (n == 0)
		{
			return;
		}
		if (capped)
		{
			v.capHeldS = n;
		}
		else
		{
			v.lowFpsS = n;
			v.lowFps = median(rates, n);
		}
	}

	// ------------------------------------------------------------------ the ticks

	private static void ticks(Evidence v, TickRing t, long fromMs, long toMs, boolean window)
	{
		final long head = t.head();
		int room = 0;
		long newestBefore = 0;
		boolean any = false;
		for (long q = head; q >= 0; q--)
		{
			final long at = t.atMs(q);
			final int flags = t.flags(q);
			if (!t.valid(q))
			{
				break;
			}
			if (at >= toMs)
			{
				continue;
			}
			if (!any)
			{
				// The newest tick before the span's end, masked or not.
				any = true;
				newestBefore = at;
			}
			if (at < fromMs)
			{
				break;
			}
			if (!Flags.has(flags, Flags.LOGIN_MASK))
			{
				room++;
			}
		}

		final int[] values = new int[room];
		int n = 0;
		int late = 0;
		int early = 0;
		int worst = -1;
		int off = -1;
		for (long q = head; q >= 0 && n < room; q--)
		{
			final long at = t.atMs(q);
			final int flags = t.flags(q);
			final int gap = t.gapMs(q);
			final int frame = Math.max(0, t.frameMs(q));
			final int corrected = t.corrected(q);
			final boolean isLate = t.late(q);
			final boolean isEarly = t.early(q);
			if (!t.valid(q))
			{
				break;
			}
			if (at >= toMs)
			{
				continue;
			}
			if (at < fromMs)
			{
				break;
			}
			if (Flags.has(flags, Flags.LOGIN_MASK))
			{
				continue;
			}
			values[n++] = window ? gap : Math.max(0, gap - frame);
			worst = Math.max(worst, gap);
			off = Math.max(off, corrected);
			if (corrected >= Thresholds.TICK_OFF_MS)
			{
				if (isLate)
				{
					late++;
				}
				else if (isEarly)
				{
					early++;
				}
			}
		}

		if (window)
		{
			v.ticksInWindow = n;
			v.tickWindowMedianMs = median(values, n);
			return;
		}
		v.ticks = n;
		v.tickLate = late;
		v.tickEarly = early;
		v.tickMedianMs = median(values, n);
		v.tickWorstMs = worst;
		v.noTickMs = any ? (int) Math.min(Integer.MAX_VALUE, Math.max(worst, toMs - newestBefore)) : -1;
		if (off >= 0 || v.noTickMs >= 0)
		{
			final int missing = v.noTickMs >= 0 ? v.noTickMs - Thresholds.TICK_MS : -1;
			v.tickOffMs = Math.max(0, Math.max(off, missing));
		}
	}

	// ------------------------------------------------------------------ loads, re-sends, D1's look

	private static boolean loading(SecondRing r, long sec)
	{
		if (!r.valid(sec))
		{
			return false;
		}
		final int flags = r.flags(sec);
		return r.valid(sec) && Flags.has(flags, Flags.LOADING);
	}

	private static void loads(Evidence v, SecondRing r, long startSec, long endSec)
	{
		// Every LOADING run with a second in startSec - 1 .. endSec, each run summed WHOLE.
		long sum = 0;
		long sec = startSec - 1;
		while (sec <= endSec)
		{
			if (!loading(r, sec))
			{
				sec++;
				continue;
			}
			long runStart = sec;
			while (loading(r, runStart - 1))
			{
				runStart--;
			}
			long runEnd = sec;
			while (loading(r, runEnd + 1))
			{
				runEnd++;
			}
			for (long k = runStart; k <= runEnd; k++)
			{
				final int ms = r.loadingMs(k);
				if (r.valid(k) && ms > 0)
				{
					sum += ms;
				}
			}
			sec = runEnd + 1;
		}
		v.loadMs = (int) Math.min(Integer.MAX_VALUE, sum);

		// The runs of the last LOADS_LOOK_S seconds, counted back from the event's END.
		int runs = 0;
		boolean inRun = false;
		final long lo = Math.max(endSec - Thresholds.LOADS_LOOK_S + 1, r.tail());
		final long hi = Math.min(endSec, r.head());
		for (long k = lo; k <= hi; k++)
		{
			final boolean is = loading(r, k);
			if (is && !inRun)
			{
				runs++;
			}
			inRun = is;
		}
		v.loads = runs;
	}

	private static void resends(Evidence v, SecondRing r, long from, long to)
	{
		final long[] sums = new long[3];
		sum(r, from, to, sums);
		v.sent = (int) Math.min(Integer.MAX_VALUE, sums[0]);
		v.resent = (int) Math.min(Integer.MAX_VALUE, sums[1]);
		v.resentPm = share(sums[0], sums[1]);
	}

	/** {sent, re-sent, readable seconds} over a span of seconds. */
	private static void sum(SecondRing r, long from, long to, long[] out)
	{
		final long lo = Math.max(from, r.tail());
		final long hi = Math.min(to, r.head());
		for (long sec = lo; sec <= hi; sec++)
		{
			final int sent = r.sentUnits(sec);
			final int resent = r.resentUnits(sec);
			if (!r.valid(sec))
			{
				continue;
			}
			out[0] += Math.max(0, sent);
			out[1] += Math.max(0, resent);
			out[2]++;
		}
	}

	/** {@code resent x 1000 / sent}, rounded down, at most 1000, 0 when nothing was sent. */
	private static int share(long sent, long resent)
	{
		if (sent <= 0)
		{
			return 0;
		}
		return (int) Math.min(PER_MILLE, resent * PER_MILLE / sent);
	}

	private static void beforeTheDisconnect(Evidence v, Session s)
	{
		if (v.disconnectSec < 0)
		{
			return;
		}
		final TickRing t = s.ticks;
		final long instant = s.msOfSec(v.disconnectSec + 1);
		for (long q = t.head(); q >= 0; q--)
		{
			final long at = t.atMs(q);
			if (!t.valid(q))
			{
				break;
			}
			if (at < instant)
			{
				v.lastTickSec = Math.floorDiv(at, (long) MS_PER_SECOND);
				break;
			}
		}
		if (v.lastTickSec < 0)
		{
			v.lastTickSec = -1;
			return;
		}

		final SecondRing r = s.seconds;
		final long lo = Math.max(v.lastTickSec - Thresholds.D1_LOOK_S + 1, r.tail());
		final long hi = Math.min(v.lastTickSec, r.head());
		final int[] rtts = new int[hi >= lo ? (int) (hi - lo + 1) : 0];
		int n = 0;
		for (long sec = lo; sec <= hi; sec++)
		{
			final int rtt = r.rttMs(sec);
			final int age = r.rttAgeS(sec);
			if (r.valid(sec) && fresh(rtt, age))
			{
				rtts[n++] = rtt;
				v.beforeRttMax = Math.max(v.beforeRttMax, rtt);
			}
		}
		v.beforeRtt = median(rtts, n);
		v.beforeRttSpike = n == 0 || v.rttUsual < 0 ? Evidence.NO_DATA : spikeLine(v.beforeRttMax, v.rttUsual);
		final long[] sums = new long[3];
		sum(r, lo, hi, sums);
		v.beforeResentPm = sums[2] == 0 ? -1 : share(sums[0], sums[1]);
	}

	// ------------------------------------------------------------------ the window's events

	/**
	 * True when an event of the log, open or closed, overlaps {@code first .. last}. An OPEN event is still running:
	 * the log holds it as {@code opened} handed it in, with {@code endSec} at its first trigger second, so it is taken
	 * as reaching {@code last}, the newest second.
	 */
	private static boolean eventIn(EventLog log, long first, long last)
	{
		for (int i = log.size() - 1; i >= 0; i--)
		{
			// The sampler thread is the log's one writer, and this runs on it: the size cannot shrink meanwhile.
			final LagEvent e = log.get(i);
			final long end = e.open ? last : e.endSec;
			if (end < first)
			{
				// Events never overlap and are held in the order they opened: the older ones ended earlier still.
				return false;
			}
			if (e.startSec <= last)
			{
				return true;
			}
		}
		return false;
	}
}

package com.whylag.core;

/**
 * The flag bits of one second, stored as ONE byte per second (contract 3.2, 6.1). Every bit is under 128, so the
 * byte column never goes negative.
 *
 * <p>Who sets each bit is the samplers' rule (contract section 7, L2, "The state and the flags of a second"):
 * {@link #FOCUSED} is the focus when the second is closed; {@link #NOT_LOGGED_IN} marks a second whose state is
 * OTHER, LOGIN_SCREEN or LOGGING_IN (never HOPPING or CONNECTION_LOST); {@link #LOADING}, {@link #HOP} and
 * {@link #DISCONNECT} mark every second that overlaps LOADING, HOPPING or CONNECTION_LOST time (LOADING also the
 * second a loading frame ended in); {@link #NO_FRAMES} a filled second; {@link #LOGIN_MASK} the seconds of the
 * ticks after a login, a hop or a lost connection ends.
 *
 * <p>{@link #masked(int)} is the mask EVERY lot can read: a second masked by its flags alone. The detector's own
 * {@code Masks.masked} (contract 6.1) has two rules more, which need the ring and the settings; only
 * {@code LagDetector} calls it.
 */
public final class Flags
{
	public static final int FOCUSED = 1, LOADING = 2, HOP = 4, LOGIN_MASK = 8, NOT_LOGGED_IN = 16,
		NO_FRAMES = 32, DISCONNECT = 64;

	/** The four bits that mask a second by its flags alone: LOADING, HOP, LOGIN_MASK and NOT_LOGGED_IN (30). */
	public static final int MASKED = LOADING | HOP | LOGIN_MASK | NOT_LOGGED_IN;

	private Flags()
	{
	}

	/** True when {@code bit} is set in {@code flags}. */
	public static boolean has(int flags, int bit)
	{
		return (flags & bit) != 0;
	}

	/**
	 * True when {@code flags} carry any bit of {@link #MASKED}: the second is masked BY ITS FLAGS ALONE (contract 3.2)
	 * - a load, a hop, the login mask or the login screen. {@code Masks.masked} (L3) adds the tail of a load and the
	 * unfocused second under FPS Control's unfocused limit; the verdict (L4) and the snapshot (L5) never call it, and
	 * where they must leave a second out they leave out the seconds this names (contract 6.3, "Which seconds a
	 * condition reads").
	 */
	public static boolean masked(int flags)
	{
		return (flags & MASKED) != 0;
	}
}

package com.whylag.core;

import java.time.Instant;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZoneOffset;

/**
 * Number and clock text (contract 3.2). Every method is static and pure; every answer is plain ASCII.
 */
public final class Fmt
{
	private Fmt()
	{
	}

	/** Digits grouped by commas: 1240 is "1,240", -1240 is "-1,240". */
	public static String thousands(int n)
	{
		final String digits = Long.toString(Math.abs((long) n));
		final StringBuilder out = new StringBuilder(digits.length() + 5);
		if (n < 0)
		{
			out.append('-');
		}
		int lead = digits.length() % 3;
		if (lead == 0)
		{
			lead = 3;
		}
		out.append(digits, 0, lead);
		for (int i = lead; i < digits.length(); i += 3)
		{
			out.append(',').append(digits, i, i + 3);
		}
		return out.toString();
	}

	/**
	 * Milliseconds as seconds with one decimal, rounded to the nearest tenth (half up): 900 is "0.9", 1840 is "1.8",
	 * 1850 is "1.9", 9999 is "10.0".
	 */
	public static String tenths(int ms)
	{
		final long tenthsOfASecond = (Math.abs((long) ms) + 50) / 100;
		final String text = (tenthsOfASecond / 10) + "." + (tenthsOfASecond % 10);
		return ms < 0 && tenthsOfASecond != 0 ? "-" + text : text;
	}

	/** The wall clock in {@code zone} as "21:47" (24 hours). A null zone reads as UTC. */
	public static String clock(long wallMs, ZoneId zone)
	{
		final LocalTime t = timeOf(wallMs, zone);
		return two(t.getHour()) + ":" + two(t.getMinute());
	}

	/** The wall clock in {@code zone} as "21:47:30" (24 hours). A null zone reads as UTC. */
	public static String clockSeconds(long wallMs, ZoneId zone)
	{
		final LocalTime t = timeOf(wallMs, zone);
		return two(t.getHour()) + ":" + two(t.getMinute()) + ":" + two(t.getSecond());
	}

	/**
	 * How long ago, in whole units, rounded down: "now" (under a second, or in the future), "40 s ago",
	 * "4 min ago", and from 60 minutes on whole hours, "3 h ago".
	 */
	public static String ago(long thenWallMs, long nowWallMs)
	{
		final long seconds = (nowWallMs - thenWallMs) / 1000;
		if (seconds < 1)
		{
			return "now";
		}
		if (seconds < 60)
		{
			return seconds + " s ago";
		}
		final long minutes = seconds / 60;
		if (minutes < 60)
		{
			return minutes + " min ago";
		}
		return (minutes / 60) + " h ago";
	}

	/**
	 * How much a stretched graph holds, rounded down: "30 s" under a minute, else "4 min" (at least "0 s"); the range
	 * row's note adds "so far".
	 */
	public static String held(long ms)
	{
		final long seconds = Math.max(0, ms / 1000);
		return seconds < 60 ? seconds + " s" : thousands((int) Math.min(Integer.MAX_VALUE, seconds / 60)) + " min";
	}

	/** "0 lags", "1 lag", "4 lags", "1,240 lags". */
	public static String lags(int n)
	{
		return thousands(n) + (n == 1 ? " lag" : " lags");
	}

	/** {@code v} held inside {@code lo .. hi}. */
	public static int clamp(int v, int lo, int hi)
	{
		return v < lo ? lo : (v > hi ? hi : v);
	}

	private static LocalTime timeOf(long wallMs, ZoneId zone)
	{
		return Instant.ofEpochMilli(wallMs).atZone(zone == null ? ZoneOffset.UTC : zone).toLocalTime();
	}

	private static String two(int v)
	{
		return v < 10 ? "0" + v : Integer.toString(v);
	}
}

package com.whylag.core;

/**
 * The client thread's per-frame accumulation (contract 3.10 and section 7, L2): every {@link #frame} call is
 * counted into the session second it lands in, and the first frame PAST a second's boundary closes that second into
 * the frame columns of {@link SecondRing}. Only a frame closes a second, so the ring's frame head always says where
 * the newest frame is ({@link Session#framesStopped}).
 *
 * <p><b>Missed seconds.</b> A second in which no {@code frame()} call landed is written as a filler: frames 0,
 * worst frame 0 and the {@link Flags#NO_FRAMES} flag. EVERY missed second is written, however
 * many there are; a stall is charged to the second it ENDED in, with {@code worstFrameEndMs} = where in that second
 * it ended.
 *
 * <p><b>The first frame</b> starts the frame clock: it counts in {@code frames} but closes no interval, so it adds
 * nothing to the worst frame or the slow frames.
 *
 * <p><b>The state and the flags of a second.</b> {@code state} is the code in force at the second's END;
 * {@link Flags#NOT_LOGGED_IN} goes with OTHER, LOGIN_SCREEN and LOGGING_IN; {@link Flags#LOADING},
 * {@link Flags#HOP} and {@link Flags#DISCONNECT} are set on every second that overlaps a stretch of that state (a
 * stretch runs from the {@code state()} call that entered it to the call that left it); {@code loadingMs} is the ms
 * of the second inside LOADING stretches; {@link Flags#LOADING} is also set on the second in which a frame interval
 * that overlapped any LOADING time ENDED (the loading-frame rule, contract 6.1); {@link Flags#FOCUSED}, the world
 * and the scene counts are the values in force when the second is closed; {@link Flags#LOGIN_MASK} is set on the
 * seconds in which a masked tick arrived (the tick sampler says which, {@link #maskSecond}).
 *
 * <p>Everything here runs on the client thread but {@link #focus}, which is one volatile write. {@link #frame}
 * allocates nothing, takes no lock, logs nothing and builds no string (T1, T2).
 *
 * <p>
 * Choice: state changes are kept, with their times, until the frame that closes their second; at most
 * {@value #PENDING_STATES} wait at once, and one more overwrites the code of the newest (its time is kept).
 * <br>
 * Choice: a {@code state()} call with the code already in force is no transition and changes nothing.
 * <br>
 * Choice: the state before the first {@code state()} call is OTHER, and the focus before the first
 * {@code focus()} call is true.
 * <br>
 * Choice: of two frames of the same length the LATER is the second's worst frame (as {@code Trace.frameGap}).
 * <br>
 * Choice: {@code slowFrames} stops counting at 127, the column's top.
 * <br>
 * Choice: {@link #resetWorstSinceTick()} also restarts {@link #loadingSinceTick()}, which stays true while the
 * state is LOADING.
 * <br>
 * Choice: at most {@value #PENDING_MASKS} masked seconds wait for their close; one more drops the oldest.
 * <br>
 * Choice: a frame whose time lies before the open second (a clock that ran backwards) counts in the open
 * second.
 */
public final class FrameSampler
{
	private static final long NANOS_PER_SECOND = 1_000_000_000L;
	private static final long NANOS_PER_MS = 1_000_000L;
	private static final int MS_PER_SECOND = 1000;
	/** The last ms of a second: the top of {@code worstFrameEndMs}. */
	private static final int LAST_MS = MS_PER_SECOND - 1;
	/** State changes that may wait for the frame that closes their second. */
	private static final int PENDING_STATES = 64;
	/** Masked seconds that may wait for their close. */
	private static final int PENDING_MASKS = 64;

	private final Session session;
	private final SecondRing ring;
	private final SelfTimer timer;
	/** The one carrier, reused for every second. */
	private final FrameSecond record = new FrameSecond();

	private volatile boolean focused = true;
	private int world, players, npcs, region;

	// ---- the frame clock
	private boolean started;
	private long lastFrameNanos;
	private int worstSinceTickMs;

	// ---- the open second
	private long openSec;
	private int frames, worstMs, worstEndMs, slow, extraFlags;

	// ---- the states: the code in force now, the code in force where the pending list starts, and the list
	private int liveState = State.OTHER;
	private int baseState = State.OTHER;
	/** Session nanos (since {@link Session#startNanos}) of each pending change, ascending. */
	private final long[] pendingAt = new long[PENDING_STATES];
	private final int[] pendingCode = new int[PENDING_STATES];
	private int pending;
	private boolean loadingSinceFrame, loadingSinceTick;

	// ---- the answer of walk(): plain fields, so that it allocates nothing
	private int walkFlags, walkState, walkUsed;
	private long walkLoadNanos;

	// ---- the seconds in which a masked tick arrived and which are not closed yet, ascending, a circular queue
	private final long[] maskSecs = new long[PENDING_MASKS];
	private int maskFirst, maskCount;

	public FrameSampler(Session s, SelfTimer timer)
	{
		this.session = s;
		this.ring = s.seconds;
		this.timer = timer;
		this.openSec = s.seconds.frameHead() + 1;
	}

	/**
	 * One frame, stamped {@code nanos} ({@code System.nanoTime()}), with the game cycle. Client thread; allocates
	 * nothing.
	 */
	public void frame(long nanos, int gameCycle)
	{
		final boolean timed = timer != null && timer.on();
		final long t0 = timed ? System.nanoTime() : 0L;

		final long sec = session.secOf(nanos);
		while (openSec < sec)
		{
			closeOpen();
		}
		if (frames < Integer.MAX_VALUE)
		{
			frames++;
		}
		if (started)
		{
			final long wall = Math.max(0L, nanos - lastFrameNanos);
			final int ms = (int) Math.min(wall / NANOS_PER_MS, Integer.MAX_VALUE);
			if (ms >= worstMs)
			{
				worstMs = ms;
				worstEndMs = (int) Math.max(0L, Math.min(LAST_MS, session.msOf(nanos) - openSec * MS_PER_SECOND));
			}
			if (ms >= Thresholds.SLOW_FRAME_MS && slow < Byte.MAX_VALUE)
			{
				slow++;
			}
			if (ms > worstSinceTickMs)
			{
				worstSinceTickMs = ms;
			}
			if (loadingSinceFrame || liveState == State.LOADING)
			{
				extraFlags |= Flags.LOADING;
			}
		}
		started = true;
		lastFrameNanos = nanos;
		loadingSinceFrame = false;

		if (timed)
		{
			timer.add(SelfTimer.FRAME, System.nanoTime() - t0);
		}
	}

	/** The game state changed to {@code stateCode} ({@link State}) at {@code nanos}. Client thread. */
	public void state(long nanos, int stateCode)
	{
		if (stateCode == liveState)
		{
			return;
		}
		if (stateCode == State.LOADING || liveState == State.LOADING)
		{
			loadingSinceFrame = true;
			loadingSinceTick = true;
		}
		long at = nanos - session.startNanos;
		if (pending > 0 && at < pendingAt[pending - 1])
		{
			at = pendingAt[pending - 1];
		}
		if (pending == PENDING_STATES)
		{
			pendingCode[pending - 1] = stateCode;
		}
		else
		{
			pendingAt[pending] = at;
			pendingCode[pending] = stateCode;
			pending++;
		}
		liveState = stateCode;
	}

	/** The world the player is in; written into every second closed from now on. Client thread. */
	public void world(int world)
	{
		this.world = world;
	}

	/** The scene counts and the region; written into every second closed from now on. Client thread. */
	public void scene(int players, int npcs, int region)
	{
		this.players = players;
		this.npcs = npcs;
		this.region = region;
	}

	/** The window's focus: one volatile write, from any thread. A second takes the value in force at its close. */
	public void focus(boolean focused)
	{
		this.focused = focused;
	}

	/** The longest CLOSED frame interval since {@link #resetWorstSinceTick()}, in ms; 0 before the first frame. */
	public int worstFrameSinceTickMs()
	{
		return worstSinceTickMs;
	}

	/** Ms since the last {@link #frame} call, the frame still OPEN at {@code nanos}; 0 before the first. */
	public int openFrameMs(long nanos)
	{
		if (!started)
		{
			return 0;
		}
		final long wall = Math.max(0L, nanos - lastFrameNanos);
		return (int) Math.min(wall / NANOS_PER_MS, Integer.MAX_VALUE);
	}

	/**
	 * A tick has taken its frame time: {@link #worstFrameSinceTickMs()} starts again, and so does
	 * {@link #loadingSinceTick()}.
	 */
	public void resetWorstSinceTick()
	{
		worstSinceTickMs = 0;
		loadingSinceTick = liveState == State.LOADING;
	}

	/**
	 * True when any LOADING time lies between the last {@link #resetWorstSinceTick()} and now. Client thread. The
	 * fixed API of contract 3.10 names no reader for it: a tick row takes its flags from its second alone
	 * ({@link TickSampler}), so no LOADING reaches a row through this.
	 */
	public boolean loadingSinceTick()
	{
		return loadingSinceTick || liveState == State.LOADING;
	}

	// ---------------------------------------------------------------- for the tick sampler (package-private)

	/** A masked tick arrived in session second {@code sec}: that second gets {@link Flags#LOGIN_MASK} at its close. */
	void maskSecond(long sec)
	{
		if (sec < openSec)
		{
			return;
		}
		if (maskCount > 0 && maskSecs[(maskFirst + maskCount - 1) % PENDING_MASKS] >= sec)
		{
			return;
		}
		if (maskCount == PENDING_MASKS)
		{
			maskFirst = (maskFirst + 1) % PENDING_MASKS;
			maskCount--;
		}
		maskSecs[(maskFirst + maskCount) % PENDING_MASKS] = sec;
		maskCount++;
	}

	/**
	 * The flags of the second that {@code nanos} lies in, as they stand at {@code nanos}: what a tick that arrives
	 * then carries. {@link Flags#NO_FRAMES} is not among them; it is known only at the close.
	 */
	int flagsAt(long nanos)
	{
		final long sec = session.secOf(nanos);
		walk(sec * NANOS_PER_SECOND, nanos - session.startNanos, false);
		int fl = walkFlags | stateFlag(walkState);
		if (focused)
		{
			fl |= Flags.FOCUSED;
		}
		if (sec == openSec)
		{
			fl |= extraFlags;
		}
		for (int i = 0; i < maskCount; i++)
		{
			if (maskSecs[(maskFirst + i) % PENDING_MASKS] == sec)
			{
				fl |= Flags.LOGIN_MASK;
				break;
			}
		}
		return fl;
	}

	// ---------------------------------------------------------------- closing a second

	/** Writes the open second into the ring and opens the next. */
	private void closeOpen()
	{
		final long start = openSec * NANOS_PER_SECOND;
		walk(start, start + NANOS_PER_SECOND, true);
		consume(walkUsed);
		baseState = walkState;

		int fl = walkFlags | extraFlags | stateFlag(walkState);
		if (focused)
		{
			fl |= Flags.FOCUSED;
		}
		if (frames == 0)
		{
			fl |= Flags.NO_FRAMES;
		}
		while (maskCount > 0 && maskSecs[maskFirst] < openSec)
		{
			maskFirst = (maskFirst + 1) % PENDING_MASKS;
			maskCount--;
		}
		if (maskCount > 0 && maskSecs[maskFirst] == openSec)
		{
			fl |= Flags.LOGIN_MASK;
			maskFirst = (maskFirst + 1) % PENDING_MASKS;
			maskCount--;
		}

		final FrameSecond r = record;
		r.frames = frames;
		r.worstFrameMs = worstMs;
		r.worstFrameEndMs = worstEndMs;
		r.slowFrames = slow;
		r.loadingMs = (int) Math.min(MS_PER_SECOND, walkLoadNanos / NANOS_PER_MS);
		r.state = walkState;
		r.flags = fl;
		r.world = world;
		r.players = players;
		r.npcs = npcs;
		r.region = region;
		ring.putFrame(openSec, r);

		openSec++;
		frames = 0;
		worstMs = 0;
		worstEndMs = 0;
		slow = 0;
		extraFlags = 0;
	}

	/**
	 * Walks the pending state changes over the span {@code start .. end} (session nanos) and leaves the answer in
	 * the four {@code walk} fields: the LOADING, HOP and DISCONNECT bits of every stretch that overlaps the span,
	 * the LOADING time inside it, the code in force at its end and how many pending changes lie before that end.
	 * {@code closing}: the span is a whole second, its end excluded. Otherwise the span ends at a moment inside a
	 * second, that moment included, and the code in force at it counts even when it was entered at that moment.
	 */
	private void walk(long start, long end, boolean closing)
	{
		int st = baseState;
		long pos = start;
		int fl = 0;
		long load = 0;
		int i = 0;
		while (i < pending && (closing ? pendingAt[i] < end : pendingAt[i] <= end))
		{
			final long t = pendingAt[i];
			if (t > pos)
			{
				fl |= stretchFlag(st);
				if (st == State.LOADING)
				{
					load += t - pos;
				}
				pos = t;
			}
			st = pendingCode[i];
			i++;
		}
		if (end > pos || !closing)
		{
			fl |= stretchFlag(st);
			if (st == State.LOADING && end > pos)
			{
				load += end - pos;
			}
		}
		walkFlags = fl;
		walkLoadNanos = load;
		walkState = st;
		walkUsed = i;
	}

	/** Drops the {@code n} oldest pending changes. */
	private void consume(int n)
	{
		if (n <= 0)
		{
			return;
		}
		final int left = pending - n;
		if (left > 0)
		{
			System.arraycopy(pendingAt, n, pendingAt, 0, left);
			System.arraycopy(pendingCode, n, pendingCode, 0, left);
		}
		pending = left;
	}

	/** The flag a stretch of {@code state} puts on every second it overlaps; 0 for a state that has none. */
	private static int stretchFlag(int state)
	{
		switch (state)
		{
			case State.LOADING:
				return Flags.LOADING;
			case State.HOPPING:
				return Flags.HOP;
			case State.CONNECTION_LOST:
				return Flags.DISCONNECT;
			default:
				return 0;
		}
	}

	/** {@link Flags#NOT_LOGGED_IN} for OTHER, LOGIN_SCREEN and LOGGING_IN; 0 for every other code. */
	private static int stateFlag(int state)
	{
		return state == State.OTHER || state == State.LOGIN_SCREEN || state == State.LOGGING_IN
			? Flags.NOT_LOGGED_IN
			: 0;
	}
}

package com.whylag.core;

/**
 * The client thread's half of one second (contract 3.3): a mutable carrier, allocated once by its owner and
 * reused for every second, which {@link SecondRing#putFrame} copies into its columns.
 *
 * <p>{@code worstFrameEndMs} is where INSIDE the second the worst frame ENDED, 0..999: that frame ran over
 * [second start + worstFrameEndMs - worstFrameMs, second start + worstFrameEndMs], in session ms.
 */
public final class FrameSecond
{
	public int frames, worstFrameMs, worstFrameEndMs, slowFrames, loadingMs, state, flags, world, players, npcs,
		region;

	/** A cleared carrier (see {@link #clear()}). */
	public FrameSecond()
	{
		clear();
	}

	/** Every field 0. */
	public void clear()
	{
		frames = 0;
		worstFrameMs = 0;
		worstFrameEndMs = 0;
		slowFrames = 0;
		loadingMs = 0;
		state = 0;
		flags = 0;
		world = 0;
		players = 0;
		npcs = 0;
		region = 0;
	}
}

package com.whylag.core;

/**
 * What an event is counted under (contract 3.2): the list's label, the session counts' short label, and the lane
 * whose band is drawn redder. {@link #UNSURE} and {@link #NONE} have no lane.
 *
 * <p>The ORDINAL indexes {@link PanelSnapshot#sessionCounts}. Do not reorder.
 */
public enum Group
{
	CONNECTION("Conn", "Connection", Lane.PING),
	FRAME_RATE("Frame", "Frame rate", Lane.FRAME_RATE),
	WORLD("World", "World", Lane.TICKS),
	UNSURE("?", "Not sure", null),
	NONE("", "", null);

	private final String shortLabel;
	private final String label;
	private final Lane lane;

	Group(String shortLabel, String label, Lane lane)
	{
		this.shortLabel = shortLabel;
		this.label = label;
		this.lane = lane;
	}

	/** The session counts' word: "Conn", "Frame", "World", "?". */
	public String shortLabel()
	{
		return shortLabel;
	}

	/** The event list's word: "Connection", "Frame rate", "World", "Not sure". */
	public String label()
	{
		return label;
	}

	/** The culprit lane, or null for {@link #UNSURE} and {@link #NONE}. */
	public Lane lane()
	{
		return lane;
	}
}

package com.whylag.core;

/**
 * The sampler thread's half of one second (contract 3.3): the connection's readings, a mutable carrier, allocated
 * once and reused, which {@link SecondRing#putHost} copies into its columns. -1 is "no data" in every int but the
 * two unit counters; {@link #conn} says why the ping is missing ({@link NoData#NONE} when it is not).
 *
 * <p><b>A fresh RTT</b> (contract 3.3): {@code rttMs >= 0} and {@code 0 <= rttAgeS <= RTT_STALE_S}. The writer keeps
 * {@link #conn} at {@link NoData#NONE} in exactly the seconds whose RTT is fresh, and writes
 * {@link NoData#STALE} for an RTT that is kept but older than {@link Thresholds#RTT_STALE_S}, or not there yet; so a
 * reader may test either and they agree. A cleared carrier is only a starting point: the writer fills it.
 */
public final class HostSecond
{
	public int rttMs, rttAgeS, sentUnits, resentUnits;
	public NoData conn;

	/** A cleared carrier (see {@link #clear()}). */
	public HostSecond()
	{
		clear();
	}

	/** Every int -1, except {@code sentUnits = resentUnits = 0}; {@code conn = NONE}. */
	public void clear()
	{
		rttMs = -1;
		rttAgeS = -1;
		sentUnits = 0;
		resentUnits = 0;
		conn = NoData.NONE;
	}
}

package com.whylag.core;

/**
 * The game badge's picture of a cause (contract 3.2, P2.7): one of the four pictures of set A in
 * {@code game-icons.js}, or {@link #NONE}, which means the status shape alone. {@link Answer} gives every cause and
 * card state its icon; the badge's painter loads {@code badge-<file>-<state>.png} for the WARN and BAD states only,
 * so OK and NO_DATA always draw a shape.
 */
public enum Icon
{
	/** No picture: the status shape alone (smooth, measuring, waiting, not logged in). */
	NONE(""),
	/** The planet: the world is slow. */
	WORLD("world"),
	/** The Wi-Fi sign: the line between this PC and the world. */
	LINE("line"),
	/** The monitor: this PC, or the client on it. */
	PC("pc"),
	/** The question mark: a lag whose cause cannot be told. */
	UNKNOWN("unknown");

	private final String file;

	Icon(String file)
	{
		this.file = file;
	}

	/**
	 * The icon's word in its file names, {@code badge-<file>-<state>.png}: "world", "line", "pc",
	 * "unknown"; "" for {@link #NONE}, which has no file.
	 */
	public String file()
