package com.whylag.core;

import java.util.List;
import java.util.Locale;

/**
 * The text of "Copy report" (contract 6.6; lot L5): plain ASCII, every line ended with {@code \n}, made from the
 * {@link PanelSnapshot} ALONE - it reads no ring and no second, and names no player, no address and no plugin.
 * The plugin answers {@code PanelActions.report} with it; the panel never names this class.
 *
 * <pre>
 * 2h Why Lag 1.0.1 report - world 416 - 20:52 to 21:52 (60 min)
 * Now: Smooth. 50 fps, ticks 600 ms, ping 41 ms
 * 3 lags this session: 1 connection, 1 frame rate, 1 world
 * 21:47:30  14 s  WORLD  Likely  World 416 is struggling, not you. Ticks 600 to 900+ ms for 14 s. ...
 * (one line per session event, newest first)
 * Client 1.12.38, renderer GPU, draw distance 50, MSAA_2, cap 50 (the client)
 *
 * Last 60 minutes
 * 21:47  fps 48/50/51  tick 601/952 ms  ping 40-43 ms  lags 1  masked 0 s
 * (one line per minute, oldest first)
 *
 * Notes
 * 20:52:01  plugin started, version 1.0.1, client 1.12.38, Windows 11
 * (one line per note, oldest first)
 *
 * Warnings
 * (none)
 *
 * Errors
 * (none)
 * </pre>
 *
 * <ol>
 * <li>The plugin's version ({@link PanelSnapshot#pluginVersion}, left out while it is ""), the world
 * ({@code " - not logged in"} at world 0), the session's start and now as clocks, and the whole minutes between
 * them, rounded down.</li>
 * <li>The verdict's headline and the three tiles' values in {@link Lane} order - the frame rate's alone, the others
 * after their word; a "-" tile prints its word and "-".</li>
 * <li>{@link Fmt#lags} of the session total, then each group of CONNECTION, FRAME_RATE, WORLD and UNSURE
 * whose count is above 0, as the count and its label in lower case.</li>
 * <li>One line per session event, NEWEST first: the start clock, the length, the group's label in upper case, the
 * confidence word and the verdict's text ({@code headline. proof Fix: fix}), joined by two spaces.</li>
 * <li>The settings: the client's version, the renderer, the draw distance and the anti-aliasing (GPU and 117 HD
 * only) and the FOCUSED cap (the report reads no second, contract 3.7).</li>
 * <li>A blank line, then three more kinds of section from the snapshot's two texts: {@code Last 60 minutes}
 * ({@link PanelSnapshot#minuteText}) and, from {@link PanelSnapshot#diagnosticsText}, {@code Notes},
 * {@code Warnings} and {@code Errors}, a blank line before each. A section with nothing in it says
 * {@value Diagnostics#NONE}.</li>
 * </ol>
 * Every number prints through {@link Fmt#thousands}; every clock through {@link Fmt#clock} or
 * {@link Fmt#clockSeconds} in the snapshot's zone.
 *
 * <p>Choice: any character outside printable ASCII, a control character too, prints as '?'; the text is plain ASCII.
 * <p>Choice: a null verdict prints the headline "Still measuring" ({@link Answer#HEAD_MEASURING}).
 * <p>Choice: an empty proof leaves no trailing space: the text is then the headline and "." alone.
 * <p>Choice: an event with no verdict (the log never holds one closed) prints "Can't tell" and no text.
 * <p>Choice: when no group of line 3 is above 0, the line has no colon, as with no events.
 * <p>Choice: the minutes of line 1 are held at 0 or more, for a wall clock set back.
 * <p>Choice: an empty anti-aliasing name on GPU or 117 HD prints "anti-aliasing unknown".
 * <p>Choice: {@link #of(PanelSnapshot, String)} takes the text of the next lot's two sections, {@code Verdict} and
 * {@code Checks}, as a block of whole lines that goes verbatim between line 1 and {@code Now}, its own blank lines
 * included; "" leaves the report as it is, so that lot adds text, not structure.
 * <p>Choice: the last sections are made even when the snapshot was built without their texts: a report always has
 * the same headings, which is what a person reading a pasted one looks for.
 * <p>Choice: every line passes {@link Diagnostics#scrub} on its way out, so a file path in ANY field of the snapshot
 * prints {@code <path>}: the report is pasted into a public post, and a path holds the player's Windows user name.
 */
public final class ReportText
{
	private static final char NEW_LINE = '\n';
	/** What joins the parts of an event line. */
	private static final String GAP = "  ";
	private static final String DASH = "-";
	/** The heading of the minute log's section. */
	private static final String MINUTES = "Last 60 minutes";
	private static final long MS_PER_MINUTE = 60_000L;
	private static final char FIRST_PRINTABLE = ' ';
	private static final char LAST_PRINTABLE = '~';
	private static final char NOT_ASCII = '?';
	/** The groups of line 3, in the order printed. */
	private static final Group[] COUNTED = {Group.CONNECTION, Group.FRAME_RATE, Group.WORLD, Group.UNSURE};

	private ReportText()
	{
	}

	/** The report of {@code s} with no checks section: {@link #of(PanelSnapshot, String)} with "". */
	public static String of(PanelSnapshot s)
	{
		return of(s, "");
	}

	/**
	 * The report of {@code s}: the lines of the class notes, each ended with a new line.
	 *
	 * @param s      the snapshot the report is made from
	 * @param checks the lines that go between line 1 and {@code Now}, each ended with a new line, blank lines
	 *               included; "" = none
	 */
	public static String of(PanelSnapshot s, String checks)
	{
		final List<LagEvent> events = s.sessionEvents;
		final StringBuilder out = new StringBuilder(1024 + 192 * events.size() + s.minuteText.length()
			+ s.diagnosticsText.length());
		line(out, header(s));
		block(out, checks);
		line(out, now(s));
		line(out, session(s));
		for (int i = events.size() - 1; i >= 0; i--)
		{
			line(out, event(events.get(i), s));
		}
		line(out, settings(s.settings));
		line(out, "");
		line(out, MINUTES);
		if (s.minuteText.isEmpty())
		{
			line(out, Diagnostics.NONE);
		}
		else
		{
			block(out, s.minuteText);
		}
		line(out, "");
		block(out, s.diagnosticsText.isEmpty() ? Diagnostics.empty() : s.diagnosticsText);
		return out.toString();
	}

	/** Line 1: "2h Why Lag 1.0.1 report - world 416 - 20:52 to 21:52 (60 min)". */
	private static String header(PanelSnapshot s)
	{
		final long minutes = Math.max(0, (s.wallMs - s.sessionStartWallMs) / MS_PER_MINUTE);
		return "2h Why Lag" + (s.pluginVersion.isEmpty() ? "" : " " + s.pluginVersion) + " report"
			+ (s.world == 0 ? " - not logged in" : " - world " + Fmt.thousands(s.world))
			+ " - " + Fmt.clock(s.sessionStartWallMs, s.zone) + " to " + Fmt.clock(s.wallMs, s.zone)
			+ " (" + Fmt.thousands((int) Math.min(Integer.MAX_VALUE, minutes)) + " min)";
	}

	/** Line 2: "Now: Smooth. 50 fps, ticks 600 ms, ping 41 ms". */
	private static String now(PanelSnapshot s)
	{
		final String headline = s.verdict == null ? Answer.HEAD_MEASURING : s.verdict.headline;
		return "Now: " + headline + ". "
			+ tile(s, Lane.FRAME_RATE, "fps", true) + ", "
			+ tile(s, Lane.TICKS, "ticks", false) + ", "
			+ tile(s, Lane.PING, "ping", false);
	}

	/** A tile's value: alone or after its word; "word -" when the tile has no value. */
	private static String tile(PanelSnapshot s, Lane lane, String word, boolean valueAlone)
	{
		final String value = s.tiles[lane.ordinal()].value;
		if (value.isEmpty() || DASH.equals(value))
		{
			return word + " " + DASH;
		}
		return valueAlone ? value : word + " " + value;
	}

	/** Line 3: "3 lags this session: 1 connection, 1 frame rate, 1 world". */
	private static String session(PanelSnapshot s)
	{
		final StringBuilder b = new StringBuilder(Fmt.lags(s.sessionTotal)).append(" this session");
		String between = ": ";
		for (Group g : COUNTED)
		{
			final int n = s.sessionCounts[g.ordinal()];
			if (n > 0)
			{
				b.append(between).append(Fmt.thousands(n)).append(' ').append(g.label().toLowerCase(Locale.ROOT));
				between = ", ";
			}
		}
		return b.toString();
	}

	/** An event line: "21:47:30  14 s  WORLD  Likely  headline. proof Fix: fix". */
	private static String event(LagEvent e, PanelSnapshot s)
	{
		final StringBuilder b = new StringBuilder(192)
			.append(Fmt.clockSeconds(e.startWallMs, s.zone)).append(GAP)
			.append(Fmt.thousands(e.lengthS())).append(" s").append(GAP)
			.append(e.group().label().toUpperCase(Locale.ROOT)).append(GAP);
		final Verdict v = e.verdict;
		if (v == null)
		{
			return b.append(Confidence.CANT_TELL.word()).toString();
		}
		b.append(v.confidence.word()).append(GAP).append(v.headline).append('.');
		if (!v.proof.isEmpty())
		{
			b.append(' ').append(v.proof);
		}
		if (!v.fix.isEmpty())
		{
			b.append(" Fix: ").append(v.fix);
		}
		return b.toString();
	}

	/** The last line: "Client 1.12.38, renderer GPU, draw distance 50, MSAA_2, cap 50 (the client)". */
	private static String settings(SettingsView v)
	{
		final StringBuilder b = new StringBuilder(192)
			.append("Client ").append(v.clientVersion.isEmpty() ? "unknown" : v.clientVersion)
			.append(", renderer ").append(v.renderer.label());
		if (v.renderer == Renderer.GPU || v.renderer == Renderer.HD)
		{
			b.append(", draw distance ").append(Fmt.thousands(v.drawDistance))
				.append(", ").append(v.antiAliasing.isEmpty() ? "anti-aliasing unknown" : v.antiAliasing);
		}
		final int cap = v.capFps(true);
		b.append(", cap ").append(cap > 0 ? Fmt.thousands(cap) + " (" + v.capSource(true).label() + ")" : "none");
		return b.toString();
	}

	/**
	 * Appends {@code text} as one line of plain ASCII: any other character, a control one included, is '?'. A file
	 * path in it prints {@code <path>} ({@link Diagnostics#scrub}).
	 */
	private static void line(StringBuilder out, String text)
	{
		final String clean = Diagnostics.scrub(text);
		for (int i = 0; i < clean.length(); i++)
		{
			final char c = clean.charAt(i);
			out.append(c >= FIRST_PRINTABLE && c <= LAST_PRINTABLE ? c : NOT_ASCII);
		}
		out.append(NEW_LINE);
	}

	/**
	 * Appends {@code text}, which is several lines, as plain ASCII: a new line stays one, any other character outside
	 * printable ASCII is '?', and the last line is ended if it was not. Nothing is appended for "".
	 */
	private static void block(StringBuilder out, String text)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		final String clean = Diagnostics.scrub(text);
		for (int i = 0; i < clean.length(); i++)
		{
			final char c = clean.charAt(i);
			out.append(c == NEW_LINE || c >= FIRST_PRINTABLE && c <= LAST_PRINTABLE ? c : NOT_ASCII);
		}
		if (clean.charAt(clean.length() - 1) != NEW_LINE)
		{
			out.append(NEW_LINE);
		}
	}
}

package com.whylag.core;

/**
 * One row of the rules table of contract 6.3: needs, excludes and supports as small named predicates on
 * {@link Evidence}, with the row's rank, base score and ceiling.
 *
 * <p><b>Scoring (skeptic C22).</b> A rule scores 0 unless ALL its needs hold and NONE of its excludes holds; then
 * it scores {@code base + SUPPORT_POINTS x (supports that hold)}. A need on a signal with no data FAILS. An exclude
 * or a support on a signal with no data is skipped, and the rule's ceiling drops ONE step for each such signal.
 *
 * <p>Choice: a verdict's confidence IS its rule's ceiling after those drops ({@link #confidence}); the score picks
 * the winner and never raises or lowers the word.
 * <p>Choice: V2 (kind ALWAYS) scores its base, 10, on any evidence; X (kind ENGINE) scores 0: the engine makes it.
 */
public final class Rule
{
	/** What a row is: an event rule, a condition rule, V2 ("always") or X ("made by the engine"). */
	public enum Kind
	{
		EVENT, CONDITION, ALWAYS, ENGINE
	}

	/** One named predicate: {@link Evidence#YES}, {@link Evidence#NO} or {@link Evidence#NO_DATA}. */
	public interface Signal
	{
		int test(Evidence e);
	}

	private static final Signal[] NONE = new Signal[0];

	public final int rank;
	/** The row's id: "D1" .. "X"; W1's condition form is "W1c". */
	public final String id;
	public final Cause cause;
	public final Kind kind;
	public final int base;
	public final Confidence ceiling;
	private final Signal[] needs;
	private final Signal[] excludes;
	private final Signal[] supports;

	Rule(int rank, String id, Cause cause, Kind kind, int base, Confidence ceiling, Signal[] needs,
		Signal[] excludes, Signal[] supports)
	{
		this.rank = rank;
		this.id = id;
		this.cause = cause;
		this.kind = kind;
		this.base = base;
		this.ceiling = ceiling;
		this.needs = needs == null ? NONE : needs;
		this.excludes = excludes == null ? NONE : excludes;
		this.supports = supports == null ? NONE : supports;
	}

	/** The row's score on this evidence; 0 = it does not answer. */
	public int score(Evidence e)
	{
		if (kind == Kind.ENGINE)
		{
			return 0;
		}
		for (Signal need : needs)
		{
			if (need.test(e) != Evidence.YES)
			{
				return 0;
			}
		}
		for (Signal exclude : excludes)
		{
			if (exclude.test(e) == Evidence.YES)
			{
				return 0;
			}
		}
		int score = base;
		for (Signal support : supports)
		{
			if (support.test(e) == Evidence.YES)
			{
				score += Thresholds.SUPPORT_POINTS;
			}
		}
		return score;
	}

	/** The ceiling, one step lower for each exclude and each support whose signal has no data. */
	public Confidence confidence(Evidence e)
	{
		Confidence c = ceiling;
		for (Signal exclude : excludes)
		{
			if (exclude.test(e) == Evidence.NO_DATA)
			{
				c = c.lower();
			}
		}
		for (Signal support : supports)
		{
			if (support.test(e) == Evidence.NO_DATA)
			{
				c = c.lower();
			}
		}
		return c;
	}

	/** How many needs, excludes and supports the row has (the table test counts them). */
	public int needs()
	{
		return needs.length;
	}

	public int excludes()
	{
		return excludes.length;
	}

	public int supports()
	{
		return supports.length;
	}
}

package com.whylag.core;

/**
 * The rules table of contract 6.3 as data: {@link #ALL} holds one {@link Rule} per row, in rank order. The rank,
 * base and ceiling of each row live here and nowhere else ({@code RulesTableTest} pins them by literal); every line
 * a predicate compares against is a {@link Thresholds} constant.
 *
 * <p>Each need, exclude and support is one small named predicate on {@link Evidence}. A predicate answers
 * {@link Evidence#NO_DATA} when the signal it reads has none, and {@link Rule} does the rest.
 *
 * <p>Choice: N3's support "{@code tickLate >= 1} or {@code noTickMs >= NO_TICK_MS}" is never "no data": both halves
 * are counts of what arrived, and a span with no tick at all answers NO.
 * <p>Choice: N6 ("No ticks") needs the NO_TICK trigger itself (changes after the first live look, 2026-09-29): an
 * event that only TICK_OFF opened - a tick late, not a stop - never becomes N6.
 * <p>Choice: among conditions a tie goes to the lower rank; among event rules the engine, not this class, applies
 * the margin ({@link VerdictEngine}).
 * <p>Choice (1.0.0, the Hub's rule): the plugin reads no memory, no CPU and no busy share, so the rows that stood
 * on them are gone (G1, S4, G2) and S3 ("Client froze") judges by the frame gap alone. S3 keeps the one exclude it
 * shared with S4, {@code CAP_EXPLAINS_THE_GAP}: a cap that paces by waiting explains a gap of up to
 * {@link Thresholds#CAP_WAIT_FACTOR} cap intervals, and that is not a freeze.
 */
public final class Rules
{
	private static final int YES = Evidence.YES, NO = Evidence.NO, NO_DATA = Evidence.NO_DATA;

	// ------------------------------------------------------------------ the named predicates

	static final Rule.Signal DISCONNECT = e -> is(e.disconnect);
	static final Rule.Signal LOADED = e -> is(e.loadMs > 0);
	static final Rule.Signal LOAD_IS_LONG = e -> is(e.loadMs >= Thresholds.LOAD_LONG_MS);
	static final Rule.Signal RESENT_COUNTS = e -> is(e.resentCounts);
	static final Rule.Signal RESENT_ANY = e -> is(e.resent > 0);
	static final Rule.Signal RESENT_NONE = e -> is(e.resent == 0);
	static final Rule.Signal TICKS_LATE_OR_MISSING = e -> is(e.tickLate >= 1
		|| e.noTickMs >= Thresholds.NO_TICK_MS);
	/** N6's need: the event's NO_TICK trigger fired, a real stop; a late tick alone is not "No ticks". */
	static final Rule.Signal NO_TICK_FIRED = e -> is(e.noTick);
	static final Rule.Signal TICK_LATE = e -> is(e.tickLate >= 1);
	static final Rule.Signal TICK_EARLY = e -> is(e.tickEarly >= 1);
	static final Rule.Signal NO_TICK_EARLY = e -> is(e.tickEarly == 0);
	static final Rule.Signal RTT_KNOWN = e -> is(e.rttKnown);
	static final Rule.Signal RTT_SPIKE = e -> e.rttSpike;
	static final Rule.Signal NO_RTT_SPIKE = e -> e.rttSpike == NO_DATA ? NO_DATA : is(e.rttSpike == NO);
	/** "rttKnown and not rttSpike": no data when either half has none. */
	static final Rule.Signal PING_KNOWN_AND_CALM = e -> !e.rttKnown || e.rttSpike == NO_DATA ? NO_DATA
		: is(e.rttSpike == NO);
	static final Rule.Signal FRAMES_KEEP_UP = e -> e.frameMedianMs < 0 ? NO_DATA
		: is(e.frameMedianMs < Thresholds.LOW_FPS_FRAME_MS);
	static final Rule.Signal FRAME_OVER_LIMIT = e -> e.frameGapMs < 0 || e.frameLimitMs < 0 ? NO_DATA
		: is(e.frameGapMs >= e.frameLimitMs);
	static final Rule.Signal RTT_SWUNG = e -> e.rttMax < 0 || e.rttUsual < 0 ? NO_DATA
		: is(e.rttMax >= Thresholds.RTT_SWING_FACTOR * e.rttUsual);
	static final Rule.Signal ENOUGH_TICKS = e -> is(e.ticks >= Thresholds.SLOW_WORLD_MIN_TICKS);
	static final Rule.Signal TICKS_SLOW = e -> e.tickMedianMs < 0 ? NO_DATA
		: is(e.tickMedianMs >= Thresholds.SLOW_WORLD_MEDIAN_MS);
	static final Rule.Signal FRAMES_CLEAN = e -> e.frameGapMs < 0 ? NO_DATA : is(e.framesClean);
	static final Rule.Signal PING_NEAR_USUAL = e -> e.rtt < 0 || e.rttUsual < 0 ? NO_DATA
		: is(Math.abs(e.rtt - e.rttUsual) <= Thresholds.SLOW_WORLD_PING_MS);
	static final Rule.Signal PING_MAX_NEAR_USUAL = e -> e.rttMax < 0 || e.rttUsual < 0 ? NO_DATA
		: is(e.rttMax <= e.rttUsual + Thresholds.RTT_SPIKE_ADD_MS);
	static final Rule.Signal LASTED_LONG = e -> is(e.durationS >= Thresholds.SLOW_WORLD_LONG_S);
	/** S3's bar: the cap paces by waiting, and the gap is within CAP_WAIT_FACTOR cap intervals. */
	static final Rule.Signal CAP_EXPLAINS_THE_GAP = e -> is(e.capWaits
		&& e.frameGapMs <= Thresholds.CAP_WAIT_FACTOR * e.capIntervalMs);
	static final Rule.Signal CAP_SELF_SET = e -> is(e.capSelfSet);
	static final Rule.Signal CAP_HELD = e -> is(e.capHeldS >= Thresholds.CONDITION_HOLD_S);
	static final Rule.Signal F1_NEEDS_HOLD = e -> is(e.capSelfSet && e.capHeldS >= Thresholds.CONDITION_HOLD_S);
	static final Rule.Signal PING_HIGH = e -> e.rtt < 0 ? NO_DATA : is(e.rtt >= Thresholds.PING_BAD_MS);
	static final Rule.Signal PING_STEADY = e -> e.rttMax < 0 || e.rttMin < 0 ? NO_DATA
		: is(e.rttMax - e.rttMin < Thresholds.PING_STEADY_MS);
	static final Rule.Signal SLOW_FOR_LONG = e -> is(e.lowFpsS >= Thresholds.CONDITION_HOLD_S);
	static final Rule.Signal PING_KNOWN_AND_LOW = e -> !e.rttKnown || e.rtt < 0 ? NO_DATA
		: is(e.rtt < Thresholds.PING_WARN_MS);
	static final Rule.Signal ENOUGH_WINDOW_TICKS = e -> is(e.ticksInWindow >= Thresholds.SLOW_WORLD_WINDOW_TICKS);
	static final Rule.Signal WINDOW_TICKS_SLOW = e -> e.tickWindowMedianMs < 0 ? NO_DATA
		: is(e.tickWindowMedianMs >= Thresholds.SLOW_WORLD_WINDOW_MS);
	static final Rule.Signal NO_EVENT_IN_WINDOW = e -> is(!e.eventInWindow);
	static final Rule.Signal NO_DISCONNECT = e -> is(!e.disconnect);

	// ------------------------------------------------------------------ the rows

	public static final Rule D1 = new Rule(1, "D1", Cause.DISCONNECT, Rule.Kind.EVENT, 200, Confidence.SURE,
		all(DISCONNECT), null, null);
	public static final Rule S1 = new Rule(2, "S1", Cause.MAP_LOAD, Rule.Kind.EVENT, 105, Confidence.SURE,
		all(LOAD_IS_LONG), null, null);
	public static final Rule N3 = new Rule(3, "N3", Cause.UPLOAD_LOSS, Rule.Kind.EVENT, 90, Confidence.LIKELY,
		all(RESENT_COUNTS), all(DISCONNECT), all(TICKS_LATE_OR_MISSING, RTT_SPIKE));
	public static final Rule N2 = new Rule(4, "N2", Cause.PING_JUMPY, Rule.Kind.EVENT, 85, Confidence.LIKELY,
		all(RTT_SPIKE, TICK_LATE, TICK_EARLY, FRAMES_KEEP_UP), all(RESENT_ANY, FRAME_OVER_LIMIT), all(RTT_SWUNG));
	public static final Rule W1 = new Rule(5, "W1", Cause.SLOW_WORLD, Rule.Kind.EVENT, 85, Confidence.LIKELY,
		all(ENOUGH_TICKS, TICKS_SLOW, NO_TICK_EARLY, FRAMES_CLEAN, RTT_KNOWN, NO_RTT_SPIKE, PING_NEAR_USUAL,
			PING_MAX_NEAR_USUAL, RESENT_NONE),
		all(DISCONNECT), all(LASTED_LONG));
	public static final Rule S3 = new Rule(6, "S3", Cause.CLIENT_BUSY, Rule.Kind.EVENT, 80, Confidence.HINT,
		all(FRAME_OVER_LIMIT), all(LOADED, CAP_EXPLAINS_THE_GAP, RESENT_COUNTS), all(PING_KNOWN_AND_CALM));
	public static final Rule N6 = new Rule(7, "N6", Cause.DELIVERY_GAP, Rule.Kind.EVENT, 75,
		Confidence.CANT_TELL, all(NO_TICK_FIRED, FRAMES_CLEAN, RESENT_NONE), all(RTT_SPIKE, DISCONNECT),
		null);
	public static final Rule F1 = new Rule(8, "F1", Cause.FRAME_CAP, Rule.Kind.CONDITION, 120, Confidence.SURE,
		all(CAP_SELF_SET, CAP_HELD), null, null);
	public static final Rule N1 = new Rule(9, "N1", Cause.PING_HIGH, Rule.Kind.CONDITION, 60, Confidence.SURE,
		all(RTT_KNOWN, PING_HIGH, PING_STEADY), null, null);
	public static final Rule F2 = new Rule(10, "F2", Cause.SLOW_DRAWING, Rule.Kind.CONDITION, 60,
		Confidence.LIKELY, all(SLOW_FOR_LONG), all(F1_NEEDS_HOLD), all(PING_KNOWN_AND_LOW));
	public static final Rule W1C = new Rule(11, "W1c", Cause.SLOW_WORLD, Rule.Kind.CONDITION, 55, Confidence.HINT,
		all(ENOUGH_WINDOW_TICKS, WINDOW_TICKS_SLOW, NO_EVENT_IN_WINDOW, NO_DISCONNECT, FRAMES_CLEAN), null,
		all(PING_KNOWN_AND_CALM));
	public static final Rule V2 = new Rule(12, "V2", Cause.ALL_CLEAR, Rule.Kind.ALWAYS, 10, Confidence.SURE,
		null, null, null);
	public static final Rule X = new Rule(13, "X", Cause.NOT_SURE, Rule.Kind.ENGINE, 0, Confidence.CANT_TELL,
		null, null, null);

	/** One rule per row of contract 6.3, in rank order. */
	public static final Rule[] ALL = {D1, S1, N3, N2, W1, S3, N6, F1, N1, F2, W1C, V2, X};

	private Rules()
	{
	}

	/** How many rows the table has. */
	public static int count()
	{
		return ALL.length;
	}

	/** Row {@code i} of the table, 0 = rank 1. */
	public static Rule at(int i)
	{
		return ALL[i];
	}

	/** The row with this id ("D1" .. "X", "W1c"); null = none. */
	public static Rule byId(String id)
	{
		for (Rule r : ALL)
		{
			if (r.id.equals(id))
			{
				return r;
			}
		}
		return null;
	}

	/** The winning condition on this evidence: the highest score, the lower rank on a tie; null = none scores. */
	public static Rule bestCondition(Evidence e)
	{
		Rule best = null;
		int bestScore = 0;
		for (Rule r : ALL)
		{
			if (r.kind != Rule.Kind.CONDITION)
			{
				continue;
			}
			final int score = r.score(e);
			if (score > bestScore)
			{
				best = r;
				bestScore = score;
			}
		}
		return best;
	}

	private static int is(boolean holds)
	{
		return holds ? YES : NO;
	}

	private static Rule.Signal[] all(Rule.Signal... signals)
	{
		return signals;
	}
}

package com.whylag.core;


/**
 * One row per session second, in two column groups with one writer each (contract 3.3): the FRAME columns are
 * written by the client thread ({@link #putFrame}), the HOST columns by the sampler thread ({@link #putHost}).
 * Any thread reads.
 *
 * <p><b>Storage.</b> Primitive arrays allocated once in the constructor, one per column: {@code short[]} and
 * {@code byte[]}, {@code int[]} for the two unit counters, {@code char[]} for {@code region} (unsigned 16 bits).
 * The slot of second {@code sec} is {@code sec % capacity}. No method allocates and none takes a lock.
 *
 * <p><b>Clamps</b> (the clamp table of contract 3.3): every value is clamped to its column on write, and a put
 * never throws for a value. The short columns ({@code frames}, {@code worstFrameMs}, {@code loadingMs},
 * {@code world}, {@code players}, {@code npcs}, {@code rttMs}, {@code rttAgeS}) hold -1 .. 32767: EVERY negative
 * value is stored as -1 ("no data"), over 32767 as 32767. {@code worstFrameEndMs} holds 0 .. 999; the byte columns
 * ({@code slowFrames}, {@code state}, {@code flags}) 0 .. 127, a negative stored as 0; {@code region} 0 .. 65535, a
 * negative stored as 0; {@code sentUnits} and {@code resentUnits} are kept whole (the writer never hands in a
 * negative); {@code conn} is the {@link NoData} ordinal, a null stored as {@link NoData#NONE}.
 *
 * <p><b>Writing.</b> Each group must be written in order from second 0: {@code sec} must be its head + 1, and the
 * writer fills a gap by writing every missed second. A put writes its columns and THEN its volatile head.
 *
 * <p><b>One slot of slack.</b> The next put reuses the slot of second {@code head + 1 - capacity}. So that a second
 * is never readable while its slot is being overwritten, {@link #tail()} is {@code max(0, newest - capacity + 2)}:
 * the slot about to be reused is already below the tail. A ring built with capacity {@code n + 1} keeps {@code n}
 * readable seconds, which is why {@link Session} builds it one slot larger than {@link Thresholds#SECONDS}.
 *
 * <p><b>Reading.</b> Call {@link #valid(long)} before reading a second (it is published) and again after (it was
 * not overwritten meanwhile); throw the read away if the second check fails. The ordering that makes the re-check
 * sound on weakly ordered CPUs (ARM) as well as on x86 comes from volatile accesses alone, no lock and no fence
 * API: each put begins by reading its volatile head, so the column stores that follow cannot move before the head
 * store of the previous put; {@code valid} begins with a volatile store to {@link #order}, so the column reads a
 * caller made before it cannot move past the volatile head reads that follow (a plain read may otherwise be
 * reordered after a later volatile read).
 */
public final class SecondRing
{
	private static final NoData[] CONN = NoData.values();
	/** The last millisecond of a second: the range of {@code worstFrameEndMs}. */
	private static final int LAST_MS = 999;

	private final int capacity;

	private final short[] frames;
	private final short[] worstFrameMs;
	private final short[] worstFrameEndMs;
	private final byte[] slowFrames;
	private final short[] loadingMs;
	private final byte[] state;
	private final byte[] flags;
	private final short[] world;
	private final short[] players;
	private final short[] npcs;
	private final char[] region;

	private final short[] rttMs;
	private final short[] rttAgeS;
	private final int[] sentUnits;
	private final int[] resentUnits;
	private final byte[] conn;

	private volatile long frameHead = -1;
	private volatile long hostHead = -1;
	/** Written at the start of {@link #valid(long)} for its ordering only; never read. */
	private volatile int order;

	/**
	 * @param capacity slots, at least 2; {@code capacity - 1} seconds are readable
	 */
	public SecondRing(int capacity)
	{
		if (capacity < 2)
		{
			throw new IllegalArgumentException("a ring needs at least 2 slots, got " + capacity);
		}
		this.capacity = capacity;
		frames = new short[capacity];
		worstFrameMs = new short[capacity];
		worstFrameEndMs = new short[capacity];
		slowFrames = new byte[capacity];
		loadingMs = new short[capacity];
		state = new byte[capacity];
		flags = new byte[capacity];
		world = new short[capacity];
		players = new short[capacity];
		npcs = new short[capacity];
		region = new char[capacity];
		rttMs = new short[capacity];
		rttAgeS = new short[capacity];
		sentUnits = new int[capacity];
		resentUnits = new int[capacity];
		conn = new byte[capacity];
	}

	/** Slots in the ring; one fewer are readable. */
	public int capacity()
	{
		return capacity;
	}

	/**
	 * The client thread's columns of second {@code sec}, which must be {@link #frameHead()} + 1.
	 *
	 * @throws IllegalArgumentException when {@code sec} is out of order (a caller bug; nothing is written)
	 */
	public void putFrame(long sec, FrameSecond v)
	{
		final long head = frameHead;
		if (sec != head + 1)
		{
			throw new IllegalArgumentException("putFrame(" + sec + ") must follow frame head " + head);
		}
		// The slot about to be reused belongs to second sec - capacity, which the head already published puts
		// below tail(). The volatile read of frameHead above keeps that published head ahead of the column stores
		// below on every CPU (a volatile read is never reordered with the stores after it).
		final int i = slot(sec);
		frames[i] = toShort(v.frames);
		worstFrameMs[i] = toShort(v.worstFrameMs);
		worstFrameEndMs[i] = (short) Fmt.clamp(v.worstFrameEndMs, 0, LAST_MS);
		slowFrames[i] = toByte(v.slowFrames);
		loadingMs[i] = toShort(v.loadingMs);
		state[i] = toByte(v.state);
		flags[i] = toByte(v.flags);
		world[i] = toShort(v.world);
		players[i] = toShort(v.players);
		npcs[i] = toShort(v.npcs);
		region[i] = (char) Fmt.clamp(v.region, 0, Character.MAX_VALUE);
		frameHead = sec;
	}

	/**
	 * The sampler thread's columns of second {@code sec}, which must be {@link #hostHead()} + 1. A null
	 * {@code conn} is stored as {@link NoData#NONE}.
	 *
	 * @throws IllegalArgumentException when {@code sec} is out of order (a caller bug; nothing is written)
	 */
	public void putHost(long sec, HostSecond v)
	{
		final long head = hostHead;
		if (sec != head + 1)
		{
			throw new IllegalArgumentException("putHost(" + sec + ") must follow host head " + head);
		}
		// Ordered after the previous head store by the volatile read of hostHead above, as in putFrame.
		final int i = slot(sec);
		rttMs[i] = toShort(v.rttMs);
		rttAgeS[i] = toShort(v.rttAgeS);
		sentUnits[i] = v.sentUnits;
		resentUnits[i] = v.resentUnits;
		conn[i] = (byte) (v.conn == null ? NoData.NONE : v.conn).ordinal();
		hostHead = sec;
	}

	/** The newest second whose frame columns are written; -1 before the first. */
	public long frameHead()
	{
		return frameHead;
	}

	/** The newest second whose host columns are written; -1 before the first. */
	public long hostHead()
	{
		return hostHead;
	}

	/** The newest second with BOTH groups written: the slower writer's head. */
	public long head()
	{
		return Math.min(frameHead, hostHead);
	}

	/** The oldest readable second: {@code max(0, max(frameHead, hostHead) - capacity + 2)}. */
	public long tail()
	{
		return tailOf(frameHead, hostHead);
	}

	/** {@code tail() <= sec <= head()}. Starts with a volatile store: see the class notes on reading. */
	public boolean valid(long sec)
	{
		order = 0;
		final long f = frameHead;
		final long h = hostHead;
		return sec >= tailOf(f, h) && sec <= Math.min(f, h);
	}

	public int frames(long sec)
	{
		return frames[slot(sec)];
	}

	public int worstFrameMs(long sec)
	{
		return worstFrameMs[slot(sec)];
	}

	public int worstFrameEndMs(long sec)
	{
		return worstFrameEndMs[slot(sec)];
	}

	public int slowFrames(long sec)
	{
		return slowFrames[slot(sec)];
	}

	public int loadingMs(long sec)
	{
		return loadingMs[slot(sec)];
	}

	public int state(long sec)
	{
		return state[slot(sec)];
	}

	public int flags(long sec)
	{
		return flags[slot(sec)];
	}

	public int world(long sec)
	{
		return world[slot(sec)];
	}

	public int players(long sec)
	{
		return players[slot(sec)];
	}

	public int npcs(long sec)
	{
		return npcs[slot(sec)];
	}

	/** The map region id, 0 .. 65535. */
	public int region(long sec)
	{
		return region[slot(sec)];
	}

	public int rttMs(long sec)
	{
		return rttMs[slot(sec)];
	}

	public int rttAgeS(long sec)
	{
		return rttAgeS[slot(sec)];
	}

	public int sentUnits(long sec)
	{
		return sentUnits[slot(sec)];
	}

	public int resentUnits(long sec)
	{
		return resentUnits[slot(sec)];
	}

	/**
	 * Why second {@code sec} has no fresh RTT: {@link NoData#NONE} in exactly the seconds whose RTT is fresh
	 * ({@code rttMs >= 0} and {@code 0 <= rttAgeS <= RTT_STALE_S}, contract 3.3), else the reason.
	 */
	public NoData conn(long sec)
	{
		return CONN[conn[slot(sec)]];
	}

	private int slot(long sec)
	{
		return (int) (sec % capacity);
	}

	private long tailOf(long frameHeadNow, long hostHeadNow)
	{
		return Math.max(0, Math.max(frameHeadNow, hostHeadNow) - capacity + 2);
	}

	private static short toShort(int v)
	{
		return (short) Fmt.clamp(v, -1, Short.MAX_VALUE);
	}

	private static byte toByte(int v)
	{
		return (byte) Fmt.clamp(v, 0, Byte.MAX_VALUE);
	}
}

package com.whylag.core;

import java.util.concurrent.atomic.AtomicLongArray;

/**
 * The plugin's own cost on its three paths, for developer mode (contract 3.9): the frame and tick handlers on the
 * client thread, the one-second step on the sampler thread.
 *
 * <p>{@link #add} records whatever it is given; the caller asks {@link #on()} first and times the path only when it
 * is on. It allocates nothing, takes no lock and may be called from any thread (atomic counters), so it is safe on
 * the frame path. {@link #footer()} builds the developer-mode line of the panel.
 */
public final class SelfTimer
{
	public static final int FRAME = 0, TICK = 1, STEP = 2;

	private static final int PATHS = 3;
	private static final long NANOS_PER_MICRO = 1_000L;
	private static final long NANOS_PER_MILLI = 1_000_000L;

	private final AtomicLongArray count = new AtomicLongArray(PATHS);
	private final AtomicLongArray sum = new AtomicLongArray(PATHS);
	private final AtomicLongArray max = new AtomicLongArray(PATHS);
	private volatile boolean on;

	/** True while timing is wanted. */
	public boolean on()
	{
		return on;
	}

	public void on(boolean v)
	{
		on = v;
	}

	/** One timing of {@code path} ({@link #FRAME}, {@link #TICK} or {@link #STEP}); another path is ignored. */
	public void add(int path, long nanos)
	{
		if (path < 0 || path >= PATHS)
		{
			return;
		}
		count.incrementAndGet(path);
		sum.addAndGet(path, nanos);
		long seen = max.get(path);
		while (nanos > seen && !max.compareAndSet(path, seen, nanos))
		{
			seen = max.get(path);
		}
	}

	/** Timings recorded for {@code path} since the last reset; 0 for another path. */
	public long count(int path)
	{
		return path < 0 || path >= PATHS ? 0 : count.get(path);
	}

	/** The mean timing of {@code path}, 0 when none. */
	public long meanNanos(int path)
	{
		if (path < 0 || path >= PATHS)
		{
			return 0;
		}
		final long n = count.get(path);
		return n == 0 ? 0 : sum.get(path) / n;
	}

	/** The longest timing of {@code path}, 0 when none. */
	public long maxNanos(int path)
	{
		return path < 0 || path >= PATHS ? 0 : max.get(path);
	}

	/** Forgets every timing. */
	public void reset()
	{
		for (int path = 0; path < PATHS; path++)
		{
			count.set(path, 0);
			sum.set(path, 0);
			max.set(path, 0);
		}
	}

	/**
	 * The means as one line, "self: frame 180 ns, tick 2 us, step 40 us": under 1 us in ns, under 1 ms in whole us,
	 * else in whole ms. A path with no timing yet reads "-".
	 */
	public String footer()
	{
		return "self: frame " + text(FRAME) + ", tick " + text(TICK) + ", step " + text(STEP);
	}

	private String text(int path)
	{
		if (count.get(path) == 0)
		{
			return "-";
		}
		final long mean = meanNanos(path);
		if (mean < NANOS_PER_MICRO)
		{
			return mean + " ns";
		}
		if (mean < NANOS_PER_MILLI)
		{
			return (mean / NANOS_PER_MICRO) + " us";
		}
		return (mean / NANOS_PER_MILLI) + " ms";
	}
}

package com.whylag.core;

import java.time.ZoneId;

/**
 * The rings and the clocks of one plugin session, as one object (contract 3.5). Everything is allocated here,
 * once: each ring ONE SLOT LARGER than its constant, so the readable span is the constant itself (the one slot of
 * slack, section 3.3).
 *
 * <p><b>One writer for each piece.</b> The frame columns of {@link #seconds} and {@link #ticks}: the samplers, on
 * the client thread. The host columns of {@link #seconds}: the engine, on the sampler thread. {@link #events}: the
 * engine, on the sampler thread. The three usuals: the detector alone, on the sampler thread;
 * {@link #rttUsual} is reset by it when the {@code world} column changes from one second to the next. The login
 * second ({@link #loggedInSince}): {@code LagEngine.gameState} alone, on the client thread (and the test helper
 * {@code Trace}). Everyone else only reads.
 *
 * <p>Session time: second 0 starts at {@link #startNanos} ({@code System.nanoTime()} at start) and at wall time
 * {@link #startWallMs}; session ms count from the same instant. Session ms are {@code long} everywhere, so they
 * never wrap, however long the client runs.
 *
 * <p><b>Where the warm-up counts from.</b> {@link #loggedInSinceSec()} is the session second in which the CURRENT
 * logged-in stretch began: {@link #NEVER} until a login is seen. It is the one mutable field of a session, a
 * volatile long, written once per login by its one writer and read by the verdict and the snapshot through
 * {@link #warm} and {@link #warmupLeftS}, the one rule for both. It is never set back to {@link #NEVER}.
 *
 * <p><b>Now, and the newest second</b> (contract 3.5). {@code nowSec} is the clock's session second at a step,
 * {@code secOf(nanos)}: it runs on while the client is stalled or minimised, and the rings do not. Two helpers turn
 * it into ring terms, so the verdict and the snapshot read the same seconds: {@link #lastSec} is the newest
 * COMPLETE second (every "newest second" and "the window" count back from it), and {@link #framesStopped} is the
 * one rule for "no frame for longer than {@link Thresholds#NO_FRAMES_MS}".
 */
public final class Session
{
	/** {@link #loggedInSinceSec()} before any login is seen. */
	public static final long NEVER = Long.MAX_VALUE;

	/** The highest RTT, in ms, a ping usual keeps; above it a sample is clamped. */
	private static final int RTT_USUAL_MAX_MS = 2000;
	/** The highest frame rate the frame rate usual keeps. */
	private static final int FPS_USUAL_MAX = 1000;
	private static final long NANOS_PER_SECOND = 1_000_000_000L;
	private static final long NANOS_PER_MS = 1_000_000L;
	private static final long MS_PER_SECOND = 1000L;
	/**
	 * How far the frame head must lag the clock before "no frame for longer than NO_FRAMES_MS" is CERTAIN: the two
	 * seconds the newest frame may still lie in (the one it closed and the one after), plus NO_FRAMES_MS rounded up
	 * to whole seconds. Clock arithmetic, not a threshold of its own.
	 */
	private static final long FRAMES_STOPPED_BEHIND_S = 2 + (Thresholds.NO_FRAMES_MS + MS_PER_SECOND - 1) / MS_PER_SECOND;

	public final long startNanos, startWallMs;
	public final Os os;
	public final ZoneId zone;
	/** {@link Thresholds#SECONDS} + 1 slots. */
	public final SecondRing seconds;
	/** {@link Thresholds#TICKS} + 1 slots. */
	public final TickRing ticks;
	/** {@link Thresholds#EVENTS} events. */
	public final EventLog events;
	/** This world's RTT; max 2000; reset when the world COLUMN changes. */
	public final Usual rttUsual;
	/** Every world's RTT this session; max 2000. */
	public final Usual rttSession;
	/** Frames a second; max 1000. */
	public final Usual fpsUsual;

	/** The session second the current logged-in stretch began; {@link #NEVER} until a login is seen. */
	private volatile long loggedInSinceSec = NEVER;

	public Session(long startNanos, long startWallMs, Os os, ZoneId zone)
	{
		this.startNanos = startNanos;
		this.startWallMs = startWallMs;
		this.os = os;
		this.zone = zone;
		seconds = new SecondRing(Thresholds.SECONDS + 1);
		ticks = new TickRing(Thresholds.TICKS + 1);
		events = new EventLog(Thresholds.EVENTS);
		rttUsual = new Usual(RTT_USUAL_MAX_MS);
		rttSession = new Usual(RTT_USUAL_MAX_MS);
		fpsUsual = new Usual(FPS_USUAL_MAX);
	}

	/** The session second of a {@code System.nanoTime()} reading: {@code floor((nanos - startNanos) / 1e9)}. */
	public long secOf(long nanos)
	{
		return Math.floorDiv(nanos - startNanos, NANOS_PER_SECOND);
	}

	/** The wall time at which session second {@code sec} starts: {@code startWallMs + sec * 1000}. */
	public long wallMsOf(long sec)
	{
		return startWallMs + sec * MS_PER_SECOND;
	}

	/** Session ms of a {@code System.nanoTime()} reading, rounded down: {@code floor((nanos - startNanos) / 1e6)}. */
	public long msOf(long nanos)
	{
		return Math.floorDiv(nanos - startNanos, NANOS_PER_MS);
	}

	/** Session ms at which second {@code sec} starts: {@code sec * 1000}. */
	public long msOfSec(long sec)
	{
		return sec * MS_PER_SECOND;
	}

	/** The session second the current logged-in stretch began; {@link #NEVER} in a new session. A volatile read. */
	public long loggedInSinceSec()
	{
		return loggedInSinceSec;
	}

	/**
	 * A logged-in stretch began in session second {@code sec}. ONE writer: {@code LagEngine.gameState}, on the client
	 * thread, by the rule of contract 3.5 (and the test helper {@code Trace}). One volatile write.
	 */
	public void loggedInSince(long sec)
	{
		loggedInSinceSec = sec;
	}

	/** True once {@link Thresholds#WARMUP_S} seconds have passed since the login: never before a login is seen. */
	public boolean warm(long nowSec)
	{
		final long since = loggedInSinceSec;
		return since != NEVER && nowSec - since >= Thresholds.WARMUP_S;
	}

	/**
	 * Seconds of warm-up left at {@code nowSec}: 0 when {@link #warm}; {@link Thresholds#WARMUP_S} while no login is
	 * seen; else {@code WARMUP_S - (nowSec - since)}, held in 1 .. {@code WARMUP_S}.
	 * <p>Choice: with no warm-up ({@code WARMUP_S} 0 since the first live look, 2026-09-29) this is 0 from the login
	 * second on and 1 before it, where {@link #warm} is false.
	 */
	public int warmupLeftS(long nowSec)
	{
		final long since = loggedInSinceSec;
		if (since == NEVER)
		{
			return Thresholds.WARMUP_S;
		}
		final long elapsed = nowSec - since;
		if (elapsed >= Thresholds.WARMUP_S)
		{
			return 0;
		}
		return (int) Math.max(1, Math.min(Thresholds.WARMUP_S, Thresholds.WARMUP_S - elapsed));
	}

	/**
	 * The newest COMPLETE second at {@code nowSec}: {@code min(seconds.head(), nowSec - 1)}; -1 when there is none
	 * yet (or it is no longer readable). Live, {@code nowSec} is the clock's second at the step and this is
	 * {@code seconds.head()}. A test that replays one trace at an earlier {@code nowSec} sees nothing after
	 * {@code nowSec - 1}, as a live step would; "now" at the end of a trace of n seconds is {@code nowSec = n}.
	 */
	public long lastSec(long nowSec)
	{
		if (nowSec < 1)
		{
			return -1;
		}
		final long last = Math.min(seconds.head(), nowSec - 1);
		return last < seconds.tail() ? -1 : last;
	}

	/**
	 * True when no frame has been drawn for CERTAINLY longer than {@link Thresholds#NO_FRAMES_MS} at {@code nowSec}:
	 * the card's "Waiting for the game" and the frame tile's "No frames drawn" both read this. A frame head F means
	 * the newest frame came in [F + 1, F + 2) seconds (the frame that closed F; none since has closed F + 1), so at
	 * {@code nowSec} it is more than {@code nowSec - F - 2} seconds old. True once that alone is past NO_FRAMES_MS:
	 * {@code nowSec - frameHead >= 2 + ceil(NO_FRAMES_MS / 1000)}, 4 seconds at the starting 2,000 ms. While frames
	 * run the head is 1 or 2 seconds behind the clock; after a stall this turns true 2 to 3 s after the last frame.
	 * Before the first frame it turns true at second 3. Only the frame head counts: the host columns run on without
	 * the client.
	 */
	public boolean framesStopped(long nowSec)
	{
		return nowSec - seconds.frameHead() >= FRAMES_STOPPED_BEHIND_S;
	}
}

package com.whylag.core;

/**
 * The settings that change a verdict, read-only and immutable (contract 3.7), and the one rule for the frame cap
 * in force.
 *
 * <p>{@code vsyncMode} is the active renderer's own key, "OFF", "ON", "ADAPTIVE", or "" when it was not read;
 * {@code antiAliasing} the stored enum name ("" unknown); {@code clientVersion} "" when unknown. Null strings are
 * kept as "" and a null renderer as {@link Renderer#UNKNOWN}.
 *
 * <p><b>Which focus a reader passes</b> (contract 3.7). The four cap reads take the window's focus. A reader passes
 * the FOCUSED flag of the one second it judges, never a constant; only the report, which reads no second, prints
 * the focused cap.
 *
 * <p><b>The cap rule</b> (skeptic C9, C10, C11). There are TWO candidates, one from FPS Control and one from the
 * renderer. The LOWER of the two wins; a tie goes to FPS Control. A candidate of 0 or less is no cap and takes no
 * part (117 HD's target may be 0, "no target"; it must not win "lower", and {@link #capIntervalMs} must never divide
 * by it).
 *
 * <p>FPS Control's candidate is ONE of lines 1 and 2, never both. RuneLite's own limiter reads
 * {@code fps = limitFpsUnfocused && !focused ? maxFpsUnfocused : maxFps} ({@code FpsDrawListener.reloadConfig()}),
 * so while the window is unfocused and the unfocused limit is on, {@code maxFps} is NOT in force, even when lower:
 * <ol>
 * <li>FPS Control active, the window unfocused, its unfocused limit on: {@code maxFpsUnfocused},
 * FPS_CONTROL_UNFOCUSED. Line 2 is then not read; with {@code maxFpsUnfocused <= 0} FPS Control gives nothing.</li>
 * <li>Otherwise, FPS Control active and its limit on: {@code maxFps}, FPS_CONTROL. With {@code maxFps <= 0} it gives
 * nothing.</li>
 * </ol>
 * The renderer's candidate is ONE of lines 3 to 5:
 * <ol start="3">
 * <li>GPU or 117 HD, {@code unlockFps}, V-Sync "OFF", {@code fpsTarget > 0}: the target, GPU_TARGET / HD_TARGET.</li>
 * <li>GPU or 117 HD, {@code unlockFps}, V-Sync "ON" or "ADAPTIVE", {@code refreshHz > 0}: the refresh rate,
 * GPU_VSYNC / HD_VSYNC.</li>
 * <li>CPU, or GPU / 117 HD with {@code unlockFps} off: the client's own {@link Thresholds#CLIENT_CAP_FPS},
 * CLIENT_50.</li>
 * <li>An {@link Renderer#UNKNOWN} renderer: no renderer candidate; lines 1 and 2 only.</li>
 * </ol>
 * Worked case: FPS Control's limit on at 20, its unfocused limit on at 40, GPU unlocked with a target of 144.
 * Focused: 20, FPS_CONTROL. Unfocused: 40, FPS_CONTROL_UNFOCUSED (not 20).
 */
public final class SettingsView
{
	private static final int MS_PER_SECOND = 1000;
	private static final int PERCENT = 100;
	private static final String VSYNC_OFF = "OFF";
	private static final String VSYNC_ON = "ON";
	private static final String VSYNC_ADAPTIVE = "ADAPTIVE";

	public final Renderer renderer;
	public final boolean fpsControlActive, limitFps, limitFpsUnfocused, unlockFps;
	public final int maxFps, maxFpsUnfocused, fpsTarget, drawDistance, expandedMapLoading, refreshHz;
	/** "OFF" | "ON" | "ADAPTIVE" | "" (the renderer's own key, read only while it is active). */
	public final String vsyncMode;
	/** The stored enum name, "" = unknown. */
	public final String antiAliasing;
	public final Os os;
	/** "" = unknown. */
	public final String clientVersion;

	public SettingsView(Renderer renderer, boolean fpsControlActive, boolean limitFps, int maxFps,
		boolean limitFpsUnfocused, int maxFpsUnfocused, boolean unlockFps, String vsyncMode, int fpsTarget,
		int drawDistance, String antiAliasing, int expandedMapLoading, int refreshHz, Os os, String clientVersion)
	{
		this.renderer = renderer == null ? Renderer.UNKNOWN : renderer;
		this.fpsControlActive = fpsControlActive;
		this.limitFps = limitFps;
		this.maxFps = maxFps;
		this.limitFpsUnfocused = limitFpsUnfocused;
		this.maxFpsUnfocused = maxFpsUnfocused;
		this.unlockFps = unlockFps;
		this.vsyncMode = vsyncMode == null ? "" : vsyncMode;
		this.fpsTarget = fpsTarget;
		this.drawDistance = drawDistance;
		this.antiAliasing = antiAliasing == null ? "" : antiAliasing;
		this.expandedMapLoading = expandedMapLoading;
		this.refreshHz = refreshHz;
		this.os = os;
		this.clientVersion = clientVersion == null ? "" : clientVersion;
	}

	/**
	 * Settings not read yet: renderer {@link Renderer#UNKNOWN}, no cap known, refresh 0, every other number 0 and
	 * every text "".
	 */
	public static SettingsView unknown(Os os)
	{
		return new SettingsView(Renderer.UNKNOWN, false, false, 0, false, 0, false, "", 0, 0, "", 0, 0, os, "");
	}

	/** The cap in force; 0 = no cap known. */
	public int capFps(boolean focused)
	{
		return fpsOf(capSource(focused));
	}

	/** Who set the cap in force; {@link CapSource#NONE} when there is none. See the class notes. */
	public CapSource capSource(boolean focused)
	{
		final CapSource fpsControl = fpsControlCap(focused);
		final CapSource own = rendererCap();
		final int fpsControlFps = fpsOf(fpsControl);
		final int ownFps = fpsOf(own);
		if (fpsControlFps <= 0)
		{
			return ownFps > 0 ? own : CapSource.NONE;
		}
		// The lower of the two wins; a tie goes to FPS Control.
		return ownFps > 0 && ownFps < fpsControlFps ? own : fpsControl;
	}

	/** {@code 1000 / capFps}, or 0 when there is no cap. */
	public int capIntervalMs(boolean focused)
	{
		final int cap = capFps(focused);
		return cap > 0 ? MS_PER_SECOND / cap : 0;
	}

	/** The frame gap trigger: {@code max(FRAME_GAP_MS, capIntervalMs * FRAME_GAP_CAP_PCT / 100)}. */
	public int frameGapLimitMs(boolean focused)
	{
		return Math.max(Thresholds.FRAME_GAP_MS, capIntervalMs(focused) * Thresholds.FRAME_GAP_CAP_PCT / PERCENT);
	}

	/**
	 * Lines 1 and 2 of the cap rule: FPS Control's ONE candidate, as RuneLite's {@code FpsDrawListener} reads it, or
	 * NONE. Unfocused with the unfocused limit on, line 2 is not read, even when its cap is lower or line 1's is 0.
	 */
	private CapSource fpsControlCap(boolean focused)
	{
		if (!fpsControlActive)
		{
			return CapSource.NONE;
		}
		if (!focused && limitFpsUnfocused)
		{
			return maxFpsUnfocused > 0 ? CapSource.FPS_CONTROL_UNFOCUSED : CapSource.NONE;
		}
		return limitFps && maxFps > 0 ? CapSource.FPS_CONTROL : CapSource.NONE;
	}

	/** Lines 3 to 6 of the cap rule: what the renderer itself caps at, or NONE. */
	private CapSource rendererCap()
	{
		switch (renderer)
		{
			case CPU:
				return CapSource.CLIENT_50;
			case GPU:
			case HD:
				if (!unlockFps)
				{
					return CapSource.CLIENT_50;
				}
				final boolean hd = renderer == Renderer.HD;
				if (VSYNC_OFF.equals(vsyncMode))
				{
					return fpsTarget > 0 ? (hd ? CapSource.HD_TARGET : CapSource.GPU_TARGET) : CapSource.NONE;
				}
				if (VSYNC_ON.equals(vsyncMode) || VSYNC_ADAPTIVE.equals(vsyncMode))
				{
					return refreshHz > 0 ? (hd ? CapSource.HD_VSYNC : CapSource.GPU_VSYNC) : CapSource.NONE;
				}
				return CapSource.NONE;
			default:
				return CapSource.NONE;
		}
	}

	/** The frame rate a cap source stands for in THESE settings; 0 for NONE. */
	private int fpsOf(CapSource source)
	{
		switch (source)
		{
			case FPS_CONTROL_UNFOCUSED:
				return Math.max(0, maxFpsUnfocused);
			case FPS_CONTROL:
				return Math.max(0, maxFps);
			case GPU_TARGET:
			case HD_TARGET:
				return Math.max(0, fpsTarget);
			case GPU_VSYNC:
			case HD_VSYNC:
				return Math.max(0, refreshHz);
			case CLIENT_50:
				return Thresholds.CLIENT_CAP_FPS;
			default:
				return 0;
		}
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Builds what the panel reads (contract 3.8, 5.2, 5.3; lot L5): the three tiles, the three strips with the value at
 * the right of each lane, the world of now, the range's events, the session's events and the session counts.
 * The plugin calls it once a second on the sampler thread, under the engine's step lock, while the panel shows. It
 * only READS the session - the rings, the event log and this world's RTT usual - and writes nothing: it keeps no state
 * of its own, so one instance serves every call.
 *
 * <p><b>Now.</b> Every "now" is the newest COMPLETE second, {@code last = s.lastSec(nowSec)} (contract 3.5); -1 means
 * none yet. The player is logged in when that second exists and its state is in-game ({@link State#inGame}). While
 * not, every tile is "-" with "Not logged in", every lane has no value now and the snapshot's {@code world} is 0
 * whatever the world column holds. The warm-up is the card's alone: the tiles show their
 * numbers through it, and nothing here reads {@link Session#warm}.
 *
 * <p><b>The window</b> (contract 3.5) is the seconds {@code last - WINDOW_S + 1 .. last}, none before the ring's
 * tail. Its ticks are those that arrived in {@code [msOfSec(first), msOfSec(last + 1))} and are not masked: no bit
 * of {@link Flags#MASKED} on the tick nor on the second it arrived in (a hop's or a teleport's tick is no lag). The
 * Frame rate tile's "worst" is the largest {@code worstFrameMs} of the window's seconds; the Server ticks tile reads
 * the window's ticks.
 *
 * <p><b>The time map</b> (contract 5.3). The range ends at the end of the newest second: {@code msOfSec(last + 1)} in
 * session ms, {@code s.wallMsOf(last + 1)} in wall ms, and starts {@code rangeMinutes x 60,000} ms before it - or at
 * session ms 0, the session's first second, while the session holds less than the range: the columns then STRETCH
 * the data held over the full width, and the snapshot's range start says so (changes after the first live look);
 * {@link Strip#columnOf} and {@link Strip#columnStart} cut it into {@link Thresholds#STRIP_COLUMNS} columns. A second
 * belongs to every column its milliseconds touch and COUNTS when it is readable, no later than {@code last}, and not
 * flagged NOT_LOGGED_IN. A tick's gap belongs to the columns of the time it spanned, {@code atMs - gapMs .. atMs}; it
 * counts when it arrived before the range's end and is not masked (above). A column with no counting second is
 * {@link Strip#NONE} in all three lanes; a column whose counting seconds are all masked ({@link Flags#masked}) is
 * {@link Strip#NONE} in the frame rate and ticks lanes, so a load's frame-rate dip and a hop's tick gap are not
 * drawn. A column holds the WORST of its slice: the lowest {@code frames}, the largest gap, the highest FRESH RTT;
 * a -1 counts for nothing.
 *
 * <p><b>Reading the rings.</b> A second or a tick is read and then checked with {@code valid} again; a read that fails
 * the check is thrown away, as contract 3.3 asks. The event log's lists and counts are read in one hold of its lock.
 *
 * <p>Choice: a range of less than one minute is built as one minute, the shortest range the column map needs.
 * <p>Choice: with no complete second yet the range is the full chosen range (nothing is drawn); the stretch starts
 * with the first second.
 * <p>Choice: a column that holds both masked and unmasked seconds keeps the worst UNMASKED tick and frame rate; only a
 * column with no unmasked second is a gap. The ping lane keeps masked seconds: they are real readings, not a lag
 * the game made.
 * <p>Choice: a null settings view is built as {@code SettingsView.unknown(s.os)}, so nothing throws.
 * <p>Choice: the event log is read under its own lock, so the listed events, the counts and the total agree.
 * <p>Choice: the frame rate scale's "highest seen" is the highest column value drawn.
 * <p>Choice: the ping scale rounds {@code highest x STRIP_PING_PAD_PCT / 100} UP, so its top is at least that share.
 * <p>Choice: the Ping tile shows its RTT only while {@code conn} is NONE and the RTT is 0 or more; else "Nothing sent".
 * <p>Choice: a newest second with a negative frame count is a Frame rate dash with "Could not read it" (never written).
 */
public final class SnapshotBuilder implements SnapshotSource
{
	private static final int COLUMNS = Thresholds.STRIP_COLUMNS;
	private static final int LAST_COLUMN = COLUMNS - 1;
	/** The shortest range the column map takes, in minutes. */
	private static final int SHORTEST_RANGE_MINUTES = 1;
	private static final int SECONDS_PER_MINUTE = 60;
	private static final long MS_PER_MINUTE = 60_000L;
	private static final long MS_PER_SECOND = 1000L;
	/** From a second's first millisecond to its last. */
	private static final int LAST_MS_OF_SECOND = 999;
	private static final int PERCENT = 100;
	/** The Server ticks tile's small line: "plus-minus 13 ms" (contract 5.2). */
	private static final String PLUS_MINUS = "\u00b1";
	private static final String DASH = "-";

	public SnapshotBuilder()
	{
	}

	@Override
	public PanelSnapshot build(Session s, Verdict shown, int rangeMinutes, long nowSec, long wallMs,
		SettingsView settings, String footer)
	{
		final SettingsView view = settings != null ? settings : SettingsView.unknown(s.os);
		final int minutes = Math.max(SHORTEST_RANGE_MINUTES, rangeMinutes);
		final Pass p = new Pass(s, view, minutes, nowSec);
		p.readNewest();
		p.readSeconds();
		p.readTicks();
		final Tile[] tiles = {p.frameTile(), p.tickTile(), p.pingTile()};
		final Strip[] strips = {
			p.frameStrip(tiles[Lane.FRAME_RATE.ordinal()]),
			p.tickStrip(tiles[Lane.TICKS.ordinal()]),
			p.pingStrip(tiles[Lane.PING.ordinal()])};

		final List<LagEvent> rangeEvents;
		final List<LagEvent> sessionEvents = new ArrayList<>();
		final int[] counts = new int[Group.values().length];
		final int total;
		// Every method of EventLog holds its own lock (contract 3.4); holding it across the reads keeps them in step.
		synchronized (s.events)
		{
			rangeEvents = s.events.between(p.last + 1 - (long) minutes * SECONDS_PER_MINUTE, p.last);
			for (LagEvent e : s.events.copy())
			{
				if (!e.open)
				{
					sessionEvents.add(e);
				}
			}
			for (Group g : Group.values())
			{
				counts[g.ordinal()] = s.events.sessionCount(g);
			}
			total = s.events.sessionTotal();
		}

		final long rangeEndWallMs = s.wallMsOf(p.last + 1);
		return new PanelSnapshot(wallMs, s.zone, p.worldNow(), shown, tiles, minutes,
			rangeEndWallMs - (p.endMs - p.startMs), rangeEndWallMs, strips, rangeEvents, sessionEvents, counts, total,
			s.startWallMs, view, footer);
	}

	/** The work of one build: the reads of the newest second, the window's sums, and the columns of the three lanes. */
	private static final class Pass
	{
		private final Session s;
		private final SettingsView settings;
		private final long nowSec;
		/** The newest complete second; -1 = none yet. */
		private final long last;
		/** The range in session ms, {@code [startMs, endMs)}. */
		private final long startMs;
		private final long endMs;
		/** The first second of the range and of the window, none before the ring's tail. */
		private final long rangeFirst;
		private final long windowFirst;

		// The newest second.
		private boolean loggedIn;
		/** Its FOCUSED flag; the focused cap while there is no newest second (contract 3.7). */
		private boolean focused = true;
		private int frames;
		private int world;
		private int rttMs = -1;
		private NoData conn = NoData.NONE;

		// The window.
		private int worstFrameMs;
		private int ticks;
		private long gapSum;
		private int keptTicks;
		private long keptGapSum;
		private int widestRawMs;
		private int worstCorrectedMs = -1;
		private int longestGapMs;

		// The columns.
		private final boolean[] counting = new boolean[COLUMNS];
		/** A counting second of the column is not masked ({@link Flags#masked}): the ticks and frame rate may draw. */
		private final boolean[] unmasked = new boolean[COLUMNS];
		private final int[] fps = none();
		/** The FOCUSED flag of the second that gave each frame rate column its value. */
		private final boolean[] fpsFocused = new boolean[COLUMNS];
		private final int[] gaps = none();
		private final int[] corrected = none();
		private final int[] ping = none();

		Pass(Session s, SettingsView settings, int minutes, long nowSec)
		{
			this.s = s;
			this.settings = settings;
			this.nowSec = nowSec;
			last = s.lastSec(nowSec);
			endMs = s.msOfSec(last + 1);
			final long fullStart = endMs - minutes * MS_PER_MINUTE;
			// Less data than the range: the span is the data held, from the session's first second, stretched.
			startMs = last < 0 ? fullStart : Math.max(fullStart, s.msOfSec(0));
			final long tail = s.seconds.tail();
			rangeFirst = Math.max(last + 1 - (long) minutes * SECONDS_PER_MINUTE, tail);
			windowFirst = Math.max(last - Thresholds.WINDOW_S + 1, tail);
		}

		/** The newest second's columns, and whether the player is logged in. */
		void readNewest()
		{
			if (last < 0)
			{
				return;
			}
			final SecondRing r = s.seconds;
			final int state = r.state(last);
			final int flags = r.flags(last);
			final int f = r.frames(last);
			final int w = r.world(last);
			final int rtt = r.rttMs(last);
			final NoData c = r.conn(last);
			if (!r.valid(last))
			{
				return;
			}
			loggedIn = State.inGame(state);
			focused = Flags.has(flags, Flags.FOCUSED);
			frames = f;
			world = w;
			rttMs = rtt;
			conn = c;
		}

		/** One pass over the range's seconds: the window's worst frame, and the second lanes' columns. */
		void readSeconds()
		{
			final SecondRing r = s.seconds;
			for (long k = rangeFirst; k <= last; k++)
			{
				if (!r.valid(k))
				{
					continue;
				}
				final int flags = r.flags(k);
				final int f = r.frames(k);
				final int worst = r.worstFrameMs(k);
				final int rtt = r.rttMs(k);
				final int age = r.rttAgeS(k);
				if (!r.valid(k))
				{
					continue;
				}
				if (k >= windowFirst && worst > worstFrameMs)
				{
					worstFrameMs = worst;
				}
				if (Flags.has(flags, Flags.NOT_LOGGED_IN))
				{
					continue;
				}
				final long at = s.msOfSec(k);
				final int c0 = Math.max(0, Strip.columnOf(startMs, endMs, at));
				final int c1 = Math.min(LAST_COLUMN, Strip.columnOf(startMs, endMs, at + LAST_MS_OF_SECOND));
				final boolean foc = Flags.has(flags, Flags.FOCUSED);
				final boolean fresh = rtt >= 0 && age >= 0 && age <= Thresholds.RTT_STALE_S;
				final boolean clear = !Flags.masked(flags);
				for (int c = c0; c <= c1; c++)
				{
					counting[c] = true;
					unmasked[c] |= clear;
					// "<=": of several seconds with the lowest rate, the newest gives the column its focus (3.7).
					if (clear && f >= 0 && (fps[c] == Strip.NONE || f <= fps[c]))
					{
						fps[c] = f;
						fpsFocused[c] = foc;
					}
					if (fresh && rtt > ping[c])
					{
						ping[c] = rtt;
					}
				}
			}
		}

		/** One pass over the ticks, newest first: the window's tick sums, and the ticks lane's columns. */
		void readTicks()
		{
			if (last < 0)
			{
				return;
			}
			final TickRing t = s.ticks;
			final long windowStartMs = s.msOfSec(windowFirst);
			for (long seq = t.head(); seq >= 0; seq--)
			{
				if (!t.valid(seq))
				{
					break;
				}
				final long at = t.atMs(seq);
				final int gap = Math.max(0, t.gapMs(seq));
				final int flags = t.flags(seq);
				final int corr = t.corrected(seq);
				if (!t.valid(seq))
				{
					break;
				}
				if (at < startMs)
				{
					break;   // ticks arrive in order: this one and every older one ended before the range
				}
				if (at >= endMs || Flags.masked(flags) || secondMasked(Math.floorDiv(at, MS_PER_SECOND)))
				{
					continue;   // arrived at or after the range's end (not drawn yet), or a login, hop or load's tick
				}
				if (at >= windowStartMs)
				{
					ticks++;
					gapSum += gap;
					if (gap <= Thresholds.TICK_TRIM_MS)
					{
						keptTicks++;
						keptGapSum += gap;
					}
					widestRawMs = Math.max(widestRawMs, Math.abs(gap - Thresholds.TICK_MS));
					worstCorrectedMs = Math.max(worstCorrectedMs, corr);
					longestGapMs = Math.max(longestGapMs, gap);
				}
				final int c0 = Math.max(0, Strip.columnOf(startMs, endMs, at - gap));
				final int c1 = Strip.columnOf(startMs, endMs, at);
				for (int c = c0; c <= c1; c++)
				{
					if (gap > gaps[c])
					{
						gaps[c] = gap;
					}
					if (corr > corrected[c])
					{
						corrected[c] = corr;
					}
				}
			}
		}

		/** The second a tick arrived in is readable and masked by its flags ({@link Flags#masked}). */
		private boolean secondMasked(long sec)
		{
			final SecondRing r = s.seconds;
			if (!r.valid(sec))
			{
				return false;
			}
			final int flags = r.flags(sec);
			return r.valid(sec) && Flags.masked(flags);
		}

		Tile frameTile()
		{
			if (!loggedIn)
			{
				return dash(Lane.FRAME_RATE, NoData.NOT_LOGGED_IN);
			}
			if (s.framesStopped(nowSec))
			{
				return dash(Lane.FRAME_RATE, NoData.NO_FRAMES);
			}
			if (frames < 0)
			{
				return dash(Lane.FRAME_RATE, NoData.ERROR);
			}
			return new Tile(Lane.FRAME_RATE, fpsLevel(frames, focused), Fmt.thousands(frames) + " fps",
				"worst " + Fmt.thousands(worstFrameMs) + " ms", NoData.NONE);
		}

		/**
		 * The window's mean gap, rounded down, with the gaps over {@link Thresholds#TICK_TRIM_MS} left out (the mean of
		 * all of them when that leaves none); its largest RAW deviation, or the longest gap once the largest CORRECTED
		 * deviation reaches {@link Thresholds#TICK_BAD_MS}; the level on the largest corrected deviation.
		 */
		Tile tickTile()
		{
			if (!loggedIn)
			{
				return dash(Lane.TICKS, NoData.NOT_LOGGED_IN);
			}
			if (ticks == 0)
			{
				return dash(Lane.TICKS, NoData.NO_TICKS);
			}
			final long mean = keptTicks > 0 ? keptGapSum / keptTicks : gapSum / ticks;
			final String sub = worstCorrectedMs >= Thresholds.TICK_BAD_MS
				? "worst " + Fmt.thousands(longestGapMs)
				: PLUS_MINUS + Fmt.thousands(widestRawMs) + " ms";
			return new Tile(Lane.TICKS, Levels.tick(worstCorrectedMs), Fmt.thousands((int) mean) + " ms", sub,
				NoData.NONE);
		}

		/** The newest second's RTT while its {@code conn} is NONE, with this world's usual; else the reason. */
		Tile pingTile()
		{
			if (!loggedIn)
			{
				return dash(Lane.PING, NoData.NOT_LOGGED_IN);
			}
			if (conn != NoData.NONE || rttMs < 0)
			{
				return dash(Lane.PING, conn != NoData.NONE ? conn : NoData.STALE);
			}
			final int usual = s.rttUsual.median();
			final String sub = usual < 0 ? "" : "was " + Fmt.thousands(usual) + " ms";
			return new Tile(Lane.PING, Levels.ping(rttMs), Fmt.thousands(rttMs) + " ms", sub, NoData.NONE);
		}

		/** Frame rate: 0 .. max(STRIP_FPS_MAX, the newest second's cap, the highest column); each column by its cap. */
		Strip frameStrip(Tile tile)
		{
			final byte[] levels = noDataLevels();
			int highest = 0;
			for (int c = 0; c < COLUMNS; c++)
			{
				if (fps[c] != Strip.NONE)
				{
					levels[c] = ordinal(fpsLevel(fps[c], fpsFocused[c]));
					highest = Math.max(highest, fps[c]);
				}
			}
			final int top = Math.max(Thresholds.STRIP_FPS_MAX, Math.max(settings.capFps(focused), highest));
			return new Strip(Lane.FRAME_RATE, fps, levels, 0, top, valueOf(tile), levelOf(tile));
		}

		/** Ticks: STRIP_TICK_MIN_MS .. max(STRIP_TICK_MAX_MS, longest gap + STRIP_TICK_PAD_MS). */
		Strip tickStrip(Tile tile)
		{
			final byte[] levels = noDataLevels();
			long longest = -1;
			for (int c = 0; c < COLUMNS; c++)
			{
				if (!counting[c] || !unmasked[c])
				{
					gaps[c] = Strip.NONE;   // no counting second, or only masked ones: a gap in the line
				}
				else if (gaps[c] != Strip.NONE)
				{
					levels[c] = ordinal(Levels.tick(corrected[c]));
					longest = Math.max(longest, gaps[c]);
				}
			}
			final long top = longest < 0
				? Thresholds.STRIP_TICK_MAX_MS
				: Math.max(Thresholds.STRIP_TICK_MAX_MS, longest + Thresholds.STRIP_TICK_PAD_MS);
			return new Strip(Lane.TICKS, gaps, levels, Thresholds.STRIP_TICK_MIN_MS,
				(int) Math.min(Integer.MAX_VALUE, top), valueOf(tile), levelOf(tile));
		}

		/** Ping: 0 .. max(STRIP_PING_MAX_MS, the highest RTT x STRIP_PING_PAD_PCT / 100, rounded up). */
		Strip pingStrip(Tile tile)
		{
			final byte[] levels = noDataLevels();
			long highest = 0;
			for (int c = 0; c < COLUMNS; c++)
			{
				if (ping[c] != Strip.NONE)
				{
					levels[c] = ordinal(Levels.ping(ping[c]));
					highest = Math.max(highest, ping[c]);
				}
			}
			final long padded = (highest * Thresholds.STRIP_PING_PAD_PCT + PERCENT - 1) / PERCENT;
			return new Strip(Lane.PING, ping, levels, 0,
				(int) Math.min(Integer.MAX_VALUE, Math.max(Thresholds.STRIP_PING_MAX_MS, padded)), valueOf(tile),
				levelOf(tile));
		}

		/** The newest second's world while logged in; 0 while not (contract 3.8). */
		int worldNow()
		{
			return loggedIn ? world : 0;
		}

		/** The Frame rate level of {@code v} fps, under the cap in force for that focus (contract 3.7). */
		private Level fpsLevel(int v, boolean focus)
		{
			return Levels.fps(v, settings.capFps(focus), settings.capSource(focus).selfSet());
		}
	}

	private static Tile dash(Lane lane, NoData why)
	{
		return new Tile(lane, Level.NO_DATA, DASH, why.reason(), why);
	}

	/** A lane's value at the right: its tile's value, or "" when the tile shows "-". */
	private static String valueOf(Tile t)
	{
		return t.noData == NoData.NONE ? t.value : "";
	}

	private static Level levelOf(Tile t)
	{
		return t.noData == NoData.NONE ? t.level : Level.NO_DATA;
	}

	private static int[] none()
	{
		final int[] v = new int[COLUMNS];
		Arrays.fill(v, Strip.NONE);
		return v;
	}

	private static byte[] noDataLevels()
	{
		final byte[] v = new byte[COLUMNS];
		Arrays.fill(v, ordinal(Level.NO_DATA));
		return v;
	}

	private static byte ordinal(Level level)
	{
		return (byte) level.ordinal();
	}
}

