}

package com.whylag.core;


/**
 * Every tick, in arrival order, numbered by a sequence from 0 (contract 3.3). The client thread writes; any thread
 * reads. Primitive arrays allocated once; no method allocates and none takes a lock.
 *
 * <p>The same rules as {@link SecondRing}, on the sequence: one slot of slack ({@link #tail()} is
 * {@code max(0, head - capacity + 2)}, so a ring of capacity {@code n + 1} keeps {@code n} readable ticks), and a
 * reader checks {@link #valid(long)} before and after it reads, throwing the read away when the second check
 * fails.
 *
 * <p><b>Clamps</b> (the clamp table of contract 3.3): every value is clamped to its column on write and a put never
 * throws for a value. {@code frameMs}, {@code cycleJump} and {@code rttMs} are shorts, -1 .. 32767, every negative
 * stored as -1; {@code flags} a byte, 0 .. 127; {@code atMs} (a {@code long}: session ms never wrap) and
 * {@code gapMs} are kept whole.
 */
public final class TickRing
{
	private final int capacity;

	private final long[] atMs;
	private final int[] gapMs;
	private final short[] frameMs;
	private final short[] cycleJump;
	private final short[] rttMs;
	private final byte[] flags;

	private volatile long head = -1;
	/** Written at the start of {@link #valid(long)} for its ordering only; never read. */
	private volatile int order;

	/**
	 * @param capacity slots, at least 2; {@code capacity - 1} ticks are readable
	 */
	public TickRing(int capacity)
	{
		if (capacity < 2)
		{
			throw new IllegalArgumentException("a ring needs at least 2 slots, got " + capacity);
		}
		this.capacity = capacity;
		atMs = new long[capacity];
		gapMs = new int[capacity];
		frameMs = new short[capacity];
		cycleJump = new short[capacity];
		rttMs = new short[capacity];
		flags = new byte[capacity];
	}

	/** Appends one tick as sequence {@code head() + 1}. Client thread only. */
	public void put(TickRow v)
	{
		final long seq = head + 1;
		// The slot about to be reused belongs to sequence seq - capacity, already below tail(). The volatile read of
		// head above keeps that published head ahead of the column stores below on every CPU.
		final int i = slot(seq);
		atMs[i] = v.atMs;
		gapMs[i] = v.gapMs;
		frameMs[i] = toShort(v.frameMs);
		cycleJump[i] = toShort(v.cycleJump);
		rttMs[i] = toShort(v.rttMs);
		flags[i] = (byte) Fmt.clamp(v.flags, 0, Byte.MAX_VALUE);
		head = seq;
	}

	/** The sequence of the newest tick; -1 before the first. */
	public long head()
	{
		return head;
	}

	/** The oldest readable sequence: {@code max(0, head - capacity + 2)}. */
	public long tail()
	{
		return Math.max(0, head - capacity + 2);
	}

	/** {@code tail() <= seq <= head()}. Starts with a volatile store, as {@link SecondRing#valid(long)} does. */
	public boolean valid(long seq)
	{
		order = 0;
		final long h = head;
		return seq >= Math.max(0, h - capacity + 2) && seq <= h;
	}

	/** Session ms when the tick arrived. */
	public long atMs(long seq)
	{
		return atMs[slot(seq)];
	}

	public int gapMs(long seq)
	{
		return gapMs[slot(seq)];
	}

	public int frameMs(long seq)
	{
		return frameMs[slot(seq)];
	}

	public int cycleJump(long seq)
	{
		return cycleJump[slot(seq)];
	}

	public int rttMs(long seq)
	{
		return rttMs[slot(seq)];
	}

	public int flags(long seq)
	{
		return flags[slot(seq)];
	}

	/**
	 * How far the tick was off, with the frame interval taken out (C5):
	 * {@code max(0, abs(gapMs - TICK_MS) - frameMs)}. A tick can only be handled on a frame, so up to one frame
	 * interval of lateness or earliness is the client's own pacing, not the server's.
	 */
	public int corrected(long seq)
	{
		final int i = slot(seq);
		final long off = Math.abs((long) gapMs[i] - Thresholds.TICK_MS) - frameMs[i];
		return (int) Math.max(0, Math.min(Integer.MAX_VALUE, off));
	}

	/** True when the tick came later than one tick after the one before: {@code gapMs > TICK_MS}. */
	public boolean late(long seq)
	{
		return gapMs[slot(seq)] > Thresholds.TICK_MS;
	}

	/**
	 * True when the tick came sooner than one tick after the one before: {@code gapMs < TICK_MS}. A gap of exactly
	 * {@link Thresholds#TICK_MS} is neither late nor early. The evidence's {@code tickLate} and {@code tickEarly}
	 * count the late and the early ticks that are also off by {@link Thresholds#TICK_OFF_MS} or more (contract 6.3).
	 */
	public boolean early(long seq)
	{
		return gapMs[slot(seq)] < Thresholds.TICK_MS;
	}

	private int slot(long seq)
	{
		return (int) (seq % capacity);
	}

	private static short toShort(int v)
	{
		return (short) Fmt.clamp(v, -1, Short.MAX_VALUE);
	}
}

package com.whylag.core;

/**
 * One tick as the client thread saw it (contract 3.3): a mutable carrier, allocated once and reused, which
 * {@link TickRing#put} copies.
 *
 * <p>{@code atMs} is milliseconds since {@link Session#startNanos}, a {@code long} like every session ms (an int
 * would wrap after 24.8 days of uptime); {@code gapMs} the time since the tick before, 0 .. {@code Integer.MAX_VALUE};
 * {@code frameMs} the frame time that belongs to the tick - the larger of the worst CLOSED frame interval inside
 * its gap and the frame still OPEN when it arrived; {@code cycleJump} how far the game cycle moved; {@code rttMs}
 * the latest RTT when it arrived (-1 none); {@code flags} {@link Flags} bits.
 */
public final class TickRow
{
	public long atMs;
	public int gapMs, frameMs, cycleJump, rttMs, flags;
}

package com.whylag.core;

/**
 * The client thread's per-tick record (contract 3.10 and section 7, L2): one {@link TickRow} per game tick, written
 * into {@link TickRing}.
 *
 * <p><b>The tick's frame time</b> is {@code max(frames.worstFrameSinceTickMs(), frames.openFrameMs(nanos))}: after
 * a stall the client posts the tick BEFORE it draws, so the frame that holds the stall is still open when the late
 * tick arrives.
 *
 * <p><b>The session's first tick</b> has no tick before it: its gap is {@link Thresholds#TICK_MS} and its cycle
 * jump -1, so it can fire nothing. Every later gap is the difference to the tick before, held in
 * 0 .. {@code Integer.MAX_VALUE}.
 *
 * <p><b>The login mask.</b> The count of {@link Thresholds#LOGIN_MASK_TICKS} masked ticks (re)starts whenever
 * LOGGING_IN, HOPPING or CONNECTION_LOST ENDS: at the first code handed to {@link #state} after one of them that is
 * a different code. Each masked tick carries {@link Flags#LOGIN_MASK} on its own row, and the second it arrives in
 * gets the flag too.
 *
 * <p><b>Tick flags.</b> A row carries the flags of the second it arrives in, as they stand when it arrives, and
 * nothing more, as {@code Trace} writes a tick's row from its second's flags: LOADING time in the tick's gap that
 * its own second does not hold does not reach the row.
 *
 * <p>Client thread only. {@link #tick} allocates nothing and takes no lock (T1).
 *
 * <p>
 * Choice: a tick that arrives in a second which a masked tick has already marked carries
 * {@link Flags#LOGIN_MASK} by its second's flags, though it is not one of the fifteen (as {@code Trace} writes it).
 * <br>
 * Choice: a cycle jump is the difference of the two game cycles, held in -1 .. 32767 by the ring; a game cycle
 * that fell (a new login) reads -1, no data.
 */
public final class TickSampler
{
	private final Session session;
	private final FrameSampler frames;
	private final SelfTimer timer;
	/** The one carrier, reused for every tick. */
	private final TickRow row = new TickRow();

	private boolean first = true;
	private long lastAtMs;
	private int lastCycle;
	private int lastState = State.OTHER;
	private int maskLeft;

	public TickSampler(Session s, FrameSampler frames, SelfTimer timer)
	{
		this.session = s;
		this.frames = frames;
		this.timer = timer;
	}

	/**
	 * One game tick, stamped {@code nanos}, with the game cycle and the latest RTT in ms (-1 = none). Client
	 * thread; allocates nothing.
	 */
	public void tick(long nanos, int gameCycle, int latestRttMs)
	{
		final boolean timed = timer != null && timer.on();
		final long t0 = timed ? System.nanoTime() : 0L;

		final long atMs = session.msOf(nanos);
		final TickRow r = row;
		r.atMs = atMs;
		if (first)
		{
			r.gapMs = Thresholds.TICK_MS;
			r.cycleJump = -1;
		}
		else
		{
			r.gapMs = (int) Math.max(0L, Math.min(Integer.MAX_VALUE, atMs - lastAtMs));
			r.cycleJump = (int) Math.max(-1L, Math.min(Short.MAX_VALUE, (long) gameCycle - lastCycle));
		}
		r.frameMs = Math.max(frames.worstFrameSinceTickMs(), frames.openFrameMs(nanos));
		r.rttMs = latestRttMs;

		final boolean masked = maskLeft > 0;
		if (masked)
		{
			maskLeft--;
			frames.maskSecond(session.secOf(nanos));
		}
		int fl = frames.flagsAt(nanos);
		if (masked)
		{
			fl |= Flags.LOGIN_MASK;
		}
		r.flags = fl;
		session.ticks.put(r);

		frames.resetWorstSinceTick();
		first = false;
		lastAtMs = atMs;
		lastCycle = gameCycle;

		if (timed)
		{
			timer.add(SelfTimer.TICK, System.nanoTime() - t0);
		}
	}

	/**
	 * The game state changed to {@code stateCode} ({@link State}). When LOGGING_IN, HOPPING or CONNECTION_LOST ends
	 * here, the next {@link Thresholds#LOGIN_MASK_TICKS} ticks are masked. Client thread.
	 */
	public void state(long nanos, int stateCode)
	{
		if (stateCode == lastState)
		{
			return;
		}
		if (lastState == State.LOGGING_IN || lastState == State.HOPPING || lastState == State.CONNECTION_LOST)
		{
			maskLeft = Thresholds.LOGIN_MASK_TICKS;
		}
		lastState = stateCode;
	}
}

