package com.whylag.core;

/**
 * Every text of a verdict (contract 6.4): headline, proof, fix and {@code ruledOut}. The ONLY class that holds
 * verdict text. The three card states' headlines are {@link Answer}'s constants, never literals of this class.
 *
 * <p>Every headline is at most {@link #HEADLINE_MAX} characters, every proof {@link #PROOF_MAX}, every fix
 * {@link #FIX_MAX}, WITH the largest values filled in: each filler is clamped to its largest printed value before
 * it is printed. Plain ASCII; the word "to" stands where the picture has an arrow.
 *
 * <p>Choice: a filler printed in ms is held in 0 .. 9,999 (a ping in 0 .. 999); one printed in SECONDS with a
 * decimal (S1's load, N6's stretch without a tick) is held in 0 .. 120,000 ms, "120.0", the largest length of 6.4.
 * <p>Choice: counts (loads, the map loading setting, the draw distance) in 0 .. 999, V2's minutes in 1 .. 9,999.
 * <p>S1's proof is "{n} loads in the last 10 min." for every count, one included, as contract 6.4 writes it.
 * <p>N6's proof names the ping ("Frames and ping were fine.") only when the spike signal was judged and clean
 * ({@link Evidence#NO}); with no fresh RTT or no usual it has no data (contract 6.3), and the proof is the "ping no
 * data" form of 6.4, "Frames were fine.".
 * <p>Choice: F2's settings proof leaves out the anti-aliasing name when it is unknown ("") or would make the proof
 * longer than {@link #PROOF_MAX}; any text that is still too long is cut at its limit.
 * <p>Choice: X with no candidate and a first trigger that names nothing that moved by itself (none, DISCONNECT,
 * LONG_LOAD) uses the connection sentence for DISCONNECT and the freeze sentence otherwise.
 * <p>Choice: " No ping data." is added to ANY X proof when the span had no fresh RTT and the result still fits.
 * <p>Choice: {@code ruledOut} is written for an event's verdict only (X included): it names, of frames, ping and
 * ticks, those that were measured and clean and are not the verdict's own group. A condition, V2 and the card
 * states carry "".
 */
public final class Words
{
	public static final int HEADLINE_MAX = 32;
	public static final int PROOF_MAX = 64;
	public static final int FIX_MAX = 61;

	private static final int MAX_WORLD = 999;
	private static final int MAX_MS = 9_999;
	private static final int MAX_PING_MS = 999;
	private static final int MAX_S = 120;
	private static final int MAX_FPS = 999;
	private static final int MAX_COUNT = 999;
	private static final int MAX_MINUTES = 9_999;
	private static final int MS_PER_SECOND = 1000;
	private static final int SECONDS_PER_MINUTE = 60;
	private static final int SHARE_OF = 100;
	private static final int PER_MILLE = 1000;
	private static final int PER_MILLE_PER_SHARE = PER_MILLE / SHARE_OF;
	private static final int PLUS_STEP_MS = 10;

	private static final String NO_PING = " No ping data.";

	private Words()
	{
	}

	// ------------------------------------------------------------------ the rules

	/** The headline of a rule's verdict. {@code s} gives D1 its clock. */
	public static String headline(Rule r, Evidence e, Session s)
	{
		return fit(headlineOf(r, e, s), HEADLINE_MAX);
	}

	/** The proof of a rule's verdict; X's and V2's have their own methods. */
	public static String proof(Rule r, Evidence e, SettingsView settings)
	{
		return fit(proofOf(r, e, settings), PROOF_MAX);
	}

	/** The fix of a rule's verdict; "" = none. */
	public static String fix(Rule r, Evidence e, SettingsView settings)
	{
		return fit(fixOf(r, e, settings), FIX_MAX);
	}

	private static String headlineOf(Rule r, Evidence e, Session s)
	{
		switch (r.id)
		{
			case "D1":
				return "Connection lost at " + Fmt.clock(s.wallMsOf(Math.max(0, e.disconnectSec)), s.zone);
			case "S1":
				return "Map loading took " + seconds(e.loadMs) + " s";
			case "N3":
				return "Packets are being lost";
			case "N2":
				return "Your connection is unsteady";
			case "W1":
				return "World " + Fmt.clamp(e.world, 0, MAX_WORLD) + " is struggling, not you";
			case "S3":
				return "The client itself stalled";
			case "N6":
				return "The game stopped answering";
			case "F1":
				return "Frame rate is capped at " + Fmt.clamp(e.capFps, 0, MAX_FPS);
			case "N1":
				return "Ping is high but steady";
			case "F2":
				return "The game is drawing slowly";
			case "W1c":
				return "This world is running slow";
			case "V2":
				return "Smooth";
			default:
				return "Can't tell yet";
		}
	}

	private static String proofOf(Rule r, Evidence e, SettingsView settings)
	{
		switch (r.id)
		{
			case "D1":
				switch (beforeTheDisconnect(e))
				{
					case FINE:
						return "Ping and re-sends were fine just before.";
					case BAD_PING:
						return "Ping was " + ping(e.beforeRttMax) + " ms just before.";
					case BAD_RESENDS:
						return share(e.beforeResentPm) + " were re-sent just before.";
					default:
						return "No ping data just before.";
				}
			case "S1":
				if (gpu(settings))
				{
					return "Extended map loading is set to " + count(settings.expandedMapLoading) + ".";
				}
				return count(e.loads) + " loads in the last " + Thresholds.LOADS_LOOK_S / SECONDS_PER_MINUTE + " min.";
			case "N3":
				return share(e.resentPm) + " were re-sent. Ping can look fine.";
			case "N2":
				return "Ping swung " + ping(e.rttMin) + "-" + ping(e.rttMax) + " ms. Ticks came early and late.";
			case "W1":
				return "Ticks " + Thresholds.TICK_MS + " to "
					+ Fmt.thousands(Fmt.clamp(e.tickMedianMs, 0, MAX_MS) / PLUS_STEP_MS * PLUS_STEP_MS) + "+ ms for "
					+ Fmt.clamp(e.durationS, 0, MAX_S) + " s. Ping stayed " + ping(e.rtt) + " ms, " + fps(e.fps)
					+ " fps.";
			case "S3":
				return "A " + ms(e.frameGapMs) + " ms freeze. Connection and world were fine.";
			case "N6":
				// The ping part only when the spike was judged and was clean. With no fresh RTT OR no usual the spike
				// has no data (6.3), and then the words say nothing of the ping, as ruledOut does.
				return "No ticks for " + seconds(e.noTickMs) + " s. "
					+ (e.rttSpike == Evidence.NO ? "Frames and ping were fine." : "Frames were fine.");
			case "F1":
				return "Set by " + e.capLabel + ". Not lag.";
			case "N1":
				if (e.rttUsual >= 0 && e.rtt - e.rttUsual >= Thresholds.PING_USUAL_LOWER_MS)
				{
					return ping(e.rtt) + " ms. Your usual is " + ping(e.rttUsual) + " ms.";
				}
				return ping(e.rtt) + " ms, and steady.";
			case "F2":
				if (gpu(settings))
				{
					final String head = fps(e.lowFps) + " fps. Draw distance " + count(settings.drawDistance);
					final String full = head + ", " + settings.antiAliasing + ".";
					return settings.antiAliasing == null || settings.antiAliasing.isEmpty()
						|| full.length() > PROOF_MAX ? head + "." : full;
				}
				return fps(e.lowFps) + " fps for " + Fmt.clamp(e.lowFpsS, 0, MAX_S) + " s.";
			case "W1c":
				return "Ticks take " + ms(e.tickWindowMedianMs) + " ms here. Ping and frames are fine.";
			default:
				return "";
		}
	}

	private static String fixOf(Rule r, Evidence e, SettingsView settings)
	{
		switch (r.id)
		{
			case "D1":
				switch (beforeTheDisconnect(e))
				{
					case FINE:
						return "Wait a minute, then log in again.";
					case BAD_PING:
					case BAD_RESENDS:
						return "If every world does it, check cable or Wi-Fi.";
					default:
						return "Log in again. Note if it repeats.";
				}
			case "S1":
				return gpu(settings) ? "Lower Extended map loading." : "Nothing to fix. It is the map.";
			case "N3":
				return "If every world does it, check cable or Wi-Fi.";
			case "N2":
				return "Use a cable, not Wi-Fi. Pause downloads.";
			case "W1":
			case "W1c":
				return "Hop to a quieter world.";
			case "S3":
				return "Turn plugins off one at a time; try more memory for RuneLite.";
			case "N6":
				return "Hop worlds. If it follows you, it is your line.";
			case "F1":
				return "Raise or turn off that cap.";
			case "N1":
				return "Try a world closer to you.";
			case "F2":
				return settings.renderer == Renderer.CPU ? "Turn the GPU plugin on."
					: "Lower draw distance or anti-aliasing.";
			case "X":
				return "Wait for it to happen again.";
			default:
				return "";
		}
	}

	// ------------------------------------------------------------------ X, V2 and the card states

	/**
	 * X's proof. Two candidates: it names both, {@code a} first. None: it names WHAT MOVED, by the event's first
	 * trigger. X never says that nothing moved.
	 */
	public static String cantTellProof(Evidence e, Cause a, Cause b)
	{
		final String said;
		if (a != null && b != null)
		{
			said = "It was " + a.shortName() + " or " + b.shortName() + ".";
		}
		else if (e.first == Trigger.TICK_OFF || e.first == Trigger.NO_TICK)
		{
			said = "Ticks ran " + ms(e.tickOffMs) + " ms off. Cause not measured.";
		}
		else if (e.first == Trigger.RESENT || e.first == Trigger.RTT_SPIKE || e.first == Trigger.DISCONNECT)
		{
			said = "The connection wobbled. Cause not measured.";
		}
		else
		{
			said = "A " + ms(e.frameGapMs) + " ms freeze. Its cause was not measured.";
		}
		final boolean fits = said.length() + NO_PING.length() <= PROOF_MAX;
		return fit(!e.rttKnown && fits ? said + NO_PING : said, PROOF_MAX);
	}

	/**
	 * V2's proof, by the seconds since the newest event's end ({@code secondsSinceEnd < 0}: no lag yet, "No lag this
	 * session."). Under a minute: "No lag for 10 s." to "No lag for 50 s.", the seconds rounded DOWN to a multiple of
	 * {@link Thresholds#TEXT_STEP_S} and at least one step, so the counting text steps every 10 s. From a minute:
	 * "No lag for {m} min.", the whole minutes, at least 1, capped at 9,999.
	 * <p>Choice: the parameter was whole minutes until 2026-09-29; the card now goes back to Smooth 15 s after a lag
	 * ({@link Thresholds#EVENT_SHOW_S} 10), so the proof has to count seconds first.
	 */
	public static String allClearProof(long secondsSinceEnd)
	{
		if (secondsSinceEnd < 0)
		{
			return "No lag this session.";
		}
		if (secondsSinceEnd < SECONDS_PER_MINUTE)
		{
			final long step = Thresholds.TEXT_STEP_S;
			return "No lag for " + Math.max(step, secondsSinceEnd / step * step) + " s.";
		}
		final long minutes = secondsSinceEnd / SECONDS_PER_MINUTE;
		return "No lag for " + Fmt.thousands((int) Math.min(MAX_MINUTES, minutes)) + " min.";
	}

	public static String notLoggedInProof()
	{
		return "Log in to start measuring.";
	}

	/**
	 * "Ready in {40} s.": the seconds left, rounded UP to a multiple of {@link Thresholds#TEXT_STEP_S}.
	 * <p>Choice: with no warm-up ({@link Thresholds#WARMUP_S} 0, 2026-09-29) the seconds are held at one step at
	 * most, so the words never read "Ready in 0 s."; the card shows them only while no login is seen.
	 */
	public static String measuringProof(int leftS)
	{
		final int step = Thresholds.TEXT_STEP_S;
		final int held = Fmt.clamp(leftS, 1, Math.max(1, Thresholds.WARMUP_S));
		return "Ready in " + (held + step - 1) / step * step + " s.";
	}

	public static String waitingProof()
	{
		return "No frames are being drawn.";
	}

	// ------------------------------------------------------------------ ruled out

	/** What was measured and clean, for the report and the tooltip; "" = nothing to say. */
	public static String ruledOut(Cause cause, Evidence e, SettingsView settings)
	{
		if (!e.event)
		{
			return "";
		}
		final Group own = cause.group();
		final String[] clean = new String[3];
		int n = 0;
		if (e.framesClean && own != Group.FRAME_RATE)
		{
			clean[n++] = "frames";
		}
		if (e.rttSpike == Evidence.NO && own != Group.CONNECTION)
		{
			clean[n++] = "ping";
		}
		if (e.ticks > 0 && e.tickLate == 0 && e.tickEarly == 0 && e.noTickMs < Thresholds.NO_TICK_MS
			&& own != Group.WORLD)
		{
			clean[n++] = "ticks";
		}
		final StringBuilder out = new StringBuilder();
		for (int i = 0; i < n; i++)
		{
			if (i > 0)
			{
				out.append(i == n - 1 ? " and " : ", ");
			}
			out.append(clean[i]);
		}
		if (n > 0)
		{
			out.setCharAt(0, Character.toUpperCase(out.charAt(0)));
			out.append(n == 1 && "ping".equals(clean[0]) ? " was fine." : " were fine.");
		}
		return out.toString();
	}

	// ------------------------------------------------------------------ fillers

	private enum Before
	{
		FINE, BAD_PING, BAD_RESENDS, NO_DATA
	}

	/** D1: how the link looked in the seconds that end at the last tick. With both bad it is the ping. */
	private static Before beforeTheDisconnect(Evidence e)
	{
		if (e.beforeRttSpike == Evidence.YES)
		{
			return Before.BAD_PING;
		}
		if (e.beforeResentPm >= Thresholds.RESENT_PER_MILLE)
		{
			return Before.BAD_RESENDS;
		}
		if (e.beforeRttSpike == Evidence.NO && e.beforeResentPm >= 0)
		{
			return Before.FINE;
		}
		return Before.NO_DATA;
	}

	/** "{2} in 100": per mille to a share of 100, rounded half up and at least 1. */
	static String share(int perMille)
	{
		final int pm = Fmt.clamp(perMille, 0, PER_MILLE);
		return Math.max(1, (pm + PER_MILLE_PER_SHARE / 2) / PER_MILLE_PER_SHARE) + " in " + SHARE_OF;
	}

	private static boolean gpu(SettingsView settings)
	{
		return settings.renderer == Renderer.GPU || settings.renderer == Renderer.HD;
	}

	private static String ms(int v)
	{
		return Fmt.thousands(Fmt.clamp(v, 0, MAX_MS));
	}

	private static String ping(int v)
	{
		return Integer.toString(Fmt.clamp(v, 0, MAX_PING_MS));
	}

	private static String fps(int v)
	{
		return Integer.toString(Fmt.clamp(v, 0, MAX_FPS));
	}

	private static String count(int v)
	{
		return Integer.toString(Fmt.clamp(v, 0, MAX_COUNT));
	}

	/** A length in ms as seconds with one decimal, held in 0 .. 120 s. */
	private static String seconds(int ms)
	{
		return Fmt.tenths(Fmt.clamp(ms, 0, MAX_S * MS_PER_SECOND));
	}

	private static String fit(String text, int max)
	{
		return text.length() <= max ? text : text.substring(0, max);
	}
}

package com.whylag.ui;

import com.whylag.core.Answer;
import com.whylag.core.Cause;
import com.whylag.core.Fmt;
import com.whylag.core.Level;
import com.whylag.core.PanelSnapshot;
import com.whylag.core.Verdict;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.time.ZoneId;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.ToolTipManager;

/**
 * Block 2, the answer card (contract 5.1): the verdict in two big lines of {@link Answer}, its proof, its fix and
 * when it was, on a {@link Ui#CARD} ground with a 3 px edge in the level's colour ({@link Ui#RULE} at NO_DATA).
 *
 * <p>Top down: the level's shape, 14 x 14 at (10, 16); big line 1 in {@link Ui#RSB32} at x 30, baseline 32, in
 * the level's text colour; big line 2, white, 28 px under it; the proof in RuneScape, its first line's top 8 px
 * under the big block, wrapped on spaces to at most 3 lines of 196 px, 19 px apart, baseline 14 under each top;
 * with a fix, a 1 px {@link Ui#GROUND} divider 8 px under the proof, then 7 px lower the word "Fix" in bold orange,
 * a 4 px gap and the fix in white, at most 2 lines; with a when line, 6 px lower, the when words in RuneScape
 * Small on the left and the confidence word right-aligned at x 206 - on a line of its own under them when the two
 * do not fit in 196 px with 6 px between them. 9 px of padding above and below. The big lines are fixed words
 * that always fit ({@code AnswerCardTest} measures them); a 16 px line that does not fit ends in "...".
 *
 * <p>In a wider card (230 in the client) the ground fills the width, the proof and the fix wrap to {@code width - 17}
 * px (196 at 213), and the when line's confidence word ends 7 px from the right edge; the big lines and the shape
 * do not change. The wrapped lines, the height and the {@link #confidenceOwnLine} choice are made for the card's own
 * width ({@link Ui#widthOf}) and made again when that width changes.
 *
 * <p>The verdict's own headline is not painted: it is the card's tooltip, with {@code ruledOut} after it.
 *
 * <p>Choice: an empty proof takes no room, as the card before the first snapshot shows (46 px high).
 * <p>Choice: the world in the when words is printed as the plain number the verdict carries.
 * <p>Choice: a card that is asked for its height at a width it was not laid out for wraps its text again then, so
 * the panel's layout can size the card to its width first and read the height after.
 */
final class AnswerCard extends JComponent
{
	/** Padding above and below. */
	static final int PAD = 9;
	/** One big line of {@link Ui#RSB32}. */
	static final int BIG_LINE = 28;
	/** From the big block to the proof's first top. */
	static final int PROOF_GAP = 8;
	/** One 16 px line of the proof or the fix. */
	static final int LINE = 19;
	/** A 16 px line's baseline under its top. */
	static final int LINE_BASELINE = 14;
	/** From the proof's last line to the divider. */
	static final int DIVIDER_GAP = 8;
	/** From the divider to the fix's first top. */
	static final int FIX_GAP = 7;
	/** From the proof or the fix to the when line. */
	static final int WHEN_GAP = 6;
	/** One line of the when words. */
	static final int WHEN_LINE = 16;
	/** The when line's baseline under its top. */
	static final int WHEN_BASELINE = 12;
	/** Where the 16 px lines start, and the width they have at 213: x 10 .. 206. */
	static final int TEXT_X = 10;
	static final int ROOM = 196;
	/** What the lines' room is less than the card's width: 10 at the left, 7 at the right. */
	static final int ROOM_LESS = Ui.WIDTH - ROOM;
	/** Where the big lines start and end: x 30 .. 208, 178 px. */
	static final int BIG_X = 30;
	static final int BIG_END = 208;
	static final int LINE1_BASELINE = 32;
	static final int LINE2_BASELINE = 60;
	static final int SHAPE_X = 10;
	static final int SHAPE_Y = 16;
	static final int SHAPE_SIZE = 14;
	static final int EDGE = 3;
	static final int PROOF_LINES = 3;
	static final int FIX_LINES = 2;
	/** The space between the when words and the confidence word when they share a line. */
	static final int CONFIDENCE_GAP = 6;
	static final String FIX_WORD = "Fix";
	/** The fix's first line starts after "Fix" and a 4 px gap: 23 px in the real font. */
	static final int FIX_INDENT = Ui.width(Ui.RSB, FIX_WORD) + 4;

	private Level level = Level.NO_DATA;
	private String line1 = Answer.MEASURING.line1;
	private String line2 = "";
	private String proofText;
	private String fixText;
	private List<String> proof = Collections.emptyList();
	private List<String> fix = Collections.emptyList();
	/** The when words whole, and as cut to the room. */
	private String whenText = "";
	private String when = "";
	private String confidence = "";
	private boolean confidenceOwnLine;
	private String tip;
	private int height;
	/** The width the wrapped lines, {@link #when} and {@link #height} were made for; 0 = not yet. */
	private int laidWidth;

	AnswerCard()
	{
		setOpaque(true);
		ToolTipManager.sharedInstance().registerComponent(this);
		set(null, null);
	}

	/**
	 * The verdict to show and the snapshot it came with (for the clock, "4 min ago" and "this world"). A null
	 * verdict is the card before the first snapshot: "Measuring", the hollow ring, no proof. Answers true when
	 * the card's height changed.
	 */
	boolean set(Verdict v, PanelSnapshot s)
	{
		final Answer answer = Answer.of(v);
		level = v == null || v.level == null ? Level.NO_DATA : v.level;
		line1 = answer.line1;
		line2 = answer.line2;
		final int width = Ui.widthOf(this);
		final int room = width - ROOM_LESS;
		final boolean rewrap = width != laidWidth;
		final String p = v == null ? "" : v.proof;
		if (rewrap || !p.equals(proofText))
		{
			proofText = p;
			proof = Ui.wrap(Ui.RS, p, room, room, PROOF_LINES);
		}
		final String f = v == null ? "" : v.fix;
		if (rewrap || !f.equals(fixText))
		{
			fixText = f;
			fix = Ui.wrap(Ui.RS, f, room - FIX_INDENT, room, FIX_LINES);
		}
		whenText = whenWords(v, s);
		confidence = whenText.isEmpty() || v.confidence == null ? "" : v.confidence.word();
		confidenceOwnLine = ownLine(room);
		when = Ui.fit(Ui.RSS, whenText, room);
		tip = tipOf(v);
		laidWidth = width;
		final int old = height;
		height = measure();
		return height != old;
	}

	/** True when the when words and the confidence word do not fit one line of {@code room} px. */
	private boolean ownLine(int room)
	{
		return !confidence.isEmpty()
			&& Ui.width(Ui.RSS, whenText) + CONFIDENCE_GAP + Ui.width(Ui.RSS, confidence) > room;
	}

	/** Makes the wrapped lines, the when line and the height again when the card's width is not the one they are for. */
	private void refit()
	{
		final int width = Ui.widthOf(this);
		if (width == laidWidth)
		{
			return;
		}
		final int room = width - ROOM_LESS;
		proof = Ui.wrap(Ui.RS, proofText, room, room, PROOF_LINES);
		fix = Ui.wrap(Ui.RS, fixText, room - FIX_INDENT, room, FIX_LINES);
		confidenceOwnLine = ownLine(room);
		when = Ui.fit(Ui.RSS, whenText, room);
		laidWidth = width;
		height = measure();
	}

	/**
	 * The when words of contract 5.1, from the verdict's fields and the snapshot: an event's "21:47:30, world 416,
	 * 4 min ago"; all clear's "Last lag 21:47, this world" (or ", world 302"); a condition's "since 21:40"; "" when
	 * the verdict has no time ({@code whenWallMs} 0).
	 */
	static String whenWords(Verdict v, PanelSnapshot s)
	{
		if (v == null || v.whenWallMs == 0)
		{
			return "";
		}
		final ZoneId zone = s == null ? null : s.zone;
		if (v.eventId >= 0)
		{
			final long now = s == null ? v.whenWallMs : s.wallMs;
			return Fmt.clockSeconds(v.whenWallMs, zone) + ", world " + v.world + ", " + Fmt.ago(v.whenWallMs, now);
		}
		if (v.cause == Cause.ALL_CLEAR)
		{
			final boolean here = s != null && v.world == s.world;
			return "Last lag " + Fmt.clock(v.whenWallMs, zone) + (here ? ", this world" : ", world " + v.world);
		}
		return "since " + Fmt.clock(v.whenWallMs, zone);
	}

	/** The tooltip: the verdict's headline, then a space and {@code ruledOut} when there is one; null = none. */
	private static String tipOf(Verdict v)
	{
		if (v == null)
		{
			return null;
		}
		final String text = v.ruledOut.isEmpty() ? v.headline : (v.headline + " " + v.ruledOut).trim();
		return text.isEmpty() ? null : text;
	}

	private int measure()
	{
		int h = PAD + bigHeight();
		if (!proof.isEmpty())
		{
			h += PROOF_GAP + LINE * proof.size();
		}
		if (!fix.isEmpty())
		{
			h += DIVIDER_GAP + 1 + FIX_GAP + LINE * fix.size();
		}
		if (!when.isEmpty())
		{
			h += WHEN_GAP + WHEN_LINE * (confidenceOwnLine ? 2 : 1);
		}
		return h + PAD;
	}

	private int bigHeight()
	{
		return BIG_LINE * (line2.isEmpty() ? 1 : 2);
	}

	int height()
	{
		refit();
		return height;
	}

	Level level()
	{
		return level;
	}

	String line1()
	{
		return line1;
	}

	String line2()
	{
		return line2;
	}

	List<String> proofLines()
	{
		refit();
		return proof;
	}

	List<String> fixLines()
	{
		refit();
		return fix;
	}

	String when()
	{
		refit();
		return when;
	}

	String confidence()
	{
		return confidence;
	}

	boolean confidenceOwnLine()
	{
		refit();
		return confidenceOwnLine;
	}

	/** The divider's row, -1 when there is no fix. */
	int dividerY()
	{
		refit();
		return fix.isEmpty() ? -1 : PAD + bigHeight() + (proof.isEmpty() ? 0 : PROOF_GAP + LINE * proof.size())
			+ DIVIDER_GAP;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		return tip;
	}

	@Override
	public Dimension getPreferredSize()
	{
		refit();
		return new Dimension(Ui.WIDTH, height);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		refit();
		final int width = Ui.widthOf(this);
		final int room = width - ROOM_LESS;
		final Graphics2D g = Ui.prepare(graphics);
		g.setColor(Ui.CARD);
		g.fillRect(0, 0, width, height);
		g.setColor(Ui.edgeColour(level));
		g.fillRect(0, 0, EDGE, height);
		Shape.paint(g, level, SHAPE_X, SHAPE_Y, SHAPE_SIZE);
		Ui.text(g, line1, BIG_X, LINE1_BASELINE, Ui.RSB32, Ui.textColour(level));
		Ui.text(g, line2, BIG_X, LINE2_BASELINE, Ui.RSB32, Ui.WHITE);

		int top = PAD + bigHeight();
		if (!proof.isEmpty())
		{
			top += PROOF_GAP;
			for (String line : proof)
			{
				Ui.text(g, line, TEXT_X, top + LINE_BASELINE, Ui.RS, Ui.TEXT);
				top += LINE;
			}
		}
		if (!fix.isEmpty())
		{
			top += DIVIDER_GAP;
			g.setColor(Ui.GROUND);
			g.fillRect(TEXT_X, top, room, 1);
			top += 1 + FIX_GAP;
			Ui.text(g, FIX_WORD, TEXT_X, top + LINE_BASELINE, Ui.RSB, Ui.ORANGE);
			for (int i = 0; i < fix.size(); i++)
			{
				Ui.text(g, fix.get(i), i == 0 ? TEXT_X + FIX_INDENT : TEXT_X, top + LINE_BASELINE, Ui.RS, Ui.WHITE);
				top += LINE;
			}
		}
		if (!when.isEmpty())
		{
			top += WHEN_GAP;
			Ui.text(g, when, TEXT_X, top + WHEN_BASELINE, Ui.RSS, Ui.LABEL);
			final int confidenceTop = confidenceOwnLine ? top + WHEN_LINE : top;
			Ui.text(g, confidence, TEXT_X + room - Ui.width(Ui.RSS, confidence), confidenceTop + WHEN_BASELINE,
				Ui.RSS, Ui.LABEL);
		}
	}
}

package com.whylag.ui;

import com.whylag.core.Cell;
import com.whylag.core.Cells;
import com.whylag.core.Group;
import com.whylag.core.Level;
import com.whylag.core.PanelSnapshot;
import com.whylag.core.Strip;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import javax.swing.ToolTipManager;

/**
 * Block 3, the three small cells (contract 5.2): 213 x 48, the cells at x 0, 72 and 144, each 69 px wide, so the
 * strip ends at x 213: a third of the width each. In a wider strip the cells share the width less two 3 px gaps
 * ({@link #cellX}, {@link #cellW}): each is (width - 6) / 3 wide and the pixels left over go one each to the LAST
 * cells, which is what makes the 213 layout above the same rule. It paints {@link Cell}s as {@link Cells} made them
 * and holds no rule of its own.
 *
 * <p>One cell: a {@link Ui#CARD} ground; the level's shape, 7 x 7 at (5, 7); the name in RuneScape Small
 * {@link Ui#LABEL} at x 15, baseline 14; the value in white at x 5, baseline 30, in RuneScape Bold when it is 35 px
 * or less, else RuneScape when that is, else RuneScape Small; the unit in RuneScape Small {@link Ui#LABEL} at x 5,
 * baseline 43. The culprit cell has a 1 px border in its level's colour, the ground {@link Ui#CULPRIT}, its value in
 * {@link Ui#BAD_TEXT} and its name and unit in {@link Ui#CULPRIT_LABEL}. The tooltip is the cell's tip.
 *
 * <p>Choice: the leftover pixels go to the cells from the RIGHT, not from the left as the plan of 2026-09-29 says.
 * <p>Choice: the text inside a cell keeps its 35 px room and its insets in a wider cell; only the ground grows.
 * <p>Choice: a cell that is not the culprit draws no border: a border in the ground's colour is the ground.
 * <p>Choice: before the first snapshot the three cells are the dashes of an empty snapshot, with no tooltip.
 * <p>Choice: the 3 px gaps between the cells have no tooltip.
 */
final class CellStrip extends JComponent
{
	static final int HEIGHT = 48;
	/** The left edge and the width of each cell. */
	static final int[] X = {0, 72, 144};
	static final int[] W = {69, 69, 69};
	static final int GAP = 3;
	/** The text's box in a cell: x 5 .. 39, 35 px. */
	static final int TEXT_X = 5;
	static final int TEXT_ROOM = 35;
	static final int NAME_X = 15;
	static final int NAME_BASELINE = 14;
	static final int VALUE_BASELINE = 30;
	static final int UNIT_BASELINE = 43;
	static final int SHAPE_X = 5;
	static final int SHAPE_Y = 7;
	static final int SHAPE_SIZE = 7;

	private Cell[] cells = blank();

	CellStrip()
	{
		setOpaque(true);
		ToolTipManager.sharedInstance().registerComponent(this);
	}

	/** The three cells to paint, in lane order. */
	void set(Cell[] three)
	{
		cells = three == null ? blank() : three;
	}

	Cell[] cells()
	{
		return cells;
	}

	/** The face a value is painted in: the boldest of the three in which it fits 35 px. */
	static Font valueFace(String value)
	{
		if (Ui.width(Ui.RSB, value) <= TEXT_ROOM)
		{
			return Ui.RSB;
		}
		return Ui.width(Ui.RS, value) <= TEXT_ROOM ? Ui.RS : Ui.RSS;
	}

	/** Cell i's width in a strip {@code width} wide; the leftover pixels go one each to the last cells. */
	static int cellW(int i, int width)
	{
		final int room = width - (X.length - 1) * GAP;
		return room / X.length + (i >= X.length - room % X.length ? 1 : 0);
	}

	/** Cell i's left edge in a strip {@code width} wide. */
	static int cellX(int i, int width)
	{
		int x = 0;
		for (int k = 0; k < i; k++)
		{
			x += cellW(k, width) + GAP;
		}
		return x;
	}

	/** The cell under x in the 213 px strip, -1 in a gap or outside. */
	static int cellAt(int x)
	{
		return cellAt(x, Ui.WIDTH);
	}

	/** The cell under x in a strip {@code width} wide, -1 in a gap or outside. */
	static int cellAt(int x, int width)
	{
		for (int i = 0; i < X.length; i++)
		{
			if (x >= cellX(i, width) && x < cellX(i, width) + cellW(i, width))
			{
				return i;
			}
		}
		return -1;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		final int i = cellAt(e.getX(), Ui.widthOf(this));
		if (i < 0 || i >= cells.length || cells[i] == null || cells[i].tip.isEmpty())
		{
			return null;
		}
		return cells[i].tip;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(Ui.WIDTH, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		final Graphics2D g = Ui.prepare(graphics);
		final int width = Ui.widthOf(this);
		g.setColor(Ui.GROUND);
		g.fillRect(0, 0, width, HEIGHT);
		for (int i = 0; i < X.length && i < cells.length; i++)
		{
			if (cells[i] != null)
			{
				paintCell(g, cells[i], cellX(i, width), cellW(i, width));
			}
		}
	}

	private static void paintCell(Graphics2D g, Cell c, int x, int w)
	{
		final Level level = c.level == null ? Level.NO_DATA : c.level;
		g.setColor(c.culprit ? Ui.CULPRIT : Ui.CARD);
		g.fillRect(x, 0, w, HEIGHT);
		if (c.culprit)
		{
			g.setColor(Ui.edgeColour(level));
			g.drawRect(x, 0, w - 1, HEIGHT - 1);
		}
		Shape.paint(g, level, x + SHAPE_X, SHAPE_Y, SHAPE_SIZE);
		final Color quiet = c.culprit ? Ui.CULPRIT_LABEL : Ui.LABEL;
		Ui.text(g, c.name, x + NAME_X, NAME_BASELINE, Ui.RSS, quiet);
		Ui.text(g, c.value, x + TEXT_X, VALUE_BASELINE, valueFace(c.value), c.culprit ? Ui.BAD_TEXT : Ui.WHITE);
		Ui.text(g, c.unit, x + TEXT_X, UNIT_BASELINE, Ui.RSS, quiet);
	}

	/** The cells before the first snapshot: the dashes of an empty snapshot, with no tooltip. */
	private static Cell[] blank()
	{
		final Strip[] none = new Strip[0];
		final Cell[] made = Cells.now(new PanelSnapshot(0, null, 0, null, null, 0, 0, 0, none, null, null,
			new int[Group.values().length], 0, 0, null, ""));
		final Cell[] out = new Cell[made.length];
		for (int i = 0; i < made.length; i++)
		{
			final Cell c = made[i];
			out[i] = new Cell(c.lane, c.name, c.value, c.unit, c.level, false, "");
		}
		return out;
	}
}

package com.whylag.ui;

import com.whylag.core.Fmt;
import com.whylag.core.LagEvent;
import com.whylag.core.Level;
import com.whylag.core.Thresholds;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.LongConsumer;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import javax.swing.ToolTipManager;

/**
 * Block 6a, the lag event list behind the "Lags (n)" row (contract 5.4), in the layout only while that row is open.
 * The range's closed events, NEWEST FIRST, at most {@link Thresholds#EVENT_ROWS} rows of 213 x 24 (as wide as the
 * list is: the row fills it and the length stays 6 px in from the right edge), 2 px apart: a
 * {@link Ui#CARD} ground; the verdict's shape, 8 x 8 at x 9 (BAD for an event not judged yet); the start clock in
 * RuneScape {@link Ui#LABEL} at x 23; the group's word in RuneScape {@link Ui#TEXT} at x 63; the length, "14 s",
 * right-aligned at x 207; baseline 17. A selected row has the {@link Ui#CARD_SELECTED} ground, a 3 px orange left
 * edge and white text. The tooltip is the verdict's headline. More rows than fit: a last line "and 3 more" in
 * RuneScape Small {@link Ui#LABEL}, 14 px. No event: one line, 18 px, "Nothing in the last minute." (10, 60:
 * "... 10 minutes.", "... 60 minutes."). An open event is not listed. A press on a row hands its event's id to the
 * panel, which selects it, or clears the selection when it was the selected one.
 *
 * <p>A selected row draws all three of its texts white, the clock included.
 *
 * <p>Choice: an unselected row's 3 px edge shows the row's own ground, as the picture's transparent border does.
 * <p>Choice: the shape sits at y 8 of its row.
 * <p>Choice: the "and 3 more" line is 2 px under the last row, at x 9, baseline 11.
 * <p>Choice: the empty line is drawn at x 0, baseline 13.
 * <p>Choice: a range of another length reads "Nothing in the last {n} minutes."
 * <p>Choice: an event with no verdict has no tooltip.
 * <p>Choice: a press in a 2 px gap, or on the "more" line, does nothing; a hand cursor shows over a row.
 */
final class EventList extends JComponent
{
	static final int ROW_H = 24;
	static final int ROW_GAP = 2;
	static final int MORE_H = 14;
	static final int EMPTY_H = 18;
	static final int EDGE = 3;
	static final int SHAPE_X = 9;
	static final int SHAPE_Y = 8;
	static final int SHAPE_SIZE = 8;
	static final int TIME_X = 23;
	static final int LABEL_X = 63;
	static final int LENGTH_RIGHT = 207;
	static final int BASELINE = 17;
	static final int MORE_X = 9;
	static final int MORE_BASELINE = 11;
	static final int EMPTY_BASELINE = 13;

	private final List<LagEvent> rows = new ArrayList<>();
	private int more;
	private long selectedId = -1;
	private int minutes = 10;
	private ZoneId zone;
	private int height = EMPTY_H;
	private int paints;

	/** A list whose rows hand the id of their event to {@code onRow} when pressed. */
	EventList(LongConsumer onRow)
	{
		setOpaque(true);
		ToolTipManager.sharedInstance().registerComponent(this);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				final int row = rowAt(e.getY());
				if (row >= 0 && SwingUtilities.isLeftMouseButton(e))
				{
					onRow.accept(rows.get(row).id);
				}
			}
		});
		addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				setCursor(Cursor.getPredefinedCursor(rowAt(e.getY()) >= 0 ? Cursor.HAND_CURSOR
					: Cursor.DEFAULT_CURSOR));
			}
		});
	}

	/**
	 * The range's events (closed, oldest first), the selected id (-1 none), the range in minutes and the zone of the
	 * clocks. Answers true when the list's height changed.
	 */
	boolean set(List<LagEvent> rangeEvents, long selected, int rangeMinutes, ZoneId clockZone)
	{
		rows.clear();
		int closed = 0;
		final List<LagEvent> events = rangeEvents == null ? Collections.emptyList() : rangeEvents;
		for (int i = events.size() - 1; i >= 0; i--)
		{
			final LagEvent e = events.get(i);
			if (e == null || e.open)
			{
				continue;
			}
			closed++;
			if (rows.size() < Thresholds.EVENT_ROWS)
			{
				rows.add(e);
			}
		}
		more = closed - rows.size();
		selectedId = selected;
		minutes = rangeMinutes;
		zone = clockZone;
		final int old = height;
		height = measure();
		return height != old;
	}

	/** The rows as painted, newest first. */
	List<LagEvent> rows()
	{
		return Collections.unmodifiableList(rows);
	}

	/** How many closed events of the range have no row. */
	int more()
	{
		return more;
	}

	/** How many times this list has painted: a folded list is never painted (T17). */
	int paints()
	{
		return paints;
	}

	/** The words of an empty list for that range. */
	static String emptyWords(int rangeMinutes)
	{
		return rangeMinutes == 1 ? "Nothing in the last minute." : "Nothing in the last " + rangeMinutes + " minutes.";
	}

	/** The words of the "more" line. */
	static String moreWords(int n)
	{
		return "and " + Fmt.thousands(n) + " more";
	}

	/** The row under y, or -1 (a gap, the "more" line, below the rows). */
	int rowAt(int y)
	{
		if (y < 0)
		{
			return -1;
		}
		final int row = y / (ROW_H + ROW_GAP);
		return row < rows.size() && y % (ROW_H + ROW_GAP) < ROW_H ? row : -1;
	}

	/** The top of row i. */
	static int rowY(int i)
	{
		return i * (ROW_H + ROW_GAP);
	}

	private int measure()
	{
		if (rows.isEmpty())
		{
			return EMPTY_H;
		}
		final int h = rows.size() * ROW_H + (rows.size() - 1) * ROW_GAP;
		return more > 0 ? h + ROW_GAP + MORE_H : h;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		final int row = rowAt(e.getY());
		if (row < 0)
		{
			return null;
		}
		final LagEvent ev = rows.get(row);
		return ev.verdict == null || ev.verdict.headline.isEmpty() ? null : ev.verdict.headline;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(Ui.WIDTH, height);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		paints++;
		final int width = Ui.widthOf(this);
		final Graphics2D g = Ui.prepare(graphics);
		g.setColor(Ui.GROUND);
		g.fillRect(0, 0, width, height);
		if (rows.isEmpty())
		{
			Ui.text(g, emptyWords(minutes), 0, EMPTY_BASELINE, Ui.RSS, Ui.LABEL);
			return;
		}
		for (int i = 0; i < rows.size(); i++)
		{
			paintRow(g, rows.get(i), rowY(i), width);
		}
		if (more > 0)
		{
			final int top = rowY(rows.size() - 1) + ROW_H + ROW_GAP;
			Ui.text(g, moreWords(more), MORE_X, top + MORE_BASELINE, Ui.RSS, Ui.LABEL);
		}
	}

	private void paintRow(Graphics2D g, LagEvent e, int y, int width)
	{
		final boolean chosen = e.id == selectedId;
		g.setColor(chosen ? Ui.CARD_SELECTED : Ui.CARD);
		g.fillRect(0, y, width, ROW_H);
		if (chosen)
		{
			g.setColor(Ui.ORANGE);
			g.fillRect(0, y, EDGE, ROW_H);
		}
		final Level level = e.verdict == null || e.verdict.level == null ? Level.BAD : e.verdict.level;
		Shape.paint(g, level, SHAPE_X, y + SHAPE_Y, SHAPE_SIZE);
		final Color time = chosen ? Ui.WHITE : Ui.LABEL;
		final Color words = chosen ? Ui.WHITE : Ui.TEXT;
		Ui.text(g, Fmt.clock(e.startWallMs, zone), TIME_X, y + BASELINE, Ui.RS, time);
		Ui.text(g, e.group().label(), LABEL_X, y + BASELINE, Ui.RS, words);
		final String length = e.lengthS() + " s";
		Ui.text(g, length, width - (Ui.WIDTH - LENGTH_RIGHT) - Ui.width(Ui.RS, length), y + BASELINE, Ui.RS, words);
	}
}

package com.whylag.ui;

import com.whylag.core.Fmt;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;

/**
 * Blocks 5 and 6, the fold rows "Graphs" and "Lags (n)" (contract 5): 213 x 26 (as wide as the panel gives it), a {@link Ui#CARD} ground while
 * folded and {@link Ui#CARD_SELECTED} while open. The words in RuneScape white at x 8, baseline 18; the Lags row
 * adds its count in brackets, the number through {@link Fmt#thousands}. A chevron 11 x 7 at (194, 10) - 19 px in
 * from the right edge, so it follows the edge when the row is wider - two 1 px
 * lines in {@link Ui#LABEL}, points down while folded and up while open. One press anywhere on the row opens or
 * closes it; the panel holds the state.
 *
 * <p>Contract 5 names {@link Ui#LABEL} for the count, and asks 4.5:1 for every text of an enabled control; LABEL
 * on {@link Ui#CARD_SELECTED}, the open row's ground, measures 4.48:1, and {@link Ui#TEXT} 6.47:1.
 *
 * <p>Choice: the count is LABEL while the row is folded and TEXT while it is open (the paragraph above).
 * <p>Choice: the chevron's arms are six pixels each, in rows 10 .. 15 of its box, meeting in one pixel at x 199.
 * <p>Choice: the row reacts to the left button's press, and shows the hand cursor.
 */
final class FoldRow extends JComponent
{
	static final int HEIGHT = 26;
	static final int WORD_X = 8;
	static final int BASELINE = 18;
	static final int CHEVRON_X = 194;
	static final int CHEVRON_Y = 10;
	static final int CHEVRON_W = 11;
	/** Each arm of the chevron, in pixels. */
	private static final int ARM = 6;

	private final String word;
	private final boolean counted;
	private boolean open;
	private int count;

	/**
	 * A fold row. {@code counted} rows print their count in brackets after the word ("Lags (3)"); a press runs
	 * {@code onClick}.
	 */
	FoldRow(String word, boolean counted, Runnable onClick)
	{
		this.word = word;
		this.counted = counted;
		setOpaque(true);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onClick.run();
				}
			}
		});
	}

	void setOpen(boolean isOpen)
	{
		open = isOpen;
	}

	boolean isOpen()
	{
		return open;
	}

	/** The count in brackets: the closed events in the range. */
	void setCount(int n)
	{
		count = Math.max(0, n);
	}

	/** What the row says: "Graphs", "Lags (3)". */
	String words()
	{
		return counted ? word + " " + bracket() : word;
	}

	private String bracket()
	{
		return "(" + Fmt.thousands(count) + ")";
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(Ui.WIDTH, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		final Graphics2D g = Ui.prepare(graphics);
		final int width = Ui.widthOf(this);
		g.setColor(open ? Ui.CARD_SELECTED : Ui.CARD);
		g.fillRect(0, 0, width, HEIGHT);
		if (counted)
		{
			final String lead = word + " ";
			Ui.text(g, lead, WORD_X, BASELINE, Ui.RS, Ui.WHITE);
			Ui.text(g, bracket(), WORD_X + Ui.width(Ui.RS, lead), BASELINE, Ui.RS, open ? Ui.TEXT : Ui.LABEL);
		}
		else
		{
			Ui.text(g, word, WORD_X, BASELINE, Ui.RS, Ui.WHITE);
		}
		g.setColor(Ui.LABEL);
		final int left = CHEVRON_X + width - Ui.WIDTH;
		final int last = left + CHEVRON_W - 1;
		for (int i = 0; i < ARM; i++)
		{
			final int row = open ? CHEVRON_Y + ARM - 1 - i : CHEVRON_Y + i;
			g.fillRect(left + i, row, 1, 1);
			g.fillRect(last - i, row, 1, 1);
		}
	}
}

package com.whylag.ui;

import com.whylag.PanelActions;
import com.whylag.Version;
import com.whylag.core.BadgeSettings;
import com.whylag.core.BadgeStyle;
import com.whylag.core.WhenSmooth;
import java.awt.Font;
import java.util.function.Consumer;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.JCheckBoxMenuItem;
import javax.swing.JLabel;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JRadioButtonMenuItem;
import javax.swing.border.EmptyBorder;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;
import net.runelite.client.ui.ColorScheme;

/**
 * The settings menu behind the header's gear (1.0.1, lot C): a {@link JPopupMenu} that {@link #build} makes FRESH at
 * every open from the last snapshot's {@link BadgeSettings}, so what it ticks is what is stored. Top down:
 * <ol>
 * <li>{@value #SHOW}, a check box;</li>
 * <li>{@value #STYLE}, a submenu of the four {@link BadgeStyle} labels with the current one ticked;</li>
 * <li>{@value #WHEN_SMOOTH}, a check box ticked while the choice is {@link WhenSmooth#SHOW};</li>
 * <li>{@value #CHAT_LINE}, a check box;</li>
 * <li>a separator, {@value #TROUBLESHOOT}, a separator;</li>
 * <li>the version row: "2h Why Lag" and {@link Version#CURRENT} in grey, disabled, no hover and no click.</li>
 * </ol>
 * A tick or a choice hands the new value to the {@link PanelActions} method of its setting and, as every menu item
 * does, closes the menu; the menu never writes a setting itself and keeps no state between two opens.
 *
 * <p>Choice: the check boxes act after their model has toggled, so {@code isSelected()} in the listener is the NEW
 * value; the style choices are radio items in one group, so one of them is always ticked.
 * <p>Choice: every item sets its face (the default sans at 12 px): one that does not is drawn by the look and feel in
 * the 16 px bitmap RuneScape default, and the menu would look nothing like the bank tracker's.
 * <p>Choice: the version row is a panel holding a label, not a menu item: a menu item highlights under the mouse and
 * a press on it would close the menu, and the row is neither a control nor a setting. The PANEL is disabled, and the
 * label keeps the light grey of the stock small lines, which a disabled label would not paint. It is 12 px, the
 * menu's own size (the bank tracker's was 10 px until the user found it hard to read).
 * <p>Choice: {@code closed} runs when the menu goes away by any means - a choice, a press elsewhere, Escape - which
 * is the one moment the header can learn of a close (its press guard).
 */
final class GearMenu
{
	static final String SHOW = "Badge on the game screen";
	static final String STYLE = "Badge style";
	static final String WHEN_SMOOTH = "Show badge when smooth";
	static final String CHAT_LINE = "Chat line on a lag";
	static final String TROUBLESHOOT = "Troubleshoot...";
	/** The version row's words: "2h Why Lag " and the version. */
	static final String VERSION = "2h Why Lag " + Version.CURRENT;
	/** The menu's face: RuneLite's default font (Dialog) at 12 px, made whole here so no font is derived in this package. */
	private static final Font SANS = new Font(Font.DIALOG, Font.PLAIN, 12);
	private static final int ROW_GAP = 6;

	private GearMenu()
	{
	}

	/**
	 * The menu for {@code s}: a tick calls the matching method of {@code actions}, {@value #TROUBLESHOOT} runs
	 * {@code troubleshoot}, and {@code closed} runs when the menu goes away.
	 */
	static JPopupMenu build(BadgeSettings s, PanelActions actions, Runnable troubleshoot, Runnable closed)
	{
		final JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		menu.add(check(SHOW, s.show, actions::badgeShow));
		menu.add(styleMenu(s.style, actions));
		menu.add(check(WHEN_SMOOTH, s.whenSmooth == WhenSmooth.SHOW,
			on -> actions.badgeWhenSmooth(on ? WhenSmooth.SHOW : WhenSmooth.HIDE)));
		menu.add(check(CHAT_LINE, s.chatLine, actions::badgeChatLine));
		menu.addSeparator();
		final JMenuItem test = new JMenuItem(TROUBLESHOOT);
		test.setFont(SANS);
		test.addActionListener(e -> troubleshoot.run());
		menu.add(test);
		menu.addSeparator();
		menu.add(versionRow());
		menu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
				closed.run();
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});
		return menu;
	}

	/** One check box; {@code onToggle} gets the value the box now holds. */
	private static JCheckBoxMenuItem check(String text, boolean ticked, Consumer<Boolean> onToggle)
	{
		final JCheckBoxMenuItem item = new JCheckBoxMenuItem(text, ticked);
		item.setFont(SANS);
		item.addActionListener(e -> onToggle.accept(item.isSelected()));
		return item;
	}

	/** The style submenu: the four labels in the enum's order as one radio group, the current one ticked. */
	private static JMenu styleMenu(BadgeStyle current, PanelActions actions)
	{
		final JMenu menu = new JMenu(STYLE);
		menu.setFont(SANS);
		final ButtonGroup group = new ButtonGroup();
		for (BadgeStyle style : BadgeStyle.values())
		{
			final JRadioButtonMenuItem item = new JRadioButtonMenuItem(style.toString(), style == current);
			item.setFont(SANS);
			item.addActionListener(e -> actions.badgeStyle(style));
			group.add(item);
			menu.add(item);
		}
		return menu;
	}

	/** The last row: {@link #VERSION} in grey at the menu's own size, disabled, with no hover and no click. */
	private static JPanel versionRow()
	{
		final JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(2, ROW_GAP, 2, ROW_GAP));
		final JLabel label = new JLabel(VERSION);
		label.setFont(SANS);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		row.add(label);
		row.add(Box.createHorizontalGlue());
		row.setEnabled(false);
		return row;
	}
}

package com.whylag.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import java.util.function.LongSupplier;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import javax.swing.ToolTipManager;

/**
 * Block 1 of the panel (contract 5): 213 x 20 (as wide as the panel gives it). "Why Lag" in RuneScape Bold white on
 * the left, baseline 15; at the right end the settings gear (1.0.1, lot C), 12 x 12, drawn in code; and left of the
 * gear, in RuneScape Small {@link Ui#LABEL}, "World 416", or "Not logged in" while the snapshot's world is 0.
 *
 * <p><b>The gear</b> is grey at rest and orange under the mouse, as 2h Bank Portfolio Tracker's is, with the tooltip
 * {@value #GEAR_TIP}. A left press on it runs the hook the panel gave, which opens the settings menu under it.
 *
 * <p><b>A press that closes the menu opens nothing</b> (the bank tracker's rule). The gear cannot see its own menu:
 * RuneLite makes every popup heavy-weight, and Swing's popup grabber cancels an open popup on any press OUTSIDE it -
 * the gear is outside - BEFORE that press reaches the gear's own mouse listener. A second press on the gear
 * therefore always finds the menu already closed, and would open it again in a loop. So the panel tells the row
 * WHEN the menu went away ({@link #menuClosed}), and a press within {@value #MENU_REOPEN_MS} ms of that is the close
 * it really was: it opens nothing.
 *
 * <p>Choice: the world words are right-aligned 6 px left of the gear on the same baseline, 15.
 * <p>Choice: before the first snapshot the world words are empty.
 * <p>Choice: the gear's hit area is its 12 px, 4 px more on its left and the whole 20 px of the row's height, so a
 * small glyph is not a small target; the tooltip and the hand cursor follow the same area.
 * <p>Choice: 300 ms is a click and not a pause: longer than the gap between the grabber's cancel and the press it
 * belongs to, shorter than any deliberate re-open.
 * <p>Choice: the clock is a field so a test can move it; the client reads the wall clock.
 */
final class HeaderRow extends JComponent
{
	static final int HEIGHT = 20;
	/** The gear's side, in px. */
	static final int GEAR = 12;
	/** The gear's top edge: it is centred on the row. */
	static final int GEAR_Y = (HEIGHT - GEAR) / 2;
	/** The gear's tooltip. */
	static final String GEAR_TIP = "Settings";
	/** How long after the menu closes a press on the gear opens nothing. */
	static final long MENU_REOPEN_MS = 300L;
	private static final int BASELINE = 15;
	private static final int WORLD_GAP = 6;
	private static final int HIT_LEFT = 4;
	private static final int TEETH = 8;
	private static final String TITLE = "Why Lag";
	/** What {@link #menuClosedAt} holds while the menu has never closed. */
	private static final long NEVER = Long.MIN_VALUE;
	/** The gear at rest and under the mouse, drawn once. */
	private static final BufferedImage GEAR_REST = gear(Ui.LABEL);
	private static final BufferedImage GEAR_HOT = gear(Ui.ORANGE);

	/** What "now" is when a press asks how long ago the menu closed; a seam: tests move it. */
	LongSupplier clock = System::currentTimeMillis;

	private final Runnable openMenu;
	private String world = "";
	private long menuClosedAt = NEVER;
	private boolean hot;

	/** A row whose gear runs {@code openMenu} when a press on it opens the menu. */
	HeaderRow(Runnable openMenu)
	{
		this.openMenu = openMenu;
		setOpaque(true);
		ToolTipManager.sharedInstance().registerComponent(this);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onGear(e.getX(), e.getY(), Ui.widthOf(HeaderRow.this))
					&& gearPressOpens())
				{
					HeaderRow.this.openMenu.run();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				over(false);
			}
		});
		addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				over(onGear(e.getX(), e.getY(), Ui.widthOf(HeaderRow.this)));
			}
		});
	}

	/** The snapshot's world: 0 is not logged in (contract 3.8). */
	void set(int snapshotWorld)
	{
		world = snapshotWorld == 0 ? "Not logged in" : "World " + snapshotWorld;
	}

	/** The words left of the gear, "" before the first snapshot. */
	String worldWords()
	{
		return world;
	}

	/** The gear's box in the row's own coordinates: 12 x 12 at the right edge. */
	Rectangle gearBounds()
	{
		return new Rectangle(Ui.widthOf(this) - GEAR, GEAR_Y, GEAR, GEAR);
	}

	/** The menu went away, by whatever means (the gear, a press elsewhere, Escape, a choice): the time is kept. */
	void menuClosed()
	{
		menuClosedAt = clock.getAsLong();
	}

	/**
	 * Whether a press on the gear now opens the menu: true unless the menu went away within the last
	 * {@value #MENU_REOPEN_MS} ms, in which case this press is the one that took it away.
	 */
	boolean gearPressOpens()
	{
		return menuClosedAt == NEVER || clock.getAsLong() - menuClosedAt >= MENU_REOPEN_MS;
	}

	/** True while the gear is drawn in its hot colour. */
	boolean hot()
	{
		return hot;
	}

	/** True when a point is on the gear's hit area: {@link #HIT_LEFT} px left of it to the row's edge, the row's height. */
	static boolean onGear(int x, int y, int width)
	{
		return x >= width - GEAR - HIT_LEFT && x < width && y >= 0 && y < HEIGHT;
	}

	private void over(boolean on)
	{
		if (hot != on)
		{
			hot = on;
			setCursor(Cursor.getPredefinedCursor(on ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
			repaint();
		}
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		return onGear(e.getX(), e.getY(), Ui.widthOf(this)) ? GEAR_TIP : null;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(Ui.WIDTH, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		final Graphics2D g = Ui.prepare(graphics);
		final int width = Ui.widthOf(this);
		g.setColor(Ui.GROUND);
		g.fillRect(0, 0, width, HEIGHT);
		Ui.text(g, TITLE, 0, BASELINE, Ui.RSB, Ui.WHITE);
		final int gearX = width - GEAR;
		Ui.text(g, world, gearX - WORLD_GAP - Ui.width(Ui.RSS, world), BASELINE, Ui.RSS, Ui.LABEL);
		g.drawImage(hot ? GEAR_HOT : GEAR_REST, gearX, GEAR_Y, null);
	}

	/**
	 * The gear as 2h Bank Portfolio Tracker draws it: a ring of stroke, not a filled disc, so the middle stays clear
	 * and the glyph reads as a gear at 12 px, and eight round-capped teeth every 45 degrees, rooted on the ring's own
	 * circle. Every length is a fraction of the side. Drawn and not loaded: this plugin ships no image files.
	 */
	private static BufferedImage gear(Color colour)
	{
		final BufferedImage img = new BufferedImage(GEAR, GEAR, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour);
			final double centre = GEAR / 2.0;
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, GEAR * 0.2);
			final float toothWidth = (float) Math.max(1.3, GEAR * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring, centre + cos * toothOut,
					centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return img;
	}
}

package com.whylag.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/**
 * The sidebar button's icon, 16 x 16, drawn in code so the panel ships no image file: the 2hBuilds "2h" coin and the
 * plugin's own picture, four rising bars. The user chose it from the rendered sheets of 2026-09-29 (picture 29, R1,
 * then "make the other image 25 % smaller"): a hammered gold coin 9 px across in the top-left corner, its "2h" struck
 * in dark brown, and four bars 3 px wide (green, green, amber, red) rising to 9 px along the bottom (V9 of picture 30, chosen 2026-09-29).
 *
 * <p>The coin is the family mark every 2hBuilds plugin can carry; the bars are this plugin's. The two never touch:
 * the coin sits on the clear ground above the short bars, so its letters stay readable at true size.
 *
 * <p>Choice: the coin's edge is a closed path through sixteen jittered radii, the same every time, so it reads as
 * hammered rather than round; the letters are 7 x 5 pixel glyphs, the smallest "2h" that still reads.
 */
public final class NavIcon
{
	/** The size the sidebar draws a navigation icon at. */
	private static final int SIZE = 16;

	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);
	private static final Color GREEN = new Color(55, 240, 70);
	private static final Color AMBER = new Color(230, 150, 30);
	private static final Color RED = new Color(230, 30, 30);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	/** The bars: left edge, height (75 % of 3, 6, 9, 12) and colour, each 3 px wide with a 1 px gap, standing on the bottom row. */
	private static final int[] BAR_X = {1, 5, 9, 13};
	private static final int[] BAR_HEIGHT = {2, 5, 7, 9};
	private static final Color[] BAR_COLOUR = {GREEN, GREEN, AMBER, RED};
	private static final int BAR_WIDTH = 3;

	private NavIcon()
	{
	}

	/** A new 16 x 16 ARGB image of the icon. */
	public static BufferedImage create()
	{
		final BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			for (int i = 0; i < BAR_X.length; i++)
			{
				g.setColor(BAR_COLOUR[i]);
				g.fillRect(BAR_X[i], SIZE - BAR_HEIGHT[i], BAR_WIDTH, BAR_HEIGHT[i]);
			}
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			for (int i = 0; i < RADII.length; i++)
			{
				g.setColor(RINGS[i]);
				g.fill(coin(RADII[i]));
			}
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			glyph(g, TWO, LETTERS_X, LETTERS_Y);
			glyph(g, H, LETTERS_X + 4, LETTERS_Y);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

package com.whylag.ui;

import com.whylag.GraphRange;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.IntConsumer;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;

/**
 * Block 4, the range row (contract 5): 213 x 23. "Last" in RuneScape Small {@link Ui#LABEL} at x 0, baseline 16,
 * then three chips 58 x 23 at x 33, 94 and 155 (3 px apart; the last ends at x 213): "1 min", "10 min", "60 min".
 * In a wider row "Last" keeps its 33 px and the chips share the rest ({@link #chipX}, {@link #chipW}): each is
 * (width - 33 - 6) / 3 wide, the pixels left over going to the chips from the left, one each.
 * A chip is a {@link Ui#CARD} ground with a 1 px {@link Ui#RULE} border and its words in RuneScape Small
 * {@link Ui#LABEL}, centred, baseline 16; the chosen one has an {@link Ui#ORANGE} border and white words. A press
 * on a chip hands its minutes to the panel, which tells {@code PanelActions.rangeChanged}. The row is always in
 * view: the range sets both the graphs and the list.
 *
 * <p>While the graphs are stretched (the session holds less than the range) a grey note says how much is held,
 * "30 s" over "so far", in {@link Ui#LABEL} in place of "Last", baselines 10 and 21.
 * <p>Choice: the note takes the place of "Last": the 33 px before the first chip is the only free room in the row, and
 * two short lines fit it, so no chip and no block moves.
 *
 * <p>Choice: a chip reacts to the left button's press, and the hand cursor shows over the chips.
 */
final class RangeRow extends JComponent
{
	static final int HEIGHT = 23;
	static final int[] CHIP_X = {33, 94, 155};
	static final int CHIP_W = 58;
	static final int CHIP_GAP = 3;
	static final int BASELINE = 16;
	static final String LAST = "Last";
	static final String SO_FAR = "so far";
	static final int NOTE_BASELINE_1 = 10;
	static final int NOTE_BASELINE_2 = 21;
	/** The note's room: up to the first chip, less a pixel of air. */
	static final int NOTE_ROOM = 32;

	private final GraphRange[] ranges = GraphRange.values();
	private int minutes;
	/** How much the stretched graphs hold ("30 s", "4 min"); "" while they are not stretched. */
	private String held = "";

	RangeRow(IntConsumer onChip)
	{
		setOpaque(true);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				final int chip = chipAt(e.getX(), e.getY(), Ui.widthOf(RangeRow.this));
				if (chip >= 0 && SwingUtilities.isLeftMouseButton(e))
				{
					onChip.accept(ranges[chip].minutes());
				}
			}
		});
		addMouseMotionListener(new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				setCursor(Cursor.getPredefinedCursor(chipAt(e.getX(), e.getY(), Ui.widthOf(RangeRow.this)) >= 0
					? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
			}
		});
	}

	/** The chosen range, 1, 10 or 60. */
	void set(int chosenMinutes)
	{
		minutes = chosenMinutes;
	}

	int minutes()
	{
		return minutes;
	}

	/** The note's amount while the graphs are stretched ("30 s"); "" or null for none. */
	void held(String amount)
	{
		held = amount == null ? "" : amount;
	}

	String held()
	{
		return held;
	}

	/** Chip i's width in a row {@code width} wide: the room after "Last" less two gaps, over three; the rest from the left. */
	static int chipW(int i, int width)
	{
		final int room = width - CHIP_X[0] - 2 * CHIP_GAP;
		return room / CHIP_X.length + (i < room % CHIP_X.length ? 1 : 0);
	}

	/** Chip i's left edge in a row {@code width} wide. */
	static int chipX(int i, int width)
	{
		int x = CHIP_X[0];
		for (int k = 0; k < i; k++)
		{
			x += chipW(k, width) + CHIP_GAP;
		}
		return x;
	}

	/** The chip under (x, y) in a row {@code width} wide, 0 .. 2, or -1. */
	static int chipAt(int x, int y, int width)
	{
		if (y < 0 || y >= HEIGHT)
		{
			return -1;
		}
		for (int i = 0; i < CHIP_X.length; i++)
		{
			if (x >= chipX(i, width) && x < chipX(i, width) + chipW(i, width))
			{
				return i;
			}
		}
		return -1;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(Ui.WIDTH, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		final Graphics2D g = Ui.prepare(graphics);
		final int width = Ui.widthOf(this);
		g.setColor(Ui.GROUND);
		g.fillRect(0, 0, width, HEIGHT);
		if (held.isEmpty())
		{
			Ui.text(g, LAST, 0, BASELINE, Ui.RSS, Ui.LABEL);
		}
		else
		{
			Ui.text(g, Ui.fit(Ui.RSS, held, NOTE_ROOM), 0, NOTE_BASELINE_1, Ui.RSS, Ui.LABEL);
			Ui.text(g, Ui.fit(Ui.RSS, SO_FAR, NOTE_ROOM), 0, NOTE_BASELINE_2, Ui.RSS, Ui.LABEL);
		}
		for (int i = 0; i < CHIP_X.length && i < ranges.length; i++)
		{
			final boolean chosen = ranges[i].minutes() == minutes;
			final int x = chipX(i, width);
			final int w = chipW(i, width);
			g.setColor(Ui.CARD);
			g.fillRect(x, 0, w, HEIGHT);
			g.setColor(chosen ? Ui.ORANGE : Ui.RULE);
			g.drawRect(x, 0, w - 1, HEIGHT - 1);
			final String words = ranges[i].toString();
			Ui.text(g, words, x + (w - Ui.width(Ui.RSS, words)) / 2, BASELINE, Ui.RSS,
				chosen ? Ui.WHITE : Ui.LABEL);
		}
	}
}

package com.whylag.ui;

import com.whylag.core.Group;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.ToolTipManager;

/**
 * Block 8, the session's counts by group (contract 5): RuneScape Small {@link Ui#TEXT}, baseline 12, 11 px between
 * items: "Conn 1", "Frame 1", "World 1", and "? 1" only while the UNSURE count is above 0 (its tooltip
 * "Can't tell"). A count over 99 prints "99+". When the items are wider than the block (213 px at the least) on one line,
 * the items that do not fit go to a second 16 px line and the block is 32 high. An item is never split and never
 * clipped. The lines are made for the block's own width ({@link Ui#widthOf}) and made again when that changes.
 *
 * <p>Choice: an item starts a new line only when it does not fit after the one before it.
 * <p>Choice: a missing count reads 0.
 */
final class SessionCounts extends JComponent
{
	static final int LINE_H = 16;
	static final int BASELINE = 12;
	static final int GAP = 11;
	static final int CAP = 99;
	static final String UNSURE_TIP = "Can't tell";
	private static final Group[] ALWAYS = {Group.CONNECTION, Group.FRAME_RATE, Group.WORLD};

	/** Each item: its words, its line (0 or 1) and its x, made for {@link #placedWidth}. */
	private final List<String> words = new ArrayList<>();
	private final List<int[]> places = new ArrayList<>();
	private int unsureItem = -1;
	private int lines = 1;
	/** The width the places were made for; 0 = not yet. */
	private int placedWidth;

	SessionCounts()
	{
		setOpaque(true);
		ToolTipManager.sharedInstance().registerComponent(this);
		set(null);
	}

	/** The session's counts by {@link Group} ordinal. Answers true when the block's height changed. */
	boolean set(int[] counts)
	{
		words.clear();
		unsureItem = -1;
		for (Group group : ALWAYS)
		{
			words.add(item(group, count(counts, group)));
		}
		if (count(counts, Group.UNSURE) > 0)
		{
			unsureItem = words.size();
			words.add(item(Group.UNSURE, count(counts, Group.UNSURE)));
		}
		final int old = lines;
		place();
		return lines != old;
	}

	/** Puts the items on their lines for the block's own width. */
	private void place()
	{
		final int room = Ui.widthOf(this);
		places.clear();
		int line = 0;
		int x = 0;
		for (String w : words)
		{
			final int width = Ui.width(Ui.RSS, w);
			if (x > 0 && x + GAP + width > room)
			{
				line++;
				x = 0;
			}
			final int at = x == 0 ? 0 : x + GAP;
			places.add(new int[] {line, at});
			x = at + width;
		}
		lines = line + 1;
		placedWidth = room;
	}

	/** Puts the items on their lines again when the block's width is not the one they were placed for. */
	private void replace()
	{
		if (Ui.widthOf(this) != placedWidth)
		{
			place();
		}
	}

	/** "Conn 1", "? 99+": the group's short word, a space and the count, over 99 as "99+". */
	static String item(Group group, int n)
	{
		return group.shortLabel() + " " + (n > CAP ? CAP + "+" : Integer.toString(Math.max(0, n)));
	}

	private static int count(int[] counts, Group g)
	{
		return counts == null || g.ordinal() >= counts.length ? 0 : counts[g.ordinal()];
	}

	/** The items as painted, in order. */
	List<String> items()
	{
		return Collections.unmodifiableList(words);
	}

	/** 1 or 2. */
	int lines()
	{
		replace();
		return lines;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		if (unsureItem < 0)
		{
			return null;
		}
		replace();
		final int[] p = places.get(unsureItem);
		final int w = Ui.width(Ui.RSS, words.get(unsureItem));
		final boolean inside = e.getX() >= p[1] && e.getX() < p[1] + w
			&& e.getY() >= p[0] * LINE_H && e.getY() < (p[0] + 1) * LINE_H;
		return inside ? UNSURE_TIP : null;
	}

	@Override
	public Dimension getPreferredSize()
	{
		replace();
		return new Dimension(Ui.WIDTH, LINE_H * lines);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		replace();
		final Graphics2D g = Ui.prepare(graphics);
		g.setColor(Ui.GROUND);
		g.fillRect(0, 0, Ui.widthOf(this), LINE_H * lines);
		for (int i = 0; i < words.size(); i++)
		{
			final int[] p = places.get(i);
			Ui.text(g, words.get(i), p[1], p[0] * LINE_H + BASELINE, Ui.RSS, Ui.TEXT);
		}
	}
}

