package com.whylag.ui;

import com.whylag.core.Level;
import java.awt.Graphics2D;

/**
 * The status shapes (contract 5): every coloured status draws its shape as well as its colour, so no status rests
 * on colour alone. OK a filled circle, WARN a filled triangle pointing up, BAD a filled square, NO_DATA a hollow
 * ring in {@link Ui#LABEL} whose line is {@code max(1, size / 7)} px thick. Sizes used: 14 on the answer card, 7 in
 * the cells, 8 in the list rows.
 *
 * <p>Choice: each shape is set pixel by pixel by one rule per level, the badge's rule of P2.4 scaled to the size.
 *
 * <p>The rule, for a pixel (px, py) of the size x size square, with its centre at (px + 0.5, py + 0.5) and the
 * square's centre at (size / 2, size / 2): the circle holds the pixels within size / 2 of the centre; the triangle
 * those within (py + 1) / 2 of the middle column, so its point is one or two pixels at the top and its base the
 * whole bottom row; the ring those of the circle further than size / 2 - thickness from the centre. So a shape is
 * sharp at every size and exactly the same in every block.
 */
final class Shape
{
	private Shape()
	{
	}

	/** Paints the shape of {@code level}, {@code size} x {@code size}, with its top left at (x, y). */
	static void paint(Graphics2D g, Level level, int x, int y, int size)
	{
		if (size <= 0)
		{
			return;
		}
		final Level l = level == null ? Level.NO_DATA : level;
		g.setColor(Ui.markColour(l));
		for (int py = 0; py < size; py++)
		{
			int run = -1;
			for (int px = 0; px <= size; px++)
			{
				final boolean in = px < size && inside(l, px, py, size);
				if (in && run < 0)
				{
					run = px;
				}
				else if (!in && run >= 0)
				{
					g.fillRect(x + run, y + py, px - run, 1);
					run = -1;
				}
			}
		}
	}

	/** True when pixel (px, py) of a {@code size} square belongs to the shape of {@code level}. */
	private static boolean inside(Level level, int px, int py, int size)
	{
		final double half = size / 2.0;
		final double dx = px + 0.5 - half;
		final double dy = py + 0.5 - half;
		final double d2 = dx * dx + dy * dy;
		switch (level)
		{
			case OK:
				return d2 <= half * half;
			case WARN:
				return Math.abs(dx) <= (py + 1) / 2.0;
			case BAD:
				return true;
			default:
				final double inner = half - Math.max(1, size / 7);
				return d2 <= half * half && d2 > inner * inner;
		}
	}
}

package com.whylag.ui;

import com.whylag.core.EventView;
import com.whylag.core.Fmt;
import com.whylag.core.Group;
import com.whylag.core.LagEvent;
import com.whylag.core.Lane;
import com.whylag.core.Level;
import com.whylag.core.PanelSnapshot;
import com.whylag.core.Strip;
import com.whylag.core.Thresholds;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.util.Arrays;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.ToolTipManager;

/**
 * Block 5a, the three stacked lanes behind the "Graphs" row (contract 5.3, the lanes of picture 15): 213 x 106, in
 * the layout only while that row is open. Three lanes 27 px high at y 0, 30 and 60 - frame rate, ticks, ping - and
 * the time axis from y 90.
 *
 * <p>A lane: a {@link Ui#CARD} ground; its label in RuneScape Small {@link Ui#LABEL} at x 3, baseline y + 11; its
 * value right-aligned at x 210 on the same baseline, with a 1 px black shadow, in its level's text colour (one "-"
 * in {@link Ui#LABEL} when it has none); its line, one point per column in the rows y + 13 .. y + 25, coloured per
 * column by the strip's levels, with a gap where a column has no data. With an event selected the three values are
 * that event's ({@link EventView}).
 *
 * <p>Bands: each event of the range, from the column of its first millisecond to that of its last, at least 2 px
 * wide - {@link Ui#BAND} across the three lanes, {@link Ui#BAND_CULPRIT} in its cause's lane, and for the selected
 * event {@link Ui#BAND_SELECTED} with a 1 px orange frame from y 0 to y 87. The axis: a 1 px {@link Ui#RULE} line
 * at y 90, 3 px ticks at x 0, 71, 142 and 212, labels at baseline 104 ("-60 s", "-40 s", "-20 s" for one minute,
 * else the clock of each tick's column; while stretched, that clock with seconds) and "now" in {@link Ui#TEXT} at
 * the right. The tooltip over the lanes names a column's clock and its three numbers.
 *
 * <p><b>Width.</b> The data is always {@link #COLUMNS} (213) columns; the chart may be wider (230 in the client) and
 * paints to its own width ({@link Ui#widthOf}). Pixel x of a chart {@code width} wide is column
 * {@code x * 213 / width} ({@link #columnAt}), so at 213 the map is the identity and in a wider chart some columns
 * are two pixels wide: column c starts at pixel {@code ceil(c * width / 213)} ({@link #xOf}), and the columns tile
 * the width with no gap. Bands and the selected frame map the same way, the values are right-aligned 3 px in from
 * the right edge, the axis rule fills the width and its ticks sit at 0, a third, two thirds and the last pixel
 * ({@link #tick}); the hover reads its column with the same map.
 *
 * <p>The lane texts are drawn last, each on a flat backing, so no band tint and no frame line runs through their
 * letters, and every lane text meets the 4.5:1 rule on the card's ground.
 *
 * <p>Choice: a column starts at the first pixel that maps to it (the ceiling), so painting and hovering agree to the
 * pixel; the axis label under a tick is the clock of the column that pixel maps to.
 * <p>Choice: a column's point joins the point before it with a vertical run in the column's own colour.
 * <p>Choice: each lane text sits on a flat CARD backing: its rows and its shadow's, one pixel either side.
 * <p>Choice: bands sharing a column are painted there once, not stacked: culprit over selected over plain.
 * <p>Choice: a scale whose top is not above its bottom puts every point on the lane's lowest row.
 * <p>Choice: the first axis label starts at x 0, the next two are centred on their ticks; "now" ends at x 213.
 * <p>Choice: the label has no shadow; the value has one, and so has the "-" of a lane with no value.
 * <p>Choice: with no snapshot, or a range the column map refuses, no band and no clock is drawn ("-" in a tip).
 */
final class StripChart extends JComponent
{
	static final int HEIGHT = 106;
	static final int LANES = 3;
	static final int LANE_H = 27;
	static final int[] LANE_Y = {0, 30, 60};
	static final int LABEL_X = 3;
	static final int TEXT_BASELINE = 11;
	/** A lane's value is right-aligned here in the 213 px chart; in a wider one 3 px in from the right edge. */
	static final int VALUE_RIGHT = 210;
	/** The line's rows in a lane: y + 13 .. y + 25. */
	static final int LINE_TOP = 13;
	static final int LINE_BOTTOM = 25;
	static final int AXIS_Y = 90;
	static final int TICK_LEN = 3;
	/** The ticks: the start, a third, two thirds and the end (x 0, 71, 142 and 212 at 213). */
	static final int TICK_COUNT = 4;
	static final int AXIS_BASELINE = 104;
	/** The selected band's frame runs from y 0 to this row. */
	static final int FRAME_BOTTOM = 87;
	/** The tooltip answers from y 0 to this row. */
	static final int TIP_BOTTOM = 86;
	static final int COLUMNS = Thresholds.STRIP_COLUMNS;
	static final int MIN_BAND = 2;
	static final String DASH = "-";
	static final String NOW = "now";
	static final String[] ONE_MINUTE = {"-60 s", "-40 s", "-20 s"};
	/** What covers a column of a lane, weakest first: nothing, a band, the selected band, the culprit's band. */
	private static final byte NO_BAND = 0;
	private static final byte PLAIN_BAND = 1;
	private static final byte SELECTED_BAND = 2;
	private static final byte CULPRIT_BAND = 3;

	private PanelSnapshot snapshot;
	private LagEvent picked;
	private final String[] values = new String[LANES];
	private final Level[] valueLevels = new Level[LANES];
	/** Four ints a band: first column, last column, culprit lane (-1 none), 1 when it is the selected event. */
	private int[] bands = new int[0];
	private int bandCount;
	/** The band that covers each column of the lane being painted; reused. */
	private final byte[] kind = new byte[COLUMNS];
	private int paints;

	StripChart()
	{
		setOpaque(true);
		ToolTipManager.sharedInstance().registerComponent(this);
		Arrays.fill(values, "");
		Arrays.fill(valueLevels, Level.NO_DATA);
	}

	/** The snapshot to draw, and the selected event (null = none), whose numbers the lane values then show. */
	void set(PanelSnapshot s, LagEvent selected)
	{
		snapshot = s;
		picked = selected;
		if (selected != null)
		{
			final String[] v = EventView.laneValues(selected);
			final Level[] l = EventView.laneLevels(selected);
			for (int i = 0; i < LANES; i++)
			{
				values[i] = i < v.length && v[i] != null ? v[i] : "";
				valueLevels[i] = i < l.length && l[i] != null ? l[i] : Level.NO_DATA;
			}
		}
		else
		{
			for (int i = 0; i < LANES; i++)
			{
				final Strip strip = strip(i);
				values[i] = strip == null ? "" : strip.now;
				valueLevels[i] = strip == null || strip.nowLevel == null ? Level.NO_DATA : strip.nowLevel;
			}
		}
		placeBands();
	}

	/** How many times this chart has painted: a folded chart is never painted (T17). */
	int paints()
	{
		return paints;
	}

	/** The value at a lane's right as painted: "" = none (one dash is drawn). */
	String value(int lane)
	{
		return values[lane];
	}

	/** The columns of the band of the event with that id, {first, last}; null when it has none. */
	int[] bandOf(long id)
	{
		if (snapshot == null || !validRange())
		{
			return null;
		}
		for (LagEvent e : snapshot.rangeEvents)
		{
			if (e.id == id)
			{
				return columns(e);
			}
		}
		return null;
	}

	private Strip strip(int lane)
	{
		if (snapshot == null || snapshot.strips == null || lane >= snapshot.strips.length)
		{
			return null;
		}
		return snapshot.strips[lane];
	}

	private boolean validRange()
	{
		return snapshot != null && snapshot.rangeEndWallMs - snapshot.rangeStartWallMs >= COLUMNS;
	}

	/** The first and last column of an event's band, clipped and at least {@link #MIN_BAND} wide; null = out. */
	private int[] columns(LagEvent e)
	{
		final long start = snapshot.rangeStartWallMs;
		final long end = snapshot.rangeEndWallMs;
		int a = Strip.columnOf(start, end, e.startWallMs);
		int b = Strip.columnOf(start, end, e.startWallMs + Math.max(1, e.lengthS()) * 1000L - 1);
		if (b < 0 || a >= COLUMNS)
		{
			return null;
		}
		a = Math.max(0, a);
		b = Math.min(COLUMNS - 1, Math.max(a, b));
		if (b - a + 1 < MIN_BAND)
		{
			if (b < COLUMNS - 1)
			{
				b = a + MIN_BAND - 1;
			}
			else
			{
				a = b - MIN_BAND + 1;
			}
		}
		return new int[] {a, b};
	}

	private void placeBands()
	{
		bandCount = 0;
		if (snapshot == null || !validRange())
		{
			return;
		}
		final List<LagEvent> events = snapshot.rangeEvents;
		if (bands.length < events.size() * 4)
		{
			bands = new int[events.size() * 4];
		}
		for (LagEvent e : events)
		{
			if (e == null || e.open)
			{
				continue;
			}
			final int[] c = columns(e);
			if (c == null)
			{
				continue;
			}
			final Group group = e.group();
			final Lane lane = group == null ? null : group.lane();
			final int k = bandCount * 4;
			bands[k] = c[0];
			bands[k + 1] = c[1];
			bands[k + 2] = lane == null ? -1 : lane.ordinal();
			bands[k + 3] = picked != null && picked.id == e.id ? 1 : 0;
			bandCount++;
		}
	}

	// ------------------------------------------------------------------ the tooltip

	/** The pixel where column c starts in a chart {@code width} wide (c = {@link #COLUMNS} gives the width). */
	static int xOf(int column, int width)
	{
		return (column * width + COLUMNS - 1) / COLUMNS;
	}

	/** The column under pixel x of a chart {@code width} wide, held to 0 .. {@link #COLUMNS} - 1. */
	static int columnAt(int x, int width)
	{
		return Math.max(0, Math.min(COLUMNS - 1, x * COLUMNS / width));
	}

	/** Axis tick i (0 .. 3) of a chart {@code width} wide: 0, a third, two thirds, the last pixel. */
	static int tick(int i, int width)
	{
		return i == TICK_COUNT - 1 ? width - 1 : i * width / (TICK_COUNT - 1);
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		if (snapshot == null || e.getY() < 0 || e.getY() > TIP_BOTTOM)
		{
			return null;
		}
		return columnText(columnAt(e.getX(), Ui.widthOf(this)));
	}

	/** "21:47:30 - 50 fps, ticks 952 ms, ping 41 ms" for column c. */
	String columnText(int c)
	{
		final String clock = validRange()
			? Fmt.clockSeconds(Strip.columnStart(snapshot.rangeStartWallMs, snapshot.rangeEndWallMs, c), snapshot.zone)
			: DASH;
		final int fps = at(strip(Lane.FRAME_RATE.ordinal()), c);
		final int ticks = at(strip(Lane.TICKS.ordinal()), c);
		final int ping = at(strip(Lane.PING.ordinal()), c);
		return clock + " - "
			+ (fps == Strip.NONE ? "fps -" : Fmt.thousands(fps) + " fps") + ", "
			+ (ticks == Strip.NONE ? "ticks -" : "ticks " + Fmt.thousands(ticks) + " ms") + ", "
			+ (ping == Strip.NONE ? "ping -" : "ping " + Fmt.thousands(ping) + " ms");
	}

	/** Column c of a strip; {@link Strip#NONE} when it has none. */
	private static int at(Strip s, int c)
	{
		if (s == null)
		{
			return Strip.NONE;
		}
		final int[] v = s.values;
		return v == null || c < 0 || c >= v.length ? Strip.NONE : v[c];
	}

	private static boolean empty(int[] v)
	{
		if (v == null)
		{
			return true;
		}
		for (int x : v)
		{
			if (x != Strip.NONE)
			{
				return false;
			}
		}
		return true;
	}

	// ------------------------------------------------------------------ painting

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(Ui.WIDTH, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		paints++;
		final int width = Ui.widthOf(this);
		final Graphics2D g = Ui.prepare(graphics);
		g.setColor(Ui.GROUND);
		g.fillRect(0, 0, width, HEIGHT);
		for (int y : LANE_Y)
		{
			g.setColor(Ui.CARD);
			g.fillRect(0, y, width, LANE_H);
		}
		paintBands(g, width);
		for (int lane = 0; lane < LANES; lane++)
		{
			final Strip s = strip(lane);
			if (s == null)
			{
				continue;
			}
			line(g, s.values, s.levels, LANE_Y[lane], s.min, s.max, width);
		}
		paintFrame(g, width);
		for (int lane = 0; lane < LANES; lane++)
		{
			paintLaneTexts(g, lane, width);
		}
		paintAxis(g, width);
	}

	/**
	 * The bands, lane by lane: each column takes the strongest band that covers it - the culprit's, then the
	 * selected event's, then the plain one - and is painted once, so bands that share a column never stack.
	 */
	private void paintBands(Graphics2D g, int width)
	{
		if (bandCount == 0)
		{
			return;
		}
		for (int lane = 0; lane < LANES; lane++)
		{
			Arrays.fill(kind, NO_BAND);
			for (int i = 0; i < bandCount; i++)
			{
				final int k = i * 4;
				final byte mine = lane == bands[k + 2] ? CULPRIT_BAND : bands[k + 3] == 1 ? SELECTED_BAND : PLAIN_BAND;
				for (int c = bands[k]; c <= bands[k + 1]; c++)
				{
					kind[c] = (byte) Math.max(kind[c], mine);
				}
			}
			int start = 0;
			for (int c = 1; c <= COLUMNS; c++)
			{
				if (c == COLUMNS || kind[c] != kind[start])
				{
					if (kind[start] != NO_BAND)
					{
						g.setColor(bandColour(kind[start]));
						g.fillRect(xOf(start, width), LANE_Y[lane], xOf(c, width) - xOf(start, width), LANE_H);
					}
					start = c;
				}
			}
		}
	}

	private static Color bandColour(byte kind)
	{
		return kind == CULPRIT_BAND ? Ui.BAND_CULPRIT : kind == SELECTED_BAND ? Ui.BAND_SELECTED : Ui.BAND;
	}

	private void paintFrame(Graphics2D g, int width)
	{
		for (int i = 0; i < bandCount; i++)
		{
			final int k = i * 4;
			if (bands[k + 3] == 1)
			{
				g.setColor(Ui.ORANGE);
				final int left = xOf(bands[k], width);
				g.drawRect(left, 0, xOf(bands[k + 1] + 1, width) - 1 - left, FRAME_BOTTOM);
			}
		}
	}

	/** One lane's line: a point per column, joined to the column before by a vertical run; a gap at NONE. */
	private static void line(Graphics2D g, int[] v, byte[] levels, int laneY, int min, int max, int width)
	{
		if (v == null)
		{
			return;
		}
		boolean joined = false;
		int before = 0;
		for (int c = 0; c < COLUMNS && c < v.length; c++)
		{
			if (v[c] == Strip.NONE)
			{
				joined = false;
				continue;
			}
			final int y = yOf(v[c], laneY, min, max);
			g.setColor(columnColour(levels, c));
			final int top = joined ? Math.min(before, y) : y;
			final int bottom = joined ? Math.max(before, y) : y;
			g.fillRect(xOf(c, width), top, xOf(c + 1, width) - xOf(c, width), bottom - top + 1);
			before = y;
			joined = true;
		}
	}

	/** The row of a value on a lane's scale: its top at y + 13, its bottom at y + 25. */
	static int yOf(int value, int laneY, int min, int max)
	{
		if (max <= min)
		{
			return laneY + LINE_BOTTOM;
		}
		final double f = Math.max(0.0, Math.min(1.0, ((double) value - min) / ((double) max - min)));
		return laneY + LINE_BOTTOM - (int) Math.round(f * (LINE_BOTTOM - LINE_TOP));
	}

	private static Color columnColour(byte[] levels, int c)
	{
		if (levels == null || c >= levels.length || levels[c] < 0 || levels[c] >= Level.values().length)
		{
			return Ui.LABEL;
		}
		return Ui.markColour(Level.values()[levels[c]]);
	}

	private void paintLaneTexts(Graphics2D g, int lane, int width)
	{
		final int y = LANE_Y[lane];
		final int valueRight = width - (Ui.WIDTH - VALUE_RIGHT);
		final String label = Lane.values()[lane].label();
		laneText(g, label, LABEL_X, y, Ui.LABEL, false, width);
		final String v = values[lane];
		if (v.isEmpty() || DASH.equals(v))
		{
			dash(g, y, valueRight, width);
			return;
		}
		laneText(g, v, valueRight - Ui.width(Ui.RSS, v), y, Ui.textColour(valueLevels[lane]), true, width);
	}

	private static void dash(Graphics2D g, int laneY, int valueRight, int width)
	{
		laneText(g, DASH, valueRight - Ui.width(Ui.RSS, DASH), laneY, Ui.LABEL, true, width);
	}

	/**
	 * A lane text at the lane's text baseline, with the 1 px black shadow when {@code shadow}, on its flat
	 * backing: the text's rows and the shadow's, one pixel either side.
	 */
	private static void laneText(Graphics2D g, String text, int x, int laneY, Color colour, boolean shadow,
		int width)
	{
		final int left = Math.max(0, x - 1);
		final int right = Math.min(width, x + Ui.width(Ui.RSS, text) + 2);
		g.setColor(Ui.CARD);
		g.fillRect(left, laneY, right - left, LINE_TOP);
		if (shadow)
		{
			Ui.shadowed(g, text, x, laneY + TEXT_BASELINE, Ui.RSS, colour);
		}
		else
		{
			Ui.text(g, text, x, laneY + TEXT_BASELINE, Ui.RSS, colour);
		}
	}

	private void paintAxis(Graphics2D g, int width)
	{
		g.setColor(Ui.RULE);
		g.fillRect(0, AXIS_Y, width, 1);
		for (int i = 0; i < TICK_COUNT; i++)
		{
			g.fillRect(tick(i, width), AXIS_Y, 1, TICK_LEN);
		}
		Ui.text(g, NOW, width - Ui.width(Ui.RSS, NOW), AXIS_BASELINE, Ui.RSS, Ui.TEXT);
		if (!validRange())
		{
			return;
		}
		for (int i = 0; i < ONE_MINUTE.length; i++)
		{
			final String label = axisLabel(i);
			final int w = Ui.width(Ui.RSS, label);
			final int x = i == 0 ? 0 : tick(i, width) - w / 2;
			Ui.text(g, label, x, AXIS_BASELINE, Ui.RSS, Ui.LABEL);
		}
	}

	/**
	 * The label under tick i (0 .. 2): "-60 s", "-40 s", "-20 s" for one minute, else the clock of its column; while
	 * the graph is stretched, the clock of its column with seconds, the first label the session's first second.
	 * <p>Choice: a stretched span prints seconds ("21:47:30") in every range, since it may be shorter than a minute.
	 */
	String axisLabel(int i)
	{
		final int width = Ui.widthOf(this);
		final int column = columnAt(tick(i, width), width);
		if (snapshot.stretched())
		{
			return Fmt.clockSeconds(Strip.columnStart(snapshot.rangeStartWallMs, snapshot.rangeEndWallMs, column),
				snapshot.zone);
		}
		if (snapshot.rangeMinutes == 1)
		{
			return ONE_MINUTE[i];
		}
		return Fmt.clock(Strip.columnStart(snapshot.rangeStartWallMs, snapshot.rangeEndWallMs, column),
			snapshot.zone);
	}
}

package com.whylag.ui;

import com.whylag.Report;
import com.whylag.Version;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dialog;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Insets;
import java.awt.Window;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.function.Predicate;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.Timer;
import javax.swing.WindowConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The window the gear menu's <i>Troubleshoot...</i> opens (1.0.1, lot C; the shape of 2h Bank Portfolio Tracker's
 * window): the verdict of the ten checks on top in one line, the whole report under it in a read-only monospace
 * box, and two buttons, <i>Copy report</i> and <i>Close</i>. Non-modal, in RuneLite's dark colours, about
 * {@value #WIDTH} x {@value #HEIGHT}.
 *
 * <p>It opens at once on "Testing..." with the report box empty - the checks take a moment - and {@link #show} fills
 * it in when the report comes back. <i>Copy report</i> puts exactly the report's text on the clipboard and reads
 * "Copied" for {@value #COPIED_MS} ms. Nothing is written to disk: the report lives in this window and, when the
 * player presses <i>Copy report</i>, on the clipboard.
 *
 * <p><b>The model and the window are apart.</b> The panel of controls ({@link #content}) is built without a window,
 * so a test can press its buttons on a machine with no screen; the {@link JDialog} that hosts it is made only by
 * {@link #window}. A window that stands is re-used for another test ({@link #testing}); one that was closed is
 * {@linkplain #isOpen not open} and the panel makes a new one.
 *
 * <p>Choice: <i>Copy report</i> is disabled while the window says "Testing..." and while the report is empty, so a
 * press always has a text to copy.
 * <p>Choice: "Copied" shows only when the clipboard took the text; otherwise the button keeps its label.
 * <p>Choice: a new answer, and a new test in the same window, put the button back to its label and stop the timer.
 * <p>Choice: the verdict is in the window and the report's own "Verdict:" line is in the report; the window adds
 * nothing to the text that is copied.
 */
final class TroubleshootDialog
{
	/** The window's title. */
	static final String TITLE = "2h Why Lag " + Version.CURRENT + " - Troubleshoot";
	/** The verdict's words until the report is in. */
	static final String TESTING = "Testing...";
	static final String COPY_TEXT = "Copy report";
	/** The copy button's words for {@value #COPIED_MS} ms after it copied. */
	static final String COPIED_TEXT = "Copied";
	static final String CLOSE_TEXT = "Close";
	static final int COPIED_MS = 2000;
	static final int WIDTH = 560;
	static final int HEIGHT = 440;
	private static final int PADDING = 10;

	/** Everything the window shows, built without a window. */
	final JPanel content = new JPanel(new BorderLayout());
	final JTextArea verdictArea = new JTextArea(TESTING);
	final JTextArea reportArea = new JTextArea();
	final JButton copyButton;
	final JButton closeButton;
	/** The "Copied" timer: one shot, {@value #COPIED_MS} ms; tests read its delay and fire it. */
	final Timer copiedTimer;
	private final Predicate<String> clipboard;
	/** The report on show, which the copy button copies; empty until {@link #show}. Swing thread. */
	private String report = "";
	/** The hosting dialog; null without a window and again once closed. Swing thread. */
	private JDialog dialog;
	private boolean closed;

	/**
	 * @param clipboard where <i>Copy report</i> puts the text; answers true when the clipboard took it
	 */
	TroubleshootDialog(Predicate<String> clipboard)
	{
		this.clipboard = clipboard;
		content.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		content.setBorder(new EmptyBorder(PADDING, PADDING, PADDING, PADDING));

		verdictArea.setEditable(false);
		verdictArea.setLineWrap(true);
		verdictArea.setWrapStyleWord(true);
		verdictArea.setOpaque(false);
		verdictArea.setFont(new Font(Font.DIALOG, Font.BOLD, 14));
		verdictArea.setForeground(Color.WHITE);
		verdictArea.setBorder(new EmptyBorder(0, 0, PADDING, 0));
		// A read-only text box that can take the focus shows its caret; this one is a label that wraps, not a box.
		verdictArea.setFocusable(false);
		content.add(verdictArea, BorderLayout.NORTH);

		reportArea.setEditable(false);
		reportArea.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 11));
		reportArea.setBackground(ColorScheme.DARK_GRAY_COLOR);
		reportArea.setForeground(Color.WHITE);
		reportArea.setCaretColor(Color.WHITE);
		final JScrollPane scroll = new JScrollPane(reportArea);
		scroll.setBorder(null);
		content.add(scroll, BorderLayout.CENTER);

		copyButton = button(COPY_TEXT);
		copyButton.addActionListener(e -> copy());
		copyButton.setEnabled(false);
		closeButton = button(CLOSE_TEXT);
		closeButton.addActionListener(e -> dispose());
		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		buttons.setOpaque(false);
		buttons.setBorder(new EmptyBorder(PADDING, 0, 0, 0));
		buttons.add(copyButton);
		buttons.add(closeButton);
		content.add(buttons, BorderLayout.SOUTH);

		copiedTimer = new Timer(COPIED_MS, e -> copyButton.setText(COPY_TEXT));
		copiedTimer.setRepeats(false);
	}

	private static JButton button(String text)
	{
		final JButton b = new JButton(text);
		b.setFocusPainted(false);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setMargin(new Insets(1, 5, 1, 5));
		return b;
	}

	/**
	 * Swing thread. Opens the window on "Testing..." and answers it, so the caller can {@link #show} the report later.
	 *
	 * @param owner     the RuneLite frame (the panel's window ancestor), or null
	 * @param clipboard where <i>Copy report</i> puts the text
	 */
	static TroubleshootDialog open(Window owner, Predicate<String> clipboard)
	{
		final TroubleshootDialog window = window(owner, clipboard);
		window.dialog.setVisible(true);
		// Enter presses whichever control holds the focus, and a focused text box shows a caret: Close while the
		// window says "Testing..." (Copy report is disabled then).
		window.closeButton.requestFocusInWindow();
		return window;
	}

	/**
	 * The window built and sized but not yet shown: a non-modal {@link JDialog} owned by {@code owner}, titled
	 * {@link #TITLE}, closing by disposing, hosting {@link #content}. Needs a display.
	 */
	static TroubleshootDialog window(Window owner, Predicate<String> clipboard)
	{
		final TroubleshootDialog window = new TroubleshootDialog(clipboard);
		final JDialog host = new JDialog(owner, TITLE);
		host.setModalityType(Dialog.ModalityType.MODELESS);
		host.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
		host.setContentPane(window.content);
		host.setSize(WIDTH, HEIGHT);
		host.setLocationRelativeTo(owner);
		host.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosed(WindowEvent e)
			{
				window.closed();
			}
		});
		window.dialog = host;
		return window;
	}

	/**
	 * Swing thread. The report is in: its verdict replaces "Testing...", its text fills the box, scrolled to the top,
	 * and <i>Copy report</i> is ready when there is a text.
	 */
	void show(Report answer)
	{
		final Report r = answer == null ? new Report("", "") : answer;
		verdictArea.setText(r.verdict);
		reportArea.setText(r.text);
		reportArea.setCaretPosition(0);
		report = r.text;
		resetCopy(!report.isEmpty());
		if (!report.isEmpty())
		{
			// The answer is in: Copy report takes the focus, so Enter copies and no text box shows a caret. Answers
			// false without a window, which is a test.
			copyButton.requestFocusInWindow();
		}
	}

	/** Swing thread. Another test starts in this same window: "Testing..." and an empty box, as when it opened. */
	void testing()
	{
		verdictArea.setText(TESTING);
		reportArea.setText("");
		report = "";
		resetCopy(false);
	}

	/** True until the window is closed, by {@link #dispose}, by Close or by its own close box. */
	boolean isOpen()
	{
		return !closed;
	}

	/** Swing thread. Brings a standing window to the front; nothing without one. */
	void toFront()
	{
		final JDialog host = dialog;
		if (host != null && !closed)
		{
			host.toFront();
		}
	}

	/** Swing thread. Closes the window and stops the timer; harmless when it is already closed or never had one. */
	void dispose()
	{
		final JDialog host = dialog;
		dialog = null;
		closed();
		if (host != null)
		{
			host.dispose();
		}
	}

	/** The report on show: "" until {@link #show} and again after {@link #testing}. */
	String report()
	{
		return report;
	}

	private void closed()
	{
		closed = true;
		copiedTimer.stop();
	}

	/** The copy button back to its label, enabled or not, with the timer stopped. */
	private void resetCopy(boolean enabled)
	{
		copiedTimer.stop();
		copyButton.setText(COPY_TEXT);
		copyButton.setEnabled(enabled);
	}

	/** The copy button's press: the report to the clipboard, and "Copied" for {@value #COPIED_MS} ms if it took it. */
	private void copy()
	{
		if (clipboard.test(report))
		{
			copyButton.setText(COPIED_TEXT);
			copiedTimer.restart();
		}
	}
}

package com.whylag.ui;

import com.whylag.core.Level;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The panel's colours, fonts and text helpers (contract 5): one place, so every block of picture 18 paints from the
 * same table. Stateless; the painters call it on the Swing thread.
 *
 * <p><b>Fonts.</b> The three RuneScape faces at their native 16 px, and ONE derived font, {@link #RSB32}: the bold
 * face at its exact double, for the two big lines of the answer card and nothing else. A pixel font is sharp only
 * at whole multiples, so no other size is ever made; {@code AnswerCardTest} scans this package and finds the one
 * derivation, here. Text anti-aliasing is off everywhere ({@link #prepare}).
 *
 * <p><b>Colours.</b> The table of contract 5. The three level colours are {@code ColorScheme}'s progress colours;
 * red TEXT is never the stock red, which measures under 4.5:1 on the card, but {@link #BAD_TEXT}.
 *
 * <p>Choice: text is measured on a 1 x 1 image with the painters' own settings, so a measured width is painted.
 */
final class Ui
{
	/**
	 * The narrowest a block may be, and the width it assumes while it has no size yet: {@code PANEL_WIDTH} (225) less
	 * the 6 px border on each side. A block paints to {@link #widthOf} - its own width - and never to this constant.
	 */
	static final int WIDTH = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET;

	/** The panel; the divider inside the card; the ground between blocks. #282828. */
	static final Color GROUND = ColorScheme.DARK_GRAY_COLOR;
	/** The card, the cells, the lanes, the rows, the fold rows, the buttons. #1E1E1E. */
	static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
	/** A selected row; an OPENED fold row. #3C3C3C. */
	static final Color CARD_SELECTED = ColorScheme.DARKER_GRAY_HOVER_COLOR;
	/** Chip borders, the axis, the card's edge at NO_DATA. #4D4D4D. */
	static final Color RULE = ColorScheme.MEDIUM_GRAY_COLOR;
	/** Button borders. #171717. */
	static final Color BORDER = ColorScheme.BORDER_COLOR;
	/** Body text. #C6C6C6. */
	static final Color TEXT = ColorScheme.TEXT_COLOR;
	/** Labels, small lines, chevrons. #A5A5A5. */
	static final Color LABEL = ColorScheme.LIGHT_GRAY_COLOR;
	/** Values, line 2 of the answer, selected text. */
	static final Color WHITE = new Color(255, 255, 255);
	/** The chosen chip, "Fix", the main button, the selection. #DC8A00. */
	static final Color ORANGE = ColorScheme.BRAND_ORANGE;
	/** OK: shape, edge, line AND text. 55,240,70. */
	static final Color OK = ColorScheme.PROGRESS_COMPLETE_COLOR;
	/** WARN: shape, edge, line AND text. 230,150,30. */
	static final Color WARN = ColorScheme.PROGRESS_INPROGRESS_COLOR;
	/** BAD: shape, edge, line. NEVER text. 230,30,30. */
	static final Color BAD = ColorScheme.PROGRESS_ERROR_COLOR;
	/** Every red TEXT: the big line, a culprit's value, a strip value. 255,90,90. */
	static final Color BAD_TEXT = new Color(255, 90, 90);
	/** The ground of the culprit cell. #3A2424. */
	static final Color CULPRIT = new Color(58, 36, 36);
	/** The name and the unit in the culprit cell. #D6C0C0. */
	static final Color CULPRIT_LABEL = new Color(214, 192, 192);
	/** An event band. */
	static final Color BAND = new Color(230, 150, 30, 33);
	/** The band in the culprit lane. */
	static final Color BAND_CULPRIT = new Color(230, 30, 30, 102);
	/** The band of the selected event. */
	static final Color BAND_SELECTED = new Color(220, 138, 0, 77);
	/** The 1 px shadow under a lane's value. */
	static final Color SHADOW = new Color(0, 0, 0);

	/** RuneScape, 16 px. */
	static final Font RS = FontManager.getRunescapeFont();
	/** RuneScape Bold, 16 px. */
	static final Font RSB = FontManager.getRunescapeBoldFont();
	/** RuneScape Small, 16 px. */
	static final Font RSS = FontManager.getRunescapeSmallFont();
	/** RuneScape Bold at 32 px, its exact double: the answer card's two big lines, and nothing else. */
	static final Font RSB32 = FontManager.getRunescapeBoldFont().deriveFont(32f);

	/** What a line that does not fit ends with: three ASCII dots (the RuneScape faces have no U+2026). */
	static final String DOTS = "...";

	/** The image text is measured on; see the class notes. */
	private static final Graphics2D MEASURE = measureGraphics();

	private Ui()
	{
	}

	/**
	 * The width a block paints to and hit-tests against: its own width, held at {@link #WIDTH} at the least, and
	 * {@link #WIDTH} while it has no size yet.
	 */
	static int widthOf(java.awt.Component c)
	{
		return c.getWidth() > 0 ? Math.max(WIDTH, c.getWidth()) : WIDTH;
	}

	/** The graphics as a {@link Graphics2D} with text anti-aliasing, shape anti-aliasing and fractions off. */
	static Graphics2D prepare(Graphics g)
	{
		final Graphics2D g2 = (Graphics2D) g;
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
		return g2;
	}

	/** The metrics of a font as the blocks paint it. */
	static FontMetrics metrics(Font font)
	{
		synchronized (MEASURE)
		{
			return MEASURE.getFontMetrics(font);
		}
	}

	/** The painted width of {@code text} in {@code font}; 0 for null or "". */
	static int width(Font font, String text)
	{
		return text == null || text.isEmpty() ? 0 : metrics(font).stringWidth(text);
	}

	/** Draws {@code text} with its baseline at {@code baseline}, left edge at {@code x}. */
	static void text(Graphics2D g, String text, int x, int baseline, Font font, Color colour)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		g.setFont(font);
		g.setColor(colour);
		g.drawString(text, x, baseline);
	}

	/** {@link #text}, with a 1 px black shadow one pixel right and down. */
	static void shadowed(Graphics2D g, String text, int x, int baseline, Font font, Color colour)
	{
		text(g, text, x + 1, baseline + 1, font, SHADOW);
		text(g, text, x, baseline, font, colour);
	}

	/**
	 * {@code text} as it fits {@code room} px of {@code font}: whole when it fits, else cut at a character and ended
	 * with {@link #DOTS}. Never clipped mid-glyph.
	 */
	static String fit(Font font, String text, int room)
	{
		final String full = text == null ? "" : text;
		if (width(font, full) <= room)
		{
			return full;
		}
		for (int end = full.length() - 1; end > 0; end--)
		{
			final String cut = full.substring(0, end).trim() + DOTS;
			if (width(font, cut) <= room)
			{
				return cut;
			}
		}
		return width(font, DOTS) <= room ? DOTS : "";
	}

	/**
	 * {@code text} wrapped on spaces into lines of {@code font}: the first line has {@code firstRoom} px, every
	 * other {@code room} px. At most {@code maxLines}: what does not fit on the last one is cut with
	 * {@link #DOTS} ({@link #fit}). A word wider than its line is cut the same way. "" gives no line.
	 */
	static List<String> wrap(Font font, String text, int firstRoom, int room, int maxLines)
	{
		if (text == null || text.trim().isEmpty() || maxLines <= 0)
		{
			return Collections.emptyList();
		}
		final List<String> all = new ArrayList<>();
		final StringBuilder line = new StringBuilder();
		for (String word : text.trim().split(" +"))
		{
			final int lineRoom = all.isEmpty() ? firstRoom : room;
			if (line.length() == 0)
			{
				line.append(word);
				continue;
			}
			final String longer = line + " " + word;
			if (width(font, longer) <= lineRoom)
			{
				line.append(' ').append(word);
			}
			else
			{
				all.add(fit(font, line.toString(), lineRoom));
				line.setLength(0);
				line.append(word);
			}
		}
		all.add(fit(font, line.toString(), all.isEmpty() ? firstRoom : room));
		if (all.size() <= maxLines)
		{
			return all;
		}
		// Too many lines: the last one allowed takes the rest, cut with the dots.
		final List<String> out = new ArrayList<>(all.subList(0, maxLines - 1));
		final String rest = String.join(" ", all.subList(maxLines - 1, all.size()));
		out.add(fit(font, rest, maxLines == 1 ? firstRoom : room));
		return out;
	}

	/** The colour of a level's TEXT: OK green, WARN amber, BAD {@link #BAD_TEXT}, NO_DATA {@link #LABEL}. */
	static Color textColour(Level level)
	{
		if (level == null)
		{
			return LABEL;
		}
		switch (level)
		{
			case OK:
				return OK;
			case WARN:
				return WARN;
			case BAD:
				return BAD_TEXT;
			default:
				return LABEL;
		}
	}

	/**
	 * The colour of a level's MARK - a shape, an edge, a line: OK green, WARN amber, BAD the stock red, and
	 * NO_DATA {@link #LABEL}, the hollow ring's grey.
	 */
	static Color markColour(Level level)
	{
		if (level == null)
		{
			return LABEL;
		}
		switch (level)
		{
			case OK:
				return OK;
			case WARN:
				return WARN;
			case BAD:
				return BAD;
			default:
				return LABEL;
		}
	}

	/** The colour of a coloured EDGE or border: the level's mark, and {@link #RULE} at NO_DATA. */
	static Color edgeColour(Level level)
	{
		return level == null || level == Level.NO_DATA ? RULE : markColour(level);
	}

	private static Graphics2D measureGraphics()
	{
		final Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		return prepare(g);
	}
}

package com.whylag.ui;

import com.whylag.GraphRange;
import com.whylag.PanelActions;
import com.whylag.PanelControl;
import com.whylag.Report;
import com.whylag.core.Cells;
import com.whylag.core.Fmt;
import com.whylag.core.LagEvent;
import com.whylag.core.PanelSnapshot;
import com.whylag.core.ReportText;
import com.whylag.core.Verdict;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.HeadlessException;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.datatransfer.StringSelection;
import java.util.Collections;
import java.util.function.BiFunction;
import java.util.function.Predicate;
import javax.swing.JComponent;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.PluginPanel;

/**
 * The side panel of picture 18, "Big Answer" (contract 5): top down, the header with the settings gear at its right
 * end, the answer card, the three cells, the range row, the "Graphs" fold row with the three lanes behind it, the
 * "Lags (n)" fold row with the event list behind it, the session's total and its counts, and in developer mode a
 * footer under that. The gear opens a menu of the badge's four settings and "Troubleshoot...", which runs the ten
 * checks and shows the report in a window (1.0.1, lot C); the panel has no button, no verdict line and no version
 * row - the version is the menu's last row. Content width 213 px at the panel's own 225, and the
 * width of the sidebar less the border when it is wider (230 in the client), on the {@link Ui#GROUND} ground. Every
 * block is one custom-painted component, so a one-second update is a few field writes and one repaint of each
 * block.
 *
 * <p><b>Showing.</b> {@link #show} runs on the Swing thread. While the panel is hidden it keeps the snapshot and
 * paints nothing (T9); {@link #onActivate} asks the plugin for one snapshot at once. A show changes the layout only
 * when a block in it changed its height - the card's text, the list's rows, the counts' lines (T11) - and
 * repaints each block in the layout once.
 *
 * <p><b>The fold rows.</b> Both are folded when the panel is built; the state is two fields that last as long as
 * the panel. A folded block is not in the layout, so it is neither measured nor painted (T17); a press on a row
 * lays the panel out once.
 *
 * <p><b>A selected event.</b> A press on a list row selects its event: the card shows that event's verdict, the
 * cells and the lane values its numbers, and its band is drawn as selected. A second press on the row, a range
 * change or {@link #onDeactivate} clears it; a fold does not.
 *
 * <p>Choice: a column layout of the panel's own puts each block at the left border, as wide as the panel less its
 * border (213 at least), under its gap of contract 5.
 * <p>Choice: a show lays out only when a block in the layout changed its height; a fold press lays out once.
 * <p>Choice: {@link #onActivate} paints the kept snapshot at once, then asks the plugin for a fresh one.
 * <p>Choice: an id not among the snapshot's range events clears the selection, also when its event ages out.
 * <p>Choice: a selected event with no verdict (only a test builds one) leaves the card on the snapshot's verdict.
 * <p>Choice: a press on the chip of the range already shown does nothing.
 * <p>Choice: the gear does nothing before the first snapshot: the menu is built from the last snapshot's settings, and
 * the first one comes within a second of the panel showing ({@link #onActivate} asks for it at once).
 * <p>Choice: the menu is built FRESH at every open, so it ticks what the newest snapshot holds; a press on the gear
 * while the menu stands takes it down and opens nothing, and a press within {@code HeaderRow.MENU_REOPEN_MS} of its
 * closing opens nothing either (the header's rule). The menu opens under the gear with its right edge at the gear's.
 * <p>Choice: "Troubleshoot..." does nothing before the first snapshot, and answers "" then; it opens the window at
 * once on "Testing..." - or re-uses the one that stands, for a new test - and hands the last snapshot to the actions.
 * <p>Choice: a press also starts a one-shot Swing timer of {@value #TEST_TIMEOUT_MS} ms, stopped when the report
 * comes back and when the panel is hidden. When it fires first the sampler thread is hung, and the window is filled
 * with a FALLBACK report made here: {@link ReportText#of(PanelSnapshot, String)} of the kept last snapshot with a
 * Verdict and a Checks block that say the sampler did not answer, and {@value #NO_ANSWER} as its verdict. The
 * press's generation is then spent, so a report that comes later is ignored.
 * <p>Choice: the fallback is safe on the Swing thread because the snapshot is immutable and every string in it (the
 * minute log, the diagnostics text) was made on the sampler thread before it was handed over: the fallback only
 * joins them, and reads no ring, no client state and no lock the hung thread could hold.
 * <p>Choice: the report comes back on the Swing thread through {@code PanelActions.testAndReport}'s callback and
 * fills the window it was asked for, when that window still stands; nothing is copied until the player presses
 * "Copy report" in it.
 * <p>Choice: hiding the panel closes the window and stops the timeout: nobody is waiting for the report.
 * <p>Choice: {@link #troubleshoot()} answers the text only when the callback ran before it returned (a stub's); the
 * plugin's answer comes later, so it answers "".
 * <p>Choice: {@link #component()} is the panel itself.
 * <p>Choice: the developer-mode footer is a block of 213 x 14 (as wide as the panel gives it), RuneScape Small at
 * baseline 11, cut with "...".
 * <p>Choice: the session's counts are the last block of the panel, and the developer-mode footer sits under them
 * with its 6 px gap.
 */
public final class WhyLagPanel extends PluginPanel implements PanelControl
{
	/** The client property that holds a block's gap above it. */
	private static final String GAP = "whylag.gap";
	/** How long a press waits for the sampler's report before the panel copies its own fallback. */
	static final int TEST_TIMEOUT_MS = 3000;
	/** The fallback report's verdict, shown in the window when the fallback was made. */
	static final String NO_ANSWER = "Sampler did not answer in 3 s";
	/** The Verdict and Checks lines the fallback report carries in place of the checks, blank lines included. */
	private static final String NO_ANSWER_CHECKS = "Verdict: The plugin's sampler did not answer in 3 s.\n\n"
		+ "Checks: not run (the sampler thread did not answer; the notes and the last 60 minutes below are from the"
		+ " last snapshot)\n\n";

	private final PanelActions actions;
	private final HeaderRow header;
	private final AnswerCard card = new AnswerCard();
	private final CellStrip cells = new CellStrip();
	private final RangeRow rangeRow;
	private final FoldRow graphsRow;
	private final FoldRow lagsRow;
	private final StripChart strips = new StripChart();
	private final EventList list;
	private final SessionHeader sessionHeader = new SessionHeader();
	private final SessionCounts counts = new SessionCounts();
	private final Timer testTimeout;
	private final Footer footer;

	/** Where the report is copied to; true when the clipboard took it. A seam: tests hand in their own. */
	Predicate<String> clipboard = WhyLagPanel::toSystemClipboard;
	/**
	 * How the Troubleshoot window is opened, handed the panel's window and the clipboard: the real one, which needs a
	 * display. A seam: tests hand in a window-less one.
	 */
	BiFunction<Window, Predicate<String>, TroubleshootDialog> dialogOpener = TroubleshootDialog::open;

	private volatile int range;
	private volatile boolean graphsOpen;
	private volatile boolean lagsOpen;
	private volatile boolean active;
	private volatile int activations;
	private volatile int deactivations;
	/** The newest snapshot handed to {@link #show}; Swing thread only. Package-private: a test seam (PanelPeek). */
	PanelSnapshot last;
	/** The selected event's id, -1 = none; Swing thread only. */
	private long selectedId = -1;
	/** Counts presses and spent fallbacks: a report whose press is not the newest generation is stale; Swing thread only. */
	private int pressGeneration;
	/** The Troubleshoot window that stands, null when none does; Swing thread only. */
	private TroubleshootDialog dialog;
	/** The gear menu built at the last open, null before the first; Swing thread only. */
	private JPopupMenu menu;

	/**
	 * The panel. {@code initial} is the range its chips show first (null: 10 min); {@code developerMode} adds the
	 * footer.
	 */
	public WhyLagPanel(PanelActions actions, GraphRange initial, boolean developerMode)
	{
		super();
		this.actions = actions;
		range = (initial == null ? GraphRange.TEN_MIN : initial).minutes();
		rangeRow = new RangeRow(this::pressRange);
		graphsRow = new FoldRow("Graphs", false, () -> fold(!graphsOpen, lagsOpen));
		lagsRow = new FoldRow("Lags", true, () -> fold(graphsOpen, !lagsOpen));
		list = new EventList(this::rowPressed);
		header = new HeaderRow(this::openMenu);
		testTimeout = new Timer(TEST_TIMEOUT_MS, e -> samplerDidNotAnswer());
		testTimeout.setRepeats(false);
		footer = developerMode ? new Footer() : null;

		rangeRow.set(range);
		list.set(Collections.emptyList(), -1, range, null);
		setLayout(new Column());
		setBackground(Ui.GROUND);
		gap(header, 0);
		gap(card, 8);
		gap(cells, 8);
		gap(rangeRow, 12);
		gap(graphsRow, 4);
		gap(strips, 3);
		gap(lagsRow, 4);
		gap(list, 3);
		gap(sessionHeader, 12);
		gap(counts, 4);
		add(header);
		add(card);
		add(cells);
		add(rangeRow);
		add(graphsRow);
		add(lagsRow);
		add(sessionHeader);
		add(counts);
		if (footer != null)
		{
			gap(footer, 6);
			add(footer);
		}
	}

	private static void gap(JComponent block, int px)
	{
		block.putClientProperty(GAP, px);
	}

	/** Draws a snapshot. Swing thread only. While the panel is hidden it is kept, and nothing is painted. */
	public void show(PanelSnapshot s)
	{
		if (s == null)
		{
			return;
		}
		last = s;
		if (active)
		{
			apply(s);
		}
	}

	private void apply(PanelSnapshot s)
	{
		final LagEvent picked = picked(s);
		final Verdict shown = picked != null && picked.verdict != null ? picked.verdict : s.verdict;
		boolean layout = false;
		header.set(s.world);
		layout |= card.set(shown, s);
		cells.set(picked != null ? Cells.of(picked) : Cells.now(s));
		rangeRow.set(range);
		rangeRow.held(s.stretched() ? Fmt.held(s.rangeEndWallMs - s.rangeStartWallMs) : "");
		graphsRow.setOpen(graphsOpen);
		lagsRow.setOpen(lagsOpen);
		lagsRow.setCount(s.rangeEvents.size());
		strips.set(s, picked);
		layout |= list.set(s.rangeEvents, selectedId, s.rangeMinutes, s.zone) && lagsOpen;
		sessionHeader.set(s.sessionTotal);
		layout |= counts.set(s.sessionCounts);
		if (footer != null)
		{
			footer.set(s.footer);
		}
		if (layout)
		{
			revalidate();
		}
		repaintBlocks();
	}

	/** The selected event among the snapshot's range events; clears the selection when it is not there. */
	private LagEvent picked(PanelSnapshot s)
	{
		if (selectedId < 0)
		{
			return null;
		}
		final LagEvent e = inRange(s, selectedId);
		if (e == null)
		{
			selectedId = -1;
		}
		return e;
	}

	private static LagEvent inRange(PanelSnapshot s, long id)
	{
		if (s == null)
		{
			return null;
		}
		for (LagEvent e : s.rangeEvents)
		{
			if (e != null && !e.open && e.id == id)
			{
				return e;
			}
		}
		return null;
	}

	@Override
	public void onActivate()
	{
		active = true;
		activations++;
		if (last != null)
		{
			apply(last);
		}
		actions.activated();
	}

	@Override
	public void onDeactivate()
	{
		active = false;
		deactivations++;
		selectedId = -1;
		testTimeout.stop();
		closeDialog();
	}

