					final int n = a.line2.isEmpty() ? 1 : 2;
					final int tw = Math.max(width(a.line1), width(a.line2));
					assertSize(style + " " + a.oneLine + " " + level + ": 5 + pw + 5 + tw + 7 by 8 + max(ph, 17 n)",
