		assertEquals("one line", 25, paint(BadgeStyle.SHAPE_AND_WORDS, Level.OK, Answer.SMOOTH, false).getHeight());
		assertEquals("one line", 25, paint(BadgeStyle.SHAPE_AND_WORDS, Level.NO_DATA, Answer.WAITING, false)
