	@Test
	public void aWordStyleWithNoIconDrawsTheShape()
	{
		final BufferedImage smooth = paint(BadgeStyle.ICON_AND_WORDS, Level.OK, Answer.SMOOTH, false);
		assertSize("smooth: the 14 px circle", 5 + 14 + 5 + width("Smooth") + 7, 25, smooth);
