import com.whylag.core.Level;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.ui.FontManager;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Pictures for the checker's eye (contract P2.3, section 8): every state of picture 22, part A - smooth, world lag,
 * ping lag, low FPS, client froze (slow, not lag: a triangle), not sure, measuring - and the
 * dimmed world lag, in each of the four styles, each on a dark green ground ({@code badge-<style>-<state>}), and ONE
 * sheet of them all ({@code badge-sheet}). The pictures are checked in memory to exist and not to be blank; the
 * local-only probe's {@code PicturesTest} writes them to {@code build/whylag/<name>.png}.
 *
 * <p>Choice: the ground is 38,58,30 with 6 px round each badge; the sheet: styles as columns, states as rows.
 * <p>Choice: a file is badge-{style}-{state}.png, both in lower case with dashes: badge-icon-and-words-world-lag.png.
 * <p>Choice: the client-froze row is WARN with "Client froze", as picture 22's row 5 ("slow, not lag: triangle").
 */
public class BadgeRenderTest
{
	private static final Color GRASS = new Color(38, 58, 30);
	private static final int MARGIN = 6;
	private static final String[] STYLE_NAMES = {"icon", "icon-and-words", "shape-and-words", "shape-only"};

	/** One row of picture 22, part A (and the dimmed lag of part D). */
	private static final class State
	{
		final String name;
		final Level level;
		final Answer answer;
		final boolean dimmed;
		final String tip1;
		final String tip2;

		State(String name, Level level, Answer answer, boolean dimmed, String tip1, String tip2)
		{
			this.name = name;
			this.level = level;
			this.answer = answer;
			this.dimmed = dimmed;
			this.tip1 = tip1;
			this.tip2 = tip2;
		}

		BadgeView view(BadgeStyle style)
		{
			return new BadgeView(true, style, level, answer.icon, dimmed, answer.line1, answer.line2, tip1, tip2);
		}
	}

	private static List<State> states()
	{
		final List<State> out = new ArrayList<>();
		out.add(new State("smooth", Level.OK, Answer.SMOOTH, false, "Smooth. No lag for 4 min.", ""));
		final Answer world = Answer.of(Cause.SLOW_WORLD);
		out.add(new State("world-lag", Level.BAD, world, false, world.oneLine, "Ticks 1,240 ms, ping 41 ms"));
		final Answer ping = Answer.of(Cause.PING_JUMPY);
		out.add(new State("ping-lag", Level.BAD, ping, false, ping.oneLine, "Ping 310 ms, ticks 1,240 ms"));
		final Answer fps = Answer.of(Cause.SLOW_DRAWING);
		out.add(new State("low-fps", Level.BAD, fps, false, fps.oneLine, "Worst frame 480 ms, 50 fps"));
		final Answer froze = Answer.of(Cause.CLIENT_BUSY);
		out.add(new State("client-froze", Level.WARN, froze, false, froze.oneLine, "Worst frame 340 ms, 50 fps"));
		final Answer lag = Answer.of(Cause.NOT_SURE);
		out.add(new State("not-sure", Level.BAD, lag, false, lag.oneLine, "Ticks 1,240 ms, worst frame 170 ms"));
		out.add(new State("measuring", Level.NO_DATA, Answer.MEASURING, false, "Still measuring", "Ready in 40 s."));
		out.add(new State("world-lag-dimmed", Level.BAD, world, true, world.oneLine, "Ticks 1,240 ms, ping 41 ms"));
		return out;
	}

	/**
	 * The pictures of this test, by file name without the extension: every state in every style on the grass,
	 * {@code badge-<style>-<state>}, and the sheet of them all, {@code badge-sheet}. The probe's {@code PicturesTest}
	 * writes them to {@code build/whylag} for the lead's eye; this test checks them in memory.
	 */
	public static Map<String, BufferedImage> pictures()
	{
		final BadgePainter painter = new BadgePainter(new BadgeIcons());
		final List<State> states = states();
		final BadgeStyle[] styles = BadgeStyle.values();
		final BufferedImage[][] badges = new BufferedImage[states.size()][styles.length];
		final Map<String, BufferedImage> out = new LinkedHashMap<>();
		for (int r = 0; r < states.size(); r++)
		{
			for (int c = 0; c < styles.length; c++)
			{
				final BufferedImage badge = painter.paint(states.get(r).view(styles[c]));
				assertNotNull(badge);
				badges[r][c] = badge;
				final BufferedImage onGrass = new BufferedImage(badge.getWidth() + 2 * MARGIN,
					badge.getHeight() + 2 * MARGIN, BufferedImage.TYPE_INT_ARGB);
				final Graphics2D g = onGrass.createGraphics();
				g.setColor(GRASS);
				g.fillRect(0, 0, onGrass.getWidth(), onGrass.getHeight());
				g.drawImage(badge, MARGIN, MARGIN, null);
				g.dispose();
				out.put("badge-" + STYLE_NAMES[c] + "-" + states.get(r).name, onGrass);
			}
		}
		out.put("badge-sheet", sheet(states, styles, badges));
		return out;
	}

	@Test
	public void paintsEveryStateInEveryStyle()
	{
		final Map<String, BufferedImage> pictures = pictures();
		final BadgePainter painter = new BadgePainter(new BadgeIcons());
		final List<State> states = states();
		final BadgeStyle[] styles = BadgeStyle.values();

		assertEquals("8 states x 4 styles, and the sheet", 33, pictures.size());
		for (Map.Entry<String, BufferedImage> e : pictures.entrySet())
		{
			final String name = e.getKey();
			final BufferedImage picture = e.getValue();
			assertTrue(name.startsWith("badge-"));
			assertNotNull(name, picture);
			assertTrue(name + " is not blank", distinctColours(picture) >= 3);
			assertEquals(name + ": the grass in the corner", GRASS.getRGB(), picture.getRGB(0, 0));
		}
		for (int r = 0; r < states.size(); r++)
		{
			for (int c = 0; c < styles.length; c++)
			{
				final String name = "badge-" + STYLE_NAMES[c] + "-" + states.get(r).name;
				final BufferedImage badge = painter.paint(states.get(r).view(styles[c]));
				final BufferedImage picture = pictures.get(name);
				assertNotNull(name, picture);
				assertEquals(name + ": the badge and the grass round it", badge.getWidth() + 2 * MARGIN,
					picture.getWidth());
				assertEquals(badge.getHeight() + 2 * MARGIN, picture.getHeight());
				assertTrue(name + ": the badge's box is on the grass", picture.getRGB(MARGIN, MARGIN) != GRASS.getRGB());
			}
		}
	}

	/** The styles as columns, the states as rows, every badge on the grass with its state's name beside it. */
	private static BufferedImage sheet(List<State> states, BadgeStyle[] styles, BufferedImage[][] badges)
	{
		final int labelWidth = 120;
		final int headerHeight = 22;
		final int[] columnWidth = new int[styles.length];
		final int[] rowHeight = new int[states.size()];
		final Graphics2D scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		final java.awt.FontMetrics small = scratch.getFontMetrics(FontManager.getRunescapeSmallFont());
		for (int c = 0; c < styles.length; c++)
		{
			columnWidth[c] = small.stringWidth(styles[c].toString()) + 2 * MARGIN;
		}
		scratch.dispose();
		for (int r = 0; r < states.size(); r++)
		{
			for (int c = 0; c < styles.length; c++)
			{
				columnWidth[c] = Math.max(columnWidth[c], badges[r][c].getWidth() + 2 * MARGIN);
				rowHeight[r] = Math.max(rowHeight[r], badges[r][c].getHeight() + 2 * MARGIN);
			}
		}
		int width = labelWidth;
		for (int w : columnWidth)
		{
			width += w;
		}
		int height = headerHeight;
		for (int h : rowHeight)
		{
			height += h;
		}
		final BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		g.setColor(GRASS);
		g.fillRect(0, 0, width, height);
		g.setFont(FontManager.getRunescapeSmallFont());
		int x = labelWidth;
		for (int c = 0; c < styles.length; c++)
		{
			label(g, styles[c].toString(), x + MARGIN, 16);
			x += columnWidth[c];
		}
		int y = headerHeight;
		for (int r = 0; r < states.size(); r++)
		{
			label(g, states.get(r).name, MARGIN, y + rowHeight[r] / 2 + 5);
			x = labelWidth;
			for (int c = 0; c < styles.length; c++)
			{
				g.drawImage(badges[r][c], x + MARGIN, y + MARGIN, null);
				x += columnWidth[c];
			}
			y += rowHeight[r];
		}
		g.dispose();
		return out;
	}

	private static void label(Graphics2D g, String text, int x, int y)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(Color.WHITE);
		g.drawString(text, x, y);
	}

	private static int distinctColours(BufferedImage img)
	{
		final Set<Integer> seen = new HashSet<>();
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				seen.add(img.getRGB(x, y));
			}
		}
		return seen.size();
	}
}

package com.whylag;

import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.verifyNoMoreInteractions;

/**
 * The badge's chat line (contract P2.6, T21): one CONSOLE message QUEUED on the {@link ChatMessageManager}, its
 * RuneLite-formatted text the line as given, with no tag or colour added, and nothing else asked of the manager;
 * {@code send} never throws, and a null or empty line queues nothing.
 */
public class ChatLineTest
{
	private static final String LINE = "[Why Lag] World lag - not you (14 s). Ticks 1,240 ms, ping 41 ms.";

	@Test
	public void queuesOneConsoleMessage()
	{
		final ChatMessageManager chat = mock(ChatMessageManager.class);
		new ChatLine(chat).send(LINE);
		final ArgumentCaptor<QueuedMessage> queued = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(chat, times(1)).queue(queued.capture());
		verifyNoMoreInteractions(chat);
		final QueuedMessage m = queued.getValue();
		assertSame(ChatMessageType.CONSOLE, m.getType());
		assertEquals("the line as given: no tag, no colour of its own", LINE, m.getRuneLiteFormattedMessage());
		assertNull("no raw value", m.getValue());
		assertNull("no name", m.getName());
		assertNull("no sender", m.getSender());
		assertEquals("no timestamp of its own", 0, m.getTimestamp());
	}

	@Test
	public void eachSendQueuesItsOwnMessage()
	{
		final ChatMessageManager chat = mock(ChatMessageManager.class);
		final ChatLine line = new ChatLine(chat);
		line.send(LINE);
		line.send("[Why Lag] Lag - can't tell why (3 s).");
		final ArgumentCaptor<QueuedMessage> queued = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(chat, times(2)).queue(queued.capture());
		final List<QueuedMessage> all = queued.getAllValues();
		assertEquals(LINE, all.get(0).getRuneLiteFormattedMessage());
		assertEquals("[Why Lag] Lag - can't tell why (3 s).", all.get(1).getRuneLiteFormattedMessage());
		verifyNoMoreInteractions(chat);
	}

	@Test
	public void neverThrows()
	{
		final ChatMessageManager chat = mock(ChatMessageManager.class);
		doThrow(new IllegalStateException("the queue refused")).when(chat).queue(any());
		final ChatLine line = new ChatLine(chat);
		line.send(LINE);
		line.send(LINE);
		verify(chat, times(2)).queue(any());

		new ChatLine(null).send(LINE);
	}

	/** Choice of ChatLine: RuneLite would fail on a message with no text later, on the client thread. */
	@Test
	public void aNullOrEmptyLineQueuesNothing()
	{
		final ChatMessageManager chat = mock(ChatMessageManager.class);
		final ChatLine line = new ChatLine(chat);
		line.send(null);
		line.send("");
		verifyNoInteractions(chat);
	}
}

package com.whylag;

import com.whylag.core.NoData;
import java.io.FileDescriptor;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.client.plugins.worldhopper.ping.Ping;
import net.runelite.client.plugins.worldhopper.ping.TCPInfo;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The connection probe (contract 3.11, 7 L7; T13): one test per outcome - not logged in, no socket, no TCPInfo, a
 * LinkageError, a RuntimeException, a reading - and {@code neverThrows}, which throws every kind of failure from
 * every point the probe calls. A read without data never hands on an earlier read's numbers.
 */
public class ConnectionProbeTest
{
	private static final FileDescriptor SOCKET = new FileDescriptor();

	/** The five points the probe calls, in its order. */
	private enum Point
	{
		SOCKET, INFO, RTT, SENT, RESENT
	}

	@Test
	public void notLoggedInIsNotLoggedIn()
	{
		final AtomicInteger asked = new AtomicInteger();
		final ConnectionProbe probe = new ConnectionProbe(() ->
		{
			asked.incrementAndGet();
			return SOCKET;
		}, fd -> tcp(40_000, 900, 0));
		final ConnSample out = reading();
		probe.read(false, out);
		assertNoData(NoData.NOT_LOGGED_IN, out);
		assertEquals("the socket is not asked while logged out", 0, asked.get());
	}

	@Test
	public void noSocketIsNotConnected()
	{
		final AtomicInteger infos = new AtomicInteger();
		final ConnSample out = reading();
		new ConnectionProbe(() -> null, fd ->
		{
			infos.incrementAndGet();
			return tcp(40_000, 900, 0);
		}).read(true, out);
		assertNoData(NoData.NOT_CONNECTED, out);
		assertEquals("no socket, no TCP numbers asked", 0, infos.get());
	}

	@Test
	public void noTcpInfoIsUnsupported()
	{
		final ConnSample out = reading();
		new ConnectionProbe(() -> SOCKET, fd -> null).read(true, out);
		assertNoData(NoData.UNSUPPORTED, out);
	}

	@Test
	public void aLinkageErrorIsUnsupported()
	{
		for (Point at : Point.values())
		{
			for (LinkageError e : new LinkageError[] {new NoClassDefFoundError("com/sun/jna/Native"),
				new UnsatisfiedLinkError("WSAIoctl"), new NoSuchMethodError("getSocketFD")})
			{
				final ConnSample out = reading();
				failingAt(at, e).read(true, out);
				assertNoData(e + " at " + at, NoData.UNSUPPORTED, out);
			}
		}
	}

	@Test
	public void aRuntimeExceptionIsError()
	{
		for (Point at : Point.values())
		{
			for (RuntimeException e : new RuntimeException[] {
				new SecurityException("JDK 17 without --add-opens: FileDescriptor.fd"),
				new IllegalStateException("closed"), new NullPointerException()})
			{
				final ConnSample out = reading();
				failingAt(at, e).read(true, out);
				assertNoData(e + " at " + at, NoData.ERROR, out);
			}
		}
	}

	@Test
	public void aReadingIsPassedOnAsTheSocketGivesIt()
	{
		final ConnSample out = new ConnSample();
		final ConnectionProbe probe = new ConnectionProbe(() -> SOCKET, fd ->
		{
			assertTrue("the socket's own descriptor is asked", fd == SOCKET);
			return tcp(41_250, 1_234_567_890_123L, 4_321);
		});
		probe.read(true, out);
		assertEquals(NoData.NONE, out.conn);
		assertEquals("microseconds, as TCPInfo gives them", 41_250, out.rttMicros);
		assertEquals("cumulative, not per second", 1_234_567_890_123L, out.sent);
		assertEquals(4_321, out.resent);
	}

	@Test
	public void aReadWithoutDataLeavesNoOldNumbers()
	{
		final boolean[] loggedIn = {true};
		final FileDescriptor[] socket = {SOCKET};
		final TCPInfo[] info = {tcp(40_000, 900, 7)};
		final ConnectionProbe probe = new ConnectionProbe(() -> socket[0], fd -> info[0]);
		final ConnSample out = new ConnSample();
		probe.read(true, out);
		assertEquals(NoData.NONE, out.conn);

		socket[0] = null;
		probe.read(true, out);
		assertNoData(NoData.NOT_CONNECTED, out);

		socket[0] = SOCKET;
		probe.read(true, out);
		assertEquals("the same sample reads again", NoData.NONE, out.conn);
		assertEquals(40_000, out.rttMicros);

		info[0] = null;
		probe.read(true, out);
		assertNoData(NoData.UNSUPPORTED, out);

		info[0] = tcp(40_000, 900, 7);
		probe.read(true, out);
		loggedIn[0] = false;
		probe.read(loggedIn[0], out);
		assertNoData(NoData.NOT_LOGGED_IN, out);
	}

	@Test
	public void aFailingGetterLeavesNoHalfReading()
	{
		final ConnSample out = new ConnSample();
		final ConnectionProbe good = new ConnectionProbe(() -> SOCKET, fd -> tcp(40_000, 900, 7));
		good.read(true, out);
		failingAt(Point.RESENT, new IllegalStateException()).read(true, out);
		assertNoData("rtt and sent were read before resent threw", NoData.ERROR, out);
	}

	@Test
	public void neverThrows()
	{
		final Throwable[] failures = {new RuntimeException(), new IllegalArgumentException(),
			new SecurityException("x"), new ArithmeticException(), new NoClassDefFoundError(),
			new UnsatisfiedLinkError(), new NoSuchMethodError(), new NoSuchFieldError(), new ClassFormatError(),
			new ExceptionInInitializerError()};
		for (Point at : Point.values())
		{
			for (Throwable t : failures)
			{
				final ConnSample out = reading();
				failingAt(at, t).read(true, out);
				assertNotEquals(t + " at " + at, NoData.NONE, out.conn);
				assertNotNull(out.conn);
			}
		}
		final ConnSample out = reading();
		new ConnectionProbe(null, null).read(true, out);
		assertNoData("no suppliers at all", NoData.ERROR, out);
		new ConnectionProbe(() -> SOCKET, fd -> tcp(1, 2, 3)).read(true, null);
		new ConnectionProbe(null, null).read(false, null);
	}

	@Test
	public void aNewSampleHoldsNoData()
	{
		final ConnSample fresh = new ConnSample();
		assertEquals(-1, fresh.rttMicros);
		assertEquals(-1, fresh.sent);
		assertEquals(-1, fresh.resent);
		assertNotNull("never null: a null would be stored as NONE, a fresh RTT (contract 3.3)", fresh.conn);
		assertNotEquals(NoData.NONE, fresh.conn);
	}

	/**
	 * The real seam, {@code Ping::getTCPInfo}, on a descriptor that is no socket: never NONE and never a throw. On
	 * JDK 17 without {@code --add-opens} Ping cannot read the descriptor and throws, which is ERROR, "Could not
	 * read it" (contract 7, L9); with the opens, the system call fails and Ping answers null, which is UNSUPPORTED.
	 */
	@Test
	public void theRealPingOnANonSocketIsNeverNone()
	{
		final ConnSample out = reading();
		new ConnectionProbe(FileDescriptor::new, Ping::getTCPInfo).read(true, out);
		assertTrue("ERROR or UNSUPPORTED: " + out.conn, out.conn == NoData.ERROR || out.conn == NoData.UNSUPPORTED);
		assertNoData(out.conn, out);
	}

	// ---------------------------------------------------------------- helpers

	/** A sample that holds a good reading, so a test sees each outcome overwrite it. */
	private static ConnSample reading()
	{
		final ConnSample s = new ConnSample();
		s.rttMicros = 39_000;
		s.sent = 800;
		s.resent = 1;
		s.conn = NoData.NONE;
		return s;
	}

	private static void assertNoData(NoData why, ConnSample out)
	{
		assertNoData(why.name(), why, out);
	}

	private static void assertNoData(String message, NoData why, ConnSample out)
	{
		assertEquals(message, why, out.conn);
		assertEquals(message + ": rtt", -1, out.rttMicros);
		assertEquals(message + ": sent", -1, out.sent);
		assertEquals(message + ": resent", -1, out.resent);
	}

	private static TCPInfo tcp(long rttMicros, long sent, long resent)
	{
		return new FakeTcp(rttMicros, sent, resent, null, null);
	}

	/** A probe whose call at {@code at} throws {@code t}; every other call answers a good reading. */
	private static ConnectionProbe failingAt(Point at, Throwable t)
	{
		final Supplier<FileDescriptor> socket = () ->
		{
			if (at == Point.SOCKET)
			{
				sneak(t);
			}
			return SOCKET;
		};
		final Function<FileDescriptor, TCPInfo> info = fd ->
		{
			if (at == Point.INFO)
			{
				sneak(t);
			}
			return new FakeTcp(40_000, 900, 0, at, t);
		};
		return new ConnectionProbe(socket, info);
	}

	private static void sneak(Throwable t)
	{
		if (t instanceof RuntimeException)
		{
			throw (RuntimeException) t;
		}
		throw (Error) t;
	}

	/** TCP numbers, one of whose getters may throw. */
	private static final class FakeTcp implements TCPInfo
	{
		private final long rtt;
		private final long sent;
		private final long resent;
		private final Point failAt;
		private final Throwable failure;

		FakeTcp(long rtt, long sent, long resent, Point failAt, Throwable failure)
		{
			this.rtt = rtt;
			this.sent = sent;
			this.resent = resent;
			this.failAt = failAt;
			this.failure = failure;
		}

		@Override
		public long getRTT()
		{
			fail(Point.RTT);
			return rtt;
		}

		@Override
		public long getTransmitted()
		{
			fail(Point.SENT);
			return sent;
		}

		@Override
		public long getRetransmitted()
		{
			fail(Point.RESENT);
			return resent;
		}

		private void fail(Point here)
		{
			if (failAt == here)
			{
				sneak(failure);
			}
		}
	}
}

