/**
 * The badge's four settings as the gear menu ticks them (1.0.1, lot C, C4): the config's own defaults, a null that
 * keeps them, and the snapshot that carries them - by default, and after {@code withBadgeSettings} and
 * {@code withDiagnostics}, which keep each other's fields.
 */
public class BadgeSettingsTest
{
	/** The defaults are the config's: show on, the icon, shown while smooth, the chat line on. */
	@Test
	public void theDefaultsAreTheConfigsOwn()
	{
		assertTrue(BadgeSettings.DEFAULTS.show);
		assertEquals(BadgeStyle.ICON, BadgeSettings.DEFAULTS.style);
		assertEquals(WhenSmooth.SHOW, BadgeSettings.DEFAULTS.whenSmooth);
		assertTrue(BadgeSettings.DEFAULTS.chatLine);
	}

	/** What is given is what is kept; a null style or choice is the default, so the menu can always be drawn. */
	@Test
	public void theValuesAreKeptAndANullIsTheDefault()
	{
		final BadgeSettings s = new BadgeSettings(false, BadgeStyle.SHAPE_ONLY, WhenSmooth.HIDE, false);
		assertFalse(s.show);
		assertEquals(BadgeStyle.SHAPE_ONLY, s.style);
		assertEquals(WhenSmooth.HIDE, s.whenSmooth);
		assertFalse(s.chatLine);

		final BadgeSettings none = new BadgeSettings(false, null, null, false);
		assertEquals(BadgeStyle.ICON, none.style);
		assertEquals(WhenSmooth.SHOW, none.whenSmooth);
		assertFalse("the two booleans are never defaulted", none.show || none.chatLine);
	}

	/** A snapshot built without them holds the defaults; {@code withBadgeSettings} and {@code withDiagnostics} keep the rest. */
	@Test
	public void theSnapshotCarriesThemAndEachWithMethodKeepsTheOthersFields()
	{
		final PanelSnapshot plain = new PanelSnapshot(1_000L, null, 416, null, new Tile[0], 10, 0, 0, new Strip[0],
			Collections.emptyList(), Collections.emptyList(), new int[Group.values().length], 0, 0, null, "foot");
		assertSame(BadgeSettings.DEFAULTS, plain.badgeSettings);

		final BadgeSettings odd = new BadgeSettings(false, BadgeStyle.SHAPE_AND_WORDS, WhenSmooth.HIDE, false);
		final PanelSnapshot withBadge = plain.withBadgeSettings(odd);
		assertNotSame(plain, withBadge);
		assertSame(odd, withBadge.badgeSettings);
		assertEquals(416, withBadge.world);
		assertEquals("foot", withBadge.footer);
		assertSame("the arrays are shared", plain.sessionCounts, withBadge.sessionCounts);
		assertSame("the original is untouched", BadgeSettings.DEFAULTS, plain.badgeSettings);

		final PanelSnapshot both = withBadge.withDiagnostics("1.0.1", "minutes\n", "notes");
		assertSame("the diagnostics keep the settings", odd, both.badgeSettings);
		assertEquals("1.0.1", both.pluginVersion);
		assertEquals("minutes\n", both.minuteText);
		assertEquals("notes", both.diagnosticsText);
		final PanelSnapshot back = both.withBadgeSettings(BadgeSettings.DEFAULTS);
		assertEquals("the settings keep the diagnostics", "notes", back.diagnosticsText);
		assertEquals("1.0.1", back.pluginVersion);

		assertSame("a null is the defaults", BadgeSettings.DEFAULTS, plain.withBadgeSettings(null).badgeSettings);
	}
}

package com.whylag.core;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * What the game badge shows (contract 3.8): the hidden view, null texts kept as "", and {@code sameAs}, which the
 * badge's state machine uses to answer the SAME object while nothing changed (T19) - so every one of the nine fields
 * must count, and a field added later must be counted too.
 */
public class BadgeViewTest
{
	@Test
	public void hiddenIsNotVisible()
	{
		final BadgeView h = BadgeView.HIDDEN;
		assertFalse(h.visible);
		assertSame(BadgeStyle.ICON, h.style);
		assertSame(Level.NO_DATA, h.level);
		assertSame(Icon.NONE, h.icon);
		assertFalse(h.dimmed);
		assertEquals("", h.line1);
		assertEquals("", h.line2);
		assertEquals("", h.tip1);
		assertEquals("", h.tip2);
		assertTrue(h.sameAs(new BadgeView(false, BadgeStyle.ICON, Level.NO_DATA, Icon.NONE, false, "", "", "", "")));
	}

	@Test
	public void nullTextsAreEmpty()
	{
		final BadgeView v = new BadgeView(true, BadgeStyle.SHAPE_ONLY, Level.OK, Icon.NONE, false, null, null, null,
			null);
		assertEquals("", v.line1);
		assertEquals("", v.line2);
		assertEquals("", v.tip1);
		assertEquals("", v.tip2);
		assertTrue("a null text and \"\" are the same view",
			v.sameAs(new BadgeView(true, BadgeStyle.SHAPE_ONLY, Level.OK, Icon.NONE, false, "", "", "", "")));
	}

	/** Every field counts: the same values are the same view, and a change in any ONE field is another view. */
	@Test
	public void sameAsComparesEveryField()
	{
		final BadgeView lag = lag();
		assertTrue(lag.sameAs(lag));
		assertTrue("equal fields, another object", lag.sameAs(lag()));
		assertFalse(lag.sameAs(null));

		assertFalse("visible", lag.sameAs(new BadgeView(false, BadgeStyle.ICON, Level.BAD, Icon.WORLD, false,
			"World lag", "Not you", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("style", lag.sameAs(new BadgeView(true, BadgeStyle.ICON_AND_WORDS, Level.BAD, Icon.WORLD, false,
			"World lag", "Not you", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("level", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.WARN, Icon.WORLD, false,
			"World lag", "Not you", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("icon", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.UNKNOWN, false,
			"World lag", "Not you", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("dimmed", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.WORLD, true,
			"World lag", "Not you", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("line 1", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.WORLD, false,
			"Lag", "Not you", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("line 2", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.WORLD, false,
			"World lag", "", "World lag - not you", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("tip 1", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.WORLD, false,
			"World lag", "Not you", "Lag - can't tell why", "Ticks 1,240 ms, ping 41 ms")));
		assertFalse("tip 2", lag.sameAs(new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.WORLD, false,
			"World lag", "Not you", "World lag - not you", "Ticks 1,300 ms, ping 41 ms")));
	}

	/** The picture's lag while it happens: the globe with its red square, two lines and the tooltip's two lines. */
	private static BadgeView lag()
	{
		return new BadgeView(true, BadgeStyle.ICON, Level.BAD, Icon.WORLD, false, "World lag", "Not you",
			"World lag - not you", "Ticks 1,240 ms, ping 41 ms");
	}
}

package com.whylag.core;

import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The causes (contract 3.2): ids are unique, exactly the thirteen named there are in wave one (F2 is one), and the
 * groups and short names of wave one's causes. The memory causes (G1, G2, G3), S4 (the client waiting) and S5
 * (another program) are gone with the readings they stood on (1.0.0, the Hub's rule). The other small types of 3.2
 * are {@code EnumsTest}'s.
 */
public class CauseTest
{
	@Test
	public void idsAreUnique()
	{
		final Set<String> ids = new HashSet<>();
		for (Cause c : Cause.values())
		{
			assertTrue("id " + c.id() + " twice", ids.add(c.id()));
		}
		assertEquals(24, ids.size());
		for (String gone : new String[] {"G1", "G2", "G3", "S4", "S5"})
		{
			assertFalse(gone + " is gone", ids.contains(gone));
		}
	}

	@Test
	public void exactlyTheThirteenOfWaveOne()
	{
		final Set<Cause> expected = EnumSet.of(Cause.DISCONNECT, Cause.MAP_LOAD, Cause.UPLOAD_LOSS, Cause.PING_JUMPY,
			Cause.SLOW_WORLD, Cause.CLIENT_BUSY, Cause.DELIVERY_GAP, Cause.FRAME_CAP, Cause.PING_HIGH,
			Cause.SLOW_DRAWING, Cause.ALL_CLEAR, Cause.NOT_SURE, Cause.WARMING_UP);
		final Set<Cause> actual = EnumSet.noneOf(Cause.class);
		for (Cause c : Cause.values())
		{
			if (c.inWaveOne())
			{
				actual.add(c);
			}
		}
		assertEquals(expected, actual);
		assertEquals(13, actual.size());
		assertTrue("F2 is one of them", Cause.SLOW_DRAWING.inWaveOne());
	}

	@Test
	public void theTwelveRuleIdsAreInWaveOne()
	{
		final Set<String> ids = new TreeSet<>();
		for (Cause c : Cause.values())
		{
			if (c.inWaveOne())
			{
				ids.add(c.id());
			}
		}
		assertEquals(new TreeSet<>(java.util.Arrays.asList("D1", "S1", "N3", "N2", "W1", "S3", "N6", "F1", "N1", "F2",
			"V2", "X", "-")), ids);
	}

	@Test
	public void groupsAndShortNamesOfWaveOne()
	{
		assertEquals(Group.UNSURE, Cause.DELIVERY_GAP.group());
		assertEquals(Group.UNSURE, Cause.NOT_SURE.group());
		assertEquals(Group.WORLD, Cause.SLOW_WORLD.group());
		assertEquals(Group.CONNECTION, Cause.DISCONNECT.group());
		assertEquals(Group.FRAME_RATE, Cause.CLIENT_BUSY.group());
		assertEquals(Group.NONE, Cause.ALL_CLEAR.group());
		assertEquals("a client stall", Cause.CLIENT_BUSY.shortName());
		assertEquals("lost packets", Cause.UPLOAD_LOSS.shortName());
		assertEquals("", Cause.WARMING_UP.shortName());
	}
}

package com.whylag.core;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The three cells of the panel of picture 18 (contract 3.8, 5.2): the picture's quiet cells and its selected lag,
 * with the WORST tick in the Tick cell and the culprit marked at the verdict's level; no culprit for a "Not sure"
 * event; a dash with the reason in the tip; numbers held to 9,999; every tip of 5.2's two tables; and the three in
 * {@link Lane} order. The memory and CPU cells are gone (1.0.0, the Hub's rule).
 */
public class CellsTest
{
	/** The plus-minus sign the Server ticks tile's small line starts with, as in "plus-minus 13 ms" (contract 5.2). */
	private static final String PLUS_MINUS = "±";

	/** The picture's quiet numbers: 50 fps, 600 ms, 41 ms (was 39). */
	static PanelSnapshot quietSnapshot()
	{
		return snapshot(new Tile[] {
			new Tile(Lane.FRAME_RATE, Level.OK, "50 fps", "worst 35 ms", NoData.NONE),
			new Tile(Lane.TICKS, Level.OK, "600 ms", PLUS_MINUS + "13 ms", NoData.NONE),
			new Tile(Lane.PING, Level.OK, "41 ms", "was 39 ms", NoData.NONE)});
	}

	@Test
	public void nowOfThePicturesQuietSnapshot()
	{
		final Cell[] c = Cells.now(quietSnapshot());
		assertEquals(3, c.length);
		assertCell(c[0], Lane.FRAME_RATE, "FPS", "50", "fps", Level.OK, false);
		assertCell(c[1], Lane.TICKS, "Tick", "600", "ms", Level.OK, false);
		assertCell(c[2], Lane.PING, "Ping", "41", "ms", Level.OK, false);
	}

	/** A cell takes its tile's level. */
	@Test
	public void nowTakesTheTilesLevels()
	{
		final Cell[] c = Cells.now(snapshot(new Tile[] {
			new Tile(Lane.FRAME_RATE, Level.BAD, "12 fps", "worst 480 ms", NoData.NONE),
			new Tile(Lane.TICKS, Level.WARN, "672 ms", PLUS_MINUS + "72 ms", NoData.NONE),
			new Tile(Lane.PING, Level.BAD, "310 ms", "was 41 ms", NoData.NONE)}));
		assertEquals(Level.BAD, c[0].level);
		assertEquals(Level.WARN, c[1].level);
		assertEquals(Level.BAD, c[2].level);
		for (Cell cell : c)
		{
			assertFalse("no cell of now is a culprit", cell.culprit);
		}
	}

	/** The picture's selected lag: the Tick cell is the WORST tick, 1,240, and it is the one culprit, at BAD. */
	@Test
	public void ofThePicturesEvent()
	{
		final Cell[] c = Cells.of(EventViewTest.picturesEvent().withVerdict(verdict(Cause.SLOW_WORLD)));
		assertEquals(3, c.length);
		assertCell(c[0], Lane.FRAME_RATE, "FPS", "50", "fps", Level.OK, false);
		assertCell(c[1], Lane.TICKS, "Tick", "1,240", "ms", Level.BAD, true);
		assertCell(c[2], Lane.PING, "Ping", "41", "ms", Level.OK, false);
		assertEquals("one culprit", 1, culprits(c));
	}

	/**
	 * The culprit is the cell of the verdict's group's lane, at the verdict's level whatever its own number says, so
	 * its edge, its ground and its shape agree - also when its number is missing.
	 */
	@Test
	public void theCulpritTakesTheVerdictsLevel()
	{
		final LagEvent e = EventViewTest.picturesEvent();
		final Cell[] line = Cells.of(e.withVerdict(verdict(Cause.UPLOAD_LOSS)));
		assertCell(line[2], Lane.PING, "Ping", "41", "ms", Level.BAD, true);
		assertEquals(1, culprits(line));
		assertEquals("the Tick cell keeps its own level", Level.BAD, line[1].level);
		assertFalse(line[1].culprit);

		final Cell[] frames = Cells.of(e.withVerdict(verdict(Cause.CLIENT_BUSY)));
		assertCell(frames[0], Lane.FRAME_RATE, "FPS", "50", "fps", Level.BAD, true);
		assertEquals("the frame rate tile alone says OK", Level.OK, EventView.tiles(e)[0].level);
		assertEquals(1, culprits(frames));

		final LagEvent noPing = event(50, 34, 952, 1240, 640, -1, 41);
		final Cell[] blind = Cells.of(noPing.withVerdict(verdict(Cause.UPLOAD_LOSS)));
		assertCell(blind[2], Lane.PING, "Ping", "-", "", Level.BAD, true);
	}

	@Test
	public void aNotSureEventHasNoCulprit()
	{
		final LagEvent e = EventViewTest.picturesEvent();
		assertEquals("X: the group UNSURE has no lane", 0, culprits(Cells.of(e.withVerdict(verdict(Cause.NOT_SURE)))));
		assertEquals("N6 is not sure too", 0, culprits(Cells.of(e.withVerdict(verdict(Cause.DELIVERY_GAP)))));
		assertEquals("an event not judged yet counts as not sure", 0, culprits(Cells.of(e)));
		assertEquals("the group NONE has no lane", 0, culprits(Cells.of(e.withVerdict(verdict(Cause.ALL_CLEAR)))));
		assertEquals("its Tick cell keeps its own level", Level.BAD,
			Cells.of(e.withVerdict(verdict(Cause.NOT_SURE)))[1].level);
	}

	/** A tile's "-" is a dash cell: no unit, the hollow ring, and the reason in the tip, never painted in the cell. */
	@Test
	public void noDataIsADashWithTheReasonInTheTip()
	{
		final Tile[] quiet = quietSnapshot().tiles;
		final Cell stale = Cells.now(snapshot(new Tile[] {quiet[0], quiet[1],
			new Tile(Lane.PING, Level.NO_DATA, "-", NoData.STALE.reason(), NoData.STALE)}))[2];
		assertCell(stale, Lane.PING, "Ping", "-", "", Level.NO_DATA, false);
		assertEquals("Ping: Nothing sent", stale.tip);

		// Not logged in, as the snapshot builder writes it: world 0 and every tile "Not logged in".
		final Tile[] out = new Tile[Lane.TILES];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = new Tile(Lane.values()[i], Level.NO_DATA, "-", NoData.NOT_LOGGED_IN.reason(),
				NoData.NOT_LOGGED_IN);
		}
		final Cell[] loggedOut = Cells.now(snapshot(0, out));
		for (Cell c : loggedOut)
		{
			assertEquals(c.name, "-", c.value);
			assertEquals(c.name, "", c.unit);
			assertEquals(c.name, Level.NO_DATA, c.level);
		}
		assertEquals("Frame rate: Not logged in", loggedOut[0].tip);
		assertEquals("Ticks: Not logged in", loggedOut[1].tip);
		assertEquals("Ping: Not logged in", loggedOut[2].tip);

		final Cell forced = Cells.now(snapshot(new Tile[] {quiet[0], quiet[1],
			new Tile(Lane.PING, Level.BAD, "-", "Could not read it", NoData.ERROR)}))[2];
		assertEquals("a dash is always the hollow ring", Level.NO_DATA, forced.level);
		assertEquals("Ping: Could not read it", forced.tip);

		final Cell[] event = Cells.of(event(-1, -1, 952, 1240, 640, 41, 41));
		assertCell(event[0], Lane.FRAME_RATE, "FPS", "-", "", Level.NO_DATA, false);
		assertEquals("an event's dash has no reason to give", "Frame rate: -", event[0].tip);
	}

	@Test
	public void numbersAreHeldToNineThousandNineHundredNinetyNine()
	{
		final Cell tick = Cells.of(event(50, 34, 952, 12400, 11800, 41, 41))[1];
		assertEquals("9,999", tick.value);
		assertEquals("the tip keeps the true number", "Ticks: worst 12,400 ms, mean 952 ms", tick.tip);

		final Cell[] big = Cells.now(snapshot(new Tile[] {
			new Tile(Lane.FRAME_RATE, Level.OK, "12000 fps", "worst 35 ms", NoData.NONE),
			new Tile(Lane.TICKS, Level.BAD, "12,400 ms", "worst 12,400", NoData.NONE),
			new Tile(Lane.PING, Level.BAD, "9,999 ms", "was 39 ms", NoData.NONE)}));
		assertEquals("9,999", big[0].value);
		assertEquals("9,999", big[1].value);
		assertEquals("9,999", big[2].value);
		assertEquals("Ticks: 12,400 ms, worst 12,400", big[1].tip);

		final Cell[] small = Cells.now(snapshot(new Tile[] {
			new Tile(Lane.FRAME_RATE, Level.BAD, "0 fps", "worst 1,000 ms", NoData.NONE),
			new Tile(Lane.TICKS, Level.OK, "1,000 ms", "worst 1,000", NoData.NONE),
			new Tile(Lane.PING, Level.OK, "999 ms", "", NoData.NONE)}));
		assertEquals("0", small[0].value);
		assertEquals("the commas are taken out and put back", "1,000", small[1].value);
		assertEquals("999", small[2].value);
	}

	/** Each tip of 5.2's two tables, and the parts left out when there is nothing to say. */
	@Test
	public void tips()
	{
		final Cell[] now = Cells.now(quietSnapshot());
		assertEquals("Frame rate: 50 fps, worst 35 ms", now[0].tip);
		assertEquals("Ticks: 600 ms, " + PLUS_MINUS + "13 ms", now[1].tip);
		assertEquals("Ping: 41 ms, was 39 ms", now[2].tip);

		final Cell[] of = Cells.of(EventViewTest.picturesEvent().withVerdict(verdict(Cause.SLOW_WORLD)));
		assertEquals("Frame rate: 50 fps, worst 34 ms", of[0].tip);
		assertEquals("Ticks: worst 1,240 ms, mean 952 ms", of[1].tip);
		assertEquals("Ping: 41 ms, was 41 ms", of[2].tip);

		final Tile[] quiet = quietSnapshot().tiles;
		final Cell noUsual = Cells.now(snapshot(new Tile[] {quiet[0], quiet[1],
			new Tile(Lane.PING, Level.OK, "41 ms", "", NoData.NONE)}))[2];
		assertEquals("no small line: no comma", "Ping: 41 ms", noUsual.tip);

		assertEquals("Ticks: worst 1,240 ms", Cells.of(event(50, 34, -1, 1240, 640, 41, 41))[1].tip);
		final Cell meanOnly = Cells.of(event(50, 34, 952, -1, -1, 41, 41))[1];
		assertEquals("Ticks: mean 952 ms", meanOnly.tip);
		assertEquals("no worst tick: a dash", "-", meanOnly.value);
		assertEquals("", meanOnly.unit);
		assertEquals(Level.NO_DATA, meanOnly.level);
		assertEquals("Ticks: -", Cells.of(event(50, 34, -1, -1, -1, 41, 41))[1].tip);
	}

	/** An event's Tick cell prints the worst gap, at the level of its worst CORRECTED deviation (C5). */
	@Test
	public void theEventsTickCellIsTheWorstGapAtItsCorrectedLevel()
	{
		final Cell paced = Cells.of(event(50, 34, 610, 640, 20, 41, 41))[1];
		assertEquals("640", paced.value);
		assertEquals("20 ms after the frame time is taken off", Level.OK, paced.level);
		// TICK_WARN_MS corrected (200 since the first live look) is WARN; 80 is OK now.
		assertEquals(Level.WARN, Cells.of(event(50, 34, 610, 600 + Thresholds.TICK_WARN_MS + 22,
			Thresholds.TICK_WARN_MS, 41, 41))[1].level);
		assertEquals(Level.OK, Cells.of(event(50, 34, 610, 700, 80, 41, 41))[1].level);
	}

	@Test
	public void threeCellsInLaneOrder()
	{
		final String[] names = {"FPS", "Tick", "Ping"};
		for (Cell[] cells : new Cell[][] {Cells.now(quietSnapshot()), Cells.of(EventViewTest.picturesEvent()),
			Cells.now(snapshot(new Tile[0]))})
		{
			assertEquals(3, cells.length);
			assertEquals(Lane.values().length, cells.length);
			for (int i = 0; i < cells.length; i++)
			{
				assertEquals(Lane.values()[i], cells[i].lane);
				assertEquals(names[i], cells[i].name);
			}
		}
	}

	/** A snapshot with no tiles (only a test builds one) gives three dashes and never throws. */
	@Test
	public void missingTilesAreDashes()
	{
		final Cell[] c = Cells.now(snapshot(null));
		for (int i = 0; i < Lane.TILES; i++)
		{
			assertEquals("-", c[i].value);
			assertEquals(Level.NO_DATA, c[i].level);
			assertEquals(Lane.values()[i].label() + ": -", c[i].tip);
		}
	}

	@Test
	public void nullTextsAreEmpty()
	{
		final Cell c = new Cell(Lane.PING, null, null, null, Level.NO_DATA, false, null);
		assertEquals("", c.name);
		assertEquals("", c.value);
		assertEquals("", c.unit);
		assertEquals("", c.tip);
		assertTrue(new Cell(Lane.PING, "Ping", "41", "ms", Level.OK, true, "t").culprit);
	}

	// ---------------------------------------------------------------- helpers

	private static void assertCell(Cell c, Lane lane, String name, String value, String unit, Level level,
		boolean culprit)
	{
		assertEquals(name + ": lane", lane, c.lane);
		assertEquals(name + ": name", name, c.name);
		assertEquals(name + ": value", value, c.value);
		assertEquals(name + ": unit", unit, c.unit);
		assertEquals(name + ": level", level, c.level);
		assertEquals(name + ": culprit", culprit, c.culprit);
	}

	private static int culprits(Cell[] cells)
	{
		int n = 0;
		for (Cell c : cells)
		{
			n += c.culprit ? 1 : 0;
		}
		return n;
	}

	/** A logged-in snapshot, on world 416. */
	private static PanelSnapshot snapshot(Tile[] tiles)
	{
		return snapshot(416, tiles);
	}

	/** A snapshot on that world; 0 = not logged in (contract 3.8). */
	private static PanelSnapshot snapshot(int world, Tile[] tiles)
	{
		return new PanelSnapshot(0, null, world, null, tiles, 10, 0, 0, new Strip[0], null, null,
			new int[Group.values().length], 0, 0, null, "");
	}

	/** An event's verdict of that cause: BAD, as every event rule's is (contract 6.4). */
	private static Verdict verdict(Cause c)
	{
		return new Verdict(c, Confidence.LIKELY, Level.BAD, "headline", "proof", "fix", "", 1, 14, 416, 7, null,
			null);
	}

	private static LagEvent event(int fps, int worstFrameMs, int meanTickGapMs, int worstTickGapMs,
		int worstCorrectedTickMs, int rttMs, int rttBeforeMs)
	{
		return new LagEvent(7, 100, 113, 0, Trigger.TICK_OFF.bit(), Trigger.TICK_OFF, 416, 0, 0, 0, fps,
			worstFrameMs, meanTickGapMs, worstTickGapMs, worstCorrectedTickMs, rttMs, rttMs, rttBeforeMs, 900, 0,
			false, false, null);
	}
}

package com.whylag.core;

import java.time.ZoneId;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What {@link CheckFacts.Builder#session} reads from the rings (1.0.1, lot B): a steady minute, a logged-out
 * session, frames that stopped, ticks that stopped or slowed, each state of the ping, and a session that has nothing
 * yet - each read from a {@link Trace}, the way the sampler thread reads the session. The settings' two facts are
 * read from a {@link SettingsView}.
 */
public class CheckFactsTest
{
	private static final long NANOS_PER_SECOND = 1_000_000_000L;

	/** The facts of the session {@code seconds} seconds after its start. */
	private static CheckFacts at(Session s, int seconds)
	{
		return new CheckFacts.Builder().session(s, s.startNanos + seconds * NANOS_PER_SECOND).build();
	}

	/** A steady minute read at its end: logged in to 416, 50 fps, a tick every 600 ms, a ping of 40 ms. */
	@Test
	public void aSteadyMinute()
	{
		final CheckFacts f = at(Trace.steady(60).build(), 60);

		assertTrue(f.loggedIn);
		assertEquals(416, f.world);
		assertEquals("two complete seconds of 50", 100, f.framesLast2s);
		assertEquals(50, f.fps);
		assertEquals("the last of the 99 ticks came at 59.4 s", 600, f.lastTickAgoMs);
		assertEquals("ticks 84 to 99 lie in the last 10 s", 16, f.ticksLast10s);
		assertEquals(600, f.meanGapMs);
		assertEquals(CheckFacts.Ping.READING, f.pingState);
		assertEquals(40, f.rttMs);
		assertEquals(0, f.pingAgeS);
		assertEquals("logged in at second 0", 60, f.loggedInS);
		assertTrue("the steady trace passes the checks that read the rings", Checks.run(f).get(0).pass);
	}

	/** Seconds before the login are at the login screen: nobody is logged in, and no time has counted. */
	@Test
	public void theLoginScreenIsNotLoggedIn()
	{
		final CheckFacts out = at(Trace.steady(60).loginAt(40).build(), 30);
		assertFalse(out.loggedIn);
		assertEquals(0, out.world);
		assertEquals(0, out.loggedInS);

		final CheckFacts in = at(Trace.steady(60).loginAt(40).build(), 50);
		assertTrue(in.loggedIn);
		assertEquals(10, in.loggedInS);
	}

	/** A client that stopped drawing: the newest seconds the ring holds are old, so the facts read 0 frames. */
	@Test
	public void framesThatStoppedReadZero()
	{
		final Session s = Trace.steady(60).build();
		final CheckFacts stopped = at(s, 70);
		assertEquals("no frame for certainly more than 2 s", 0, stopped.framesLast2s);
		assertEquals(0, stopped.fps);
		assertEquals("the ticks are read from the clock, so they age too", 10600, stopped.lastTickAgoMs);
		assertEquals(0, stopped.ticksLast10s);

		final CheckFacts gap = at(Trace.steady(60).fps(58, 59, 0).build(), 60);
		assertEquals("seconds with no frame, as the sampler fills them", 0, gap.framesLast2s);
		assertEquals(0, gap.fps);
	}

	/** Ticks that slowed, or stopped, inside the last 10 s. */
	@Test
	public void ticksThatSlowedOrStopped()
	{
		final CheckFacts slow = at(Trace.steady(60).ticksEvery(50, 59, 1000).build(), 60);
		assertTrue("a mean gap near 1,000 ms: " + slow.meanGapMs, slow.meanGapMs > 900 && slow.meanGapMs < 1100);
		assertTrue(slow.ticksLast10s < 12);

		final CheckFacts none = at(Trace.steady(60).noTicks(50, 59).build(), 60);
		assertEquals(0, none.ticksLast10s);
		assertEquals("nothing to average", -1, none.meanGapMs);
		assertTrue("the newest tick is 10 s old or more: " + none.lastTickAgoMs, none.lastTickAgoMs >= 10000);
	}

	/** Each state the ring can hold for the ping, and the age of the reading. */
	@Test
	public void eachStateOfThePing()
	{
		assertEquals(CheckFacts.Ping.UNSUPPORTED, at(Trace.steady(60).rttNoData(0, 59, NoData.UNSUPPORTED).build(), 60)
			.pingState);
		assertEquals(CheckFacts.Ping.ERROR, at(Trace.steady(60).rttNoData(0, 59, NoData.ERROR).build(), 60).pingState);
		assertEquals(CheckFacts.Ping.STALE, at(Trace.steady(60).rttStale(40, 59).build(), 60).pingState);
		assertEquals(CheckFacts.Ping.NONE, at(Trace.steady(60).rttNoData(0, 59, NoData.NOT_CONNECTED).build(), 60)
			.pingState);
		assertEquals(CheckFacts.Ping.NONE, at(Trace.steady(60).rttNoData(0, 59, NoData.NOT_LOGGED_IN).build(), 60)
			.pingState);
		final CheckFacts none = at(Trace.steady(60).rttNoData(0, 59, NoData.UNSUPPORTED).build(), 60);
		assertEquals(-1, none.rttMs);
		assertEquals(-1, none.pingAgeS);
		assertEquals(12, at(Trace.steady(60).rtt(0, 59, 12).build(), 60).rttMs);
	}

	/** A session that has nothing yet has no facts: every reading is "none" and nothing is thrown. */
	@Test
	public void aSessionWithNothingYet()
	{
		final Session fresh = new Session(System.nanoTime(), 1_790_000_000_000L, Os.WINDOWS, ZoneId.of("UTC"));
		final CheckFacts f = at(fresh, 1);

		assertFalse(f.loggedIn);
		assertEquals(0, f.world);
		assertEquals(-1, f.framesLast2s);
		assertEquals(-1, f.fps);
		assertEquals(-1, f.lastTickAgoMs);
		assertEquals(0, f.ticksLast10s);
		assertEquals(-1, f.meanGapMs);
		assertEquals(CheckFacts.Ping.NONE, f.pingState);
		assertEquals(0, f.loggedInS);
		assertEquals(10, Checks.run(f).size());
	}

	/** The facts of a builder nobody filled say "nothing known", with a zone and a card state that are never null. */
	@Test
	public void anEmptyBuilderKnowsNothing()
	{
		final CheckFacts f = new CheckFacts.Builder().build();
		assertFalse(f.loggedIn);
		assertEquals(-1, f.lastStepAgoMs);
		assertEquals(-1, f.stepCostUs);
		assertEquals(Renderer.UNKNOWN, f.renderer);
		assertEquals("UTC", f.zone.getId());
		assertEquals(Answer.MEASURING, f.cardState);
		assertEquals("", f.clientVersion);
		assertEquals(CheckFacts.Ping.NONE, f.pingState);

		final CheckFacts.Builder b = new CheckFacts.Builder();
		b.pingState = null;
		b.renderer = null;
		b.zone = null;
		b.cardState = null;
		b.os = null;
		final CheckFacts n = b.build();
		assertEquals(CheckFacts.Ping.NONE, n.pingState);
		assertEquals(Renderer.UNKNOWN, n.renderer);
		assertEquals("UTC", n.zone.getId());
		assertEquals(Answer.MEASURING, n.cardState);
		assertEquals("", n.os);
	}

	/** The renderer and the cap of a settings view; a V-Sync cap needs the refresh rate. */
	@Test
	public void theSettingsFacts()
	{
		final CheckFacts none = new CheckFacts.Builder().settings(null).build();
		assertEquals(Renderer.UNKNOWN, none.renderer);
		assertFalse(none.capKnown);

		assertFalse("an unread renderer", CheckFacts.capKnown(SettingsView.unknown(Os.WINDOWS)));
		assertTrue("CPU has the client's own cap", CheckFacts.capKnown(view(Renderer.CPU, false, "", 0, 0)));
		assertTrue("an unlocked GPU with V-Sync off and no target: no cap is a known state",
			CheckFacts.capKnown(view(Renderer.GPU, true, "OFF", 0, 0)));
		assertFalse("V-Sync on, refresh rate unread", CheckFacts.capKnown(view(Renderer.GPU, true, "ON", 0, 0)));
		assertFalse("adaptive too, on 117 HD", CheckFacts.capKnown(view(Renderer.HD, true, "ADAPTIVE", 0, 0)));
		assertTrue("V-Sync on with its refresh rate", CheckFacts.capKnown(view(Renderer.GPU, true, "ON", 0, 144)));
		assertTrue("a locked GPU is the client's 50", CheckFacts.capKnown(view(Renderer.GPU, false, "ON", 0, 0)));

		final CheckFacts ok = new CheckFacts.Builder().settings(view(Renderer.GPU, true, "OFF", 144, 0)).build();
		assertEquals(Renderer.GPU, ok.renderer);
		assertTrue(ok.capKnown);
	}

	private static SettingsView view(Renderer renderer, boolean unlockFps, String vsync, int target, int refreshHz)
	{
		return new SettingsView(renderer, false, false, 0, false, 0, unlockFps, vsync, target, 50, "", 0, refreshHz,
			Os.WINDOWS, "1.13.0");
	}
}

package com.whylag.core;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;

/**
 * The facts of the ten checks for the tests (1.0.1, lot B; ten since 1.0.0, the Hub's rule): one set that passes
 * every check, and, for each check, the states that make it fail with the detail it then says.
 * {@link ChecksTest} reads the table for its
 * words and the panel's tests read it for the widest verdict, so neither can drift from the other.
 */
public final class CheckFixtures
{
	/** The wall time of the jump in the clock fixture: 2026-09-28 21:47 UTC. */
	public static final long JUMP_AT = Instant.parse("2026-09-28T21:47:00Z").toEpochMilli();

	/** One way a check fails: which one, a name for the failure message, what sets it up, and what it then says. */
	public static final class Failing
	{
		public final int check;
		public final String why;
		public final Consumer<CheckFacts.Builder> setUp;
		public final String detail;

		Failing(int check, String why, Consumer<CheckFacts.Builder> setUp, String detail)
		{
			this.check = check;
			this.why = why;
			this.setUp = setUp;
			this.detail = detail;
		}

		/** The healthy facts with this failure set up. */
		public CheckFacts facts()
		{
			final CheckFacts.Builder b = healthy();
			setUp.accept(b);
			return b.build();
		}

		@Override
		public String toString()
		{
			return "C" + check + " " + why;
		}
	}

	private static final List<Failing> FAILING = build();

	private CheckFixtures()
	{
	}

	/** A run that passes all ten checks: logged in to 416, 50 fps, a steady tick, a ping of 41 ms, and so on. */
	public static CheckFacts.Builder healthy()
	{
		final CheckFacts.Builder b = new CheckFacts.Builder();
		b.loggedIn = true;
		b.world = 416;
		b.framesLast2s = 100;
		b.fps = 50;
		b.lastTickAgoMs = 350;
		b.ticksLast10s = 16;
		b.meanGapMs = 601;
		b.pingState = CheckFacts.Ping.READING;
		b.rttMs = 41;
		b.pingAgeS = 1;
		b.lastStepAgoMs = 340;
		b.stepCostUs = 120;
		b.renderer = Renderer.GPU;
		b.capKnown = true;
		b.badgeRegistered = true;
		b.badgeShow = true;
		b.clientVersion = "1.13.0";
		b.javaVersion = "17.0.18";
		b.os = "Windows 11";
		b.loggedInS = 300;
		b.cardState = Answer.SMOOTH;
		return b;
	}

	/** Every way each check fails, C1 first, in the order the tests read them. */
	public static List<Failing> failing()
	{
		return FAILING;
	}

	private static List<Failing> build()
	{
		final List<Failing> out = new ArrayList<>();
		out.add(new Failing(1, "not logged in", b -> b.loggedIn = false,
			"not logged in: nothing is measured yet"));
		out.add(new Failing(1, "no world", b -> b.world = 0, "logged in, but the world is not known yet"));

		out.add(new Failing(2, "no frames", b -> b.framesLast2s = 0, "no frames counted for 2 s"));
		out.add(new Failing(2, "no second yet", b -> b.framesLast2s = -1, "no frames counted for 2 s"));
		out.add(new Failing(2, "frame rate 0", b -> b.fps = 0, "the frame rate reads 0"));
		out.add(new Failing(2, "frame rate 1,500", b -> b.fps = 1500, "the frame rate reads 1,500"));

		out.add(new Failing(3, "no tick yet", b -> b.lastTickAgoMs = -1, "no tick has arrived yet"));
		out.add(new Failing(3, "last tick 4 s ago", b -> b.lastTickAgoMs = 4000, "no ticks for 4 s"));
		out.add(new Failing(3, "last tick 1.2 s ago", b -> b.lastTickAgoMs = 1200, "no ticks for 1 s"));
		out.add(new Failing(3, "three ticks", b -> b.ticksLast10s = 3, "only 3 ticks in 10 s"));
		out.add(new Failing(3, "gaps of 900", b -> b.meanGapMs = 900, "ticks average 900 ms"));
		out.add(new Failing(3, "gaps of 400", b -> b.meanGapMs = 400, "ticks average 400 ms"));

		out.add(new Failing(4, "not offered", b -> b.pingState = CheckFacts.Ping.UNSUPPORTED,
			"ping cannot be read on this PC"));
		out.add(new Failing(4, "error", b -> b.pingState = CheckFacts.Ping.ERROR,
			"ping cannot be read from this client"));
		out.add(new Failing(4, "stale", b -> b.pingState = CheckFacts.Ping.STALE,
			"ping is stale: nothing sent lately"));
		out.add(new Failing(4, "none yet", b -> b.pingState = CheckFacts.Ping.NONE, "no ping reading yet"));
		out.add(new Failing(4, "reading with no number", b -> b.rttMs = -1, "no ping reading yet"));
		out.add(new Failing(4, "reading 6 s old", b -> b.pingAgeS = 6, "ping reading is 6 s old"));

		out.add(new Failing(5, "no step for 5 s", b -> b.lastStepAgoMs = 5000, "the sampler has not run for 5 s"));
		out.add(new Failing(5, "a step of 2.5 ms", b -> b.stepCostUs = 2500, "sampler steps are slow: 2.5 ms"));

		out.add(new Failing(6, "renderer", b -> b.renderer = Renderer.UNKNOWN,
			"settings not read: renderer"));
		out.add(new Failing(6, "cap", b -> b.capKnown = false, "settings not read: cap"));
		out.add(new Failing(6, "both", b ->
		{
			b.renderer = Renderer.UNKNOWN;
			b.capKnown = false;
		}, "settings not read: renderer, cap"));

		out.add(new Failing(7, "not registered", b -> b.badgeRegistered = false,
			"the badge is not registered with the client"));

		out.add(new Failing(8, "client 1.12.38", b -> b.clientVersion = "1.12.38",
			"client 1.12.38 is older than 1.13.0"));
		out.add(new Failing(8, "client 0.9", b -> b.clientVersion = "0.9", "client 0.9 is older than 1.13.0"));
		out.add(new Failing(8, "Java 8", b -> b.javaVersion = "1.8.0_352",
			"Java 1.8.0_352 is older than 11"));
		out.add(new Failing(8, "system not named", b -> b.os = "", "the operating system is not named"));

		out.add(new Failing(9, "a jump of 5 s", b ->
		{
			b.clockJumpedBackS = 5;
			b.clockJumpAtWallMs = JUMP_AT;
		}, "the clock jumped back 5 s at 21:47"));
		out.add(new Failing(9, "a jump at no known time", b -> b.clockJumpedBackS = 12,
			"the clock jumped back 12 s"));

		out.add(new Failing(10, "measuring for 75 s", b ->
		{
			b.loggedInS = 75;
			b.cardState = Answer.MEASURING;
		}, "measuring for 75 s: no readings arrive"));
		return Collections.unmodifiableList(out);
	}
}

package com.whylag.core;

import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The ten checks (1.0.1, lot B; ten since 1.0.0, the Hub's rule): each one passes on the healthy facts with the
 * detail it names, fails on its own failing states with the plain words it then says and nothing else failing, and the verdict is the first failure
 * in order; the notes the plan fixes (nothing yet, not offered, hidden by setting) pass. The failing states are
 * {@link CheckFixtures#failing()}, shared with the panel tests.
 */
public class ChecksTest
{
	private static final String[] NAMES = {"Logged in", "Frames arrive", "Ticks arrive", "Ping readable",
		"The sampler runs", "Settings read", "The badge is up", "Client fits", "Clock sane", "Not stuck measuring"};

	private static List<CheckResult> run(Consumer<CheckFacts.Builder> setUp)
	{
		final CheckFacts.Builder b = CheckFixtures.healthy();
		setUp.accept(b);
		return Checks.run(b.build());
	}

	private static CheckResult one(int check, Consumer<CheckFacts.Builder> setUp)
	{
		return run(setUp).get(check - 1);
	}

	/** Ten results, C1 to C10 in the proposal's order and words; each passes on the healthy facts. */
	@Test
	public void healthyFactsPassAllTenInOrder()
	{
		final List<CheckResult> results = Checks.run(CheckFixtures.healthy().build());
		assertEquals(10, results.size());
		final String[] details = {"world 416", "50 fps, 100 frames in 2 s",
			"16 in 10 s, last 350 ms ago, mean gap 601 ms", "41 ms, 1 s old", "last step 340 ms ago, work 120 us",
			"renderer GPU, cap known", "registered, Show is on", "client 1.13.0, Java 17.0.18, Windows 11",
			"never went back, zone UTC", "card: Smooth"};
		for (int i = 0; i < 10; i++)
		{
			final CheckResult r = results.get(i);
			assertEquals("C" + (i + 1), r.id);
			assertEquals(NAMES[i], r.name);
			assertTrue(r.id + " " + r.detail, r.pass);
			assertEquals(r.id, details[i], r.detail);
		}
	}

	/** Every failing state fails its own check with its own words, and no other check. */
	@Test
	public void eachCheckFailsWithItsOwnWordsAndNoOther()
	{
		final boolean[] seen = new boolean[10];
		for (CheckFixtures.Failing f : CheckFixtures.failing())
		{
			final List<CheckResult> results = Checks.run(f.facts());
			seen[f.check - 1] = true;
			for (int i = 0; i < 10; i++)
			{
				final CheckResult r = results.get(i);
				if (i == f.check - 1)
				{
					assertFalse(f + " must fail: " + r.line(), r.pass);
					assertEquals(f.toString(), f.detail, r.detail);
				}
				else
				{
					assertTrue(f + " must leave " + r.id + " passing: " + r.line(), r.pass);
				}
			}
		}
		for (int i = 0; i < 10; i++)
		{
			assertTrue("C" + (i + 1) + " has a failing state", seen[i]);
		}
	}

	/** The plan's notes: nothing yet, hidden by setting - each a PASS. */
	@Test
	public void theNotesPass()
	{
		final CheckResult hidden = one(7, b ->
		{
			b.badgeShow = false;
			b.badgeRegistered = false;
		});
		assertTrue(hidden.line(), hidden.pass);
		assertEquals("hidden by setting", hidden.detail);

		final CheckResult noStep = one(5, b ->
		{
			b.lastStepAgoMs = -1;
			b.stepCostUs = -1;
		});
		assertTrue(noStep.line(), noStep.pass);
		assertEquals("no step yet, the plugin has just started", noStep.detail);
		assertEquals("last step 340 ms ago", one(5, b -> b.stepCostUs = -1).detail);

		assertEquals("client dev, Java 17.0.18, Windows 11", one(8, b -> b.clientVersion = "dev").detail);
		assertEquals("client 1.13.1-SNAPSHOT, Java 17.0.18, Windows 11",
			one(8, b -> b.clientVersion = "1.13.1-SNAPSHOT").detail);
		assertEquals("client unknown, Java 17.0.18, Windows 11", one(8, b -> b.clientVersion = "").detail);
		assertTrue(one(8, b -> b.clientVersion = "2.0.0").pass);
		assertTrue("Java 11 is the floor", one(8, b -> b.javaVersion = "11.0.2").pass);
		assertEquals("mean gap left out when nothing could be averaged", "16 in 10 s, last 350 ms ago",
			one(3, b -> b.meanGapMs = -1).detail);
	}

	/** Nobody logged in: C1 fails and is the verdict; the three checks that need a player say so and pass. */
	@Test
	public void notLoggedInFailsOnlyTheFirst()
	{
		final List<CheckResult> r = run(b ->
		{
			b.loggedIn = false;
			b.world = 0;
			b.lastTickAgoMs = -1;
			b.pingState = CheckFacts.Ping.NONE;
			b.rttMs = -1;
			b.cardState = Answer.MEASURING;
		});
		for (int i = 0; i < 10; i++)
		{
			assertEquals(r.get(i).line(), i != 0, r.get(i).pass);
		}
		for (int c : new int[] {3, 4, 10})
		{
			assertEquals("not logged in, not checked", r.get(c - 1).detail);
		}
		assertEquals("Not logged in: nothing is measured yet", Checks.verdict(r));
	}

	/** The edges of each number: where a check turns from pass to fail. */
	@Test
	public void theEdges()
	{
		assertTrue(one(2, b -> b.fps = 1).pass);
		assertTrue(one(2, b -> b.fps = 1000).pass);
		assertFalse(one(2, b -> b.fps = 1001).pass);
		assertTrue(one(3, b -> b.lastTickAgoMs = 1199).pass);
		assertFalse(one(3, b -> b.lastTickAgoMs = 1200).pass);
		assertTrue(one(3, b -> b.ticksLast10s = 5).pass);
		assertFalse(one(3, b -> b.ticksLast10s = 4).pass);
		assertTrue(one(3, b -> b.meanGapMs = 500).pass);
		assertTrue(one(3, b -> b.meanGapMs = 700).pass);
		assertFalse(one(3, b -> b.meanGapMs = 499).pass);
		assertFalse(one(3, b -> b.meanGapMs = 701).pass);
		assertTrue("a ping is fresh at 5 s, as the rings count it", one(4, b -> b.pingAgeS = 5).pass);
		assertFalse(one(4, b -> b.pingAgeS = 6).pass);
		assertTrue(one(4, b -> b.pingAgeS = -1).pass);
		assertEquals("41 ms", one(4, b -> b.pingAgeS = -1).detail);
		assertTrue(one(5, b -> b.lastStepAgoMs = 2000).pass);
		assertFalse(one(5, b -> b.lastStepAgoMs = 2001).pass);
		assertTrue(one(5, b -> b.stepCostUs = 1999).pass);
		assertFalse(one(5, b -> b.stepCostUs = 2000).pass);
		assertTrue("a minute of measuring is allowed", one(10, b ->
		{
			b.loggedInS = 60;
			b.cardState = Answer.MEASURING;
		}).pass);
		assertFalse(one(10, b ->
		{
			b.loggedInS = 61;
			b.cardState = Answer.MEASURING;
		}).pass);
		assertTrue("any other card state is out of measuring", one(10, b ->
		{
			b.loggedInS = 600;
			b.cardState = Answer.WAITING;
		}).pass);
	}

	/** The verdict is the detail of the FIRST failure in C1..C10 order with its first letter raised. */
	@Test
	public void theVerdictIsTheFirstFailureInOrder()
	{
		final List<CheckResult> two = run(b ->
		{
			b.clockJumpedBackS = 5;
			b.clockJumpAtWallMs = CheckFixtures.JUMP_AT;
			b.pingState = CheckFacts.Ping.UNSUPPORTED;
		});
		assertEquals("C4 comes before C9", "Ping cannot be read on this PC", Checks.verdict(two));

		final List<CheckResult> late = run(b ->
		{
			b.lastTickAgoMs = 4000;
			b.framesLast2s = 0;
		});
		assertEquals("No frames counted for 2 s", Checks.verdict(late));

		for (CheckFixtures.Failing f : CheckFixtures.failing())
		{
			final String verdict = Checks.verdict(Checks.run(f.facts()));
			assertEquals(f.toString(), Character.toUpperCase(f.detail.charAt(0)) + f.detail.substring(1), verdict);
		}
	}

	@Test
	public void allPassingGivesTheMeasuredLine()
	{
		assertEquals("Everything is being measured.", Checks.ALL_GOOD);
		assertEquals("Everything is being measured.", Checks.verdict(Checks.run(CheckFixtures.healthy().build())));
		assertEquals("an empty list has no failure", Checks.ALL_GOOD, Checks.verdict(Arrays.asList()));
	}

	/** {@code tests run: 9 pass, 1 fail: C4 Ping readable}; several failures are comma separated. */
	@Test
	public void theNoteCountsAndNamesTheFailures()
	{
		assertEquals("tests run: 10 pass, 0 fail", Checks.summary(Checks.run(CheckFixtures.healthy().build())));
		assertEquals("tests run: 9 pass, 1 fail: C4 Ping readable",
			Checks.summary(run(b -> b.pingState = CheckFacts.Ping.UNSUPPORTED)));
		assertEquals("tests run: 8 pass, 2 fail: C2 Frames arrive, C9 Clock sane", Checks.summary(run(b ->
		{
			b.framesLast2s = 0;
			b.clockJumpedBackS = 3;
		})));
	}

	/** The report's two sections: the verdict line, a blank line, "Checks:", ten lines, a blank line. */
	@Test
	public void theSectionIsTheVerdictAndTenLines()
	{
		final String ok = Checks.section(Checks.run(CheckFixtures.healthy().build()));
		final String[] lines = ok.split("\n", -1);
		assertEquals("Verdict: Everything is being measured.", lines[0]);
		assertEquals("", lines[1]);
		assertEquals("Checks:", lines[2]);
		assertEquals("PASS  C1 Logged in  world 416", lines[3]);
		assertEquals("PASS  C4 Ping readable  41 ms, 1 s old", lines[6]);
		assertEquals("PASS  C10 Not stuck measuring  card: Smooth", lines[12]);
		assertEquals("", lines[13]);
		assertEquals("ends with a new line after the blank one", "", lines[14]);
		assertEquals(15, lines.length);

		final String bad = Checks.section(run(b -> b.lastTickAgoMs = 4000));
