package com.whylag.core;

import java.io.IOException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The diagnostics memory of 1.0.1 (lot A, A2): a ring of the newest 200 notes printed {@code hh:mm:ss  text}; a key
 * that is new once and counted every time; the last ten DISTINCT errors, each with three frames and a count; a
 * scrub that takes every file path out of every text that comes in; and the text in its three sections. The clock is
 * a parameter and the zone is fixed, so every stamp is a known one.
 */
public class DiagnosticsTest
{
	/** 2026-09-30T14:05:09Z. */
	private static final long T0 = Instant.parse("2026-09-30T14:05:09Z").toEpochMilli();

	private final Diagnostics d = new Diagnostics(ZoneOffset.UTC);

	// ---------------------------------------------------------------- the notes

	@Test
	public void aNoteIsStampedHoursMinutesSecondsThenTwoSpacesThenTheText()
	{
		d.note(T0, "plugin started, version 1.0.1, client 1.13.0, Windows 11");

		assertEquals(Arrays.asList("14:05:09  plugin started, version 1.0.1, client 1.13.0, Windows 11"),
			section(d.text(), "Notes"));
	}

	@Test
	public void theStampFollowsTheZone()
	{
		final Diagnostics tokyo = new Diagnostics(ZoneId.of("Asia/Tokyo"));

		tokyo.note(T0, "x");

		assertEquals(Arrays.asList("23:05:09  x"), section(tokyo.text(), "Notes"));
	}

	/** Two hundred and fifty notes in, the newest two hundred out, oldest first: note 51 to note 250. */
	@Test
	public void theRingKeepsTheNewestTwoHundredOfTwoHundredFiftyNotes()
	{
		assertEquals(200, Diagnostics.NOTES);
		for (int i = 1; i <= 250; i++)
		{
			d.note(T0 + i * 1000L, "note " + i);
		}

		final List<String> notes = section(d.text(), "Notes");

		assertEquals(200, notes.size());
		assertEquals("the oldest fifty are gone", "14:06:00  note 51", notes.get(0));
		assertEquals("14:09:19  note 250", notes.get(199));
		for (int i = 0; i < notes.size(); i++)
		{
			assertTrue("in order: " + notes.get(i), notes.get(i).endsWith("  note " + (51 + i)));
		}
	}

	@Test
	public void aLineBreakInANoteNeverBreaksTheText()
	{
		d.note(T0, "a\nb\r\nc\rd");

		assertEquals(Arrays.asList("14:05:09  a b c d"), section(d.text(), "Notes"));
	}

	// ---------------------------------------------------------------- the warnings

	@Test
	public void aKeyIsNewOnceAndCountedEveryTime()
	{
		assertEquals(0, d.warningCount("step: IllegalStateException"));

		assertTrue(d.warnOnce("step: IllegalStateException", "boom"));
		assertFalse(d.warnOnce("step: IllegalStateException", "boom"));
		assertFalse(d.warnOnce("step: IllegalStateException", "boom"));
		assertTrue("another key is its own", d.warnOnce("probe", "no beans"));

		assertEquals(3, d.warningCount("step: IllegalStateException"));
		assertEquals(1, d.warningCount("probe"));
		assertEquals(Arrays.asList("step: IllegalStateException  3 times  boom", "probe  1 time  no beans"),
			section(d.text(), "Warnings"));
	}

	@Test
	public void aWarningKeepsTheTextOfItsFirstTime()
	{
		d.warnOnce("k", "first");
		d.warnOnce("k", "second");

		assertEquals(Arrays.asList("k  2 times  first"), section(d.text(), "Warnings"));
	}

	// ---------------------------------------------------------------- the errors

	/** Eleven distinct errors, the ten newest kept; a repeat bumps its count and keeps its place. */
	@Test
	public void tenDistinctErrorsOfElevenAreKeptAndTheRepeatIsCounted()
	{
		assertEquals(10, Diagnostics.ERRORS);
		for (int i = 1; i <= 11; i++)
		{
			d.error(T0 + i * 1000L, new IllegalStateException("message " + i));
		}
		d.error(T0 + 12_000L, new IllegalStateException("message 5"));

		final List<String> errors = errorLines(d.text());

		assertEquals("the first error is gone, ten are kept", 10, errors.size());
		assertEquals("14:05:11  java.lang.IllegalStateException: message 2", errors.get(0));
		assertEquals("a repeat keeps its place and its first time, and counts",
			"14:05:14  java.lang.IllegalStateException: message 5  (2 times)", errors.get(3));
		assertEquals("14:05:20  java.lang.IllegalStateException: message 11", errors.get(9));
		assertFalse(d.text().contains("message 1\n"));
	}

	@Test
	public void theSameClassWithAnotherMessageIsAnotherError()
	{
		d.error(T0, new IllegalStateException("a"));
		d.error(T0, new IllegalArgumentException("a"));
		d.error(T0, new IllegalStateException("b"));
		d.error(T0, new IllegalStateException("a"));

		final List<String> errors = errorLines(d.text());

		assertEquals(3, errors.size());
		assertEquals("14:05:09  java.lang.IllegalStateException: a  (2 times)", errors.get(0));
	}

	/** An error keeps its class, its message and its first three frames, and no more. */
	@Test
	public void anErrorKeepsItsFirstThreeFrames()
	{
		assertEquals(3, Diagnostics.FRAMES);
		final IllegalStateException boom = new IllegalStateException("the probe fails");
		boom.setStackTrace(new StackTraceElement[] {
			new StackTraceElement("a.A", "one", "A.java", 1), new StackTraceElement("b.B", "two", "B.java", 2),
			new StackTraceElement("c.C", "three", "C.java", 3), new StackTraceElement("d.D", "four", "D.java", 4)});

		d.error(T0, boom);

		assertEquals(Arrays.asList("14:05:09  java.lang.IllegalStateException: the probe fails",
			"    at a.A.one(A.java:1)", "    at b.B.two(B.java:2)", "    at c.C.three(C.java:3)"),
			section(d.text(), "Errors"));
	}

	@Test
	public void anErrorWithNoMessageIsItsClassAlone()
	{
		d.error(T0, new NoClassDefFoundError());

		assertTrue(errorLines(d.text()).get(0), errorLines(d.text()).get(0).endsWith("  java.lang.NoClassDefFoundError"));
	}

	// ---------------------------------------------------------------- the scrub

	@Test
	public void scrubTakesEveryKindOfPathOut()
	{
		assertEquals("<path>", Diagnostics.scrub("C:\\Users\\john\\x.txt"));
		assertEquals("<path>", Diagnostics.scrub("/home/john/x"));
		assertEquals("<path>", Diagnostics.scrub("/Users/john/x"));
		assertEquals("<path>", Diagnostics.scrub("/tmp/whylag/x.txt"));
		assertEquals("a path before words", "<path> (Access is denied)",
			Diagnostics.scrub("C:\\Users\\John Smith\\AppData\\x.txt (Access is denied)"));
		assertEquals("a path inside words", "cannot open <path> now",
			Diagnostics.scrub("cannot open C:\\Users\\john\\x.txt now"));
		assertEquals("a name with a space after a drive-less Users\\", "<path>",
			Diagnostics.scrub("Users\\John Smith\\x"));
		assertEquals("a network path", "<path>", Diagnostics.scrub("\\\\host\\share\\x.txt"));
		assertEquals("a Unix path of two parts", "read <path> failed", Diagnostics.scrub("read /var/log failed"));
		assertEquals("a file URL", "file://<path>", Diagnostics.scrub("file:///home/john/x"));
		assertEquals("a forward-slash drive path", "<path>", Diagnostics.scrub("C:/Users/john/x.txt"));
	}

	@Test
	public void scrubLeavesWordsAndNumbersAlone()
	{
		for (String plain : new String[] {"world 416", "hop to world 302", "fps 48/50/51", "and/or", "a / b",
			"https://example.com/a/b", "ticks 1,240 ms, ping 41 ms", "lag closed after 14 s: World lag - not you, Likely",
			"plugin started, version 1.0.1, client 1.13.0, Windows 11"})
		{
			assertEquals(plain, Diagnostics.scrub(plain));
		}
		assertEquals("", Diagnostics.scrub(null));
		assertEquals("", Diagnostics.scrub(""));
	}

	/** A message that is only a path: the error prints the class and "<path>", and nothing of the path. */
	@Test
	public void anExceptionMessageThatIsOnlyAPathLeavesNothingOfIt()
	{
		d.error(T0, new IOException("C:\\Users\\john\\AppData\\Roaming\\x"));
		d.error(T0, new IOException("/home/john/x"));

		final String text = d.text();

		assertTrue(text, text.contains("java.io.IOException: <path>"));
		assertFalse(text, text.contains("john"));
		assertFalse(text, text.contains("AppData"));
		assertEquals("both are one error: the same class and the same scrubbed message", 1,
			errorLines(text).size());
		assertTrue(errorLines(text).get(0).endsWith("  (2 times)"));
	}

	/** Every door a text comes in by is scrubbed: a note, a warning's key and text, an error's message. */
	@Test
	public void everyEntryPointIsScrubbed()
	{
		d.note(T0, "cannot open C:\\Users\\john\\x.txt");
		d.warnOnce("key /home/john/x", "text /Users/john/y");
		d.error(T0, new IllegalStateException("bad C:\\Users\\john\\z"));

		final String text = d.text();

		assertFalse(text, text.contains("john"));
		assertFalse(text, text.contains("Users"));
		assertEquals(4, count(text, "<path>"));
	}

	// ---------------------------------------------------------------- the text

	@Test
	public void theTextIsNotesThenWarningsThenErrorsWithABlankLineBetween()
	{
		d.note(T0, "n");
		d.warnOnce("w", "t");
		d.error(T0, new IllegalStateException("e"));

		final String[] lines = d.text().split("\n", -1);

		assertEquals(Arrays.asList("Notes", "14:05:09  n", "", "Warnings", "w  1 time  t", "", "Errors"),
			Arrays.asList(lines).subList(0, 7));
		assertTrue(lines[7], lines[7].startsWith("14:05:09  java.lang.IllegalStateException: e"));
		assertTrue("ends with a new line", d.text().endsWith("\n"));
	}

	@Test
	public void aSectionWithNothingInItSaysNone()
	{
		assertEquals("Notes\n(none)\n\nWarnings\n(none)\n\nErrors\n(none)\n", d.text());
		assertEquals(d.text(), Diagnostics.empty());
		assertEquals("(none)", Diagnostics.NONE);
	}

	// ---------------------------------------------------------------- threads

	/** The sampler writes while the report reads: no exception, and the ring is still 200. */
	@Test
	public void itIsSafeToReadWhileTheOtherThreadWrites() throws Exception
	{
		final AtomicReference<Throwable> failed = new AtomicReference<>();
		final Thread writer = new Thread(() ->
		{
			try
			{
				for (int i = 0; i < 2000; i++)
				{
					d.note(T0, "note " + i);
					d.warnOnce("k" + i % 7, "t");
					d.error(T0, new IllegalStateException("e" + i % 13));
				}
			}
			catch (Throwable t)
			{
				failed.set(t);
			}
		}, "test-writer");
		writer.start();
		for (int i = 0; i < 200; i++)
		{
			assertTrue(d.text().startsWith("Notes\n"));
		}
		writer.join(20_000);
		assertFalse(writer.isAlive());
		assertEquals(null, failed.get());
		assertEquals(200, section(d.text(), "Notes").size());
		assertEquals(10, errorLines(d.text()).size());
	}

	// ---------------------------------------------------------------- helpers

	/** The lines under one heading, up to the blank line or the end. */
	private static List<String> section(String text, String heading)
	{
		final String[] lines = text.split("\n", -1);
		final List<String> out = new ArrayList<>();
		boolean in = false;
		for (String line : lines)
		{
			if (!in)
			{
				in = line.equals(heading);
			}
			else if (line.isEmpty())
			{
				break;
			}
			else
			{
				out.add(line);
			}
		}
		return out;
	}

	/** The first line of each error: the ones that start with a clock. */
	private static List<String> errorLines(String text)
	{
		final List<String> out = new ArrayList<>();
		for (String line : section(text, "Errors"))
		{
			if (!line.startsWith("    at "))
			{
				out.add(line);
			}
		}
		return out;
	}

	private static int count(String text, String part)
	{
		int n = 0;
		for (int at = text.indexOf(part); at >= 0; at = text.indexOf(part, at + 1))
		{
			n++;
		}
		return n;
	}
}

package com.whylag.core;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The small enums and codes of contract 3.2: the three lanes, each with a tile; the operating systems and their
 * units (C1); the cap sources and the renderers' words; the confidence steps; one bit per trigger; the state codes;
 * the flag bits and the mask of the flags alone; the groups' lanes and labels; the ordinals that are stored; and
 * the game badge's enums - its two settings and its four pictures. {@link Cause} has its own test, and the stored
 * NAMES of the badge's settings are pinned in {@code WhyLagConfigTest}.
 */
public class EnumsTest
{
	@Test
	public void lanesAreThreeAndEachHasATile()
	{
		assertEquals(3, Lane.values().length);
		assertEquals(3, Lane.TILES);
		assertEquals(Lane.values().length, Lane.TILES);
		assertEquals(Arrays.asList(Lane.FRAME_RATE, Lane.TICKS, Lane.PING), Arrays.asList(Lane.values()));
		assertEquals("Frame rate", Lane.FRAME_RATE.label());
		assertEquals("Ticks", Lane.TICKS.label());
		assertEquals("Ping", Lane.PING.label());
	}

	@Test
	public void operatingSystems()
	{
		assertEquals(Os.WINDOWS, Os.of("Windows 11"));
		assertEquals(Os.WINDOWS, Os.of("Windows 10"));
		assertEquals(Os.MAC, Os.of("Mac OS X"));
		assertEquals("Darwin holds 'win' but is a Mac", Os.MAC, Os.of("Darwin"));
		assertEquals(Os.LINUX, Os.of("Linux"));
		assertEquals(Os.OTHER, Os.of("FreeBSD"));
		assertEquals(Os.OTHER, Os.of(null));
		assertTrue(Os.WINDOWS.countsBytes());
		assertFalse(Os.MAC.countsBytes());
		assertFalse(Os.LINUX.countsBytes());
		assertFalse(Os.OTHER.countsBytes());
		assertEquals(Thresholds.RESENT_MIN_BYTES, Os.WINDOWS.resentMinSent());
		assertEquals(Thresholds.RESENT_MIN_UNITS, Os.LINUX.resentMinSent());
		assertEquals(Thresholds.CLICK_SENT_BYTES, Os.WINDOWS.clickSent());
		assertEquals(Thresholds.CLICK_SENT_UNITS, Os.MAC.clickSent());
	}

	@Test
	public void capSources()
	{
		assertFalse(CapSource.NONE.selfSet());
		assertFalse(CapSource.CLIENT_50.selfSet());
		assertFalse(CapSource.CLIENT_50.waits());
		for (CapSource c : new CapSource[] {CapSource.FPS_CONTROL, CapSource.FPS_CONTROL_UNFOCUSED,
			CapSource.GPU_TARGET, CapSource.GPU_VSYNC, CapSource.HD_TARGET, CapSource.HD_VSYNC})
		{
			assertTrue(c + " is set by the player", c.selfSet());
			assertTrue(c + " paces by waiting", c.waits());
		}
		assertEquals("the client", CapSource.CLIENT_50.label());
		assertEquals("FPS Control (unfocused)", CapSource.FPS_CONTROL_UNFOCUSED.label());
		assertEquals("117 HD: V-Sync", CapSource.HD_VSYNC.label());
		assertEquals("117 HD", Renderer.HD.label());
		assertEquals("unknown", Renderer.UNKNOWN.label());
	}

	@Test
	public void confidenceSteps()
	{
		assertEquals(Confidence.LIKELY, Confidence.SURE.lower());
		assertEquals(Confidence.HINT, Confidence.LIKELY.lower());
		assertEquals(Confidence.CANT_TELL, Confidence.HINT.lower());
		assertEquals("Can't tell stays", Confidence.CANT_TELL, Confidence.CANT_TELL.lower());
		assertEquals(Confidence.HINT, Confidence.weaker(Confidence.SURE, Confidence.HINT));
		assertEquals(Confidence.HINT, Confidence.weaker(Confidence.HINT, Confidence.LIKELY));
		assertSame(Confidence.SURE, Confidence.weaker(Confidence.SURE, Confidence.SURE));
		assertEquals("Sure", Confidence.SURE.word());
		assertEquals("Likely", Confidence.LIKELY.word());
		assertEquals("Hint", Confidence.HINT.word());
		assertEquals("Can't tell", Confidence.CANT_TELL.word());
	}

	@Test
	public void triggerBits()
	{
		final Set<Integer> bits = new HashSet<>();
		int all = 0;
		for (Trigger t : Trigger.values())
		{
			assertEquals(1 << t.ordinal(), t.bit());
			assertTrue(bits.add(t.bit()));
			all |= t.bit();
		}
		assertEquals("seven triggers, one bit each", 127, all);
	}

	@Test
	public void stateCodes()
	{
		assertEquals(0, State.OTHER);
		assertEquals(1, State.LOGIN_SCREEN);
		assertEquals(2, State.LOGGING_IN);
		assertEquals(3, State.LOADING);
		assertEquals(4, State.LOGGED_IN);
		assertEquals(5, State.CONNECTION_LOST);
		assertEquals(6, State.HOPPING);
		assertTrue(State.inGame(State.LOGGED_IN));
		assertTrue(State.inGame(State.LOADING));
		assertFalse(State.inGame(State.OTHER));
		assertFalse(State.inGame(State.LOGIN_SCREEN));
		assertFalse(State.inGame(State.LOGGING_IN));
		assertFalse(State.inGame(State.HOPPING));
		assertFalse(State.inGame(State.CONNECTION_LOST));
	}

	@Test
	public void flagBits()
	{
		assertEquals(1, Flags.FOCUSED);
		assertEquals(2, Flags.LOADING);
		assertEquals(4, Flags.HOP);
		assertEquals(8, Flags.LOGIN_MASK);
		assertEquals(16, Flags.NOT_LOGGED_IN);
		assertEquals(32, Flags.NO_FRAMES);
		assertEquals(64, Flags.DISCONNECT);
		assertTrue(Flags.has(Flags.FOCUSED | Flags.HOP, Flags.HOP));
		assertFalse(Flags.has(Flags.FOCUSED, Flags.HOP));
		final int every = Flags.FOCUSED | Flags.LOADING | Flags.HOP | Flags.LOGIN_MASK | Flags.NOT_LOGGED_IN
			| Flags.NO_FRAMES | Flags.DISCONNECT;
		assertEquals("seven bits, one byte, never negative", 127, every);
	}

	/** The mask every lot can read: the four flags that mask a second by themselves, and no other. */
	@Test
	public void maskedIsTheFourFlags()
	{
		assertEquals(30, Flags.MASKED);
		assertEquals(Flags.LOADING | Flags.HOP | Flags.LOGIN_MASK | Flags.NOT_LOGGED_IN, Flags.MASKED);
		for (int bit : new int[] {Flags.LOADING, Flags.HOP, Flags.LOGIN_MASK, Flags.NOT_LOGGED_IN})
		{
			assertTrue("flag " + bit + " masks its second", Flags.masked(bit));
			assertTrue("flag " + bit + " masks beside the focus", Flags.masked(bit | Flags.FOCUSED));
		}
		for (int bit : new int[] {Flags.FOCUSED, Flags.NO_FRAMES, Flags.DISCONNECT})
		{
			assertFalse("flag " + bit + " alone masks nothing", Flags.masked(bit));
		}
		assertFalse("a steady second", Flags.masked(0));
		assertFalse(Flags.masked(Flags.FOCUSED | Flags.NO_FRAMES | Flags.DISCONNECT));
		assertTrue("every flag", Flags.masked(127));
	}

	/** The badge's two settings: the names the settings list shows, and what each style draws (contract P2.3). */
	@Test
	public void badgeStylesAndWhenSmooth()
	{
		assertEquals(Arrays.asList(BadgeStyle.ICON, BadgeStyle.ICON_AND_WORDS, BadgeStyle.SHAPE_AND_WORDS,
			BadgeStyle.SHAPE_ONLY), Arrays.asList(BadgeStyle.values()));
		assertEquals("Icon", BadgeStyle.ICON.toString());
		assertEquals("Icon and words", BadgeStyle.ICON_AND_WORDS.toString());
		assertEquals("Shape and words", BadgeStyle.SHAPE_AND_WORDS.toString());
		assertEquals("Shape only", BadgeStyle.SHAPE_ONLY.toString());

		assertTrue(BadgeStyle.ICON.icon());
		assertFalse(BadgeStyle.ICON.words());
		assertTrue(BadgeStyle.ICON_AND_WORDS.icon());
		assertTrue(BadgeStyle.ICON_AND_WORDS.words());
		assertFalse("never an icon", BadgeStyle.SHAPE_AND_WORDS.icon());
		assertTrue(BadgeStyle.SHAPE_AND_WORDS.words());
		assertFalse(BadgeStyle.SHAPE_ONLY.icon());
		assertFalse(BadgeStyle.SHAPE_ONLY.words());

		assertEquals(Arrays.asList(WhenSmooth.SHOW, WhenSmooth.HIDE), Arrays.asList(WhenSmooth.values()));
		assertEquals("Show", WhenSmooth.SHOW.toString());
		assertEquals("Hide", WhenSmooth.HIDE.toString());
	}

	/** The badge's four pictures, and each one's word in the icon files' names; NONE has no file. */
	@Test
	public void icons()
	{
		assertEquals(Arrays.asList(Icon.NONE, Icon.WORLD, Icon.LINE, Icon.PC, Icon.UNKNOWN),
			Arrays.asList(Icon.values()));
		assertEquals("", Icon.NONE.file());
		assertEquals("world", Icon.WORLD.file());
		assertEquals("line", Icon.LINE.file());
		assertEquals("pc", Icon.PC.file());
		assertEquals("unknown", Icon.UNKNOWN.file());
	}

	@Test
	public void groupsAndLanes()
	{
		assertEquals(Lane.PING, Group.CONNECTION.lane());
		assertEquals(Lane.FRAME_RATE, Group.FRAME_RATE.lane());
		assertEquals(Lane.TICKS, Group.WORLD.lane());
		assertNull(Group.UNSURE.lane());
		assertNull(Group.NONE.lane());
		assertEquals("Conn", Group.CONNECTION.shortLabel());
		assertEquals("Frame", Group.FRAME_RATE.shortLabel());
		assertEquals("World", Group.WORLD.shortLabel());
		assertEquals("?", Group.UNSURE.shortLabel());
		assertEquals("Connection", Group.CONNECTION.label());
		assertEquals("Not sure", Group.UNSURE.label());
	}

	@Test
	public void storedOrdinalsKeepTheirPlaces()
	{
		// Levels are stored per strip column, groups index the session counts, NoData is a ring column, and the
		// lanes index the snapshot's strips.
		assertEquals(0, Level.OK.ordinal());
		assertEquals(1, Level.WARN.ordinal());
		assertEquals(2, Level.BAD.ordinal());
		assertEquals(3, Level.NO_DATA.ordinal());
		assertEquals(0, Group.CONNECTION.ordinal());
		assertEquals(1, Group.FRAME_RATE.ordinal());
		assertEquals(2, Group.WORLD.ordinal());
		assertEquals(3, Group.UNSURE.ordinal());
		assertEquals(4, Group.NONE.ordinal());
		assertEquals(0, NoData.NONE.ordinal());
		assertEquals(9, NoData.values().length);
		assertEquals(3, Lane.values().length);
		assertEquals(2, Lane.PING.ordinal());
	}
}

package com.whylag.core;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * The event log (contract 3.4): the cap of 500 with the session counts kept, {@code replace} re-counting the
 * group, {@code between}, and every reader of closed events skipping the open one. With it, the verdict (3.6):
 * what makes two verdicts the same and its texts never null; and every public field of the carriers is final. The
 * event itself is {@code LagEventTest}'s; the carriers the panel reads are {@code PanelTypesTest}'s.
 */
public class EventLogTest
{
	@Test
	public void capAtFiveHundredKeepsTheSessionCounts()
	{
		final EventLog log = new EventLog(Thresholds.EVENTS);
		for (int i = 0; i < 520; i++)
		{
			log.add(closed(i, 10L * i, 10L * i + 2, i % 2 == 0 ? Cause.SLOW_WORLD : Cause.CLIENT_BUSY));
		}
		assertEquals(500, log.size());
		assertEquals("the oldest twenty were dropped", 20, log.get(0).id);
		assertEquals(519, log.get(499).id);
		assertEquals("dropped events stay counted", 520, log.sessionTotal());
		assertEquals(260, log.sessionCount(Group.WORLD));
		assertEquals(260, log.sessionCount(Group.FRAME_RATE));
		assertEquals(0, log.sessionCount(Group.CONNECTION));
		assertNull("a dropped event is not held", log.byId(3));
		assertEquals(500, log.copy().size());
	}

	@Test
	public void replaceRecountsTheGroup()
	{
		final EventLog log = new EventLog(10);
		log.add(open(1, 100));
		assertEquals("an open event is not counted", 0, log.sessionTotal());
		assertTrue(log.replace(closed(1, 100, 113, Cause.SLOW_WORLD)));
		assertEquals(1, log.sessionTotal());
		assertEquals(1, log.sessionCount(Group.WORLD));
		assertEquals("held once", 1, log.size());
		assertTrue(log.replace(closed(1, 100, 113, Cause.UPLOAD_LOSS)));
		assertEquals(1, log.sessionTotal());
		assertEquals(0, log.sessionCount(Group.WORLD));
		assertEquals(1, log.sessionCount(Group.CONNECTION));
		assertFalse("no event 2 is held", log.replace(closed(2, 200, 201, Cause.CLIENT_BUSY)));
		assertEquals(1, log.size());
		assertEquals(1, log.sessionTotal());
	}

	@Test
	public void anUnjudgedClosedEventCountsAsNotSure()
	{
		final EventLog log = new EventLog(10);
		log.add(event(1, 100, 101, false, null));
		assertEquals(1, log.sessionCount(Group.UNSURE));
		log.add(closed(2, 110, 112, Cause.DELIVERY_GAP));
		assertEquals("N6 is counted as not sure", 2, log.sessionCount(Group.UNSURE));
	}

	@Test
	public void between()
	{
		final EventLog log = new EventLog(10);
		log.add(closed(1, 100, 105, Cause.SLOW_WORLD));
		log.add(closed(2, 200, 200, Cause.CLIENT_BUSY));
		log.add(closed(3, 300, 320, Cause.CLIENT_BUSY));
		log.add(open(4, 400));
		assertIds(log.between(0, 1000), 1, 2, 3);
		assertIds(log.between(105, 200), 1, 2);
		assertIds(log.between(106, 199));
		assertIds(log.between(310, 310), 3);
		assertIds("the open event is not listed", log.between(400, 500));
		try
		{
			log.between(0, 1000).add(closed(9, 1, 1, Cause.CLIENT_BUSY));
			fail("unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// as the contract says
		}
	}

	@Test
	public void lastSkipsTheOpenEvent()
	{
		final EventLog log = new EventLog(10);
		assertNull(log.last());
		log.add(closed(1, 100, 105, Cause.SLOW_WORLD));
		log.add(open(2, 200));
		assertEquals(1, log.last().id);
		log.replace(closed(2, 200, 204, Cause.CLIENT_BUSY));
		assertEquals(2, log.last().id);
	}

	@Test
	public void copyHoldsEverythingOldestFirst()
	{
		final EventLog log = new EventLog(3);
		for (int i = 1; i <= 4; i++)
		{
			log.add(closed(i, i * 10L, i * 10L, Cause.CLIENT_BUSY));
		}
		log.add(open(5, 60));
		assertIds(log.copy(), 3, 4, 5);
		assertSame(log.get(2), log.byId(5));
		assertEquals(4, log.sessionTotal());
		try
		{
			log.get(3);
			fail("only three are held");
		}
		catch (IndexOutOfBoundsException expected)
		{
			// as it should
		}
	}

	@Test
	public void sameVerdict()
	{
		final Verdict a = aVerdict(Cause.SLOW_WORLD, "World 416 is struggling, not you");
		final Verdict b = new Verdict(Cause.SLOW_WORLD, Confidence.HINT, Level.WARN, a.headline, a.proof, a.fix,
			"other ruled out", 99, 7, 302, a.eventId, null, null);
		assertTrue("confidence, level, when and ruled-out do not make it different", a.sameAs(b));
		assertFalse(a.sameAs(aVerdict(Cause.SLOW_WORLD, "another headline")));
		assertFalse(a.sameAs(aVerdict(Cause.DELIVERY_GAP, a.headline)));
		assertFalse(a.sameAs(new Verdict(a.cause, a.confidence, a.level, a.headline, a.proof, a.fix, "", 0, 0, 0,
			a.eventId + 1, null, null)));
		assertFalse(a.sameAs(new Verdict(a.cause, a.confidence, a.level, a.headline, "other proof", a.fix, "", 0, 0,
			0, a.eventId, null, null)));
		assertFalse(a.sameAs(new Verdict(a.cause, a.confidence, a.level, a.headline, a.proof, "", "", 0, 0, 0,
			a.eventId, null, null)));
		assertFalse(a.sameAs(null));
	}

	@Test
	public void verdictTextsAreNeverNull()
	{
		final Verdict v = new Verdict(Cause.ALL_CLEAR, Confidence.SURE, Level.OK, null, null, null, null, 0, 0, 0,
			-1, null, null);
		assertEquals("", v.headline);
		assertEquals("", v.proof);
		assertEquals("", v.fix);
		assertEquals("", v.ruledOut);
		assertTrue(v.sameAs(new Verdict(Cause.ALL_CLEAR, Confidence.SURE, Level.OK, "", "", "", "", 0, 0, 0, -1,
			null, null)));
	}

	private static void assertIds(List<LagEvent> events, long... ids)
	{
		assertIds("", events, ids);
	}

	private static void assertIds(String why, List<LagEvent> events, long... ids)
	{
		assertEquals(why, ids.length, events.size());
		for (int i = 0; i < ids.length; i++)
		{
			assertEquals(why, ids[i], events.get(i).id);
		}
	}

	private static LagEvent open(long id, long startSec)
	{
		return event(id, startSec, startSec, true, null);
	}

	private static LagEvent closed(long id, long startSec, long endSec, Cause cause)
	{
		final Verdict v = new Verdict(cause, Confidence.LIKELY, Level.BAD, "h", "p", "f", "", 0, 0, 416, id, null,
			null);
		return event(id, startSec, endSec, false, v);
	}

	private static LagEvent event(long id, long startSec, long endSec, boolean open, Verdict v)
	{
		return new LagEvent(id, startSec, endSec, 0, Trigger.FRAME_GAP.bit(), Trigger.FRAME_GAP, 416, 0, 0, 0, 50,
			300, 600, 610, 0, 40, 41, 40, 900, 0, open, false, v);
	}

	private static Verdict aVerdict(Cause cause, String headline)
	{
		return new Verdict(cause, Confidence.LIKELY, Level.BAD, headline, "Ticks 600 to 900+ ms for 14 s.",
			"Hop to a quieter world.", "Frames and ping were fine.", 1_790_000_100_000L, 14, 416, 11, null, null);
	}
}

package com.whylag.core;

import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * One event as the three tiles and the three lane values (contract 3.8, 5.2, 5.3): the picture's "lag found" event
 * and the dash for every field with no data. The memory tile and the CPU lane are gone (1.0.0, the Hub's rule).
 */
public class EventViewTest
{
	/** The picture's event: 50 fps, worst frame 34, ticks 952 mean / 1,240 worst, ping 41 (was 41). */
	static LagEvent picturesEvent()
	{
		return event(50, 34, 952, 1240, 640, 41, 41);
	}

	@Test
	public void thePicturesEvent()
	{
		final LagEvent e = picturesEvent();
		final Tile[] t = EventView.tiles(e);
		assertEquals(3, t.length);
		assertEquals(Lane.TILES, t.length);
		assertTile(t[0], Lane.FRAME_RATE, "50 fps", "worst 34 ms", Level.OK);
		assertTile(t[1], Lane.TICKS, "952 ms", "worst 1,240", Level.BAD);
		assertTile(t[2], Lane.PING, "41 ms", "was 41 ms", Level.OK);
		for (Tile tile : t)
		{
			assertEquals(NoData.NONE, tile.noData);
		}
		assertArrayEquals("three lane values", new String[] {"50 fps", "952 ms", "41 ms"}, EventView.laneValues(e));
		assertArrayEquals(new Level[] {Level.OK, Level.BAD, Level.OK}, EventView.laneLevels(e));
	}

	/** The lane values and levels ARE the tiles'. */
	@Test
	public void laneValuesAreTheTileValues()
	{
		for (LagEvent e : new LagEvent[] {picturesEvent(), event(-1, -1, -1, -1, -1, -1, -1),
			event(12, 400, 1500, 2400, 900, 310, 40)})
		{
			final Tile[] tiles = EventView.tiles(e);
			final String[] values = EventView.laneValues(e);
			final Level[] levels = EventView.laneLevels(e);
			assertEquals(3, values.length);
			assertEquals(3, levels.length);
			assertEquals(Lane.values().length, values.length);
			for (int i = 0; i < Lane.TILES; i++)
			{
				assertEquals(Lane.values()[i], tiles[i].lane);
				assertEquals("lane " + i, tiles[i].value, values[i]);
				assertEquals("lane " + i, tiles[i].level, levels[i]);
			}
		}
	}

	@Test
	public void noDataFieldsGiveADash()
	{
		final LagEvent none = event(-1, -1, -1, -1, -1, -1, -1);
		final Tile[] t = EventView.tiles(none);
		for (int i = 0; i < Lane.TILES; i++)
		{
			assertTile(t[i], Lane.values()[i], "-", "", Level.NO_DATA);
		}
		assertArrayEquals(new String[] {"-", "-", "-"}, EventView.laneValues(none));
		assertArrayEquals(new Level[] {Level.NO_DATA, Level.NO_DATA, Level.NO_DATA}, EventView.laneLevels(none));
	}

	@Test
	public void aMissingSubFieldLeavesTheValue()
	{
		// Known values with unknown small lines: no usual yet, no worst gap.
		final Tile[] t = EventView.tiles(event(50, -1, 952, -1, -1, 41, -1));
		assertTile(t[0], Lane.FRAME_RATE, "50 fps", "", Level.OK);
		assertTile(t[1], Lane.TICKS, "952 ms", "", Level.NO_DATA);
		assertTile(t[2], Lane.PING, "41 ms", "", Level.OK);
	}

	@Test
	public void noCapIsKnownForAPastEvent()
	{
		// 20 fps under a cap of 20 is OK on the live tile, but a past event knows no cap.
		assertEquals(Level.BAD, EventView.tiles(event(20, 50, 600, 610, 0, 41, 41))[0].level);
	}

	@Test
	public void bigNumbersAreGrouped()
	{
		final Tile[] t = EventView.tiles(event(999, 9999, 1240, 9999, 9000, 999, 1500));
		assertEquals("worst 9,999 ms", t[0].sub);
		assertEquals("1,240 ms", t[1].value);
		assertEquals("was 1,500 ms", t[2].sub);
	}

	private static void assertTile(Tile t, Lane lane, String value, String sub, Level level)
	{
		assertEquals(lane, t.lane);
		assertEquals(value, t.value);
		assertEquals(sub, t.sub);
		assertEquals(level, t.level);
	}

	private static LagEvent event(int fps, int worstFrameMs, int meanTickGapMs, int worstTickGapMs,
		int worstCorrectedTickMs, int rttMs, int rttBeforeMs)
	{
		return new LagEvent(7, 100, 113, 0, Trigger.TICK_OFF.bit(), Trigger.TICK_OFF, 416, 0, 0, 0, fps,
			worstFrameMs, meanTickGapMs, worstTickGapMs, worstCorrectedTickMs, rttMs, rttMs, rttBeforeMs, 900, 0,
			false, false, null);
	}
}

package com.whylag.core;

import org.junit.Test;
import static com.whylag.core.VerdictCauseTest.USUAL;
import static com.whylag.core.VerdictCauseTest.event;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The evidence of contract 6.3, field by field, against traces whose numbers are worked by hand.
 */
public class EvidenceBuilderTest
{
	private static final SettingsView DEFAULT = Trace.steady(1).settings();

	/** FPS Control with its focused limit off and its unfocused limit on at 10, on the CPU renderer (3.7). */
	private static SettingsView unfocusedLimit()
	{
		return new SettingsView(Renderer.CPU, true, false, 0, true, 10, false, "", 0, 0, "", 0, 60, Os.WINDOWS, "");
	}

	private static Evidence ofEvent(Trace t, int from, int to, Trigger first, Trigger... more)
	{
		final Session s = t.build();
		return EvidenceBuilder.forEvent(s, event(s, 0, from, to, first, more), t.settings());
	}

	private static Evidence ofWindow(Trace t, int nowSec)
	{
		return EvidenceBuilder.forCondition(t.build(), nowSec, t.settings());
	}

	@Test
	public void aSteadySpanAndASteadyWindow()
	{
		final Evidence e = ofEvent(Trace.steady(200).usual(USUAL), 120, 129, Trigger.TICK_OFF);
		assertTrue(e.event);
		assertEquals(Trigger.TICK_OFF, e.first);
		assertFalse(e.disconnect);
		assertEquals(-1, e.disconnectSec);
		assertEquals(-1, e.lastTickSec);
		assertEquals(22, e.frameGapMs);
		assertEquals(200, e.frameLimitMs);
		assertEquals(0, e.loadMs);
		assertEquals(0, e.loads);
		assertEquals(50, e.capFps);
		assertEquals(20, e.capIntervalMs);
		assertFalse(e.capSelfSet);
		assertFalse(e.capWaits);
		assertEquals("the client", e.capLabel);
		assertEquals(50, e.fps);
		assertEquals(20, e.frameMedianMs);
		assertTrue(e.framesClean);
		assertTrue(e.rttKnown);
		assertEquals(40, e.rtt);
		assertEquals(40, e.rttMin);
		assertEquals(40, e.rttMax);
		assertEquals(40, e.rttUsual);
		assertEquals(Evidence.NO, e.rttSpike);
		assertEquals("seconds 118 to 131", 14 * 900, e.sent);
		assertEquals(0, e.resent);
		assertEquals(0, e.resentPm);
		assertFalse(e.resentCounts);
		assertEquals("120.0 to 129.6 s", 17, e.ticks);
		assertEquals(0, e.tickLate);
		assertEquals(0, e.tickEarly);
		assertEquals(578, e.tickMedianMs);
		assertEquals(600, e.tickWorstMs);
		assertEquals(600, e.noTickMs);
		assertEquals(0, e.tickOffMs);
		assertEquals(10, e.durationS);
		assertEquals(416, e.world);
		assertEquals(-1, e.beforeRtt);
		assertEquals(Evidence.NO_DATA, e.beforeRttSpike);
		assertEquals(-1, e.beforeResentPm);

		final Evidence w = ofWindow(Trace.steady(200).usual(USUAL), 200);
		assertFalse(w.event);
		assertEquals(50, w.fps);
		assertEquals(22, w.frameGapMs);
		assertEquals(100, w.ticksInWindow);
		assertEquals(600, w.tickWindowMedianMs);
		assertEquals(40, w.rtt);
		assertEquals(40, w.rttUsual);
		assertEquals(Evidence.NO, w.rttSpike);
		assertEquals(0, w.lowFpsS);
		assertEquals(-1, w.lowFps);
		assertEquals(0, w.capHeldS);
		assertFalse(w.eventInWindow);
		assertEquals(416, w.world);
		assertEquals(0, w.durationS);
		assertEquals(0, w.loadMs);

		// A window at an earlier nowSec replays the trace as it stood then (3.5).
		final Trace later = Trace.steady(200).usual(USUAL).rtt(150, 199, 180);
		assertEquals(40, ofWindow(later, 150).rttMax);
		assertEquals(180, ofWindow(later, 151).rttMax);
		// Before any second is complete there is nothing to read.
		final Evidence none = ofWindow(Trace.steady(200), 0);
		assertEquals(-1, none.fps);
		assertFalse(none.capSelfSet);
	}

	/** The worked case of 6.2: loading 1000, 1000 and 400 ms in seconds 100 to 102, LONG_LOAD in 103. */
	@Test
	public void loadMsReachesBackToTheRunThatFiredLongLoad()
	{
		final Trace t = Trace.steady(200).usual(USUAL).loading(100, 1000).loading(101, 1000).loading(102, 400);
		final Evidence e = ofEvent(t, 103, 103, Trigger.LONG_LOAD);
		assertEquals(2400, e.loadMs);
		assertEquals(1, e.loads);

		// The run is summed WHOLE, its seconds after the event's start and before it alike.
		final Evidence inside = ofEvent(t, 101, 101, Trigger.FRAME_GAP);
		assertEquals(2400, inside.loadMs);
		// A run that ended two seconds before the event is not its load.
		final Evidence after = ofEvent(t, 104, 106, Trigger.FRAME_GAP);
		assertEquals(0, after.loadMs);
		assertEquals("but it is one of the loads of the last ten minutes", 1, after.loads);

		// Two runs that touch the span are both summed; a gap of one second makes them two.
		final Trace two = Trace.steady(200).usual(USUAL).loading(100, 1000).loading(101, 700).loading(103, 300)
			.loading(104, 200);
		final Evidence both = ofEvent(two, 102, 103, Trigger.FRAME_GAP);
		assertEquals(1700 + 500, both.loadMs);
		assertEquals(2, both.loads);
	}

	@Test
	public void frameMedianMsIsTheIntervalAtTheMedianRate()
	{
		final Evidence fifty = ofEvent(Trace.steady(200), 120, 124, Trigger.TICK_OFF);
		assertEquals(50, fifty.fps);
		assertEquals(20, fifty.frameMedianMs);

		final Evidence slow = ofEvent(Trace.steady(200).fps(120, 124, 24), 120, 124, Trigger.TICK_OFF);
		assertEquals(24, slow.fps);
		assertEquals("ceil(1000 / 24)", 42, slow.frameMedianMs);

		final Evidence none = ofEvent(Trace.steady(200).fps(120, 124, 0), 120, 124, Trigger.FRAME_GAP);
		assertEquals(0, none.fps);
		assertEquals(1000, none.frameMedianMs);

		// The MEDIAN rate, not the mean and not the worst: two slow seconds of five.
		final Evidence mixed = ofEvent(Trace.steady(200).fps(120, 121, 10), 120, 124, Trigger.TICK_OFF);
		assertEquals(50, mixed.fps);
		assertEquals(20, mixed.frameMedianMs);

		final Evidence gone = new Evidence();
		assertEquals("no fps, no interval", -1, gone.frameMedianMs);
	}

	@Test
	public void worldIsTheFirstSeconds()
	{
		final Trace t = Trace.steady(200).usual(USUAL).hop(125, 302);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 120, 130, Trigger.TICK_OFF);
		assertEquals(416, EvidenceBuilder.forEvent(s, e, t.settings()).world);
		assertEquals("the same number as LagEvent.world", e.world, EvidenceBuilder.forEvent(s, e, t.settings()).world);
		assertEquals(302, EvidenceBuilder.forEvent(s, event(s, 1, 125, 130, Trigger.TICK_OFF), t.settings()).world);
		assertEquals(416, new VerdictEngine().judgeEvent(s, e, t.settings()).world);

		// A condition's world is the newest second's.
		assertEquals(416, EvidenceBuilder.forCondition(s, 125, t.settings()).world);
		assertEquals(302, EvidenceBuilder.forCondition(s, 126, t.settings()).world);
		assertEquals(302, EvidenceBuilder.forCondition(s, 200, t.settings()).world);
	}

	@Test
	public void aMedianOfAnEvenCountIsTheLowerMiddle()
	{
		assertEquals(-1, EvidenceBuilder.median(new int[0], 0));
		assertEquals(7, EvidenceBuilder.median(new int[] {7}, 1));
		assertEquals(3, EvidenceBuilder.median(new int[] {9, 3}, 2));
		assertEquals(5, EvidenceBuilder.median(new int[] {9, 3, 5}, 3));
		assertEquals(5, EvidenceBuilder.median(new int[] {9, 3, 7, 5}, 4));
		assertEquals("only the first n count", 3, EvidenceBuilder.median(new int[] {9, 3, 1, 1}, 2));
		final int[] kept = {9, 3, 7, 5};
		EvidenceBuilder.median(kept, 4);
		assertEquals("the values are not moved", 9, kept[0]);

		// In the evidence: two seconds, 30 and 50 frames, 40 and 80 ms of ping.
		final Trace t = Trace.steady(200).usual(USUAL).fps(120, 120, 30).rtt(121, 121, 80);
		final Evidence e = ofEvent(t, 120, 121, Trigger.TICK_OFF);
		assertEquals(30, e.fps);
		assertEquals(40, e.rtt);
		assertEquals(40, e.rttMin);
		assertEquals(80, e.rttMax);
		// As Usual.median() does.
		final Usual usual = new Usual(100);
		for (int i = 0; i < Thresholds.USUAL_MIN_SAMPLES / 2; i++)
		{
			usual.add(30);
			usual.add(50);
		}
		assertEquals(30, usual.median());

		// Four ticks in the span, gaps 850, 350, 600, 600 less the 22 ms frame: 328, 578, 578, 828.
		final Evidence ticks = ofEvent(Trace.steady(200).usual(USUAL).tickLate(120, 250, true), 120, 121,
			Trigger.TICK_OFF);
		assertEquals(4, ticks.ticks);
		assertEquals(578, ticks.tickMedianMs);
		assertEquals(850, ticks.tickWorstMs);
	}

	@Test
	public void lastTickIsBeforeTheEndOfTheDisconnectSecond()
	{
		// Steady ticks come every 600 ms from 0: one lands at 120.0 s exactly, the first ms of second 120.
		final Evidence e = ofEvent(Trace.steady(200).usual(USUAL).disconnect(119), 119, 119, Trigger.DISCONNECT);
		assertTrue(e.disconnect);
		assertEquals(119, e.disconnectSec);
		assertEquals("the tick at 119.4 s; the one at 120.0 s is not before the end of second 119", 119,
			e.lastTickSec);

		final Evidence in = ofEvent(Trace.steady(200).usual(USUAL).disconnect(120), 120, 120, Trigger.DISCONNECT);
		assertEquals("the ticks at 120.0 and 120.6 s are inside the disconnect's second", 120, in.lastTickSec);

		final Evidence quiet = ofEvent(Trace.steady(200).usual(USUAL).noTicks(112, 120).disconnect(120), 113, 120,
			Trigger.NO_TICK, Trigger.DISCONNECT);
		assertEquals("the tick at 111.6 s", 111, quiet.lastTickSec);

		// The FIRST second with the flag, and the look is the D1_LOOK_S seconds that END at the last tick.
		final Trace bad = Trace.steady(200).usual(USUAL).noTicks(112, 125).rtt(100, 101, 300).rtt(102, 111, 60)
			.resent(101, 5000).rtt(112, 125, 900).resent(115, 5000).disconnect(120).disconnect(125);
		final Evidence b = ofEvent(bad, 113, 125, Trigger.NO_TICK, Trigger.DISCONNECT);
		assertEquals(120, b.disconnectSec);
		assertEquals(111, b.lastTickSec);
		assertEquals("seconds 102 to 111 alone", 60, b.beforeRtt);
		assertEquals(60, b.beforeRttMax);
		assertEquals(Evidence.NO, b.beforeRttSpike);
		assertEquals(0, b.beforeResentPm);

		// A masked tick still counts as the last tick.
		final Evidence masked = ofEvent(Trace.steady(200).usual(USUAL).hop(115, 302).disconnect(120), 120, 120,
			Trigger.DISCONNECT);
		assertEquals(120, masked.lastTickSec);

		// No tick at all before it.
		final Evidence never = ofEvent(Trace.steady(200).usual(USUAL).noTicks(0, 120).disconnect(120), 120, 120,
			Trigger.DISCONNECT);
		assertEquals(-1, never.lastTickSec);
		assertEquals(-1, never.beforeResentPm);
		assertEquals(Evidence.NO_DATA, never.beforeRttSpike);
	}

	@Test
