package com.whylag.core;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Number and clock text (contract 3.2).
 */
public class FmtTest
{
	private static final long T = Instant.parse("2026-09-28T21:47:30Z").toEpochMilli();

	/** The range row's note while the graphs are stretched (the first live look): seconds, then whole minutes. */
	@Test
	public void held()
	{
		assertEquals("0 s", Fmt.held(0));
		assertEquals("0 s", Fmt.held(-5));
		assertEquals("30 s", Fmt.held(30_999));
		assertEquals("59 s", Fmt.held(59_999));
		assertEquals("1 min", Fmt.held(60_000));
		assertEquals("4 min", Fmt.held(299_999));
		assertEquals("59 min", Fmt.held(3_599_999));
	}

	@Test
	public void thousands()
	{
		assertEquals("0", Fmt.thousands(0));
		assertEquals("999", Fmt.thousands(999));
		assertEquals("1,000", Fmt.thousands(1000));
		assertEquals("1,240", Fmt.thousands(1240));
		assertEquals("9,999", Fmt.thousands(9999));
		assertEquals("1,234,567", Fmt.thousands(1_234_567));
		assertEquals("-1,240", Fmt.thousands(-1240));
		assertEquals("-7", Fmt.thousands(-7));
		assertEquals("-2,147,483,648", Fmt.thousands(Integer.MIN_VALUE));
	}

	@Test
	public void tenths()
	{
		assertEquals("0.9", Fmt.tenths(900));
		assertEquals("1.8", Fmt.tenths(1840));
		assertEquals("2.4", Fmt.tenths(2400));
		assertEquals("0.0", Fmt.tenths(0));
		assertEquals("rounded to the nearest tenth", "1.9", Fmt.tenths(1850));
		assertEquals("1.8", Fmt.tenths(1849));
		assertEquals("10.0", Fmt.tenths(9999));
		assertEquals("-0.9", Fmt.tenths(-900));
		assertEquals("0.0", Fmt.tenths(-40));
	}

	@Test
	public void clock()
	{
		assertEquals("21:47", Fmt.clock(T, ZoneOffset.UTC));
		assertEquals("21:47:30", Fmt.clockSeconds(T, ZoneOffset.UTC));
		assertEquals("in the player's zone", "17:47", Fmt.clock(T, ZoneId.of("America/Toronto")));
		assertEquals("00:05:09", Fmt.clockSeconds(Instant.parse("2026-09-29T00:05:09Z").toEpochMilli(),
			ZoneOffset.UTC));
		assertEquals("a missing zone reads as UTC", "21:47", Fmt.clock(T, null));
	}

	@Test
	public void ago()
	{
		assertEquals("now", Fmt.ago(T, T));
		assertEquals("now", Fmt.ago(T, T + 999));
		assertEquals("a time in the future is now", "now", Fmt.ago(T + 5000, T));
		assertEquals("1 s ago", Fmt.ago(T, T + 1000));
		assertEquals("40 s ago", Fmt.ago(T, T + 40_000));
		assertEquals("59 s ago", Fmt.ago(T, T + 59_999));
		assertEquals("1 min ago", Fmt.ago(T, T + 60_000));
		assertEquals("4 min ago", Fmt.ago(T, T + 4 * 60_000 + 59_000));
	}

	@Test
	public void agoTurnsToHoursAtSixtyMinutes()
	{
		assertEquals("59 min ago", Fmt.ago(T, T + 59 * 60_000 + 59_999));
		assertEquals("1 h ago", Fmt.ago(T, T + 60 * 60_000));
		assertEquals("3 h ago", Fmt.ago(T, T + 3 * 3_600_000 + 59 * 60_000));
		assertEquals("25 h ago", Fmt.ago(T, T + 25 * 3_600_000L));
	}

	@Test
	public void lags()
	{
		assertEquals("0 lags", Fmt.lags(0));
		assertEquals("1 lag", Fmt.lags(1));
		assertEquals("4 lags", Fmt.lags(4));
		assertEquals("1,240 lags", Fmt.lags(1240));
	}

	@Test
	public void clamp()
	{
		assertEquals(5, Fmt.clamp(5, 0, 10));
		assertEquals(0, Fmt.clamp(-3, 0, 10));
		assertEquals(10, Fmt.clamp(11, 0, 10));
		assertEquals(-1, Fmt.clamp(-9, -1, 32767));
	}
}

package com.whylag.core;

import java.time.ZoneOffset;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link FrameSampler} (contract section 7, L2): what a second holds once the first frame past its boundary has
 * closed it. Times are session ms; the frame clock of a test runs on a 20 ms grid unless the test says otherwise.
 */
public class FrameSamplerTest
{
	private static final long START = 5_000_000_000_000L;
	private static final long NANOS_PER_MS = 1_000_000L;
	private static final int FRAME_MS = 20;

	private Session session;
	private SecondRing ring;
	private FrameSampler frames;

	@Before
	public void setUp()
	{
		session = new Session(START, 1_000_000L, Os.WINDOWS, ZoneOffset.UTC);
		ring = session.seconds;
		frames = new FrameSampler(session, new SelfTimer());
	}

	private static long at(long ms)
	{
		return START + ms * NANOS_PER_MS;
	}

	private void frame(long ms)
	{
		frames.frame(at(ms), (int) (ms / FRAME_MS));
	}

	/** Frames at {@code fromMs}, {@code fromMs + 20} ... up to and including {@code toMs}. */
	private void run(long fromMs, long toMs)
	{
		for (long t = fromMs; t <= toMs; t += FRAME_MS)
		{
			frame(t);
		}
	}

	private boolean has(long sec, int bit)
	{
		return Flags.has(ring.flags(sec), bit);
	}

	@Test
	public void fiftyFramesASecond()
	{
		frames.state(at(0), State.LOGGED_IN);
		frames.world(416);
		frames.scene(7, 9, 12850);
		run(0, 2980);
		assertEquals("no frame has passed second 2's boundary yet", 1, ring.frameHead());
		frame(3000);
		assertEquals(2, ring.frameHead());
		for (long sec = 0; sec <= 2; sec++)
		{
			assertEquals("frames of second " + sec, 50, ring.frames(sec));
			assertEquals(FRAME_MS, ring.worstFrameMs(sec));
			assertEquals(0, ring.slowFrames(sec));
			assertEquals(State.LOGGED_IN, ring.state(sec));
			assertEquals(Flags.FOCUSED, ring.flags(sec));
			assertEquals(416, ring.world(sec));
			assertEquals(7, ring.players(sec));
			assertEquals(9, ring.npcs(sec));
			assertEquals(12850, ring.region(sec));
			assertEquals(0, ring.loadingMs(sec));
		}
		assertEquals("of equal frames the later is the worst", 980, ring.worstFrameEndMs(1));
	}

	@Test
	public void aStallIsChargedToTheSecondItEndedIn()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 1500);
		run(3700, 5000);
		assertEquals(4, ring.frameHead());

		assertEquals("1000 .. 1500", 26, ring.frames(1));
		assertEquals("the stall is not charged to the second it began in", FRAME_MS, ring.worstFrameMs(1));
		assertFalse(has(1, Flags.NO_FRAMES));

		assertEquals(0, ring.frames(2));
		assertEquals(0, ring.worstFrameMs(2));
		assertTrue(has(2, Flags.NO_FRAMES));

		assertEquals("3700 .. 3980", 15, ring.frames(3));
		assertEquals(2200, ring.worstFrameMs(3));
		assertEquals(700, ring.worstFrameEndMs(3));
		assertEquals(1, ring.slowFrames(3));
		assertFalse(has(3, Flags.NO_FRAMES));

		assertEquals(FRAME_MS, ring.worstFrameMs(4));
	}

	@Test
	public void worstFrameEndIsItsOffsetInTheSecond()
	{
		run(0, 1240);
		frame(1340);
		run(1360, 1900);
		frame(1960);
		run(1980, 2000);
		assertEquals(100, ring.worstFrameMs(1));
		assertEquals("the 100 ms frame ended 340 ms into second 1", 340, ring.worstFrameEndMs(1));
		assertEquals("100 ms and 60 ms", 2, ring.slowFrames(1));

		// a frame that ends in the first ms of a second, and one that ends in its last
		setUp();
		run(0, 900);
		frame(1000);
		run(1020, 1900);
		frame(2999);
		frame(3000);
		assertEquals(100, ring.worstFrameMs(1));
		assertEquals(0, ring.worstFrameEndMs(1));
		assertEquals(1099, ring.worstFrameMs(2));
		assertEquals(999, ring.worstFrameEndMs(2));
	}

	@Test
	public void missedSecondsAreNoFrames()
	{
		frames.state(at(0), State.LOGGED_IN);
		frames.world(302);
		frame(500);
		frame(520);
		frame(4500);
		assertEquals(3, ring.frameHead());

		assertEquals(2, ring.frames(0));
		assertFalse(has(0, Flags.NO_FRAMES));
		for (long sec = 1; sec <= 3; sec++)
		{
			assertEquals(0, ring.frames(sec));
			assertEquals(0, ring.worstFrameMs(sec));
			assertEquals(0, ring.worstFrameEndMs(sec));
			assertEquals(0, ring.slowFrames(sec));
			assertEquals("a filled second keeps the code in force", State.LOGGED_IN, ring.state(sec));
			assertEquals(302, ring.world(sec));
			assertEquals(Flags.NO_FRAMES | Flags.FOCUSED, ring.flags(sec));
		}
		frame(5000);
		assertEquals(3980, ring.worstFrameMs(4));
		assertEquals(500, ring.worstFrameEndMs(4));
		assertFalse(has(4, Flags.NO_FRAMES));
	}

	@Test
	public void aDayAwayIsFilledInOneGo()
	{
		final long day = 86_400;
		frames.state(at(0), State.LOGGED_IN);
		run(0, 500);
		final long before = System.nanoTime();
		frame((day + 1) * 1000 + 500);
		final long tookMs = (System.nanoTime() - before) / NANOS_PER_MS;
		assertEquals("seconds 0 .. 86,400 are written by the one frame", day, ring.frameHead());
		assertTrue("filling a day took " + tookMs + " ms", tookMs < 2000);

		// the host half, so that the ring's newest seconds are readable
		final HostSecond h = new HostSecond();
		for (long sec = 0; sec <= day; sec++)
		{
			ring.putHost(sec, h);
		}
		final long tail = ring.tail();
		assertEquals(day - Thresholds.SECONDS + 1, tail);
		for (long sec = tail; sec <= day; sec++)
		{
			assertTrue(ring.valid(sec));
			assertTrue("second " + sec, has(sec, Flags.NO_FRAMES));
			assertEquals(0, ring.frames(sec));
			assertEquals(State.LOGGED_IN, ring.state(sec));
		}
		frame((day + 2) * 1000);
		assertEquals("the day is charged to the second it ended in, clamped to the column", Short.MAX_VALUE,
			ring.worstFrameMs(day + 1));
		assertEquals(500, ring.worstFrameEndMs(day + 1));
		assertEquals(1, ring.frames(day + 1));
	}

	@Test
	public void loadingMsIsSummed()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 2100);
		frames.state(at(2110), State.LOADING);
		run(2120, 2220);
		frames.state(at(2230), State.LOGGED_IN);
		run(2240, 2600);
		frames.state(at(2610), State.LOADING);
		run(2620, 2680);
		frames.state(at(2690), State.LOGGED_IN);
		run(2700, 4000);

		assertEquals(0, ring.loadingMs(1));
		assertFalse(has(1, Flags.LOADING));
		assertEquals("120 ms and 80 ms", 200, ring.loadingMs(2));
		assertTrue(has(2, Flags.LOADING));
		assertEquals(State.LOGGED_IN, ring.state(2));
		assertEquals(0, ring.loadingMs(3));
		assertFalse("every loading frame ended in second 2", has(3, Flags.LOADING));
	}

	@Test
	public void teleportFrameAfterLoadIsMasked()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 2700);
		frames.state(at(2705), State.LOADING);
		frame(2720);
		frames.state(at(2900), State.LOGGED_IN);
		frame(3170);
		run(3190, 5000);

		assertEquals(195, ring.loadingMs(2));
		assertTrue(has(2, Flags.LOADING));

		assertEquals(450, ring.worstFrameMs(3));
		assertEquals(170, ring.worstFrameEndMs(3));
		assertEquals("second 3 holds no LOADING time", 0, ring.loadingMs(3));
		assertEquals(State.LOGGED_IN, ring.state(3));
		assertTrue("the frame that began under LOADING ended here", has(3, Flags.LOADING));

		assertFalse("the frames after it are ordinary", has(4, Flags.LOADING));
	}

	@Test
	public void aLoadBetweenTwoFramesMarksTheFrameThatHeldIt()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 1900);
		// entered and left between two frames, in second 1; the frame that held it ends in second 2
		frames.state(at(1910), State.LOADING);
		frames.state(at(1990), State.LOGGED_IN);
		frame(2300);
		run(2320, 4000);
		assertEquals(80, ring.loadingMs(1));
		assertTrue(has(1, Flags.LOADING));
		assertEquals(0, ring.loadingMs(2));
		assertTrue(has(2, Flags.LOADING));
		assertFalse(has(3, Flags.LOADING));
	}

	@Test
	public void aSecondKeepsTheStateInForceAtItsEnd()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 2680);
		frames.state(at(2700), State.LOGIN_SCREEN);
		run(2700, 2980);
		frames.focus(false);
		frame(3000);
		frames.state(at(3001), State.LOGGING_IN);
		run(3020, 3980);
		frames.focus(true);
		run(4000, 5000);

		assertEquals(State.LOGGED_IN, ring.state(1));
		assertFalse(has(1, Flags.NOT_LOGGED_IN));
		assertTrue(has(1, Flags.FOCUSED));

		assertEquals("handed in 300 ms before the end", State.LOGIN_SCREEN, ring.state(2));
		assertTrue(has(2, Flags.NOT_LOGGED_IN));
		assertFalse("the focus at the close", has(2, Flags.FOCUSED));

		assertEquals("handed in just after second 2's end", State.LOGGING_IN, ring.state(3));
		assertTrue(has(3, Flags.NOT_LOGGED_IN));
		assertTrue(has(3, Flags.FOCUSED));
	}

	@Test
	public void aStateHandedInBeforeTheClosingFrameKeepsItsTime()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 5500);
		// no frame between these three calls: the frame at 8020 closes seconds 5, 6 and 7
		frames.state(at(5700), State.LOGIN_SCREEN);
		frames.state(at(6001), State.LOGGING_IN);
		frames.state(at(7999), State.LOADING);
		assertEquals("a state call closes no second: the frame head says where the frames are", 4,
			ring.frameHead());
		run(8020, 9000);

		assertEquals(State.LOGIN_SCREEN, ring.state(5));
		assertTrue(has(5, Flags.NOT_LOGGED_IN));
		assertEquals(State.LOGGING_IN, ring.state(6));
		assertTrue(has(6, Flags.NOT_LOGGED_IN));
		assertEquals(State.LOADING, ring.state(7));
		assertFalse(has(7, Flags.NOT_LOGGED_IN));
		assertTrue(has(7, Flags.LOADING));
		assertEquals(1, ring.loadingMs(7));
		assertEquals(1000, ring.loadingMs(8));
	}

	@Test
	public void hopAndLostConnectionFlagEachOfTheirSeconds()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 1980);
		frames.state(at(2000), State.HOPPING);
		run(2000, 4980);
		frames.state(at(5000), State.LOGGED_IN);
		run(5000, 7980);
		frames.state(at(8000), State.CONNECTION_LOST);
		run(8000, 10980);
		frames.state(at(11000), State.LOGGED_IN);
		run(11000, 13480);
		frames.state(at(13500), State.LOADING);
		frames.state(at(16100), State.LOGGED_IN);
		run(16200, 18000);

		assertFalse(has(1, Flags.HOP));
		for (long sec = 2; sec <= 4; sec++)
		{
			assertTrue("hop second " + sec, has(sec, Flags.HOP));
			assertEquals(State.HOPPING, ring.state(sec));
			assertFalse(has(sec, Flags.NOT_LOGGED_IN));
			assertFalse(has(sec, Flags.DISCONNECT));
		}
		assertFalse("the hop ended with second 4", has(5, Flags.HOP));
		assertEquals(State.LOGGED_IN, ring.state(5));

		assertFalse(has(7, Flags.DISCONNECT));
		for (long sec = 8; sec <= 10; sec++)
		{
			assertTrue("lost second " + sec, has(sec, Flags.DISCONNECT));
			assertEquals(State.CONNECTION_LOST, ring.state(sec));
			assertFalse(has(sec, Flags.NOT_LOGGED_IN));
			assertFalse(has(sec, Flags.HOP));
		}
		assertFalse(has(11, Flags.DISCONNECT));

		assertEquals(500, ring.loadingMs(13));
		assertTrue(has(13, Flags.LOADING));
		for (long sec = 14; sec <= 15; sec++)
		{
			assertTrue("a filled second", has(sec, Flags.NO_FRAMES));
			assertEquals(1000, ring.loadingMs(sec));
			assertTrue(has(sec, Flags.LOADING));
			assertEquals(State.LOADING, ring.state(sec));
		}
		assertEquals(100, ring.loadingMs(16));
		assertTrue(has(16, Flags.LOADING));
		assertEquals(State.LOGGED_IN, ring.state(16));
		assertFalse(has(17, Flags.LOADING));
	}

	@Test
	public void theFirstFrameClosesNoInterval()
	{
		frames.state(at(0), State.LOGGED_IN);
		assertEquals(0, frames.openFrameMs(at(4000)));
		assertEquals(0, frames.worstFrameSinceTickMs());
		frame(5300);
		assertEquals("the first frame is not measured from the session's start", 0, frames.worstFrameSinceTickMs());
		assertEquals(4, ring.frameHead());
		for (long sec = 0; sec <= 4; sec++)
		{
			assertTrue("second " + sec, has(sec, Flags.NO_FRAMES));
			assertEquals(0, ring.frames(sec));
		}
		assertEquals(250, frames.openFrameMs(at(5550)));
		frame(6100);
		frame(7000);

		assertEquals("the first frame counts", 1, ring.frames(5));
		assertEquals("and closes no interval", 0, ring.worstFrameMs(5));
		assertEquals(0, ring.worstFrameEndMs(5));
		assertEquals(0, ring.slowFrames(5));
		assertFalse(has(5, Flags.NO_FRAMES));

		assertEquals(800, ring.worstFrameMs(6));
		assertEquals(100, ring.worstFrameEndMs(6));
		assertEquals(1, ring.slowFrames(6));
	}

	@Test
	public void theWorstFrameSinceTheTickStartsAgainAtAReset()
	{
		run(0, 400);
		frame(480);
		run(500, 600);
		assertEquals(80, frames.worstFrameSinceTickMs());
		frames.resetWorstSinceTick();
		assertEquals(0, frames.worstFrameSinceTickMs());
		run(620, 700);
		assertEquals(FRAME_MS, frames.worstFrameSinceTickMs());
		assertEquals(35, frames.openFrameMs(at(735)));
	}

	@Test
	public void loadingSinceTickSeesALoadThatCameAndWent()
	{
		frames.state(at(0), State.LOGGED_IN);
		assertFalse(frames.loadingSinceTick());
		frames.state(at(100), State.LOADING);
		assertTrue(frames.loadingSinceTick());
		frames.resetWorstSinceTick();
		assertTrue("still loading", frames.loadingSinceTick());
		frames.state(at(300), State.LOGGED_IN);
		assertTrue("the load ended inside this tick's gap", frames.loadingSinceTick());
		frames.resetWorstSinceTick();
		assertFalse(frames.loadingSinceTick());
	}

	@Test
	public void moreStateChangesThanTheSamplerKeepsAreSafe()
	{
		frames.state(at(0), State.LOGGED_IN);
		run(0, 900);
		for (int i = 0; i < 300; i++)
		{
			frames.state(at(1000 + i * 10), i % 2 == 0 ? State.LOADING : State.LOGGED_IN);
		}
		frames.state(at(4500), State.HOPPING);
		run(5020, 7000);
		assertEquals(6, ring.frameHead());
		assertEquals("the newest code is never lost", State.HOPPING, ring.state(5));
		assertTrue(has(5, Flags.HOP));
		assertTrue(has(1, Flags.LOADING));
		assertEquals(State.HOPPING, ring.state(6));
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.function.Consumer;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * The detector's properties over random traces, seeds 1 .. 50 (contract 7, L3): events never overlap, come in order
 * and are numbered 0, 1, 2 ...; reading in one step, second by second or in random steps gives the same events; a
 * fully masked trace and a steady one have none; shifting a trace shifts its events; and a ring that lost its
 * oldest seconds still finds every later event, the same in every field but the id.
 *
 * <p>A random trace is a {@link Recipe}: incidents (freezes, pauses, late and missing ticks, slow worlds, ping
 * changes, re-sends, loads, hops, lost connections, focus, frame rates, CPU and scene columns, storms of frame gaps
 * that outlast {@link Thresholds#EVENT_MAX_S}) laid on a steady trace, kept as steps so the same incidents can be
 * laid on a trace of another length. A step that {@link Trace} refuses changes nothing and is skipped.
 *
 * <p>Choice: wrapLosesOnlyTheOldest lays one recipe on SECONDS s and on m s more, and compares events from m + 60.
 * <p>Choice: a trace is fully masked one of four ways: the login screen, one endless load, FPS Control unfocused, hops.
 * <p>Choice: in shiftingTheTraceShiftsTheEvents no tick gap is under TICK_MS, so the ring holds every tick (bound c).
 * <p>Choice: traces run 60 to 3,600 s (3,600 + m when wrapped), with random settings, OS and steps of advance.
 */
public class LagDetectorPropertyTest
{
	private static final int SEEDS = 50;
	/** The steady seconds that the wrap property keeps free of incidents where the wrapped ring begins. */
	private static final int CALM_S = 60;
	/** Where the wrap property's incidents end. */
	private static final int WRAP_INCIDENTS_END = 3400;

	@Test
	public void eventsNeverOverlapAndAreOrdered()
	{
		// What the seeds reached, so a generator that stopped making some kind of event fails here.
		final int[] withTrigger = new int[Trigger.values().length];
		int conditions = 0;
		int merged = 0;
		for (long seed = 1; seed <= SEEDS; seed++)
		{
			final Random r = new Random(seed);
			final int n = 300 + r.nextInt(3300);
			final Trace t = anything(r, n).on(n);
			final SettingsView v = randomSettings(r);
			final Session s = t.build();
			final LagDetector d = new LagDetector();
			final LagDetectorTest.Recorder out = new LagDetectorTest.Recorder();
			advanceInSteps(r, d, s, n, v, out);
			checkOrder("seed " + seed, s, d, out, n);
			for (LagEvent e : out.closed)
			{
				for (Trigger trigger : Trigger.values())
				{
					withTrigger[trigger.ordinal()] += e.has(trigger) ? 1 : 0;
				}
				conditions += e.becameCondition ? 1 : 0;
				merged += e.lengthS() > 1 ? 1 : 0;
			}
		}
		for (Trigger trigger : Trigger.values())
		{
			assertTrue("the seeds reach an event with " + trigger, withTrigger[trigger.ordinal()] > 0);
		}
		assertTrue("the seeds reach an event that became a condition", conditions > 0);
		assertTrue("the seeds reach an event of several seconds", merged > 0);
	}

	@Test
	public void advanceInOneStepEqualsAdvanceSecondBySecond()
	{
		for (long seed = 1; seed <= SEEDS; seed++)
		{
			final Random r = new Random(seed);
			final int n = 200 + r.nextInt(2400);
			final Trace t = anything(r, n).on(n);
			final SettingsView v = randomSettings(r);

			final Session oneS = t.build();
			final LagDetector one = new LagDetector();
			final LagDetectorTest.Recorder oneOut = new LagDetectorTest.Recorder();
			one.advance(oneS, n - 1, v, oneOut);

			final Session bySecondS = t.build();
			final LagDetector bySecond = new LagDetector();
			final LagDetectorTest.Recorder bySecondOut = new LagDetectorTest.Recorder();
			for (long k = 0; k < n; k++)
			{
				bySecond.advance(bySecondS, k, v, bySecondOut);
			}

			final Session stepsS = t.build();
			final LagDetector steps = new LagDetector();
			final LagDetectorTest.Recorder stepsOut = new LagDetectorTest.Recorder();
			advanceInSteps(r, steps, stepsS, n, v, stepsOut);

			final String at = "seed " + seed;
			assertFalse(at + ": a trace with incidents has events", oneOut.opened.isEmpty());
			assertEquals(at + ": one step against second by second", oneOut.log, bySecondOut.log);
			assertEquals(at + ": one step against random steps", oneOut.log, stepsOut.log);
			final String openOne = LagDetectorTest.describe(one.open(), 0, true);
			assertEquals(at, openOne, LagDetectorTest.describe(bySecond.open(), 0, true));
			assertEquals(at, openOne, LagDetectorTest.describe(steps.open(), 0, true));
			for (long sec = 0; sec < n; sec++)
			{
				assertEquals(at + ": triggers @" + sec, one.triggers(sec), bySecond.triggers(sec));
				assertEquals(at + ": triggers @" + sec, one.triggers(sec), steps.triggers(sec));
			}
			assertSameUsuals(at, oneS, bySecondS);
			assertSameUsuals(at, oneS, stepsS);
		}
	}

	@Test
	public void fullyMaskedTraceHasNoEvents()
	{
		for (long seed = 1; seed <= SEEDS; seed++)
		{
			final Random r = new Random(seed);
			final int n = 60 + r.nextInt(2000);
			final int how = (int) (seed % 4);
			final Space space = new Space(0, how == 0 ? n - 1 : n);
			space.disconnects = false;
			space.loads = false;
			space.tickMoves = how != 3;
			final Recipe recipe = incidents(r, space, n / 20);
			SettingsView v = Trace.steady(1).settings();
			switch (how)
			{
				case 0:
					// The login screen, and a load in the last second, which has not ended.
					recipe.add(t -> t.loginAt(n - 1));
					recipe.add(t -> t.loading(n - 1, 100));
					break;
				case 1:
					// One load from the first second to the last, which has not ended.
					for (int sec = 0; sec < n; sec++)
					{
						final int s = sec;
						final int ms = 1 + r.nextInt(1000);
						recipe.add(t -> t.loading(s, ms));
					}
					break;
				case 2:
					// Unfocused throughout, under FPS Control's unfocused limit.
					v = new SettingsView(Renderer.CPU, true, r.nextBoolean(), 30, true, 1 + r.nextInt(50), false, "", 0,
						0, "", 0, 60, Os.WINDOWS, "");
					recipe.add(t -> t.unfocused(0, n - 1));
					break;
				default:
					// A hop every 5 s: each masks its own second and the nine after it.
					for (int sec = 0; sec < n; sec += 5)
					{
						final int s = sec;
						recipe.add(t -> t.hop(s, 300 + s % 7));
					}
					break;
			}
			final Session s = recipe.on(n).build();
			for (long sec = 0; sec < n; sec++)
			{
				if (!Masks.masked(s.seconds, sec, v))
				{
					fail("seed " + seed + ", way " + how + ": the generator left second " + sec + " unmasked");
				}
			}
			// A recipe may hold Trace.usual, which build() puts in rttUsual before the detector reads anything.
			final int given = s.rttUsual.count();
			final LagDetector d = new LagDetector();
			final LagDetectorTest.Recorder out = new LagDetectorTest.Recorder();
			advanceInSteps(r, d, s, n, v, out);
			final String at = "seed " + seed + ", way " + how;
			assertTrue(at + ": " + out.log, out.opened.isEmpty());
			assertNull(at, d.open());
			for (long sec = 0; sec < n; sec++)
			{
				assertTrue(at + ": quiet @" + sec, d.quiet(sec));
			}
			// rttSession is never reset and build() puts nothing in it: it counts every RTT the detector fed.
			assertEquals(at + ": a masked second feeds no usual", 0, s.rttSession.count());
			assertEquals(at, 0, s.fpsUsual.count());
			assertTrue(at + ": rttUsual as built, or emptied by a world change",
				s.rttUsual.count() == given || s.rttUsual.count() == 0);
		}
	}

	@Test
	public void steadyTraceHasNoEvents()
	{
		final Os[] systems = Os.values();
		for (long seed = 1; seed <= SEEDS; seed++)
		{
			final Random r = new Random(seed);
			final int n = 1 + r.nextInt(Thresholds.SECONDS);
			final Trace t = Trace.steady(n).os(systems[r.nextInt(systems.length)]);
			final boolean usual = r.nextBoolean();
			if (usual)
			{
				t.usual(40);
			}
			final SettingsView v = randomSettings(r);
			final Session s = t.build();
			final LagDetector d = new LagDetector();
			final LagDetectorTest.Recorder out = new LagDetectorTest.Recorder();
			advanceInSteps(r, d, s, n, v, out);
			final String at = "seed " + seed + " (" + n + " s)";
			assertTrue(at + ": " + out.log, out.opened.isEmpty());
			assertNull(at, d.open());
			for (long sec = 0; sec < n; sec++)
			{
				assertTrue(at + ": quiet @" + sec, d.quiet(sec));
			}
			assertEquals(at + ": every steady second feeds", n, s.fpsUsual.count());
			assertEquals(at, n, s.rttSession.count());
			assertEquals(at, usual || n >= Thresholds.USUAL_MIN_SAMPLES ? 40 : -1, s.rttUsual.median());
		}
	}

	@Test
	public void shiftingTheTraceShiftsTheEvents()
	{
		for (long seed = 1; seed <= SEEDS; seed++)
		{
			final Random r = new Random(seed);
			final int n = 200 + r.nextInt(2400);
			final int k = 1 + r.nextInt(Thresholds.SECONDS - n);
			// Bound (a): the first USUAL_MIN_SAMPLES seconds untouched, or the login screen before a login.
			final boolean login = r.nextBoolean();
			final int lo = login ? 1 + r.nextInt(100) : Thresholds.USUAL_MIN_SAMPLES;
			final Space space = new Space(lo, n);
			// Bound (b): every fresh RTT is the steady 40.
			space.pingFortyOnly = true;
			// No tick is added (the ring holds every tick of a shifted trace of at most SECONDS seconds, bound (c)).
			space.fewTicksOnly = true;
			final Recipe recipe = new Recipe();
			if (login)
			{
				recipe.add(t -> t.loginAt(lo));
			}
			recipe.addAll(incidents(r, space, n / 20));
			final Trace t = recipe.on(n);
			final SettingsView v = randomSettings(r);

			final Session plain = t.build();
			final LagDetector before = new LagDetector();
			final LagDetectorTest.Recorder beforeOut = new LagDetectorTest.Recorder();
			before.advance(plain, n - 1, v, beforeOut);

			t.shift(k);
			final Session shifted = t.build();
			final LagDetector after = new LagDetector();
			final LagDetectorTest.Recorder afterOut = new LagDetectorTest.Recorder();
			after.advance(shifted, n + k - 1, v, afterOut);

			final String at = "seed " + seed + " (shift " + k + ")";
			assertFalse(at + ": a trace with incidents has events", beforeOut.opened.isEmpty());
			assertEquals(at, texts(beforeOut.opened, 0, true), texts(afterOut.opened, k, true));
			assertEquals(at, texts(beforeOut.closed, 0, true), texts(afterOut.closed, k, true));
			assertEquals(at, LagDetectorTest.describe(before.open(), 0, true),
				LagDetectorTest.describe(after.open(), k, true));
		}
	}

	@Test
	public void wrapLosesOnlyTheOldest()
	{
		for (long seed = 1; seed <= SEEDS; seed++)
		{
			final Random r = new Random(seed);
			// The wrapped trace is m seconds longer than the ring, so its ring begins at second m: the incidents
			// before m are lost to it. The first CALM_S seconds from m hold no incident.
			final int m = 200 + r.nextInt(1800);
			final Space space = new Space(0, WRAP_INCIDENTS_END);
			space.holeLo = m;
			space.holeHi = m + CALM_S;
			space.pingFortyOnly = true;
			space.fewTicksOnly = true;
			final Recipe recipe = incidents(r, space, WRAP_INCIDENTS_END / 20);
			// One freeze that only the whole trace sees, and one that both see.
			recipe.add(t -> t.frameGap(m / 2, 500, 400));
			recipe.add(t -> t.frameGap(m + CALM_S + 40, 500, 400));
			final SettingsView v = randomSettings(r);

			final Session whole = recipe.on(Thresholds.SECONDS).build();
			final LagDetector all = new LagDetector();
			final LagDetectorTest.Recorder allOut = new LagDetectorTest.Recorder();
			all.advance(whole, Thresholds.SECONDS - 1, v, allOut);

			final Session wrapped = recipe.on(Thresholds.SECONDS + m).build();
			assertEquals("seed " + seed + ": the premise", m, wrapped.seconds.tail());
			final LagDetector late = new LagDetector();
			final LagDetectorTest.Recorder lateOut = new LagDetectorTest.Recorder();
			late.advance(wrapped, Thresholds.SECONDS + m - 1, v, lateOut);

			final String at = "seed " + seed + " (the ring begins at " + m + ")";
			final List<LagEvent> seenByAll = from(allOut.closed, m + CALM_S);
			final List<LagEvent> seenLate = from(lateOut.closed, m + CALM_S);
			assertFalse(at + ": events after the calm", seenLate.isEmpty());
			assertEquals(at, texts(seenByAll, 0, false), texts(seenLate, 0, false));
			assertTrue(at + ": the whole trace has an event the wrapped ring lost",
				allOut.closed.get(0).startSec < m);
			final long offset = seenByAll.get(0).id - seenLate.get(0).id;
			assertTrue(at + ": the late detector numbers from 0, so its ids are lower", offset >= 1);
			for (int i = 0; i < seenLate.size(); i++)
			{
				assertEquals(at + ": ids move by one offset", offset, seenByAll.get(i).id - seenLate.get(i).id);
			}
			for (int i = 0; i < lateOut.opened.size(); i++)
			{
				assertEquals(at + ": the late detector counts from 0", i, lateOut.opened.get(i).id);
			}
			assertNull(at, all.open());
			assertNull(at, late.open());
		}
	}

	// ---------------------------------------------------------------- checks

	/** Events in order, never overlapping, numbered 0, 1, 2 ..., each closed by the rules of contract 6.2. */
	private static void checkOrder(String at, Session s, LagDetector d, LagDetectorTest.Recorder out, int n)
	{
		final int opened = out.opened.size();
		final int closed = out.closed.size();
		assertTrue(at + ": opened " + opened + ", closed " + closed, closed == opened || closed == opened - 1);
		assertEquals(at + ": one open event at most", closed == opened - 1, d.open() != null);
		for (int i = 0; i < out.log.size(); i++)
		{
			final String turn = i % 2 == 0 ? "opened" : "closed";
			assertTrue(at + ": opened and closed take turns", out.log.get(i).startsWith(turn));
		}
		for (int i = 0; i < opened; i++)
		{
			final LagEvent o = out.opened.get(i);
			assertEquals(at + ": ids count up from 0", i, o.id);
			assertTrue(at, o.open);
			assertEquals(at, o.startSec, o.endSec);
			assertEquals(at, s.wallMsOf(o.startSec), o.startWallMs);
		}
		for (int i = 0; i < closed; i++)
		{
			final LagEvent e = out.closed.get(i);
			final String which = at + ", event " + i + " (" + e.startSec + " .. " + e.endSec + ")";
			assertEquals(which + ": the id opened handed", out.opened.get(i).id, e.id);
			assertEquals(which, out.opened.get(i).startSec, e.startSec);
			assertFalse(which, e.open);
			assertTrue(which, e.startSec <= e.endSec);
			assertTrue(which + ": at most EVENT_MAX_S", e.lengthS() <= Thresholds.EVENT_MAX_S);
			assertEquals(which, s.wallMsOf(e.startSec), e.startWallMs);
			assertTrue(which + ": it opens on an opening trigger",
				e.first != Trigger.RTT_SPIKE || Thresholds.RTT_SPIKE_OPENS);
			assertTrue(which + ": its first trigger fired in its first second",
				(d.triggers(e.startSec) & e.first.bit()) != 0);
			assertFalse(which + ": it ends on a trigger second", d.quiet(e.endSec));
			int bits = 0;
			int quietRun = 0;
			for (long sec = e.startSec; sec <= e.endSec; sec++)
			{
				bits |= d.triggers(sec);
				quietRun = d.quiet(sec) ? quietRun + 1 : 0;
				assertTrue(which + ": no EVENT_QUIET_S quiet seconds inside it", quietRun < Thresholds.EVENT_QUIET_S);
			}
			assertEquals(which + ": its triggers are its seconds'", bits, e.triggers);
			if (e.becameCondition)
			{
				// Closed by the trigger second that would carry it past EVENT_MAX_S.
				final long crossing = e.startSec + Thresholds.EVENT_MAX_S;
				boolean found = false;
				for (long sec = e.endSec + 1; sec <= e.endSec + Thresholds.EVENT_QUIET_S && sec < n; sec++)
				{
					if (!d.quiet(sec))
					{
						assertTrue(which + ": the first trigger after it crosses EVENT_MAX_S", sec >= crossing);
						found = true;
						break;
					}
				}
				assertTrue(which + ": a condition is closed by a trigger", found);
			}
			else
			{
				for (long sec = e.endSec + 1; sec <= e.endSec + Thresholds.EVENT_QUIET_S; sec++)
				{
					assertTrue(which + ": closed by quiet seconds @" + sec, d.quiet(sec));
				}
			}
			final LagEvent next = i + 1 < opened ? out.opened.get(i + 1) : null;
			if (next == null)
			{
				continue;
			}
			assertTrue(which + ": the next starts after it", next.startSec > e.endSec);
			if (!e.becameCondition || next.first != Trigger.DISCONNECT)
			{
				assertTrue(which + ": EVENT_QUIET_S quiet seconds come before the next",
					longestQuietRun(d, e.endSec + 1, next.startSec - 1) >= Thresholds.EVENT_QUIET_S);
			}
		}
	}

	private static int longestQuietRun(LagDetector d, long from, long to)
	{
		int best = 0;
		int run = 0;
		for (long sec = from; sec <= to; sec++)
		{
			run = d.quiet(sec) ? run + 1 : 0;
			best = Math.max(best, run);
		}
		return best;
	}

	private static void assertSameUsuals(String at, Session a, Session b)
	{
		assertEquals(at, a.rttUsual.count(), b.rttUsual.count());
		assertEquals(at, a.rttUsual.median(), b.rttUsual.median());
		assertEquals(at, a.rttSession.count(), b.rttSession.count());
		assertEquals(at, a.rttSession.median(), b.rttSession.median());
		assertEquals(at, a.fpsUsual.count(), b.fpsUsual.count());
		assertEquals(at, a.fpsUsual.median(), b.fpsUsual.median());
	}

	private static List<String> texts(List<LagEvent> events, long shiftSec, boolean withId)
	{
		final List<String> out = new ArrayList<>();
		for (LagEvent e : events)
		{
			out.add(LagDetectorTest.describe(e, shiftSec, withId));
		}
		return out;
	}

	private static List<LagEvent> from(List<LagEvent> events, long startSec)
	{
		final List<LagEvent> out = new ArrayList<>();
		for (LagEvent e : events)
		{
			if (e.startSec >= startSec)
			{
				out.add(e);
			}
		}
		return out;
	}

	/** Reads seconds 0 .. n - 1 in random steps of 1 to 300 seconds. */
	private static void advanceInSteps(Random r, LagDetector d, Session s, int n, SettingsView v, DetectorListener out)
	{
		long k = -1;
		while (k < n - 1)
		{
			k = Math.min(n - 1, k + 1 + r.nextInt(300));
			d.advance(s, k, v, out);
		}
	}

	// ---------------------------------------------------------------- random traces

	/** Incidents anywhere in a trace of {@code n} seconds, of every kind, any ping, sometimes a usual and an OS. */
	private static Recipe anything(Random r, int n)
	{
		final Recipe recipe = new Recipe();
		final Os[] systems = Os.values();
		final Os os = systems[r.nextInt(systems.length)];
		recipe.add(t -> t.os(os));
		recipe.addAll(incidents(r, new Space(0, n), n / 15));
		return recipe;
	}

	/** About {@code count} random incidents in {@code space}. */
	private static Recipe incidents(Random r, Space space, int count)
	{
		final Recipe recipe = new Recipe();
		for (int i = 0; i < count + r.nextInt(10); i++)
		{
			incident(r, recipe, space);
		}
		return recipe;
	}

	private static void incident(Random r, Recipe recipe, Space sp)
	{
		final int at = sp.pick(r);
		final int top = sp.lastOfASpanFrom(at);
		final int to = Math.min(top, at + r.nextInt(12));
		switch (r.nextInt(21))
		{
			case 0:
			case 1:
			case 2:
			{
				final int end = r.nextInt(1000);
				final int ms = Math.min(20 + r.nextInt(1600), sp.longestFrameEndingIn(at, end));
				recipe.add(t -> t.frameGap(at, end, ms));
				break;
			}
			case 3:
			case 4:
				// The two memory incidents of the first build (a known pause, an inferred collection) are gone: the
				// plugin reads no memory any more (1.0.0, the Hub's rule). The draws keep their places.
				break;
			case 5:
				if (sp.tickMoves)
				{
					final int late = 30 + r.nextInt(900);
					final boolean catchUp = r.nextBoolean();
					recipe.add(t -> t.tickLate(at, late, catchUp));
				}
				break;
			case 6:
				if (sp.tickMoves)
				{
					// A slow world; with fewTicksOnly never faster than one tick in TICK_MS, so no tick is added.
					final int spanTo = Math.min(top, at + 2 + r.nextInt(40));
					final int gap = (sp.fewTicksOnly ? Thresholds.TICK_MS + 10 : 350) + r.nextInt(900);
					recipe.add(t -> t.ticksEvery(at, spanTo, gap));
				}
				break;
			case 7:
				if (sp.tickMoves)
				{
					final int holeTo = Math.min(top, at + r.nextInt(3));
					recipe.add(t -> t.noTicks(at, holeTo));
				}
				break;
			case 8:
			case 9:
				ping(r, recipe, sp, at, to);
				break;
			case 10:
			{
				final int units = r.nextInt(3000);
				recipe.add(t -> t.resent(at, units));
				break;
			}
			case 11:
			{
				final int units = r.nextInt(3000);
				recipe.add(t -> t.sent(at, to, units));
				break;
			}
			case 12:
				if (sp.loads)
				{
					final int runTo = Math.min(top, at + r.nextInt(4));
					for (int sec = at; sec <= runTo; sec++)
					{
						final int s = sec;
						final int ms = 100 + r.nextInt(901);
						recipe.add(t -> t.loading(s, ms));
					}
				}
				break;
			case 13:
			{
				final int world = 300 + r.nextInt(260);
				recipe.add(t -> t.hop(at, world));
				break;
			}
			case 14:
				if (sp.disconnects)
				{
					recipe.add(t -> t.disconnect(at));
				}
				break;
			case 15:
			{
				final int focusTo = Math.min(top, at + r.nextInt(60));
				recipe.add(t -> t.unfocused(at, focusTo));
				break;
			}
			case 16:
			{
				final int fps = r.nextInt(61);
				recipe.add(t -> t.fps(at, to, fps));
				break;
			}
			case 17:
			{
				final int players = r.nextInt(300);
				final int npcs = r.nextInt(300);
				final int region = r.nextInt(65536);
				recipe.add(t -> t.players(at, to, players).npcs(at, to, npcs).region(at, to, region));
				break;
			}
			case 18:
			{
				// A storm: a frame gap every second, often for longer than EVENT_MAX_S.
				final int stormTo = Math.min(top, at + 60 + r.nextInt(160));
				for (int sec = at; sec <= stormTo; sec++)
				{
					final int s = sec;
					final int ms = Math.min(250 + r.nextInt(300), sp.longestFrameEndingIn(s, 500));
					recipe.add(t -> t.frameGap(s, 500, ms));
				}
				break;
			}
			case 19:
				if (!sp.pingFortyOnly)
				{
					// A spike, sometimes with a click in the same second.
					final int rtt = 100 + r.nextInt(500);
					recipe.add(t -> t.rtt(at, at, rtt));
					if (r.nextBoolean())
					{
						final int sent = 900 + r.nextInt(1500);
						recipe.add(t -> t.sent(at, at, sent));
					}
				}
				break;
			default:
				if (sp.disconnects)
				{
					// A lost connection inside a lag.
					final int end = r.nextInt(1000);
					final int ms = Math.min(300 + r.nextInt(900), sp.longestFrameEndingIn(at, end));
					recipe.add(t -> t.frameGap(at, end, ms));
					recipe.add(t -> t.disconnect(to));
				}
				break;
		}
	}

	private static void ping(Random r, Recipe recipe, Space sp, int at, int to)
	{
		final int kind = r.nextInt(sp.pingFortyOnly ? 3 : 4);
		if (kind == 0)
		{
			final int ms = sp.pingFortyOnly ? 40 : 10 + r.nextInt(600);
			recipe.add(t -> t.rtt(at, to, ms));
		}
		else if (kind == 1)
		{
			final NoData[] reasons = {NoData.NOT_CONNECTED, NoData.UNSUPPORTED, NoData.ERROR};
			final NoData why = reasons[r.nextInt(reasons.length)];
			recipe.add(t -> t.rttNoData(at, to, why));
		}
		else if (kind == 2)
		{
			recipe.add(t -> t.rttStale(at, to));
		}
		else
		{
			final int usual = 20 + r.nextInt(100);
			recipe.add(t -> t.usual(usual));
		}
	}

	/** Random settings: the defaults, a GPU target, 117 HD with V-Sync, FPS Control, or the fallback memory source. */
	private static SettingsView randomSettings(Random r)
	{
		switch (r.nextInt(5))
		{
			case 1:
				return new SettingsView(Renderer.GPU, false, false, 0, false, 0, true, "OFF", r.nextInt(241), 50,
					"MSAA_2", 3, 60, Os.WINDOWS, "");
			case 2:
				return new SettingsView(Renderer.HD, false, false, 0, false, 0, true, "ON", 0, 90, "", 3,
					30 + r.nextInt(200), Os.WINDOWS, "");
			case 3:
				return new SettingsView(Renderer.CPU, true, r.nextBoolean(), 1 + r.nextInt(60), r.nextBoolean(),
					r.nextInt(60), false, "", 0, 0, "", 0, 60, Os.WINDOWS, "");
			case 4:
				return new SettingsView(Renderer.CPU, false, false, 0, false, 0, false, "", 0, 0, "", 0, 60,
					Os.WINDOWS, "");
			default:
				return Trace.steady(1).settings();
		}
	}

	/** Where random incidents may land: {@code lo .. hi - 1}, never in {@code holeLo .. holeHi - 1}. */
	private static final class Space
	{
		final int lo;
		final int hi;
		int holeLo = Integer.MAX_VALUE;
		int holeHi = Integer.MAX_VALUE;
		/** Every fresh RTT is the steady 40 (bound (b) of the shift property). */
		boolean pingFortyOnly;
		/** No incident adds ticks: a slow world is never faster than one tick in TICK_MS. */
		boolean fewTicksOnly;
		boolean disconnects = true;
		boolean loads = true;
		boolean tickMoves = true;

		Space(int lo, int hi)
		{
			this.lo = lo;
			this.hi = hi;
		}

		int pick(Random r)
		{
			while (true)
			{
				final int at = lo + r.nextInt(hi - lo);
				if (at < holeLo || at >= holeHi)
				{
					return at;
				}
			}
		}

		/** The last second a span that starts at {@code at} may reach: before the hole, or before {@code hi}. */
		int lastOfASpanFrom(int at)
		{
			return at < holeLo ? Math.min(hi, holeLo) - 1 : hi - 1;
		}

		/** The longest frame that ends {@code end} ms into {@code at} and starts inside the space. */
		int longestFrameEndingIn(int at, int end)
		{
			final int floor = at >= holeHi ? holeHi : lo;
			return (at - floor) * 1000 + end;
		}
	}

	/** Incidents kept as steps, so the same ones can be laid on a trace of any length. */
	private static final class Recipe
	{
		private final List<Consumer<Trace>> steps = new ArrayList<>();

		void add(Consumer<Trace> step)
		{
			steps.add(step);
		}

		void addAll(Recipe other)
		{
			steps.addAll(other.steps);
		}

		Trace on(int seconds)
		{
			final Trace t = Trace.steady(seconds);
			for (Consumer<Trace> step : steps)
			{
				try
				{
					step.accept(t);
				}
				catch (IllegalArgumentException refused)
				{
					// Trace refused the step and changed nothing (a tick that is not there, a span past the end).
				}
			}
			return t;
		}
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The detector (contract 6.1, 6.2, 3.4, 3.6; the test list of contract 7, L3): each trigger fires at its line and
 * not one below it; the named traps (a teleport, a long load, low frame rates, a cap of 4 fps, a click burst, a stale
 * RTT, the frame gap limit of the second's own focus); how events open, merge, close and turn into conditions; what
 * feeds the usuals; the event's own numbers, open and closed; and the ids.
 *
 * <p>Every trace is a {@link Trace}; its steady second is 50 fps with a 22 ms worst frame, ticks every 600 ms from
 * session ms 0, a fresh RTT of 40, 900 bytes sent a second, on the CPU renderer (cap 50, so the frame gap limit is
 * {@link Thresholds#FRAME_GAP_MS}). The expected numbers below are worked out by hand from those rules.
 *
 * <p>Choice: an at-the-line test takes its line from Thresholds, so a line tuned live moves with it (NO_TICK: pinned).
 * <p>Choice: the lost-seconds and live-growth cases write a Session by hand; Trace writes a whole trace at once.
 * <p>Choice: LagDetector's package-private triggers(sec) shows which triggers fired in a second (3.10 allows it).
 */
public class LagDetectorTest
{
	private static final int N = 200;

	// ---------------------------------------------------------------- one per trigger, at the line

	@Test
	public void disconnectFires()
	{
		final Run r = run(Trace.steady(N).disconnect(120));
		assertEquals(Trigger.DISCONNECT.bit(), r.d.triggers(120));
		assertEquals("no flag, no trigger", 0, r.d.triggers(119));
		assertEquals(1, r.rec.closed.size());
		final LagEvent e = r.rec.closed.get(0);
		assertEquals(120, e.startSec);
		assertEquals(120, e.endSec);
		assertEquals(Trigger.DISCONNECT, e.first);
		assertEquals(Trigger.DISCONNECT.bit(), e.triggers);
	}

	@Test
	public void longLoadFiresAtTheLine()
	{
		// A run of LOAD_LONG_MS (2,000: 1,000 ms a second from 100) fires LONG_LOAD in the first second after it.
		final int after = 100 + (Thresholds.LOAD_LONG_MS + 999) / 1000;
		final Run at = run(loadRun(Trace.steady(N), 100, Thresholds.LOAD_LONG_MS));
		assertEquals(Trigger.LONG_LOAD.bit(), at.d.triggers(after));
		assertEquals(1, at.rec.closed.size());
		assertEquals(after, at.rec.closed.get(0).startSec);
		final Run below = run(loadRun(Trace.steady(N), 100, Thresholds.LOAD_LONG_MS - 1));
		assertTrue("a run of one ms less", below.rec.opened.isEmpty());
		assertAllQuiet(below, 0, N - 1);
	}

	@Test
	public void frameGapFiresAtTheLine()
	{
		// The CPU renderer's cap of 50 leaves the limit at its floor, FRAME_GAP_MS (200).
		final int line = Trace.steady(1).settings().frameGapLimitMs(true);
		final Run at = run(Trace.steady(N).frameGap(120, 500, line));
		assertEquals(Trigger.FRAME_GAP.bit(), at.d.triggers(120));
		assertEquals(Trigger.FRAME_GAP, at.rec.closed.get(0).first);
		final Run below = run(Trace.steady(N).frameGap(120, 500, line - 1));
		assertEquals(0, below.d.triggers(120));
		assertTrue(below.rec.opened.isEmpty());
	}

	@Test
	public void tickOffFiresAtTheLine()
	{
		// The first tick of 120 comes TICK_OFF_MS + 22 ms late (722 ms after the one before): less the steady 22 ms
		// frame it carries, TICK_OFF_MS off; its catch-up gap (478) is as far off the other way.
		final int frame = Trace.steady(1).build().ticks.frameMs(0);
		final Run at = run(Trace.steady(N).tickLate(120, Thresholds.TICK_OFF_MS + frame, true));
		assertEquals(Trigger.TICK_OFF.bit(), at.d.triggers(120));
		assertEquals(Trigger.TICK_OFF, at.rec.closed.get(0).first);
		final Run below = run(Trace.steady(N).tickLate(120, Thresholds.TICK_OFF_MS + frame - 1, true));
		assertEquals(0, below.d.triggers(120));
		assertTrue(below.rec.opened.isEmpty());
	}

	@Test
	public void noTickFiresAtTheLine()
	{
		// The ticks of 50 .. 52 are gone; the newest before 51,000 is 49,800: 1,200 ms old at the second's end.
		assertEquals("the premise: the hole is laid for this line", 1200, Thresholds.NO_TICK_MS);
		final Run at = run(Trace.steady(N).noTicks(50, 52));
		assertEquals(0, at.d.triggers(49));
		assertEquals(Trigger.NO_TICK.bit(), at.d.triggers(50));
		assertEquals(Trigger.NO_TICK.bit(), at.d.triggers(52));
		final LagEvent e = at.rec.closed.get(0);
		assertEquals(50, e.startSec);
		assertEquals(Trigger.NO_TICK, e.first);
		assertTrue("the tick after the hole is off", e.has(Trigger.TICK_OFF));
		assertEquals(53, e.endSec);
		// Every tick from 49,200 on one ms later: the newest before 51,000 is 49,801, 1,199 ms old.
		final Run below = run(Trace.steady(N).tickLate(49, 1, false).noTicks(50, 52));
		assertEquals(0, below.d.triggers(50));
		assertEquals(Trigger.NO_TICK.bit(), below.d.triggers(51));
		assertEquals(51, below.rec.closed.get(0).startSec);
	}

	@Test
	public void resentFiresAtTheLine()
	{
		// Windows counts bytes: RESENT_WINDOW_S seconds of 900 is 14,400 sent; the least re-sent that makes
		// RESENT_PER_MILLE of it (144 is 10 per mille) fires, one less (143 is 9) does not.
		final long windowSent = (long) Thresholds.RESENT_WINDOW_S * 900;
		final int line = (int) ((Thresholds.RESENT_PER_MILLE * windowSent + 999) / 1000);
		final Run at = run(Trace.steady(N).resent(120, line));
		assertEquals(Trigger.RESENT.bit(), at.d.triggers(120));
		assertEquals(Trigger.RESENT, at.rec.closed.get(0).first);
		assertEquals("the window still holds the share, but 121 re-sent nothing", 0, at.d.triggers(121));
		final Run below = run(Trace.steady(N).resent(120, line - 1));
		assertEquals(0, below.d.triggers(120));
		assertTrue(below.rec.opened.isEmpty());
		// The least sent before re-sends count: nothing sent in the window but its last second, which sends the least
		// (RESENT_MIN_BYTES), or one less.
		final int first = 121 - Thresholds.RESENT_WINDOW_S;
		final Run least = run(Trace.steady(N).sent(first, 120, 0).sent(120, 120, Os.WINDOWS.resentMinSent())
			.resent(120, 1000));
		assertEquals(Trigger.RESENT.bit(), least.d.triggers(120));
		final Run under = run(Trace.steady(N).sent(first, 120, 0).sent(120, 120, Os.WINDOWS.resentMinSent() - 1)
			.resent(120, 1000));
		assertEquals(0, under.d.triggers(120));
		// Elsewhere the counters are segments, and the least is RESENT_MIN_UNITS of them.
		final Run linux = run(Trace.steady(N).os(Os.LINUX).sent(first, 120, 0).sent(120, 120, Os.LINUX.resentMinSent())
			.resent(120, 1));
		assertEquals(Trigger.RESENT.bit(), linux.d.triggers(120));
		final Run linuxUnder = run(Trace.steady(N).os(Os.LINUX).sent(first, 120, 0)
			.sent(120, 120, Os.LINUX.resentMinSent() - 1).resent(120, 1));
		assertEquals(0, linuxUnder.d.triggers(120));
	}

	@Test
	public void rttSpikeFiresAtTheLine()
	{
		// A usual of 40: the line is the larger of 40 x 200 % = 80 and 40 + 50 = 90.
		final int line = spikeLine(40);
		final Run at = run(Trace.steady(N).usual(40).rtt(120, 120, line));
		assertEquals(Trigger.RTT_SPIKE.bit(), at.d.triggers(120));
		final Run below = run(Trace.steady(N).usual(40).rtt(120, 120, line - 1));
		assertEquals(0, below.d.triggers(120));
		// A usual of 100 (every RTT of the trace is 100): the larger of 200 and 150, the other half of the rule.
		final int high = spikeLine(100);
		final Run pct = run(Trace.steady(N).rtt(0, N - 1, 100).rtt(120, 120, high));
		assertEquals(100, pct.s.rttUsual.median());
		assertEquals(Trigger.RTT_SPIKE.bit(), pct.d.triggers(120));
		final Run pctBelow = run(Trace.steady(N).rtt(0, N - 1, 100).rtt(120, 120, high - 1));
		assertEquals(0, pctBelow.d.triggers(120));
		// No usual yet at second 10 (ten samples): nothing to spike against.
		final Trace early = Trace.steady(N).rtt(10, 10, 300);
		final Session es = early.build();
		final LagDetector ed = new LagDetector();
		ed.advance(es, 10, early.settings(), new Recorder());
		assertEquals("the premise", -1, es.rttUsual.median());
		assertEquals(0, ed.triggers(10));
	}

	// ---------------------------------------------------------------- the traps

	@Test
	public void teleportIsNotListed()
	{
		// A 1.6 s load with its long frame and no ticks: the tick after it (102,000, 2,400 ms after the one before)
		// lands in the tail of the load and fires nothing.
		final Run r = run(Trace.steady(N).loading(100, 1000).loading(101, 600).noTicks(100, 101)
			.frameGap(101, 800, 1200));
		assertTrue(r.rec.opened.isEmpty());
		assertAllQuiet(r, 0, N - 1);
	}

	@Test
	public void longLoadIsListed()
	{
		final Trace t = Trace.steady(N).loading(100, 1000).loading(101, 1000).loading(102, 400);
		final Session s = t.build();
		final LagDetector d = new LagDetector();
		final Recorder rec = new Recorder();
		d.advance(s, 102, t.settings(), rec);
		assertTrue("nothing fires while the run is still loading", rec.opened.isEmpty());
		assertEquals(0, d.triggers(100) | d.triggers(101) | d.triggers(102));
		d.advance(s, 103, t.settings(), rec);
		assertEquals(1, rec.opened.size());
		assertEquals(103, rec.opened.get(0).startSec);
		assertEquals(Trigger.LONG_LOAD, rec.opened.get(0).first);
		d.advance(s, N - 1, t.settings(), rec);
		final LagEvent e = rec.closed.get(0);
		assertEquals(103, e.startSec);
		assertEquals(103, e.endSec);
		assertEquals(Trigger.LONG_LOAD.bit(), e.triggers);
	}

	@Test
	public void noTickIsJudgedAtTheSecondsEnd()
	{
		// A hop at 40 masks the ticks 41,400 .. 49,800. Moved one ms later, the newest tick before 51,000 is the
		// masked 49,801: 1,199 ms old, so NO_TICK does not fire in 50 - though the newest UNMASKED tick, 40,800, is
		// ten seconds old.
		final Run masked = run(Trace.steady(N).hop(40, 302).tickLate(49, 1, false).noTicks(50, 50));
		assertEquals("the premise: 50 is not masked", 0, masked.s.seconds.flags(50) & Flags.MASKED);
		assertEquals("a LOGIN_MASK tick still counts", 0, masked.d.triggers(50));
		// Unmoved, the masked 49,800 is 1,200 ms old at the second's end: it fires.
		final Run fires = run(Trace.steady(N).hop(40, 302).noTicks(50, 50));
		assertEquals(Trigger.NO_TICK.bit(), fires.d.triggers(50));
		// With no tick at all before a second's end, nothing fires - not even 5 s in.
		final Run none = run(Trace.steady(30).noTicks(0, 5));
		assertTrue(none.rec.opened.isEmpty());
		assertAllQuiet(none, 0, 29);
		// Only in an in-game second that drew a frame: no tick from 117,600 on, and 120 is a lost connection's
		// second, or a second with no frame.
		final Run lost = run(Trace.steady(N).noTicks(118, 121).disconnect(120));
		assertEquals(Trigger.NO_TICK.bit(), lost.d.triggers(119));
		assertEquals("CONNECTION_LOST is not in-game", Trigger.DISCONNECT.bit(), lost.d.triggers(120));
		assertEquals(Trigger.NO_TICK.bit(), lost.d.triggers(121));
		final Run frameless = run(Trace.steady(N).noTicks(118, 121).fps(120, 120, 0));
		assertEquals(Trigger.NO_TICK.bit(), frameless.d.triggers(119));
		assertEquals("no frame drawn", 0, frameless.d.triggers(120));
		assertEquals(Trigger.NO_TICK.bit(), frameless.d.triggers(121));
	}

	@Test
	public void lowFpsDoesNotFireTheTickTrigger()
	{
		// At 8 fps a tick waits up to one 125 ms frame: late by one frame, early by one frame on the catch-up, or
		// the whole grid moved by one frame. Off by 125, less the 125 ms frame, is 0 (C5).
		final Trace slow = Trace.steady(N).fps(100, 140, 8).tickLate(105, 125, true).tickLate(110, 125, false)
			.tickLate(120, 125, true);
		final Run r = run(slow);
		assertTrue(r.rec.opened.isEmpty());
		assertAllQuiet(r, 0, N - 1);
		// At 50 fps the same lateness is 103 ms off, under TICK_OFF_MS since the first live look; a tick TICK_OFF_MS
		// off after the 22 ms frame fires.
		assertEquals(0, run(Trace.steady(N).tickLate(105, 125, true)).d.triggers(105));
		final Run fast = run(Trace.steady(N).tickLate(105, Thresholds.TICK_OFF_MS + 22, true));
		assertEquals(Trigger.TICK_OFF.bit(), fast.d.triggers(105));
	}

	@Test
	public void capOfFourFpsFiresNothing()
	{
		// FPS Control at 4 fps: the cap interval is 250, the frame gap limit 375 (C9).
		final SettingsView capped = new SettingsView(Renderer.CPU, true, true, 4, false, 0, false, "", 0, 0, "", 0,
			60, Os.WINDOWS, "");
		assertEquals("the premise", 375, capped.frameGapLimitMs(true));
		final Trace t = Trace.steady(N).fps(100, 150, 4).tickLate(110, 250, true).tickLate(120, 250, false);
		final Run r = run(t, capped);
		assertTrue(r.rec.opened.isEmpty());
		assertAllQuiet(r, 0, N - 1);
		// Without the cap the 250 ms frames are frame gaps.
		final Run uncapped = run(Trace.steady(N).fps(100, 150, 4));
		assertEquals(Trigger.FRAME_GAP.bit(), uncapped.d.triggers(100) & Trigger.FRAME_GAP.bit());
	}

	@Test
	public void clickBurstIsNotASpike()
	{
		// C21: sent jumps from 900 to 1,600 in the spike's second, 700 over the quiet median.
		final int spike = spikeLine(40) + 60;
		final Run r = run(Trace.steady(N).usual(40).rtt(120, 120, spike).sent(120, 120, 1600));
		assertEquals(0, r.d.triggers(120));
		// The jump's line is the OS's click size, CLICK_SENT_BYTES (600) on Windows: that much voids the spike, one
		// byte less does not.
		final int jump = Os.WINDOWS.clickSent();
		assertEquals(0, run(Trace.steady(N).usual(40).rtt(120, 120, spike).sent(120, 120, 900 + jump)).d.triggers(120));
		assertEquals(Trigger.RTT_SPIKE.bit(),
			run(Trace.steady(N).usual(40).rtt(120, 120, spike).sent(120, 120, 900 + jump - 1)).d.triggers(120));
	}

	@Test
	public void steadySendingStillSpikes()
	{
		// The steady 900 a second is over CLICK_SENT_BYTES, but it is no JUMP over the quiet median.
		final Run r = run(Trace.steady(N).usual(40).rtt(120, 120, spikeLine(40) + 60));
		assertEquals(Trigger.RTT_SPIKE.bit(), r.d.triggers(120));
	}

	@Test
	public void teleportFrameAfterLoadOpensNothing()
	{
		// The load's long frame ends in the next second, flagged LOADING by the loading-frame rule.
		final Run next = run(Trace.steady(N).loading(119, 800).frameGap(120, 300, 450));
		assertTrue("the premise", Flags.has(next.s.seconds.flags(120), Flags.LOADING));
		assertTrue(next.rec.opened.isEmpty());
		assertAllQuiet(next, 0, N - 1);
		// A frame that ends two seconds after the load: 120 is a no-frame second in the load's tail, 121 is flagged.
		final Run later = run(Trace.steady(N).loading(119, 800).frameGap(121, 300, 1450));
		assertTrue("the premise", Flags.has(later.s.seconds.flags(120), Flags.NO_FRAMES));
		assertTrue("the premise", Flags.has(later.s.seconds.flags(121), Flags.LOADING));
		assertTrue(later.rec.opened.isEmpty());
		assertAllQuiet(later, 0, N - 1);
	}

	@Test
	public void staleRttIsNoSpike()
	{
		final Run r = run(Trace.steady(N).usual(40).rtt(120, 120, 300).rttStale(120, 120));
		assertEquals("the premise: the RTT is kept", 300, r.s.seconds.rttMs(120));
		assertEquals(0, r.d.triggers(120));
		assertEquals(Trigger.RTT_SPIKE.bit(), run(Trace.steady(N).usual(40).rtt(120, 120, 300)).d.triggers(120));
	}

	@Test
	public void rttSpikeAloneOpensNothing()
	{
		final Run r = run(Trace.steady(N).usual(40).rtt(120, 122, 300));
		for (long sec = 120; sec <= 122; sec++)
		{
			assertEquals(Trigger.RTT_SPIKE.bit(), r.d.triggers(sec));
			assertFalse(r.d.quiet(sec));
		}
		assertTrue(r.rec.opened.isEmpty());
		assertNull(r.d.open());
		// A spike is still a trigger second: it extends an event that another trigger opened.
		final Run extend = run(Trace.steady(N).usual(40).frameGap(120, 500, 300).rtt(124, 124, 300)
			.rtt(128, 128, 300));
		assertEquals(1, extend.rec.closed.size());
		final LagEvent e = extend.rec.closed.get(0);
		assertEquals(120, e.startSec);
		assertEquals(128, e.endSec);
		assertEquals(Trigger.FRAME_GAP, e.first);
		assertEquals(Trigger.FRAME_GAP.bit() | Trigger.RTT_SPIKE.bit(), e.triggers);
	}

	@Test
	public void theFrameGapLimitIsTheSecondsOwn()
	{
		// FPS Control's limit on at 3 and its unfocused limit on at 60; GPU unlocked, V-Sync off, a target of 4.
		final SettingsView v = new SettingsView(Renderer.GPU, true, true, 3, true, 60, true, "OFF", 4, 0, "", 0, 60,
			Os.WINDOWS, "");
		assertEquals("focused: FPS Control's 3", 499, v.frameGapLimitMs(true));
		assertEquals("unfocused: the GPU's 4", 375, v.frameGapLimitMs(false));
		final Trace t = Trace.steady(N).unfocused(120, 120).frameGap(120, 500, 400).frameGap(140, 500, 400);
		final Run r = run(t, v);
		assertFalse("the unfocused second is not masked", Masks.masked(r.s.seconds, 120, v));
		assertEquals("400 ms, unfocused", Trigger.FRAME_GAP.bit(), r.d.triggers(120));
		assertEquals("400 ms, focused", 0, r.d.triggers(140));
	}

	@Test
	public void aMaskedSecondFiresOnlyDisconnectAndLongLoad()
	{
		// A load with a 900 ms frame in it fires nothing.
		final Run load = run(Trace.steady(N).loading(120, 500).frameGap(120, 800, 900));
		assertEquals(0, load.d.triggers(120));
		assertTrue(load.rec.opened.isEmpty());
		// A lost connection inside a hop's login mask fires, and opens an event.
		final Run lost = run(Trace.steady(N).hop(100, 302).disconnect(105));
		assertTrue("the premise", Masks.masked(lost.s.seconds, 105, Trace.steady(N).settings()));
		assertEquals(Trigger.DISCONNECT.bit(), lost.d.triggers(105));
		assertEquals(105, lost.rec.closed.get(0).startSec);
	}

	// ---------------------------------------------------------------- events

	@Test
	public void fiveQuietSecondsClose()
	{
		final Trace t = Trace.steady(N).frameGap(100, 500, 300).frameGap(106, 500, 300);
		final Session s = t.build();
		final LagDetector d = new LagDetector();
		final Recorder rec = new Recorder();
		d.advance(s, 104, t.settings(), rec);
		assertNotNull("four quiet seconds keep it open", d.open());
		assertTrue(rec.closed.isEmpty());
		d.advance(s, 105, t.settings(), rec);
		assertNull("the fifth closes it", d.open());
		assertEquals(1, rec.closed.size());
		assertEquals(100, rec.closed.get(0).endSec);
		d.advance(s, N - 1, t.settings(), rec);
		assertEquals(2, rec.closed.size());
		assertEquals(106, rec.closed.get(1).startSec);
		assertEquals(106, rec.closed.get(1).endSec);
	}

	@Test
	public void fourQuietSecondsMerge()
	{
		final Run r = run(Trace.steady(N).frameGap(100, 500, 300).frameGap(105, 500, 300));
		assertEquals(1, r.rec.closed.size());
		final LagEvent e = r.rec.closed.get(0);
		assertEquals(100, e.startSec);
		assertEquals(105, e.endSec);
		assertEquals(6, e.lengthS());
		assertFalse(e.becameCondition);
	}

	@Test
	public void longEventBecomesACondition()
	{
		// A frame gap every second 100 .. 299. The event cannot pass 120 s: the trigger of 220 closes it at 219 and
		// starts the wait; the triggers of the wait and the one at 302 open nothing; 303 .. 307 are the five quiet
		// seconds that end the wait, so 308, the very next second, opens.
		final Trace t = Trace.steady(400);
		for (int sec = 100; sec <= 299; sec++)
		{
			t.frameGap(sec, 500, 300);
		}
		t.frameGap(302, 500, 300).frameGap(308, 500, 300);
		final Run r = run(t);
		assertEquals(2, r.rec.closed.size());
		final LagEvent condition = r.rec.closed.get(0);
		assertEquals(100, condition.startSec);
		assertEquals(219, condition.endSec);
		assertEquals(Thresholds.EVENT_MAX_S, condition.lengthS());
		assertTrue(condition.becameCondition);
		final LagEvent after = r.rec.closed.get(1);
		assertEquals(308, after.startSec);
		assertFalse(after.becameCondition);
		// An event of exactly EVENT_MAX_S that ends quietly closes normally.
		final Trace exact = Trace.steady(400);
		for (int sec = 100; sec <= 219; sec++)
		{
			exact.frameGap(sec, 500, 300);
		}
		final LagEvent whole = run(exact).rec.closed.get(0);
		assertEquals(219, whole.endSec);
		assertFalse(whole.becameCondition);
	}

	@Test
	public void aDisconnectOpensInsideTheWaitAfterALongEvent()
	{
		final Trace t = Trace.steady(400);
		for (int sec = 100; sec <= 220; sec++)
		{
			t.frameGap(sec, 500, 300);
		}
		t.disconnect(222);
		final Run r = run(t);
		assertEquals(2, r.rec.closed.size());
		assertTrue(r.rec.closed.get(0).becameCondition);
		assertEquals(219, r.rec.closed.get(0).endSec);
		final LagEvent d1 = r.rec.closed.get(1);
		assertEquals("two seconds after the close, inside the wait", 222, d1.startSec);
		assertEquals(Trigger.DISCONNECT, d1.first);
		// A frame gap in the same place opens nothing.
		final Trace control = Trace.steady(400);
		for (int sec = 100; sec <= 220; sec++)
		{
			control.frameGap(sec, 500, 300);
		}
		control.frameGap(222, 500, 300);
		assertEquals(1, run(control).rec.closed.size());
		// A lost connection in the very second that crosses EVENT_MAX_S opens the next event there.
		final Trace crossing = Trace.steady(400);
		for (int sec = 100; sec <= 220; sec++)
		{
			crossing.frameGap(sec, 500, 300);
		}
		crossing.disconnect(220);
		final Run c = run(crossing);
		assertEquals(2, c.rec.closed.size());
		assertEquals(219, c.rec.closed.get(0).endSec);
		assertEquals(220, c.rec.closed.get(1).startSec);
		assertEquals(Trigger.DISCONNECT, c.rec.closed.get(1).first);
		assertEquals(Trigger.FRAME_GAP.bit() | Trigger.DISCONNECT.bit(), c.rec.closed.get(1).triggers);
	}

	// ---------------------------------------------------------------- the usuals

	@Test
	public void usualIgnoresEventSeconds()
	{
		// An event at 100 (at 6 fps from 101, which fires nothing) closes at 105: 0 .. 99 and 106 .. 199 feed.
		final Trace t = Trace.steady(N).frameGap(100, 500, 300).fps(101, 105, 6);
		final Run r = run(t);
		assertEquals(1, r.rec.closed.size());
		assertEquals(100, r.rec.closed.get(0).endSec);
		assertEquals(194, r.s.fpsUsual.count());
		assertEquals(194, r.s.rttSession.count());
		assertEquals(194, r.s.rttUsual.count());
