package com.whylag.core;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The tick ring (contract 3.3): wrap, the one slot of slack, the corrected deviation that takes the frame interval
 * out of a tick's lateness (skeptic C5), its row of the clamp table, and tick times in session ms as a {@code long}
 * that holds more than 24.8 days.
 */
public class TickRingTest
{
	@Test
	public void wrap()
	{
		final TickRing ring = new TickRing(8);
		assertEquals(-1, ring.head());
		assertFalse(ring.valid(0));
		final TickRow row = new TickRow();
		for (int i = 0; i < 20; i++)
		{
			row.atMs = 600 * i;
			row.gapMs = 600 + i;
			row.frameMs = i;
			row.cycleJump = 30 + i;
			row.rttMs = 40 + i;
			row.flags = i % 128;
			ring.put(row);
		}
		assertEquals(19, ring.head());
		assertEquals("capacity - 1 ticks stay readable", 13, ring.tail());
		assertFalse(ring.valid(12));
		for (long q = 13; q <= 19; q++)
		{
			assertTrue(ring.valid(q));
			assertEquals(600 * q, ring.atMs(q));
			assertEquals(600 + q, ring.gapMs(q));
			assertEquals(q, ring.frameMs(q));
			assertEquals(30 + q, ring.cycleJump(q));
			assertEquals(40 + q, ring.rttMs(q));
			assertEquals(q, ring.flags(q));
		}
	}

	@Test
	public void tailKeepsOneSlotOfSlack()
	{
		final TickRing ring = new TickRing(5);
		final TickRow row = new TickRow();
		for (int i = 0; i < 5; i++)
		{
			ring.put(row);
		}
		// Five ticks in five slots: tick 0 is still in its slot, but the next put reuses it, so it is not readable.
		assertEquals(4, ring.head());
		assertEquals(1, ring.tail());
		assertFalse(ring.valid(0));
		assertTrue(ring.valid(1));
	}

	@Test
	public void aSessionsRingHoldsSixThousandTicks()
	{
		final TickRing ring = new Session(0, 0, Os.WINDOWS, java.time.ZoneOffset.UTC).ticks;
		final TickRow row = new TickRow();
		for (int i = 0; i < 10_000; i++)
		{
			ring.put(row);
		}
		assertEquals(Thresholds.TICKS, ring.head() - ring.tail() + 1);
	}

	@Test
	public void correctedSubtractsTheFrameInterval()
	{
		final TickRing ring = new TickRing(16);
		final long steady = put(ring, 600, 22);
		final long lateByAFrame = put(ring, 725, 125);
		final long lateByMore = put(ring, 900, 250);
		final long earlyAfterAStall = put(ring, 450, 20);
		final long frameLongerThanTheGap = put(ring, 610, 400);
		final long noFrame = put(ring, 900, 0);
		assertEquals("600 on the dot", 0, ring.corrected(steady));
		assertEquals("late by exactly one frame at 8 fps is the client's pacing (C5)", 0, ring.corrected(lateByAFrame));
		assertEquals("300 late, 250 of it one frame", 50, ring.corrected(lateByMore));
		assertEquals("early counts too: |450 - 600| - 20", 130, ring.corrected(earlyAfterAStall));
		assertEquals("never below 0", 0, ring.corrected(frameLongerThanTheGap));
		assertEquals(300, ring.corrected(noFrame));
	}

	@Test
	public void lateAndEarly()
	{
		final TickRing ring = new TickRing(16);
		final long late = put(ring, 601, 22);
		final long onTime = put(ring, 600, 22);
		final long early = put(ring, 599, 22);
		final long veryEarly = put(ring, 300, 22);
		assertTrue(ring.late(late));
		assertFalse("600 is not late", ring.late(onTime));
		assertFalse(ring.late(early));
		assertFalse(ring.late(veryEarly));
		assertFalse("a late tick is not early", ring.early(late));
		assertFalse("600 is neither late nor early", ring.early(onTime));
		assertTrue("599 is early", ring.early(early));
		assertTrue(ring.early(veryEarly));
		assertEquals("the line of both is TICK_MS", 600, Thresholds.TICK_MS);
		assertEquals("an early tick is off by its distance from 600", 278, ring.corrected(veryEarly));
	}

	@Test
	public void valuesAreClamped()
	{
		final TickRing ring = new TickRing(4);
		final TickRow row = new TickRow();
		row.atMs = 3_000_000;
		row.gapMs = 90_000;
		row.frameMs = 70_000;
		row.cycleJump = -9;
		row.rttMs = 40_000;
		row.flags = 300;
		ring.put(row);
		assertEquals("atMs is whole", 3_000_000, ring.atMs(0));
		assertEquals("gapMs is whole", 90_000, ring.gapMs(0));
		assertEquals(32767, ring.frameMs(0));
		assertEquals(-1, ring.cycleJump(0));
		assertEquals(32767, ring.rttMs(0));
		assertEquals(127, ring.flags(0));

		// The other ends: every negative short is -1 (far below it too), a negative flag byte is 0.
		row.gapMs = Integer.MAX_VALUE;
		row.frameMs = -32_769;
		row.cycleJump = 40_000;
		row.rttMs = -5;
		row.flags = -3;
		ring.put(row);
		assertEquals("gapMs is whole", Integer.MAX_VALUE, ring.gapMs(1));
		assertEquals(-1, ring.frameMs(1));
		assertEquals(32767, ring.cycleJump(1));
		assertEquals(-1, ring.rttMs(1));
		assertEquals(0, ring.flags(1));
	}

	/** 3,000,000,000 ms (about 34.7 days) goes in and comes out: an int would have wrapped at 24.8 days. */
	@Test
	public void atMsHoldsMoreThanTwentyFiveDays()
	{
		final TickRing ring = new TickRing(4);
		final TickRow row = new TickRow();
		row.atMs = 3_000_000_000L;
		row.gapMs = 600;
		ring.put(row);
		row.atMs = 3_000_000_600L;
		ring.put(row);
		assertEquals(3_000_000_000L, ring.atMs(0));
		assertEquals(3_000_000_600L, ring.atMs(1));
		assertTrue(ring.atMs(0) > Integer.MAX_VALUE);
		row.atMs = Long.MAX_VALUE;
		ring.put(row);
		assertEquals("kept whole", Long.MAX_VALUE, ring.atMs(2));
	}

	private static long put(TickRing ring, int gapMs, int frameMs)
	{
		final TickRow row = new TickRow();
		row.gapMs = gapMs;
		row.frameMs = frameMs;
		ring.put(row);
		return ring.head();
	}
}

package com.whylag.core;

import java.time.ZoneOffset;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link TickSampler} (contract section 7, L2): what a tick row holds. Times are session ms. Where frames matter
 * they run on a 20 ms grid, and a tick that falls on a frame's ms arrives BEFORE that frame, as the client posts it.
 */
public class TickSamplerTest
{
	private static final long START = 9_000_000_000_000L;
	private static final long NANOS_PER_MS = 1_000_000L;
	private static final int FRAME_MS = 20;
	private static final int CYCLE_MS = 20;

	private Session session;
	private TickRing ring;
	private FrameSampler frames;
	private TickSampler ticks;

	@Before
	public void setUp()
	{
		session = new Session(START, 1_000_000L, Os.WINDOWS, ZoneOffset.UTC);
		ring = session.ticks;
		final SelfTimer timer = new SelfTimer();
		frames = new FrameSampler(session, timer);
		ticks = new TickSampler(session, frames, timer);
	}

	private static long at(long ms)
	{
		return START + ms * NANOS_PER_MS;
	}

	private void state(long ms, int code)
	{
		frames.state(at(ms), code);
		ticks.state(at(ms), code);
	}

	private void tick(long ms)
	{
		ticks.tick(at(ms), (int) (ms / CYCLE_MS), 40);
	}

	private void frame(long ms)
	{
		frames.frame(at(ms), (int) (ms / CYCLE_MS));
	}

	/**
	 * Frames every 20 ms from {@code fromMs} to {@code toMs}, both included, and a tick every 600 ms from
	 * {@code firstTickMs} on, each just before the frame of its ms.
	 */
	private void run(long fromMs, long toMs, long firstTickMs)
	{
		long nextTick = firstTickMs;
		for (long t = fromMs; t <= toMs; t += FRAME_MS)
		{
			while (nextTick <= t)
			{
				tick(nextTick);
				nextTick += Thresholds.TICK_MS;
			}
			frame(t);
		}
	}

	private boolean masked(long seq)
	{
		return Flags.has(ring.flags(seq), Flags.LOGIN_MASK);
	}

	@Test
	public void gapAndCycleJump()
	{
		state(0, State.LOGGED_IN);
		ticks.tick(at(600), 30, 41);
		ticks.tick(at(1200), 60, 42);
		ticks.tick(at(1850), 93, -1);
		assertEquals(2, ring.head());

		assertEquals(600L, ring.atMs(0));
		assertEquals(Thresholds.TICK_MS, ring.gapMs(0));
		assertEquals(-1, ring.cycleJump(0));
		assertEquals(41, ring.rttMs(0));

		assertEquals(1200L, ring.atMs(1));
		assertEquals(600, ring.gapMs(1));
		assertEquals(30, ring.cycleJump(1));
		assertEquals(42, ring.rttMs(1));

		assertEquals(1850L, ring.atMs(2));
		assertEquals(650, ring.gapMs(2));
		assertEquals(33, ring.cycleJump(2));
		assertEquals(-1, ring.rttMs(2));
		assertTrue(ring.late(2));
		assertEquals(Flags.FOCUSED, ring.flags(2));
	}

	@Test
	public void atMsIsALongAndAGapIsHeldInAnInt()
	{
		final long month = 40L * 86_400_000L;
		ticks.tick(at(600), 30, 40);
		ticks.tick(at(month), 60, 40);
		ticks.tick(at(month + 600), 90, 40);
		assertEquals("40 days in ms do not fit an int", month, ring.atMs(1));
		assertEquals(Integer.MAX_VALUE, ring.gapMs(1));
		assertEquals(600, ring.gapMs(2));
		assertEquals(month + 600, ring.atMs(2));
	}

	@Test
	public void theSessionsFirstTickIsNeverOff()
	{
		// switched on while logged in: no login mask, and the first tick comes 7 s after the session's start
		state(10, State.LOGGED_IN);
		tick(7000);
		tick(7640);
		assertEquals(7000L, ring.atMs(0));
		assertEquals("not measured from the session's start", Thresholds.TICK_MS, ring.gapMs(0));
		assertEquals(-1, ring.cycleJump(0));
		assertEquals(0, ring.corrected(0));
		assertFalse(masked(0));

		assertEquals("the true difference", 640, ring.gapMs(1));
		assertEquals(32, ring.cycleJump(1));
		assertEquals(40, ring.corrected(1));
	}

	@Test
	public void frameIntervalTravelsWithTheTick()
	{
		state(0, State.LOGGED_IN);
		run(0, 1400, 600);
		frame(1480);
		run(1500, 3000, 1800);
		assertEquals(4, ring.head());
		assertEquals("600", FRAME_MS, ring.frameMs(0));
		assertEquals("1200", FRAME_MS, ring.frameMs(1));
		assertEquals("1800: the 80 ms frame lies in its gap", 80, ring.frameMs(2));
		assertEquals("2400: it does not travel on", FRAME_MS, ring.frameMs(3));
		assertEquals(FRAME_MS, ring.frameMs(4));
	}

	@Test
	public void theOpenFrameIsChargedToTheLateTick()
	{
		state(0, State.LOGGED_IN);
		run(0, 1780, 600);
		// the client stalls for 300 ms: no frame and no tick until 2080. The tick due at 1800 is handled first ...
		tick(2080);
		// ... and then the frame that held the stall is drawn
		frame(2085);
		for (long t = 2100; t <= 2380; t += FRAME_MS)
		{
			frame(t);
		}
		// the next tick was on time at the server, so it follows only 320 ms later
		tick(2400);
		run(2400, 3600, 3000);

		assertEquals(2080L, ring.atMs(2));
		assertEquals(880, ring.gapMs(2));
		assertEquals("the frame still open when the late tick arrived", 300, ring.frameMs(2));
		assertTrue(ring.corrected(2) < Thresholds.TICK_OFF_MS);
		assertEquals(0, ring.corrected(2));

		assertEquals(320, ring.gapMs(3));
		assertTrue(ring.early(3));
		assertEquals("the stall frame itself, once: not the open and the closed reading added up", 305,
			ring.frameMs(3));
		assertTrue(ring.corrected(3) < Thresholds.TICK_OFF_MS);

		assertEquals(600, ring.gapMs(4));
		assertEquals("the stall is spent: the tick after the catch-up carries an ordinary frame", FRAME_MS,
			ring.frameMs(4));
		assertEquals(0, ring.corrected(4));
	}

	@Test
	public void withoutAFrameYetATickCarriesNoFrameTime()
	{
		state(0, State.LOGGED_IN);
		tick(600);
		tick(1200);
		assertEquals(0, ring.frameMs(0));
		assertEquals(0, ring.frameMs(1));
	}

	@Test
	public void loginMaskCoversFifteenTicks()
	{
		state(0, State.LOGIN_SCREEN);
		run(0, 980, Long.MAX_VALUE);
		state(1000, State.LOGGING_IN);
		run(1000, 1980, Long.MAX_VALUE);
		state(2000, State.LOADING);
		run(2000, 2480, Long.MAX_VALUE);
		state(2500, State.LOGGED_IN);
		// ticks at 3000, 3600 ... : the fifteenth arrives at 11,400, the sixteenth at 12,000, the last at 15,000
		run(2500, 15000, 3000);

		assertEquals(20, ring.head());
		for (long seq = 0; seq < Thresholds.LOGIN_MASK_TICKS; seq++)
		{
			assertTrue("tick " + seq, masked(seq));
		}
		for (long seq = Thresholds.LOGIN_MASK_TICKS; seq <= ring.head(); seq++)
		{
			assertFalse("tick " + seq, masked(seq));
		}
		assertEquals(11_400L, ring.atMs(Thresholds.LOGIN_MASK_TICKS - 1));

		final SecondRing seconds = session.seconds;
		assertEquals(14, seconds.frameHead());
		for (long sec = 0; sec <= 2; sec++)
		{
			assertFalse("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
		}
		for (long sec = 3; sec <= 11; sec++)
		{
			assertTrue("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
		}
		for (long sec = 12; sec <= 14; sec++)
		{
			assertFalse("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
		}
	}

	@Test
	public void aTickInAMaskedSecondCarriesItsSecondsBit()
	{
		state(0, State.HOPPING);
		state(500, State.LOGGED_IN);
		// ticks at 2600, 3200 ... : the fifteenth arrives at 11,000 and the sixteenth at 11,600, in the same second
		run(500, 14_000, 2600);
		final long last = Thresholds.LOGIN_MASK_TICKS - 1;
		assertEquals(11_000L, ring.atMs(last));
		assertTrue(masked(last));
		assertEquals(11_600L, ring.atMs(last + 1));
		assertTrue("it carries the flags of its second as they stand, as a trace's tick does", masked(last + 1));
		assertEquals(12_200L, ring.atMs(last + 2));
		assertFalse(masked(last + 2));
		assertTrue(Flags.has(session.seconds.flags(11), Flags.LOGIN_MASK));
		assertFalse(Flags.has(session.seconds.flags(12), Flags.LOGIN_MASK));
	}

	@Test
	public void aSecondWithNoMaskedTickIsNotMasked()
	{
		state(0, State.HOPPING);
		state(900, State.LOGGED_IN);
		for (long t = 0; t <= 8000; t += FRAME_MS)
		{
			// ticks 2,000 ms apart: the masked ones arrive in seconds 1, 3 and 5 only
			if (t == 1000 || t == 3000 || t == 5000)
			{
				tick(t);
			}
			frame(t);
		}
		final SecondRing seconds = session.seconds;
		assertTrue(masked(0));
		assertTrue(masked(2));
		for (long sec = 1; sec <= 5; sec += 2)
		{
			assertTrue("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
		}
		for (long sec = 2; sec <= 6; sec += 2)
		{
			assertFalse("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
		}
	}

	@Test
	public void maskedTicksMarkTheirSecondsWhileNoFrameIsDrawn()
	{
		// minimised: frames stop, ticks go on. The seconds are closed later, by the first frame that comes.
		state(0, State.HOPPING);
		run(0, 900, Long.MAX_VALUE);
		state(950, State.LOGGED_IN);
		for (long t = 1200; t <= 12_000; t += Thresholds.TICK_MS)
		{
			tick(t);
		}
		assertEquals(-1, session.seconds.frameHead());
		run(13_000, 14_000, Long.MAX_VALUE);
		final SecondRing seconds = session.seconds;
		assertEquals(13, seconds.frameHead());
		// fifteen ticks from 1,200: the last masked one arrives at 9,600
		for (long sec = 1; sec <= 9; sec++)
		{
			assertTrue("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
			assertTrue(Flags.has(seconds.flags(sec), Flags.NO_FRAMES));
		}
		for (long sec = 10; sec <= 13; sec++)
		{
			assertFalse("second " + sec, Flags.has(seconds.flags(sec), Flags.LOGIN_MASK));
		}
		assertFalse(Flags.has(seconds.flags(0), Flags.LOGIN_MASK));
	}

	@Test
	public void hopSetsTheFlag()
	{
		state(0, State.LOGGED_IN);
		run(0, 4980, 600);
		state(5000, State.HOPPING);
		for (long t = 5000; t <= 6980; t += FRAME_MS)
		{
			if (t == 5400)
			{
				tick(t);
			}
			frame(t);
		}
		state(7000, State.LOGGED_IN);
		run(7000, 20_000, 7300);

		// ticks 0 .. 7 arrived at 600 .. 4,800, tick 8 inside the hop, tick 9 after it
		assertEquals(4800L, ring.atMs(7));
		assertFalse(Flags.has(ring.flags(7), Flags.HOP));
		assertFalse(masked(7));

		assertEquals(5400L, ring.atMs(8));
		assertTrue("a tick inside the hop carries its second's flag", Flags.has(ring.flags(8), Flags.HOP));
		assertFalse(masked(8));

		for (long seq = 9; seq < 9 + Thresholds.LOGIN_MASK_TICKS; seq++)
		{
			assertTrue("tick " + seq, masked(seq));
			assertFalse(Flags.has(ring.flags(seq), Flags.HOP));
		}
		assertEquals("the first of them spans the hop", 1900, ring.gapMs(9));
		assertFalse(masked(9 + Thresholds.LOGIN_MASK_TICKS));

		final SecondRing seconds = session.seconds;
		assertFalse(Flags.has(seconds.flags(4), Flags.HOP));
		assertTrue(Flags.has(seconds.flags(5), Flags.HOP));
		assertTrue(Flags.has(seconds.flags(6), Flags.HOP));
		assertFalse(Flags.has(seconds.flags(7), Flags.HOP));
		assertTrue(Flags.has(seconds.flags(7), Flags.LOGIN_MASK));
	}

	@Test
	public void theEndOfALostConnectionMasksFifteenTicks()
	{
		state(0, State.LOGGED_IN);
		run(0, 6080, 600);
		state(6100, State.CONNECTION_LOST);
		run(6100, 14_080, Long.MAX_VALUE);
		// back with no LOGGING_IN between
		state(14_100, State.LOGGED_IN);
		run(14_100, 30_000, 14_400);

		// ticks 0 .. 9 arrived at 600 .. 6,000
		assertEquals(6000L, ring.atMs(9));
		assertFalse(masked(9));
		assertEquals(14_400L, ring.atMs(10));
		assertEquals("the tick that spans the outage", 8400, ring.gapMs(10));
		for (long seq = 10; seq < 10 + Thresholds.LOGIN_MASK_TICKS; seq++)
		{
			assertTrue("tick " + seq, masked(seq));
		}
		assertFalse(masked(10 + Thresholds.LOGIN_MASK_TICKS));
		assertTrue(Flags.has(session.seconds.flags(14), Flags.LOGIN_MASK));
		assertFalse(Flags.has(session.seconds.flags(13), Flags.LOGIN_MASK));
		assertTrue(Flags.has(session.seconds.flags(13), Flags.DISCONNECT));
	}

	@Test
	public void aMapLoadStartsNoMask()
	{
		state(0, State.LOGGED_IN);
		run(0, 2980, 600);
		state(3000, State.LOADING);
		state(3300, State.LOGGED_IN);
		run(3320, 6000, 3600);
		for (long seq = 0; seq <= ring.head(); seq++)
		{
			assertFalse("tick " + seq, masked(seq));
		}
		// the tick at 3,600 arrived in second 3, which held the load: it carries its second's flag
		assertEquals(3600L, ring.atMs(4));
		assertTrue(Flags.has(ring.flags(4), Flags.LOADING));
		assertFalse(Flags.has(ring.flags(3), Flags.LOADING));
		assertFalse(Flags.has(ring.flags(5), Flags.LOADING));
	}

	@Test
	public void aTickCarriesNoLoadingThatItsSecondDoesNotHold()
	{
		// a load from 2,800 to 2,950 ms; ticks every 600 ms from 500 ms, frames every 20 ms
		state(0, State.LOGGED_IN);
		run(0, 2780, 500);
		state(2800, State.LOADING);
		run(2800, 2940, 2900);
		state(2950, State.LOGGED_IN);
		run(2960, 5000, 3500);

		final SecondRing seconds = session.seconds;
		assertEquals(4, seconds.frameHead());
		assertEquals(150, seconds.loadingMs(2));
		assertTrue(Flags.has(seconds.flags(2), Flags.LOADING));
		assertEquals("second 3 holds no loading time", 0, seconds.loadingMs(3));
		assertFalse("and no loading frame ended in it", Flags.has(seconds.flags(3), Flags.LOADING));

		assertEquals(2900L, ring.atMs(4));
		assertTrue("a tick inside the load carries its second's flag", Flags.has(ring.flags(4), Flags.LOADING));
		assertEquals(3500L, ring.atMs(5));
		assertFalse("the load lay in this tick's gap, but not in its second", Flags.has(ring.flags(5), Flags.LOADING));
		assertEquals("exactly its second's flags as they stood", Flags.FOCUSED, ring.flags(5));
		assertFalse(Flags.has(ring.flags(6), Flags.LOADING));
	}

	@Test
	public void aTickCarriesTheFlagsOfItsSecondAsTheyStand()
	{
		state(0, State.LOGGED_IN);
		frames.focus(false);
		tick(600);
		frames.focus(true);
		state(1100, State.CONNECTION_LOST);
		tick(1200);
		state(1300, State.LOGIN_SCREEN);
		tick(1800);
		assertEquals(0, ring.flags(0));
		assertEquals(Flags.FOCUSED | Flags.DISCONNECT, ring.flags(1));
		// second 1 held lost-connection time, and the code in force at the tick is the login screen; the end of the
		// lost connection started the mask
		assertEquals(Flags.FOCUSED | Flags.DISCONNECT | Flags.NOT_LOGGED_IN | Flags.LOGIN_MASK, ring.flags(2));
	}
}

package com.whylag.core;

import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * A synthetic session written straight into the rings (contract 3.12), so the detector, the verdict and the
 * snapshot can be tested without the samplers. It never builds a {@link LagEvent}: the detector does that.
 *
 * <p><b>The frame of every trace.</b> Second 0 starts at wall time 2026-09-28T20:52:00Z, zone UTC, world 416, OS
 * WINDOWS. {@link Session#startNanos} is a fixed non-zero value.
 *
 * <p><b>The steady second</b> ({@link #steady(int)}). Every second holds exactly this, and every tick this:
 * <table>
 * <caption>The steady second</caption>
 * <tr><th>Column</th><th>Steady value</th></tr>
 * <tr><td>frames / worstFrameMs / worstFrameEndMs / slowFrames</td><td>50 / 22 / 500 / 0</td></tr>
 * <tr><td>loadingMs / state / flags / world</td><td>0 / LOGGED_IN / FOCUSED / 416</td></tr>
 * <tr><td>players / npcs / region</td><td>0 / 0 / 0 (a test that needs them sets them)</td></tr>
 * <tr><td>rttMs / rttAgeS / conn</td><td>40 / 0 (fresh) / NONE</td></tr>
 * <tr><td>sentUnits / resentUnits</td><td>900 / 0</td></tr>
 * <tr><td>each tick</td><td>one every 600 ms from session ms 0; gap 600, frameMs 22, cycle jump 30, the RTT and
 * the flags of its second. The trace's FIRST tick has no tick before it: gap 600 ({@link Thresholds#TICK_MS}) and
 * cycle jump -1, as the tick sampler writes the session's first tick (contract section 7, L2)</td></tr>
 * </table>
 * Beside the seconds, a steady trace holds:
 * <ul>
 * <li>The login: {@code loggedInSinceSec} is {@code -WARMUP_S} (0 since the first live look, 2026-09-29; it was
 * -60). The trace is WARM from second 0 and nothing
 * is masked. {@link #loginAt} sets it to its second.</li>
 * <li>NO usual: the three usuals of the session are empty (the detector fills them from the quiet seconds it
 * reads). {@link #usual} makes this world's RTT usual known.</li>
 * </ul>
 *
 * <p><b>What the builders do beyond their name.</b> Each changes only what it names, in the seconds it names (both
 * ends included), and answers this trace; a second outside the trace is an {@link IllegalArgumentException}.
 * <ul>
 * <li>{@link #fps} sets {@code frames}. It ALSO raises the worst frame to the frame interval, ceil(1000 / fps),
 * never lowers it; at an interval of {@link Thresholds#SLOW_FRAME_MS} or more every frame of the second is slow
 * ({@code slowFrames} = fps, at most 127); the ticks that arrive in those seconds carry at least that interval as
 * {@code frameMs}. {@code fps(.., 0)} is a second with no frame, as the sampler fills one: {@code frames}, the
 * worst frame and its end 0, {@code slowFrames} 0 and the NO_FRAMES flag.</li>
 * <li>{@link #frameGap} sets the worst frame and its end when it is at least as long as the second's worst so far
 * (a tie moves the end; a shorter frame leaves both alone) and, when {@code ms} is
 * {@link Thresholds#SLOW_FRAME_MS} or more, adds one slow frame; every second the frame covers WHOLE becomes a
 * no-frame second, as {@code fps(.., 0)}; ticks keep their arrival times, and those that arrive inside the frame
 * carry its length (the larger of it and their second's own frame interval). A LOADING FRAME: when any second the
 * frame touches holds loading time ({@link #loading} with more than 0 ms, called before or after), {@link #build()}
 * also sets the LOADING flag on the second the frame ends in, as the frame sampler's loading-frame rule does
 * (contract 6.1). A trace does not say where in a second its loading ms lie, so touching such a second counts as
 * overlapping its loading time. The steady frames of a second end inside it: only frameGap's frames carry a load
 * into a later second.</li>
 * <li>{@link #players}, {@link #npcs}, {@link #region} (0 .. 65535): that column.</li>
 * <li>{@link #tickLate}: the FIRST tick that arrives in the second comes {@code lateMs} later; with catch-up the
 * ones after keep their times (so the next gap is 600 - late, and a late tick that would reach the next one is
 * refused), without it that tick and every later tick move by the same amount. {@link #ticksEvery}: the ticks
 * arriving in the span are replaced by ones {@code gapMs} apart - the first is {@code gapMs} after the last tick
 * before the span, stepped on by {@code gapMs} until it lies in the span (the span's first ms when no tick comes
 * before it) - and every tick after the span moves so the first of them comes {@link Thresholds#TICK_MS} after the
 * span's last; when that moves them earlier, new ticks 600 apart carry on after the last moved one and fill the hole
 * up to where the old ones ended: up to the old last tick's time, or, when that old last tick lay in the trace's
 * final 600 ms (the grid ran to the end), up to the trace's last ms. A tick that {@link #tickLate} or
 * {@link #ticksEvery} moves past the trace's last ms (to session ms {@code n x 1000} or later, for a trace of n
 * seconds) is dropped. A {@link #ticksEvery} gap that puts no tick in its span is refused. {@link #noTicks}: the
 * ticks arriving in the span are removed.</li>
 * <li>{@link #rtt}: RTT, fresh (0 ms or more). {@link #rttNoData}: RTT and age -1 with the reason. {@link #rttStale}:
 * the RTT kept, its age past {@link Thresholds#RTT_STALE_S} and growing, reason STALE. So {@code conn} is NONE in
 * exactly the seconds whose RTT is fresh, in every trace (contract 3.3). {@link #usual}: this world's usual RTT;
 * {@link #build()} adds {@link Thresholds#USUAL_MIN_SAMPLES} samples of it to {@code Session.rttUsual} and touches
 * no ring (the last call wins).</li>
 * <li>{@link #sent}, {@link #resent} ({@code resent} does not add to {@code sent}): that column.</li>
 * <li>{@link #loading}: {@code loadingMs} and the LOADING flag, in that second only (a {@link #frameGap} frame that
 * touches it also flags the second that frame ends in, above).</li>
 * <li>{@link #hop}: the HOP flag and state HOPPING in its second, the new world from it on, and - as the tick
 * sampler does - the LOGIN_MASK flag on the seconds of the next {@link Thresholds#LOGIN_MASK_TICKS} ticks from the
 * start of the next second. It does not move the login.</li>
 * <li>{@link #disconnect}: a one-second lost connection. The DISCONNECT flag and state CONNECTION_LOST in that
 * second (so a trace that ends there reads "Not logged in" at its newest second: CONNECTION_LOST is not in-game),
 * and - as the tick sampler does when a lost connection ends - the LOGIN_MASK flag on the seconds of the next
 * {@link Thresholds#LOGIN_MASK_TICKS} ticks from the start of the next second. It does not move the login.
 * Neither a hop nor a disconnect sets NOT_LOGGED_IN: the samplers set it only on OTHER, LOGIN_SCREEN and
 * LOGGING_IN seconds (contract section 7, L2).</li>
 * <li>{@link #loginAt}: every second before it is at the login screen (state LOGIN_SCREEN, NOT_LOGGED_IN, no
 * tick, nothing sent, ping NOT_LOGGED_IN); the first {@link Thresholds#LOGIN_MASK_TICKS} ticks from it on are
 * masked; {@code loggedInSinceSec} is its second.</li>
 * <li>{@link #unfocused}: the FOCUSED flag cleared. {@link #os}: the session's OS (and the default settings').
 * {@link #settings(SettingsView)}: what {@link #settings()} answers; it writes no ring.</li>
 * <li>{@link #shift}: k steady seconds come first, and every second, tick, frame and mask moves later
 * by k seconds. A login set by
 * {@link #loginAt} moves, and then the k new seconds are login-screen seconds as {@link #loginAt} writes them (no
 * tick, nothing sent, ping NOT_LOGGED_IN), so every second before the login is still at the login screen; the
 * steady login stays at {@code -WARMUP_S}. Without {@link #loginAt} the new seconds are ordinary steady seconds,
 * with ticks on the same 600 ms grid: a detector finds them quiet and feeds its usuals from them, so a shift can
 * make a usual exist sooner (contract section 7, L3, bounds its property test for that).</li>
 * </ul>
 *
 * <p><b>Default settings</b> ({@link #settings()}): renderer CPU (cap 50, CLIENT_50), refresh 60, FPS Control
 * inactive, every renderer key unread (0 or ""), client version "". The steady 900 bytes a second is over {@link Thresholds#CLICK_SENT_BYTES} on purpose: the click filter is a JUMP over the
 * quiet median, so a steady sender can still spike.
 *
 * <p>Every tick carries the flags and the RTT of the second it arrives in. {@link #build()} can be called any
 * number of times; each call answers a fresh {@link Session}. A trace longer than a ring wraps it, as a real
 * session would.
 *
 * <p><b>Now.</b> A test that asks for "now" at the end of a trace of n seconds passes {@code nowSec = n}: second
 * n - 1 is then the newest complete second, as in a live step ({@link Session#lastSec}). An earlier {@code nowSec}
 * replays the trace as it stood then.
 */
public final class Trace
{
	private static final long START_NANOS = 7_000_000_000_000L;
	private static final long START_WALL_MS = Instant.parse("2026-09-28T20:52:00Z").toEpochMilli();
	private static final int MS = 1000;
	private static final int TICK = Thresholds.TICK_MS;
	private static final int CYCLE_MS = 20;
	private static final int LAST_MS = 999;
	private static final int BYTE_MAX = 127;
	private static final int REGION_MAX = 65_535;

	private static final int FPS = 50;
	private static final int WORST_MS = 22;
	private static final int WORST_END_MS = 500;
	private static final int WORLD_ID = 416;
	private static final int RTT_MS = 40;
	private static final int SENT_UNITS = 900;
	private static final int REFRESH_HZ = 60;

	// Per-second columns, in the ring's order; TICK_FRAME is the frame a tick in that second carries.
	private static final int FRAMES = 0, WORST = 1, WORST_END = 2, SLOW = 3, LOADING = 4, STATE = 5, FLAGS = 6,
		WORLD = 7, PLAYERS = 8, NPCS = 9, REGION = 10, RTT = 11, RTT_AGE = 12, SENT = 13, RESENT = 14,
		TICK_FRAME = 15;
	private static final int COLUMNS = 16;
	private static final int[] STEADY = new int[COLUMNS];

	static
	{
		STEADY[FRAMES] = FPS;
		STEADY[WORST] = WORST_MS;
		STEADY[WORST_END] = WORST_END_MS;
		STEADY[SLOW] = 0;
		STEADY[LOADING] = 0;
		STEADY[STATE] = State.LOGGED_IN;
		STEADY[FLAGS] = Flags.FOCUSED;
		STEADY[WORLD] = WORLD_ID;
		STEADY[PLAYERS] = 0;
		STEADY[NPCS] = 0;
		STEADY[REGION] = 0;
		STEADY[RTT] = RTT_MS;
		STEADY[RTT_AGE] = 0;
		STEADY[SENT] = SENT_UNITS;
		STEADY[RESENT] = 0;
		STEADY[TICK_FRAME] = WORST_MS;
	}

	private int n;
	private int[][] col;
	private NoData[] conn;
	/** Tick arrival times, session ms, ascending. */
	private final List<Integer> ticks = new ArrayList<>();
	/** Long frames: {start ms, end ms, length}. */
	private final List<long[]> frameGaps = new ArrayList<>();
	/** Session ms from which the next LOGIN_MASK_TICKS ticks are masked. */
	private final List<Long> maskStarts = new ArrayList<>();
	/** The session second of the login: the steady -WARMUP_S until {@link #loginAt} sets it. */
	private long loggedInSince = -Thresholds.WARMUP_S;
	private boolean loginSet;
	/** This world's usual RTT, or -1: none (the steady trace has no usual). */
	private int usualRttMs = -1;
	private Os os = Os.WINDOWS;
	private SettingsView settings;

	private Trace()
	{
	}

	/** {@code seconds} steady seconds (see the class notes). */
	public static Trace steady(int seconds)
	{
		if (seconds < 1)
		{
			throw new IllegalArgumentException("a trace needs at least one second, got " + seconds);
		}
		final Trace t = new Trace();
		t.n = seconds;
		t.col = new int[COLUMNS][seconds];
		for (int c = 0; c < COLUMNS; c++)
		{
			Arrays.fill(t.col[c], STEADY[c]);
		}
		t.conn = new NoData[seconds];
		Arrays.fill(t.conn, NoData.NONE);
		for (int at = 0; at < seconds * MS; at += TICK)
		{
			t.ticks.add(at);
		}
		return t;
	}

	/** {@code fps} frames a second in {@code fromSec .. toSec} (see the class notes). */
	public Trace fps(int fromSec, int toSec, int fps)
	{
		checkSpan(fromSec, toSec);
		if (fps < 0)
		{
			throw new IllegalArgumentException("fps must be 0 or more, got " + fps);
		}
		for (int s = fromSec; s <= toSec; s++)
		{
			if (fps == 0)
			{
				noFrames(s);
				continue;
			}
			final int interval = (MS + fps - 1) / fps;
			col[FRAMES][s] = fps;
			col[FLAGS][s] &= ~Flags.NO_FRAMES;
			col[WORST][s] = Math.max(col[WORST][s], interval);
			if (interval >= Thresholds.SLOW_FRAME_MS)
			{
				col[SLOW][s] = Math.min(fps, BYTE_MAX);
			}
			col[TICK_FRAME][s] = Math.max(col[TICK_FRAME][s], interval);
		}
		return this;
	}

	/**
	 * One frame of {@code ms} that ENDS {@code endOffsetMs} (0 .. 999) into {@code atSec}; ticks inside it carry
	 * {@code ms}. There is no two-argument form: every test says where the freeze was. It becomes the second's worst
	 * frame when it is at least as long as the worst so far, and a loading frame when it touches a second with
	 * loading time (see the class notes).
	 */
	public Trace frameGap(int atSec, int endOffsetMs, int ms)
	{
		checkSecond(atSec);
		if (endOffsetMs < 0 || endOffsetMs > LAST_MS)
		{
			throw new IllegalArgumentException("the end offset is 0 .. 999, got " + endOffsetMs);
		}
		if (ms < 0)
		{
			throw new IllegalArgumentException("a frame lasts 0 ms or more, got " + ms);
		}
		final long end = (long) atSec * MS + endOffsetMs;
		final long start = end - ms;
		if (ms >= col[WORST][atSec])
		{
			col[WORST][atSec] = ms;
			col[WORST_END][atSec] = endOffsetMs;
		}
		if (ms >= Thresholds.SLOW_FRAME_MS)
		{
			col[SLOW][atSec] = Math.min(BYTE_MAX, col[SLOW][atSec] + 1);
		}
		// A second the frame covers whole ended no frame: the sampler writes it as a NO_FRAMES second.
		for (long s = Math.floorDiv(start, MS) + 1; s < atSec; s++)
		{
			if (s >= 0)
			{
				noFrames((int) s);
			}
		}
		frameGaps.add(new long[] {start, end, ms});
		return this;
	}

	/** {@code n} players in the scene in {@code fromSec .. toSec}. */
	public Trace players(int fromSec, int toSec, int n)
	{
		checkSpan(fromSec, toSec);
		checkCount("players", n);
		for (int s = fromSec; s <= toSec; s++)
		{
			col[PLAYERS][s] = n;
		}
		return this;
	}

	/** {@code n} NPCs in the scene in {@code fromSec .. toSec}. */
	public Trace npcs(int fromSec, int toSec, int n)
	{
		checkSpan(fromSec, toSec);
		checkCount("npcs", n);
		for (int s = fromSec; s <= toSec; s++)
		{
			col[NPCS][s] = n;
		}
		return this;
	}

	/** The map region {@code id} (0 .. 65535) in {@code fromSec .. toSec}. */
	public Trace region(int fromSec, int toSec, int id)
	{
		checkSpan(fromSec, toSec);
		if (id < 0 || id > REGION_MAX)
		{
			throw new IllegalArgumentException("a region id is 0 .. 65535, got " + id);
		}
		for (int s = fromSec; s <= toSec; s++)
		{
			col[REGION][s] = id;
		}
		return this;
	}

	/** The first tick of {@code atSec} comes {@code lateMs} late: gap 600 + late; next gap 600 - late if catchUp. */
	public Trace tickLate(int atSec, int lateMs, boolean catchUp)
	{
		checkSecond(atSec);
		if (lateMs < 0)
		{
			throw new IllegalArgumentException("late is 0 ms or more, got " + lateMs);
		}
		final int idx = firstTickFrom(atSec * MS);
		if (idx < 0 || ticks.get(idx) >= (atSec + 1) * MS)
		{
			throw new IllegalArgumentException("no tick arrives in second " + atSec);
		}
		final int arrives = ticks.get(idx) + lateMs;
		if (catchUp)
		{
			if (idx + 1 < ticks.size() && arrives >= ticks.get(idx + 1))
			{
				throw new IllegalArgumentException("a late tick that catches up must still come before the next one");
			}
			ticks.set(idx, arrives);
		}
		else
		{
			for (int i = idx; i < ticks.size(); i++)
			{
				ticks.set(i, ticks.get(i) + lateMs);
			}
		}
		dropTicksPastTheEnd();
		return this;
	}

	/**
	 * Ticks {@code gapMs} apart in {@code fromSec .. toSec}; the ones after resume 600 after the last of them (see
	 * the class notes). A gap that puts no tick in the span is refused, and the trace is left as it was: a span with
	 * no tick is {@link #noTicks}.
	 */
	public Trace ticksEvery(int fromSec, int toSec, int gapMs)
	{
		checkSpan(fromSec, toSec);
		if (gapMs <= 0)
		{
			throw new IllegalArgumentException("a gap is 1 ms or more, got " + gapMs);
		}
		final int lo = fromSec * MS;
		final int hi = (toSec + 1) * MS;
		// The tick before the span is not replaced, so the first new tick is known before anything changes.
		final int before = lastTickBefore(lo);
		int at = before == Integer.MIN_VALUE ? lo : before + gapMs;
		while (at < lo)
		{
			at += gapMs;
		}
		if (at >= hi)
		{
			throw new IllegalArgumentException("a gap of " + gapMs + " ms puts no tick in " + fromSec + " .. " + toSec
				+ "; a span with no tick is noTicks");
		}
		final int oldLast = ticks.isEmpty() ? Integer.MIN_VALUE : ticks.get(ticks.size() - 1);
		removeTicks(lo, hi);
		int insertAt = firstTickFrom(lo);
		if (insertAt < 0)
		{
			insertAt = ticks.size();
		}
		int last = at;
		for (; at < hi; at += gapMs)
		{
			ticks.add(insertAt++, at);
			last = at;
		}
		if (insertAt < ticks.size())
		{
			final int delta = last + TICK - ticks.get(insertAt);
			for (int i = insertAt; i < ticks.size(); i++)
			{
				ticks.set(i, ticks.get(i) + delta);
			}
			dropTicksPastTheEnd();
			if (delta < 0)
			{
				// Moving earlier left a hole where the old ticks ended; carry the 600 ms grid back over it.
				final int until = oldLast >= n * MS - TICK ? n * MS - 1 : oldLast;
				for (int t = ticks.get(ticks.size() - 1) + TICK; t <= until; t += TICK)
				{
					ticks.add(t);
				}
			}
		}
		return this;
	}

	/** No tick arrives in {@code fromSec .. toSec}. */
	public Trace noTicks(int fromSec, int toSec)
	{
		checkSpan(fromSec, toSec);
		removeTicks(fromSec * MS, (toSec + 1) * MS);
		return this;
	}

	/** A fresh RTT of {@code ms} (0 or more; no RTT is {@link #rttNoData}) in {@code fromSec .. toSec}. */
	public Trace rtt(int fromSec, int toSec, int ms)
	{
		checkSpan(fromSec, toSec);
		if (ms < 0)
		{
			throw new IllegalArgumentException("a fresh RTT is 0 ms or more, got " + ms + "; no RTT is rttNoData");
		}
		for (int s = fromSec; s <= toSec; s++)
		{
			col[RTT][s] = ms;
			col[RTT_AGE][s] = 0;
			conn[s] = NoData.NONE;
		}
		return this;
	}

	/** No RTT in {@code fromSec .. toSec}, for the reason {@code why} (never {@link NoData#NONE}). */
	public Trace rttNoData(int fromSec, int toSec, NoData why)
	{
		checkSpan(fromSec, toSec);
		if (why == null || why == NoData.NONE)
		{
			throw new IllegalArgumentException("no data needs a reason");
		}
		for (int s = fromSec; s <= toSec; s++)
		{
			col[RTT][s] = -1;
			col[RTT_AGE][s] = -1;
			conn[s] = why;
		}
		return this;
	}

	/** The RTT goes stale in {@code fromSec .. toSec}: kept, but older than {@link Thresholds#RTT_STALE_S}. */
	public Trace rttStale(int fromSec, int toSec)
	{
		checkSpan(fromSec, toSec);
		for (int s = fromSec; s <= toSec; s++)
		{
			col[RTT_AGE][s] = Thresholds.RTT_STALE_S + 1 + (s - fromSec);
			conn[s] = NoData.STALE;
		}
		return this;
	}

	/**
	 * This world's usual RTT: {@link #build()} adds {@link Thresholds#USUAL_MIN_SAMPLES} samples of {@code rttMs} to
	 * {@code Session.rttUsual}, so its median is {@code rttMs}. The session usual and the frame rate usual stay
	 * empty, and no ring changes. The last call wins; {@link #shift} keeps it.
	 */
	public Trace usual(int rttMs)
	{
		if (rttMs < 0)
		{
			throw new IllegalArgumentException("a usual RTT is 0 ms or more, got " + rttMs);
		}
		usualRttMs = rttMs;
		return this;
	}

	/** {@code unitsPerSecond} sent in each second of {@code fromSec .. toSec}. */
	public Trace sent(int fromSec, int toSec, int unitsPerSecond)
	{
		checkSpan(fromSec, toSec);
		for (int s = fromSec; s <= toSec; s++)
		{
			col[SENT][s] = unitsPerSecond;
		}
		return this;
	}

	/** {@code units} re-sent in {@code atSec}. */
	public Trace resent(int atSec, int units)
	{
		checkSecond(atSec);
		col[RESENT][atSec] = units;
		return this;
	}

	/** {@code ms} of LOADING in {@code atSec}: its {@code loadingMs} and the LOADING flag, in that second only. */
	public Trace loading(int atSec, int ms)
	{
		checkSecond(atSec);
		if (ms < 0 || ms > MS)
		{
			throw new IllegalArgumentException("a second holds 0 .. 1000 ms of loading, got " + ms);
		}
		col[LOADING][atSec] = ms;
		col[FLAGS][atSec] |= Flags.LOADING;
		return this;
	}

	/** A hop to {@code newWorld} in {@code atSec} (see the class notes). It does not move the login. */
	public Trace hop(int atSec, int newWorld)
	{
		checkSecond(atSec);
		col[FLAGS][atSec] |= Flags.HOP;
		col[STATE][atSec] = State.HOPPING;
		for (int s = atSec; s < n; s++)
		{
			col[WORLD][s] = newWorld;
		}
		maskStarts.add((long) (atSec + 1) * MS);
		return this;
	}

	/**
	 * The connection is lost in {@code atSec} and back in the next second: the DISCONNECT flag and state
	 * CONNECTION_LOST in {@code atSec}, and - as the tick sampler does when a lost connection ends - the LOGIN_MASK
	 * flag on the seconds of the next {@link Thresholds#LOGIN_MASK_TICKS} ticks from the start of the next second.
	 * It does not move the login.
	 */
	public Trace disconnect(int atSec)
	{
		checkSecond(atSec);
		col[FLAGS][atSec] |= Flags.DISCONNECT;
		col[STATE][atSec] = State.CONNECTION_LOST;
		maskStarts.add((long) (atSec + 1) * MS);
		return this;
	}

	/** The player logs in at {@code sec}: the seconds before it are at the login screen (see the class notes). */
	public Trace loginAt(int sec)
	{
		checkSecond(sec);
		for (int s = 0; s < sec; s++)
		{
			loginScreen(s);
		}
		removeTicks(Integer.MIN_VALUE, sec * MS);
		maskStarts.add((long) sec * MS);
		loggedInSince = sec;
		loginSet = true;
		return this;
	}

	/** Second {@code s} at the login screen, as {@link #loginAt} writes the seconds before the login. */
	private void loginScreen(int s)
	{
		col[STATE][s] = State.LOGIN_SCREEN;
		col[FLAGS][s] |= Flags.NOT_LOGGED_IN;
		col[RTT][s] = -1;
		col[RTT_AGE][s] = -1;
		col[SENT][s] = 0;
		col[RESENT][s] = 0;
		conn[s] = NoData.NOT_LOGGED_IN;
	}

	/** The window is not focused in {@code fromSec .. toSec}. */
	public Trace unfocused(int fromSec, int toSec)
	{
		checkSpan(fromSec, toSec);
		for (int s = fromSec; s <= toSec; s++)
		{
			col[FLAGS][s] &= ~Flags.FOCUSED;
		}
		return this;
	}

	/** The session's operating system, and the default settings' too. */
	public Trace os(Os os)
	{
		if (os == null)
		{
			throw new IllegalArgumentException("an OS is needed");
		}
		this.os = os;
		return this;
	}

	/** What {@link #settings()} answers from now on. */
	public Trace settings(SettingsView s)
	{
		settings = s;
		return this;
	}

	/**
	 * The same trace, {@code seconds} later: steady seconds first, everything else moved by as much. After
	 * {@link #loginAt} the new seconds are at the login screen, with no tick, so every second before the login still
	 * is (see the class notes).
	 */
	public Trace shift(int seconds)
	{
		if (seconds < 0)
		{
			throw new IllegalArgumentException("a trace moves later, not earlier: " + seconds);
		}
		if (seconds == 0)
		{
			return this;
		}
		final int k = seconds;
		final int[][] moved = new int[COLUMNS][n + k];
		for (int c = 0; c < COLUMNS; c++)
		{
			Arrays.fill(moved[c], 0, k, STEADY[c]);
			System.arraycopy(col[c], 0, moved[c], k, n);
		}
		col = moved;
		final NoData[] movedConn = new NoData[n + k];
		Arrays.fill(movedConn, 0, k, NoData.NONE);
		System.arraycopy(conn, 0, movedConn, k, n);
		conn = movedConn;
		if (loginSet)
		{
			for (int s = 0; s < k; s++)
			{
				loginScreen(s);
			}
		}

		final int by = k * MS;
		for (int i = 0; i < ticks.size(); i++)
		{
			ticks.set(i, ticks.get(i) + by);
		}
		if (!loginSet)
		{
			// The filler's ticks meet the moved ones on the same 600 ms grid.
			final List<Integer> filler = new ArrayList<>();
			for (int at = by % TICK; at < by; at += TICK)
			{
				filler.add(at);
			}
			ticks.addAll(0, filler);
		}
		for (long[] f : frameGaps)
		{
			f[0] += by;
			f[1] += by;
		}
		for (int i = 0; i < maskStarts.size(); i++)
		{
			maskStarts.set(i, maskStarts.get(i) + by);
		}
		if (loginSet)
		{
			loggedInSince += k;
		}
		n += k;
		return this;
	}

	/** A fresh session holding this trace. */
	public Session build()
	{
		final Session s = new Session(START_NANOS, START_WALL_MS, os, ZoneOffset.UTC);
		final int[] flags = col[FLAGS].clone();
		// A loading frame (contract 6.1): a frameGap frame that touches a second with loading time flags the second
		// it ends in, as the frame sampler does. Where in a second its loading ms lie is not said, so a touch counts.
		for (long[] g : frameGaps)
		{
			final int endSec = (int) Math.floorDiv(g[1], MS);
			for (long sec = Math.max(0, Math.floorDiv(g[0], MS)); sec <= endSec && sec < n; sec++)
			{
				if (col[LOADING][(int) sec] > 0)
				{
					flags[endSec] |= Flags.LOADING;
					break;
				}
			}
		}
		final boolean[] masked = new boolean[ticks.size()];
		for (long start : maskStarts)
		{
			int left = Thresholds.LOGIN_MASK_TICKS;
			for (int i = 0; i < ticks.size() && left > 0; i++)
			{
				if (ticks.get(i) >= start)
				{
					masked[i] = true;
					left--;
				}
			}
		}
		for (int i = 0; i < ticks.size(); i++)
		{
			if (masked[i])
			{
				flags[ticks.get(i) / MS] |= Flags.LOGIN_MASK;
			}
		}

		final FrameSecond f = new FrameSecond();
		final HostSecond h = new HostSecond();
		for (int sec = 0; sec < n; sec++)
		{
			f.frames = col[FRAMES][sec];
			f.worstFrameMs = col[WORST][sec];
			f.worstFrameEndMs = col[WORST_END][sec];
			f.slowFrames = col[SLOW][sec];
			f.loadingMs = col[LOADING][sec];
			f.state = col[STATE][sec];
			f.flags = flags[sec];
			f.world = col[WORLD][sec];
			f.players = col[PLAYERS][sec];
			f.npcs = col[NPCS][sec];
			f.region = col[REGION][sec];
			s.seconds.putFrame(sec, f);
			h.rttMs = col[RTT][sec];
			h.rttAgeS = col[RTT_AGE][sec];
			h.sentUnits = col[SENT][sec];
			h.resentUnits = col[RESENT][sec];
			h.conn = conn[sec];
			s.seconds.putHost(sec, h);
		}

		final TickRow row = new TickRow();
		boolean first = true;
		int previous = 0;
		for (int at : ticks)
		{
			final int sec = at / MS;
			row.atMs = (long) at;
			// The first tick has no tick before it: the steady gap and no cycle jump, as the tick sampler writes
			// the session's first tick (contract section 7, L2).
			row.gapMs = first ? TICK : at - previous;
			row.frameMs = frameOfTickAt(at, sec);
			row.cycleJump = first ? -1 : (row.gapMs + CYCLE_MS / 2) / CYCLE_MS;
			row.rttMs = col[RTT][sec];
			row.flags = flags[sec];
			s.ticks.put(row);
			previous = at;
			first = false;
		}

		s.loggedInSince(loggedInSince);
		if (usualRttMs >= 0)
		{
			for (int i = 0; i < Thresholds.USUAL_MIN_SAMPLES; i++)
			{
				s.rttUsual.add(usualRttMs);
			}
		}
		return s;
	}

	/** The explicit settings, or the default ones (see the class notes). */
	public SettingsView settings()
	{
		if (settings != null)
		{
			return settings;
		}
		return new SettingsView(Renderer.CPU, false, false, 0, false, 0, false, "", 0, 0, "", 0, REFRESH_HZ, os, "");
	}

	/** How many seconds the trace holds. */
	public int seconds()
	{
		return n;
	}

	private int frameOfTickAt(int at, int sec)
	{
		long ms = col[TICK_FRAME][sec];
		for (long[] g : frameGaps)
		{
			if (at >= g[0] && at <= g[1])
			{
				ms = Math.max(ms, g[2]);
			}
		}
		return (int) ms;
	}

	private void noFrames(int s)
	{
		col[FRAMES][s] = 0;
		col[WORST][s] = 0;
		col[WORST_END][s] = 0;
		col[SLOW][s] = 0;
		col[FLAGS][s] |= Flags.NO_FRAMES;
	}

	/** The newest tick before {@code ms}, or {@link Integer#MIN_VALUE} when none is. */
	private int lastTickBefore(int ms)
	{
		int found = Integer.MIN_VALUE;
		for (int at : ticks)
		{
			if (at >= ms)
			{
				break;
			}
			found = at;
		}
		return found;
	}

	/** The index of the first tick at or after {@code ms}, or -1. */
	private int firstTickFrom(int ms)
	{
		for (int i = 0; i < ticks.size(); i++)
		{
			if (ticks.get(i) >= ms)
			{
				return i;
			}
		}
		return -1;
	}

	private void removeTicks(int fromMs, int toMsExclusive)
	{
		ticks.removeIf(at -> at >= fromMs && at < toMsExclusive);
	}

	private void dropTicksPastTheEnd()
	{
		final int end = n * MS;
		ticks.removeIf(at -> at >= end);
	}

	private void checkSecond(int sec)
	{
		if (sec < 0 || sec >= n)
		{
			throw new IllegalArgumentException("second " + sec + " is outside the trace (0 .. " + (n - 1) + ")");
		}
	}

	private void checkSpan(int fromSec, int toSec)
	{
		checkSecond(fromSec);
		checkSecond(toSec);
		if (toSec < fromSec)
		{
			throw new IllegalArgumentException("the span " + fromSec + " .. " + toSec + " runs backwards");
		}
	}

	private static void checkCount(String what, int count)
	{
		if (count < 0)
		{
			throw new IllegalArgumentException(what + " is a count, 0 or more; got " + count);
		}
	}
}

package com.whylag.core;

import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * The shared test helper does what contract 3.12 says: a steady trace is 50 fps, 600 ms ticks and no re-sends in
 * every second and a login at 0 that makes it warm from second 0; and each builder method changes ONLY what it names
 * (and what 3.12 says it changes beyond its name). Every change below is measured against a steady trace of the same length, column by column and
 * second by second, so a builder that touched one column too many fails here rather than inside another lot's test.
 */
public class TraceTest
{
	private static final int N = 100;

	// ---------------------------------------------------------------- the steady trace

	@Test
	public void aSteadyTraceIsFiftyFpsSixHundredMsTicksAndNoResendsInEverySecond()
	{
		final Session s = Trace.steady(300).build();
		final SecondRing r = s.seconds;
		assertEquals(0, r.tail());
		assertEquals(299, r.head());
		for (long sec = 0; sec < 300; sec++)
		{
			assertEquals("frames @" + sec, 50, r.frames(sec));
			assertEquals("re-sent @" + sec, 0, r.resentUnits(sec));
			assertEquals(22, r.worstFrameMs(sec));
			assertEquals(500, r.worstFrameEndMs(sec));
			assertEquals(0, r.slowFrames(sec));
			assertEquals(0, r.loadingMs(sec));
			assertEquals(State.LOGGED_IN, r.state(sec));
			assertEquals("focused, logged in, nothing masked", Flags.FOCUSED, r.flags(sec));
			assertEquals(416, r.world(sec));
			assertEquals(40, r.rttMs(sec));
			assertEquals("fresh", 0, r.rttAgeS(sec));
			assertEquals(900, r.sentUnits(sec));
			assertEquals(NoData.NONE, r.conn(sec));
		}
		final TickRing t = s.ticks;
		assertEquals("300 s of ticks 600 ms apart", 499, t.head());
		for (long q = t.tail(); q <= t.head(); q++)
		{
			assertEquals(600 * q, t.atMs(q));
			assertEquals("the first tick too has the steady gap", 600, t.gapMs(q));
			assertEquals(22, t.frameMs(q));
			assertEquals("the first tick has no tick before it: no cycle jump", q == 0 ? -1 : 30, t.cycleJump(q));
			assertEquals(0, t.corrected(q));
		}
	}

	@Test
	public void theFrameOfEveryTrace()
	{
		final Trace trace = Trace.steady(10);
		final Session s = trace.build();
		assertEquals(Instant.parse("2026-09-28T20:52:00Z").toEpochMilli(), s.startWallMs);
		assertEquals(ZoneOffset.UTC, s.zone);
		assertEquals("20:52", Fmt.clock(s.wallMsOf(0), s.zone));
		assertEquals(Os.WINDOWS, s.os);
		assertEquals(10, trace.seconds());
		assertEquals(0, s.secOf(s.startNanos));
		assertEquals("second 0 starts at the start", 1, s.secOf(s.startNanos + 1_000_000_000L));
	}

	@Test
	public void theDefaultSettingsAreTheClientsOwnFiftyFpsCap()
	{
		final SettingsView v = Trace.steady(10).settings();
		assertEquals(Renderer.CPU, v.renderer);
		assertEquals(50, v.capFps(true));
		assertEquals(CapSource.CLIENT_50, v.capSource(true));
		assertEquals(60, v.refreshHz);
		assertEquals(Os.WINDOWS, v.os);
		assertFalse(v.fpsControlActive);
	}

	/** The steady login is at -WARMUP_S (0 since the first live look): warm from second 0, nothing to wait for. */
	@Test
	public void aSteadyTraceIsAlreadyWarm()
	{
		final Session s = Trace.steady(10).build();
		assertEquals(-Thresholds.WARMUP_S, s.loggedInSinceSec());
		assertTrue(s.warm(0));
		assertEquals(0, s.warmupLeftS(0));
		assertEquals("a shift keeps the steady login", -Thresholds.WARMUP_S,
			Trace.steady(10).shift(20).build().loggedInSinceSec());
	}

	/**
	 * {@code loginAt(30)}: the login is at 30, warm WARMUP_S after it (at 30 itself since the first live look, not at
	 * 29); a shift moves a login that loginAt set.
	 */
	@Test
	public void loginAtSetsTheLogin()
	{
		final Session s = Trace.steady(200).loginAt(30).build();
		assertEquals(30, s.loggedInSinceSec());
		assertFalse(s.warm(30 + Thresholds.WARMUP_S - 1));
		assertTrue(s.warm(30 + Thresholds.WARMUP_S));
		assertEquals(Math.max(0, Thresholds.WARMUP_S - 20), s.warmupLeftS(50));
		assertEquals("shift moves it", 50, Trace.steady(200).loginAt(30).shift(20).build().loggedInSinceSec());
		assertEquals("a hop does not move it", 30, Trace.steady(200).loginAt(30).hop(100, 302).build()
			.loggedInSinceSec());
	}

	@Test
	public void buildCanBeCalledAgainAndAnswersAFreshEqualSession()
	{
		final Trace trace = Trace.steady(N).frameGap(50, 500, 450).hop(70, 302);
		final Session a = trace.build();
		final Session b = trace.build();
		assertNotSameSession(a, b);
		assertEquals(seconds(a), seconds(b));
		assertEquals(ticks(a), ticks(b));
	}

	@Test
	public void everyTickCarriesTheFlagsAndThePingOfItsSecond()
	{
		final Session s = Trace.steady(N).unfocused(10, 20).rtt(30, 40, 85).loading(45, 300).hop(60, 302)
			.rttNoData(80, 85, NoData.ERROR).build();
		for (long q = s.ticks.tail(); q <= s.ticks.head(); q++)
		{
			final long sec = s.ticks.atMs(q) / 1000;
			assertEquals("tick " + q, s.seconds.flags(sec), s.ticks.flags(q));
			assertEquals("tick " + q, s.seconds.rttMs(sec), s.ticks.rttMs(q));
		}
	}

	@Test
	public void aTraceLongerThanTheRingWrapsIt()
	{
		final Session s = Trace.steady(4000).build();
		assertEquals(3999, s.seconds.head());
		assertEquals("the ring keeps its 3,600 readable seconds", 3600, s.seconds.head() - s.seconds.tail() + 1);
	}

	@Test
	public void aSecondOutsideTheTraceIsRefused()
	{
		final Trace t = Trace.steady(10);
		refused(() -> t.fps(5, 10, 30));
		refused(() -> t.loading(-1, 500));
		refused(() -> t.frameGap(5, 1000, 300));
		refused(() -> t.rtt(6, 5, 40));
		refused(() -> t.rttNoData(1, 2, NoData.NONE));
		refused(() -> t.shift(-1));
	}

	// ---------------------------------------------------------------- each builder changes only what it names

	@Test
	public void fpsChangesTheFrameRateOfItsSecondsOnly()
	{
		final Session s = Trace.steady(N).fps(40, 42, 24).build();
		assertChanged(s, keys().span("frames", 40, 42).span("worstFrameMs", 40, 42));
		for (long sec = 40; sec <= 42; sec++)
		{
			assertEquals(24, s.seconds.frames(sec));
			assertEquals("the frame interval at 24 fps", 42, s.seconds.worstFrameMs(sec));
		}
		assertTickTimingUnchanged(s);
		assertTickFrames(s, 40_000, 43_000, 42);
	}

	@Test
	public void fpsUnderTwentyMakesEveryFrameSlow()
	{
		final Session s = Trace.steady(N).fps(40, 40, 8).build();
		assertChanged(s, keys().span("frames", 40, 40).span("worstFrameMs", 40, 40).span("slowFrames", 40, 40));
		assertEquals(125, s.seconds.worstFrameMs(40));
		assertEquals(8, s.seconds.slowFrames(40));
		assertTickFrames(s, 40_000, 41_000, 125);
	}

	@Test
	public void fpsZeroIsASecondWithNoFrame()
	{
		final Session s = Trace.steady(N).fps(40, 41, 0).build();
		assertChanged(s, keys().span("frames", 40, 41).span("worstFrameMs", 40, 41).span("worstFrameEndMs", 40, 41)
			.span("flags", 40, 41));
		assertEquals(Flags.FOCUSED | Flags.NO_FRAMES, s.seconds.flags(40));
		assertEquals(0, s.seconds.frames(41));
		assertTickTimingUnchanged(s);
	}

	@Test
	public void frameGapChangesItsSecondAndTheTicksInsideIt()
	{
		// 50.050 .. 50.500: the tick at 50.400 arrives inside the frame; the ones at 49.800 and 51.000 do not.
		final Session s = Trace.steady(N).frameGap(50, 500, 450).build();
		assertChanged(s, keys().span("worstFrameMs", 50, 50).span("slowFrames", 50, 50));
		assertEquals(450, s.seconds.worstFrameMs(50));
		assertEquals("it ended 500 ms into the second", 500, s.seconds.worstFrameEndMs(50));
		assertEquals(1, s.seconds.slowFrames(50));
		assertTickTimingUnchanged(s);
		assertTickFrames(s, 50_050, 50_501, 450);
	}

	/**
	 * A frame under {@link Thresholds#SLOW_FRAME_MS} is the worst frame of its second but not a slow one: 3.12's
	 * "adds one slow frame when ms is SLOW_FRAME_MS or more", pinned at the line and one below it.
	 */
	@Test
	public void frameGapAddsASlowFrameOnlyFromSlowFrameMs()
	{
		// 50.390 .. 50.420: longer than the steady 22 ms, so the worst frame; the tick at 50.400 is inside it.
		final Session s = Trace.steady(N).frameGap(50, 420, 30).build();
		assertChanged(s, keys().span("worstFrameMs", 50, 50).span("worstFrameEndMs", 50, 50));
		assertEquals(30, s.seconds.worstFrameMs(50));
		assertEquals(420, s.seconds.worstFrameEndMs(50));
		assertEquals("a 30 ms frame is not a slow one", 0, s.seconds.slowFrames(50));
		assertTickTimingUnchanged(s);
		assertTickFrames(s, 50_390, 50_421, 30);

		final int line = Thresholds.SLOW_FRAME_MS;
		assertEquals("one below the line", 0, Trace.steady(N).frameGap(50, 420, line - 1).build().seconds.slowFrames(50));
		assertEquals("at the line", 1, Trace.steady(N).frameGap(50, 420, line).build().seconds.slowFrames(50));
		assertChanged(Trace.steady(N).frameGap(50, 420, line).build(), keys().span("worstFrameMs", 50, 50)
			.span("worstFrameEndMs", 50, 50).span("slowFrames", 50, 50));
	}

	@Test
	public void aFrameLongerThanASecondLeavesTheSecondsItCoversWithNoFrame()
	{
		// 48.800 .. 50.300: second 49 ended no frame at all.
		final Session s = Trace.steady(N).frameGap(50, 300, 1500).build();
		assertChanged(s, keys().span("worstFrameMs", 50, 50).span("worstFrameEndMs", 50, 50)
			.span("slowFrames", 50, 50).span("frames", 49, 49).span("worstFrameMs", 49, 49)
			.span("worstFrameEndMs", 49, 49).span("flags", 49, 49));
		assertEquals(0, s.seconds.frames(49));
		assertTrue(Flags.has(s.seconds.flags(49), Flags.NO_FRAMES));
		assertEquals(300, s.seconds.worstFrameEndMs(50));
		assertTickFrames(s, 48_800, 50_301, 1500);
	}

	/**
	 * 3.12: frameGap sets the worst frame and its end when it is at least as long as the second's worst so far. A
	 * shorter frame leaves both alone; a tie keeps the length and moves the end.
	 */
	@Test
	public void aShorterFrameLeavesTheWorstFrameAlone()
	{
		// 50.410 .. 50.420: 10 ms, shorter than the steady 22; no tick arrives inside it.
		final Session s = Trace.steady(N).frameGap(50, 420, 10).build();
		assertChanged(s, keys());
		assertEquals(22, s.seconds.worstFrameMs(50));
		assertEquals(500, s.seconds.worstFrameEndMs(50));
		assertEquals(0, s.seconds.slowFrames(50));
		assertTickTimingUnchanged(s);
		for (long q = s.ticks.tail(); q <= s.ticks.head(); q++)
		{
			assertEquals("tick at " + s.ticks.atMs(q), 22, s.ticks.frameMs(q));
		}
		// 50.398 .. 50.420: a tie. The worst stays 22 and its end moves; the tick at 50.400 carries 22 still.
		final Session tie = Trace.steady(N).frameGap(50, 420, 22).build();
		assertChanged(tie, keys().span("worstFrameEndMs", 50, 50));
		assertEquals(22, tie.seconds.worstFrameMs(50));
		assertEquals(420, tie.seconds.worstFrameEndMs(50));
		assertTickTimingUnchanged(tie);
	}

	/**
	 * A loading frame (contract 6.1, as 3.12 writes it for a trace): a frameGap frame that touches a second with
	 * loading time flags the second it ENDS in with LOADING, whatever the order of the calls. A frame that touches
	 * no loading time flags nothing, and a LOADING flag with no loading time is not loading time.
	 */
	@Test
	public void aFrameThatTouchesLoadingTimeFlagsTheSecondItEndsIn()
	{
		// loading(49, 800); a 1,450 ms frame 49.850 .. 51.300 touches second 49. Second 51, where it ends, gets the
		// flag; second 50, which it covers whole, is a no-frame second with no loading time and no LOADING flag.
		final Session s = Trace.steady(N).loading(49, 800).frameGap(51, 300, 1450).build();
		assertChanged(s, keys().span("loadingMs", 49, 49).span("flags", 49, 51).span("frames", 50, 50)
			.span("worstFrameMs", 50, 51).span("worstFrameEndMs", 50, 51).span("slowFrames", 51, 51));
		assertEquals(Flags.FOCUSED | Flags.LOADING, s.seconds.flags(49));
		assertEquals(Flags.FOCUSED | Flags.NO_FRAMES, s.seconds.flags(50));
		assertEquals(Flags.FOCUSED | Flags.LOADING, s.seconds.flags(51));
		assertEquals("the flag, not loading time", 0, s.seconds.loadingMs(51));
		assertEquals("the order of the calls does not matter", seconds(s),
			seconds(Trace.steady(N).frameGap(51, 300, 1450).loading(49, 800).build()));
		assertTickTimingUnchanged(s);

		// 50.850 .. 51.300 touches seconds 50 and 51, neither with loading time: nothing is flagged.
		final Session beside = Trace.steady(N).loading(49, 800).frameGap(51, 300, 450).build();
		assertEquals(Flags.FOCUSED, beside.seconds.flags(51));
		// loading(49, 0) sets the flag and no loading time: the frame 49.850 .. 50.300 is no loading frame.
		final Session noTime = Trace.steady(N).loading(49, 0).frameGap(50, 300, 450).build();
		assertEquals(Flags.FOCUSED | Flags.LOADING, noTime.seconds.flags(49));
		assertEquals(Flags.FOCUSED, noTime.seconds.flags(50));
	}

