	/** The per-second columns of the changed session differ from a steady one of its length at exactly these keys. */
	private static void assertChanged(Session changed, Keys expected)
	{
		final Session steady = Trace.steady((int) (changed.seconds.head() + 1)).build();
		final Map<String, String> a = seconds(steady);
		final Map<String, String> b = seconds(changed);
		final Set<String> diff = new TreeSet<>();
		final Set<String> all = new TreeSet<>(a.keySet());
		all.addAll(b.keySet());
		for (String k : all)
		{
			if (!Objects.equals(a.get(k), b.get(k)))
			{
				diff.add(k);
			}
		}
		assertEquals(expected.set, diff);
	}

	private static void assertTickTimingUnchanged(Session changed)
	{
		final List<String> steady = timing(Trace.steady((int) (changed.seconds.head() + 1)).build());
		final List<String> now = timing(changed);
		assertEquals(steady.size(), now.size());
		for (int i = 0; i < steady.size(); i++)
		{
			final String[] a = steady.get(i).split(" ");
			final String[] b = now.get(i).split(" ");
			assertEquals("tick " + i + " arrives when it did", a[0], b[0]);
			assertEquals("tick " + i + " has its gap", a[1], b[1]);
		}
	}

	/** Ticks arriving in {@code fromMs .. toMs - 1} carry {@code frameMs}; every other tick the steady 22. */
	private static void assertTickFrames(Session s, int fromMs, int toMs, int frameMs)
	{
		int inside = 0;
		for (long q = s.ticks.tail(); q <= s.ticks.head(); q++)
		{
			final long at = s.ticks.atMs(q);
			final boolean in = at >= fromMs && at < toMs;
			assertEquals("tick at " + at, in ? frameMs : 22, s.ticks.frameMs(q));
			inside += in ? 1 : 0;
		}
		assertTrue("at least one tick is inside", inside > 0);
	}

	private static Map<String, String> seconds(Session s)
	{
		final Map<String, String> m = new TreeMap<>();
		final SecondRing r = s.seconds;
		for (long sec = r.tail(); sec <= r.head(); sec++)
		{
			m.put("frames@" + sec, "" + r.frames(sec));
			m.put("worstFrameMs@" + sec, "" + r.worstFrameMs(sec));
			m.put("worstFrameEndMs@" + sec, "" + r.worstFrameEndMs(sec));
			m.put("slowFrames@" + sec, "" + r.slowFrames(sec));
			m.put("loadingMs@" + sec, "" + r.loadingMs(sec));
			m.put("state@" + sec, "" + r.state(sec));
			m.put("flags@" + sec, "" + r.flags(sec));
			m.put("world@" + sec, "" + r.world(sec));
			m.put("players@" + sec, "" + r.players(sec));
			m.put("npcs@" + sec, "" + r.npcs(sec));
			m.put("region@" + sec, "" + r.region(sec));
			m.put("rttMs@" + sec, "" + r.rttMs(sec));
			m.put("rttAgeS@" + sec, "" + r.rttAgeS(sec));
			m.put("sentUnits@" + sec, "" + r.sentUnits(sec));
			m.put("resentUnits@" + sec, "" + r.resentUnits(sec));
			m.put("conn@" + sec, r.conn(sec).name());
		}
		return m;
	}

	/** Each tick as "atMs gapMs frameMs cycleJump". */
	private static List<String> timing(Session s)
	{
		final List<String> out = new ArrayList<>();
		final TickRing t = s.ticks;
		for (long q = t.tail(); q <= t.head(); q++)
		{
			out.add(t.atMs(q) + " " + t.gapMs(q) + " " + t.frameMs(q) + " " + t.cycleJump(q));
		}
		return out;
	}

	/** Each tick in full, the derived rtt and flags included. */
	private static List<String> ticks(Session s)
	{
		final List<String> out = new ArrayList<>();
		final TickRing t = s.ticks;
		for (long q = t.tail(); q <= t.head(); q++)
		{
			out.add(t.atMs(q) + " " + t.gapMs(q) + " " + t.frameMs(q) + " " + t.cycleJump(q) + " " + t.rttMs(q)
				+ " " + t.flags(q));
		}
		return out;
	}

	private static void assertNotSameSession(Session a, Session b)
	{
		assertNotSame("two builds are two sessions", a, b);
		assertNotSame("with rings of their own", a.seconds, b.seconds);
	}

	private static void refused(Runnable r)
	{
		try
		{
			r.run();
			fail("refused expected");
		}
		catch (IllegalArgumentException expected)
		{
			// the builder said why
		}
	}

	private static Keys keys()
	{
		return new Keys();
	}

	/** The expected changed keys, "column@second". */
	private static final class Keys
	{
		final Set<String> set = new TreeSet<>();

		Keys span(String column, int from, int to)
		{
			for (int s = from; s <= to; s++)
			{
				set.add(column + "@" + s);
			}
			return this;
		}
	}
}

package com.whylag.core;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * The usual (contract 3.5): the running median, -1 under thirty samples, reset, and clamping. The session that
 * holds the usuals is {@code SessionTest}'s.
 */
public class UsualTest
{
	@Test
	public void median()
	{
		final Usual u = new Usual(2000);
		for (int v = 31; v >= 1; v--)
		{
			u.add(v);
		}
		assertEquals(31, u.count());
		assertEquals("the middle of 1 .. 31", 16, u.median());
		final Usual even = new Usual(2000);
		for (int v = 1; v <= 30; v++)
		{
			even.add(v);
		}
		assertEquals("the lower middle of an even count", 15, even.median());
		final Usual spiky = new Usual(2000);
		for (int i = 0; i < 29; i++)
		{
			spiky.add(40);
		}
		spiky.add(1900);
		spiky.add(1900);
		assertEquals("two spikes do not move a median", 40, spiky.median());
	}

	@Test
	public void noMedianUnderThirtySamples()
	{
		final Usual u = new Usual(2000);
		for (int i = 0; i < Thresholds.USUAL_MIN_SAMPLES - 1; i++)
		{
			u.add(40);
		}
		assertEquals(-1, u.median());
		u.add(40);
		assertEquals(40, u.median());
	}

	@Test
	public void reset()
	{
		final Usual u = new Usual(2000);
		for (int i = 0; i < 50; i++)
		{
			u.add(40);
		}
		u.reset();
		assertEquals(0, u.count());
		assertEquals(-1, u.median());
		for (int i = 0; i < 30; i++)
		{
			u.add(90);
		}
		assertEquals("nothing from before the reset remains", 90, u.median());
	}

	@Test
	public void samplesAreClamped()
	{
		final Usual u = new Usual(1000);
		for (int i = 0; i < 30; i++)
		{
			u.add(5000);
		}
		assertEquals(1000, u.median());
		u.reset();
		for (int i = 0; i < 30; i++)
		{
			u.add(-8);
		}
		assertEquals(0, u.median());
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * One synthetic trace per rule (contract section 7, L4; section 8): each of the twelve rules answers its own
 * trace, at its full ceiling, and no other rule is within the margin. Every trace carries a usual of 40
 * ({@code Trace.usual(40)}, and {@code rttBeforeMs} 40 on its event), so no rule loses a step for a missing usual.
 *
 * <p>The judge cannot run the detector (L3), so each closed event is built by constructor over the trace's span.
 * The helpers here ({@link #event}, {@link Case}, {@link #card}) are shared by the other verdict tests.
 */
public class VerdictCauseTest
{
	static final int USUAL = 40;

	/** One trace with what is judged on it: an event, or the card at {@code nowSec} for a condition. */
	static final class Case
	{
		final String id;
		final Session s;
		final SettingsView settings;
		final LagEvent event;
		final int nowSec;

		Case(String id, Trace t, LagEventSpec spec, int nowSec)
		{
			this.id = id;
			this.s = t.build();
			this.settings = t.settings();
			this.event = spec == null ? null : spec.on(s);
			this.nowSec = nowSec;
		}

		Rule rule()
		{
			return Rules.byId(id);
		}

		/** The verdict of this case: the event's, or the card's at the end of the trace. */
		Verdict verdict()
		{
			if (event != null)
			{
				return new VerdictEngine().judgeEvent(s, event, settings);
			}
			return card(s, settings, nowSec);
		}

		Evidence evidence()
		{
			return event != null ? EvidenceBuilder.forEvent(s, event, settings)
				: EvidenceBuilder.forCondition(s, nowSec, settings);
		}
	}

	/** What a hand-built event is made of, before it meets its session. */
	static final class LagEventSpec
	{
		private final long id;
		private final int from, to;
		private final Trigger first;
		private int triggers;
		private int rttBefore = USUAL;
		private boolean open;

		LagEventSpec(long id, int from, int to, Trigger first, Trigger... more)
		{
			this.id = id;
			this.from = from;
			this.to = to;
			this.first = first;
			triggers = first.bit();
			for (Trigger t : more)
			{
				triggers |= t.bit();
			}
		}

		LagEventSpec usual(int rttBeforeMs)
		{
			rttBefore = rttBeforeMs;
			return this;
		}

		LagEventSpec open(boolean isOpen)
		{
			open = isOpen;
			return this;
		}

		/**
		 * The event over the trace's span, as the detector would hand it in. Beside the span, the id, the trigger
		 * bits, {@code first} and {@code rttBeforeMs} the judge reads nothing from it, so the event's own numbers
		 * are given values no ring holds (7777): a judge that read them would print them.
		 */
		LagEvent on(Session s)
		{
			return new LagEvent(id, from, to, s.wallMsOf(from), triggers, first, s.seconds.world(from), 0, 0, 0,
				7777, 7777, 7777, 7777, 7777, 7777, 7777, rttBefore, 7777, 7777, open, false, null);
		}
	}

	static LagEvent event(Session s, long id, int from, int to, Trigger first, Trigger... more)
	{
		return new LagEventSpec(id, from, to, first, more).on(s);
	}

	/** The card after one step a second from {@code nowSec} 1 to {@code toNowSec}, with a fresh engine. */
	static Verdict card(Session s, SettingsView settings, int toNowSec)
	{
		final VerdictEngine engine = new VerdictEngine();
		Verdict v = null;
		for (int now = 1; now <= toNowSec; now++)
		{
			v = engine.current(s, now, s.wallMsOf(now), settings);
		}
		return v;
	}

	static SettingsView fpsControl(int maxFps)
	{
		return new SettingsView(Renderer.CPU, true, true, maxFps, false, 0, false, "", 0, 0, "", 0, 60, Os.WINDOWS, "");
	}

	// ------------------------------------------------------------------ the twelve traces

	static Trace d1Trace()
	{
		return Trace.steady(200).usual(USUAL).disconnect(120);
	}

	static Case d1()
	{
		return new Case("D1", d1Trace(), new LagEventSpec(0, 120, 120, Trigger.DISCONNECT), 200);
	}

	static Trace s1Trace()
	{
		return Trace.steady(200).usual(USUAL).loading(100, 1000).loading(101, 1000).loading(102, 400);
	}

	static Case s1()
	{
		return new Case("S1", s1Trace(), new LagEventSpec(2, 103, 103, Trigger.LONG_LOAD), 200);
	}

	static Trace n3Trace()
	{
		return Trace.steady(200).usual(USUAL).resent(120, 90);
	}

	static Case n3()
	{
		return new Case("N3", n3Trace(), new LagEventSpec(3, 120, 120, Trigger.RESENT), 200);
	}

	static Trace n2Trace()
	{
		// A tick TICK_OFF_MS + 150 late (400 since the first live look; it was 250): off by 378 after the 22 ms frame,
		// and the catch-up tick as early.
		return Trace.steady(200).usual(USUAL).rtt(120, 120, 400).rtt(121, 121, 30)
			.tickLate(120, Thresholds.TICK_OFF_MS + 150, true);
	}

	static Case n2()
	{
		return new Case("N2", n2Trace(), new LagEventSpec(4, 120, 121, Trigger.TICK_OFF, Trigger.RTT_SPIKE), 200);
	}

	static Trace w1Trace()
	{
		return Trace.steady(200).usual(USUAL).ticksEvery(120, 133, 900);
	}

	static Case w1()
	{
		return new Case("W1", w1Trace(), new LagEventSpec(5, 120, 133, Trigger.TICK_OFF), 200);
	}

	static Trace s3Trace()
	{
		return Trace.steady(200).usual(USUAL).frameGap(120, 600, 480);
	}

	static Case s3()
	{
		return new Case("S3", s3Trace(), new LagEventSpec(6, 120, 120, Trigger.FRAME_GAP), 200);
	}

	static Trace n6Trace()
	{
		return Trace.steady(200).usual(USUAL).noTicks(120, 121);
	}

	static Case n6()
	{
		return new Case("N6", n6Trace(), new LagEventSpec(8, 120, 122, Trigger.NO_TICK, Trigger.TICK_OFF), 200);
	}

	static Case f1()
	{
		return new Case("F1", Trace.steady(200).usual(USUAL).fps(100, 199, 30).settings(fpsControl(30)), null, 200);
	}

	static Case n1()
	{
		return new Case("N1", Trace.steady(200).usual(USUAL).rtt(100, 199, 180), null, 200);
	}

	static Case f2()
	{
		return new Case("F2", Trace.steady(200).usual(USUAL).fps(100, 199, 24), null, 200);
	}

	static Case w1c()
	{
		return new Case("W1c", Trace.steady(200).usual(USUAL).ticksEvery(100, 199, 640), null, 200);
	}

	static Case v2()
	{
		return new Case("V2", Trace.steady(200).usual(USUAL), null, 200);
	}

	static List<Case> all()
	{
		final List<Case> out = new ArrayList<>();
		out.add(d1());
		out.add(s1());
		out.add(n3());
		out.add(n2());
		out.add(w1());
		out.add(s3());
		out.add(n6());
		out.add(f1());
		out.add(n1());
		out.add(f2());
		out.add(w1c());
		out.add(v2());
		return out;
	}

	// ------------------------------------------------------------------ the tests

	@Test
	public void thereIsOneTraceForEachOfTheTwelveRules()
	{
		final List<Case> cases = all();
		assertEquals(12, cases.size());
		for (int i = 0; i < cases.size(); i++)
		{
			assertSame("in rank order", Rules.ALL[i], cases.get(i).rule());
		}
	}

	@Test
	public void d1AnswersADisconnect()
	{
		final Verdict v = judged(d1());
		assertWords(v, "Connection lost at 20:54", "Ping and re-sends were fine just before.",
			"Wait a minute, then log in again.");
	}

	@Test
	public void s1AnswersALongLoad()
	{
		final Verdict v = judged(s1());
		// 6.4 writes "{6} loads in the last 10 min." for every count, one included.
		assertWords(v, "Map loading took 2.4 s", "1 loads in the last 10 min.", "Nothing to fix. It is the map.");
	}

	@Test
	public void n3AnswersLostPackets()
	{
		final Verdict v = judged(n3());
		// 90 re-sent of the 4,500 sent in seconds 118 to 122: 20 per mille.
		assertWords(v, "Packets are being lost", "2 in 100 were re-sent. Ping can look fine.",
			"If every world does it, check cable or Wi-Fi.");
	}

	@Test
	public void n2AnswersAnUnsteadyConnection()
	{
		final Case c = n2();
		final Verdict v = judged(c);
		assertEquals("with its support", 95, Rules.N2.score(c.evidence()));
		assertWords(v, "Your connection is unsteady", "Ping swung 30-400 ms. Ticks came early and late.",
			"Use a cable, not Wi-Fi. Pause downloads.");
	}

	@Test
	public void w1AnswersASlowWorld()
	{
		final Case c = w1();
		final Verdict v = judged(c);
		assertEquals("with its support, the length", 95, Rules.W1.score(c.evidence()));
		assertEquals("N6 needs the NO_TICK trigger since the first live look: slow ticks are no stop", 0,
			Rules.N6.score(c.evidence()));
		assertWords(v, "World 416 is struggling, not you",
			"Ticks 600 to 870+ ms for 14 s. Ping stayed 40 ms, 50 fps.", "Hop to a quieter world.");
	}

	@Test
	public void s3AnswersAClientStall()
	{
		final Case c = s3();
		final Verdict v = judged(c);
		assertEquals("its one support, a calm ping", 90, Rules.S3.score(c.evidence()));
		assertWords(v, "The client itself stalled", "A 480 ms freeze. Connection and world were fine.",
			"Turn plugins off one at a time; try more memory for RuneLite.");
	}

	@Test
	public void n6AnswersADeliveryGap()
	{
		final Verdict v = judged(n6());
		assertWords(v, "The game stopped answering", "No ticks for 3.0 s. Frames and ping were fine.",
			"Hop worlds. If it follows you, it is your line.");
	}

	@Test
	public void f1AnswersASelfSetCap()
	{
		final Verdict v = judged(f1());
		assertWords(v, "Frame rate is capped at 30", "Set by FPS Control. Not lag.", "Raise or turn off that cap.");
	}

	@Test
	public void n1AnswersAHighSteadyPing()
	{
		final Verdict v = judged(n1());
		assertWords(v, "Ping is high but steady", "180 ms. Your usual is 40 ms.", "Try a world closer to you.");
	}

	@Test
	public void f2AnswersSlowDrawing()
	{
		final Case c = f2();
		final Verdict v = judged(c);
		assertEquals("with its support, a low ping", 70, Rules.F2.score(c.evidence()));
		assertEquals("The game is drawing slowly", v.headline);
		assertTrue(v.proof, v.proof.startsWith("24 fps for "));
		assertEquals("Turn the GPU plugin on.", v.fix);
	}

	@Test
	public void w1cAnswersASlowWorldAsACondition()
	{
		final Case c = w1c();
		final Verdict v = judged(c);
		assertEquals("with its support", 65, Rules.W1C.score(c.evidence()));
		assertWords(v, "This world is running slow", "Ticks take 640 ms here. Ping and frames are fine.",
			"Hop to a quieter world.");
	}

	@Test
	public void v2AnswersASteadyTrace()
	{
		final Case c = v2();
		final Verdict v = c.verdict();
		assertEquals(Cause.ALL_CLEAR, v.cause);
		assertEquals(Confidence.SURE, v.confidence);
		assertEquals(Level.OK, v.level);
		assertWords(v, "Smooth", "No lag this session.", "");
		assertNull("no condition scores on a steady trace", Rules.bestCondition(c.evidence()));
		assertNull(new VerdictEngine().conditionNow(c.s, c.nowSec, c.settings));
		assertEquals(-1, v.eventId);
		assertEquals(0, v.durationS);
	}

	// ------------------------------------------------------------------ what every case is held to

	/**
	 * The case's verdict, held to what contract section 7 asks of each trace: its own cause, its FULL ceiling, the
	 * level of its kind, what its kind carries (3.6), and no other rule within the margin.
	 */
	private static Verdict judged(Case c)
	{
		final Rule own = c.rule();
		final Verdict v = c.verdict();
		assertNotNull(c.id, v);
		assertEquals(c.id + " cause", own.cause, v.cause);
		assertEquals(c.id + " answers at its full ceiling", own.ceiling, v.confidence);
		assertNull(v.alsoA);
		assertNull(v.alsoB);

		final Evidence e = c.evidence();
		final int score = own.score(e);
		assertTrue(c.id + " scores", score >= own.base);
		for (Rule other : Rules.ALL)
		{
			if (other == own || other.kind != own.kind)
			{
				continue;
			}
			assertTrue(c.id + ": " + other.id + " at " + other.score(e) + " is within the margin of " + score,
				score - other.score(e) >= Thresholds.SCORE_MARGIN);
		}

		if (c.event != null)
		{
			assertEquals("an event is BAD, and at most WARN when it can't tell (the first live look)",
				v.confidence == Confidence.CANT_TELL ? Level.WARN : Level.BAD, v.level);
			assertEquals(c.event.id, v.eventId);
			assertEquals(c.event.startWallMs, v.whenWallMs);
			assertEquals(c.event.lengthS(), v.durationS);
			assertEquals(416, v.world);
		}
		else
		{
			assertEquals(Level.WARN, v.level);
			assertEquals(-1, v.eventId);
			assertEquals(0, v.durationS);
			assertEquals(416, v.world);
			assertTrue("a condition is dated", v.whenWallMs > 0);
			final Verdict now = new VerdictEngine().conditionNow(c.s, c.nowSec, c.settings);
			assertNotNull(now);
			assertEquals("the card shows the condition that wins now", own.cause, now.cause);
		}
		return v;
	}

	private static void assertWords(Verdict v, String headline, String proof, String fix)
	{
		assertEquals(headline, v.headline);
		assertEquals(proof, v.proof);
		assertEquals(fix, v.fix);
	}
}

package com.whylag.core;

import org.junit.Test;
import static com.whylag.core.VerdictCauseTest.USUAL;
import static com.whylag.core.VerdictCauseTest.event;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Two causes in one event (contract 6.3, "Designed near misses"; skeptic C22): a long map load during packet loss.
 * S1 and N3 are the pair that can come within the margin in wave one once the memory rule is gone (1.0.0, the Hub's
 * rule). More evidence for the rival can never turn "Can't tell" into "Sure" - it does the opposite.
 */
public class VerdictMixedTest
{
	/** A late tick that is off after the 22 ms frame: TICK_OFF_MS + 150, 400 since the first live look (it was 250). */
	private static final int LATE = Thresholds.TICK_OFF_MS + 150;

	private final VerdictEngine judge = new VerdictEngine();

	/** A long load (seconds 100 to 102, LONG_LOAD in 103) and re-sends in the same second. */
	private static Trace loadDuringLoss()
	{
		return Trace.steady(200).usual(USUAL).loading(100, 1000).loading(101, 1000).loading(102, 400)
			.resent(103, 90);
	}

	/** S1 (105) against N3 with both supports (110): five apart, under the margin. */
	@Test
	public void loadDuringLossWithBothSupportsIsCantTell()
	{
		final Trace t = loadDuringLoss().rtt(104, 104, 400).tickLate(104, LATE, true);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 103, 104, Trigger.LONG_LOAD, Trigger.RESENT, Trigger.RTT_SPIKE,
			Trigger.TICK_OFF);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(105, Rules.S1.score(ev));
		assertEquals("a late tick and a spike: both supports", 110, Rules.N3.score(ev));

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertCantTell(v);
		assertEquals("It was map loading or lost packets.", v.proof);
	}

	/** S1 (105) against N3 with one support (100): five apart, under the margin. */
	@Test
	public void loadDuringLossWithOneSupportIsCantTellNamingBoth()
	{
		final Trace t = loadDuringLoss().tickLate(104, LATE, true);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 103, 104, Trigger.LONG_LOAD, Trigger.RESENT, Trigger.TICK_OFF);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(105, Rules.S1.score(ev));
		assertEquals("the late tick alone", 100, Rules.N3.score(ev));

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertCantTell(v);
		assertEquals("It was map loading or lost packets.", v.proof);
	}

	/** With no support N3 is 15 behind, and the load is named; each support for the rival takes that away. */
	@Test
	public void moreEvidenceForTheRivalNeverMakesItSure()
	{
		final Trace t = loadDuringLoss();
		final Session s = t.build();
		final LagEvent e = event(s, 0, 103, 103, Trigger.LONG_LOAD, Trigger.RESENT);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(105, Rules.S1.score(ev));
		assertEquals(90, Rules.N3.score(ev));

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals(Cause.MAP_LOAD, v.cause);
		assertEquals(Confidence.SURE, v.confidence);
		assertNull(v.alsoA);
		assertNull(v.alsoB);
	}

	/** The margin is on the SCORES: the rank orders the two names and never picks a winner. */
	@Test
	public void rankOnlyOrdersTheNames()
	{
		// A long load (seconds 100 to 102, LONG_LOAD in 103) and lost packets in the same second, with a late tick
		// and a ping spike. S1 (rank 2) scores its 105; N3 (rank 3) scores 90 and both supports, 110. The top SCORER
		// is the higher rank number, so a judge that named the top scorer first would put lost packets first.
		final Trace t = Trace.steady(200).usual(USUAL).loading(100, 1000).loading(101, 1000).loading(102, 400)
			.resent(103, 90).rtt(103, 103, 400).tickLate(103, LATE, true);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 103, 103, Trigger.LONG_LOAD, Trigger.RESENT, Trigger.RTT_SPIKE,
			Trigger.TICK_OFF);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(105, Rules.S1.score(ev));
		assertEquals(110, Rules.N3.score(ev));
		for (Rule other : Rules.ALL)
		{
			if (other.kind == Rule.Kind.EVENT && other != Rules.S1 && other != Rules.N3)
			{
				assertEquals(other.id, 0, other.score(ev));
			}
		}

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals("five apart, under the margin", Cause.NOT_SURE, v.cause);
		assertEquals("the lower rank first, though it scored less", Cause.MAP_LOAD, v.alsoA);
		assertEquals(Cause.UPLOAD_LOSS, v.alsoB);
		assertEquals("It was map loading or lost packets.", v.proof);

		// Where the lower rank is also the top scorer the order is the same: W1 (rank 5, 85) before N6 (rank 7, 75).
		// N6 needs the NO_TICK trigger since the first live look, so this event carries one.
		final Trace world = Trace.steady(200).usual(USUAL).ticksEvery(120, 125, 900);
		final Session ws = world.build();
		final Verdict w = judge.judgeEvent(ws, event(ws, 0, 120, 125, Trigger.TICK_OFF, Trigger.NO_TICK),
			world.settings());
		assertEquals(Cause.NOT_SURE, w.cause);
		assertEquals(Cause.SLOW_WORLD, w.alsoA);
		assertEquals(Cause.DELIVERY_GAP, w.alsoB);
	}

	private static void assertCantTell(Verdict v)
	{
		assertEquals(Cause.NOT_SURE, v.cause);
		assertEquals(Confidence.CANT_TELL, v.confidence);
		assertEquals("can't tell is never a red lag (the first live look)", Level.WARN, v.level);
		assertEquals("the lower rank first", Cause.MAP_LOAD, v.alsoA);
		assertEquals(Cause.UPLOAD_LOSS, v.alsoB);
		assertEquals("Can't tell yet", v.headline);
		assertEquals("Wait for it to happen again.", v.fix);
		assertEquals(0, v.eventId);
	}
}

package com.whylag.core;

import org.junit.Test;
import static com.whylag.core.VerdictCauseTest.USUAL;
import static com.whylag.core.VerdictCauseTest.card;
import static com.whylag.core.VerdictCauseTest.event;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The near misses of contract section 7 (L4): every skeptic trap where a trace LOOKS like one cause and is another
 * (C2, C3, C4, C5, C9, C21), the designed "Can't tell", and the three condition cases.
 */
public class VerdictNearMissTest
{
	private final VerdictEngine judge = new VerdictEngine();

	/** C3: three late deliveries, each caught up, do not make a slow world: the median gap stays 600. */
	@Test
	public void threeLateDeliveriesAreNotASlowWorld()
	{
		final int late = Thresholds.TICK_OFF_MS + 150;
		final Trace t = Trace.steady(200).usual(USUAL).tickLate(120, late, true).tickLate(123, late, true)
			.tickLate(126, late, true);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 120, 126, Trigger.TICK_OFF);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(3, ev.tickLate);
		assertEquals(3, ev.tickEarly);
		assertTrue("enough ticks for W1", ev.ticks >= Thresholds.SLOW_WORLD_MIN_TICKS);
		assertTrue("but their median is an ordinary tick", ev.tickMedianMs < Thresholds.SLOW_WORLD_MEDIAN_MS);
		assertEquals(0, Rules.W1.score(ev));

		// Late ticks with no stop are not "No ticks" since the first live look (N6 needs NO_TICK): can't tell.
		assertEquals(0, Rules.N6.score(ev));
		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals(Cause.NOT_SURE, v.cause);
		assertNotEquals(Cause.SLOW_WORLD, v.cause);
		assertEquals(Level.WARN, v.level);
	}

	/** C2: loss on the way DOWN shows as a late tick with nothing re-sent and a calm ping: it cannot be placed. */
	@Test
	public void downloadLossIsCantTell()
	{
		final Trace t = Trace.steady(200).usual(USUAL).tickLate(120, 700, false);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 120, 120, Trigger.TICK_OFF);
		final Verdict v = judge.judgeEvent(s, e, t.settings());
		// One late tick is no stop: not "No ticks" since the first live look (N6 needs NO_TICK), and amber.
		assertEquals(Cause.NOT_SURE, v.cause);
		assertEquals(Confidence.CANT_TELL, v.confidence);
		assertEquals("Can't tell", v.confidence.word());
		assertEquals(Group.UNSURE, v.cause.group());
		assertEquals(Level.WARN, v.level);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals("a late tick is no stop", 0, Rules.N6.score(ev));
		assertEquals("nothing was re-sent: it is not upload loss", 0, Rules.N3.score(ev));
		assertEquals(0, Rules.N2.score(ev));
		assertEquals(0, Rules.W1.score(ev));
	}

	/**
	 * The designed near miss of 6.3: W1 with no support (85) against N6 (75). Since the first live look N6 needs the
	 * NO_TICK trigger, so the event carries one; without it the same ticks are W1 alone.
	 */
	@Test
	public void bareSlowWorldAgainstDeliveryGapIsCantTell()
	{
		final Trace t = Trace.steady(200).usual(USUAL).ticksEvery(120, 125, 900);
		final Session s = t.build();
		assertEquals(Cause.SLOW_WORLD, judge.judgeEvent(s, event(s, 1, 120, 125, Trigger.TICK_OFF), t.settings())
			.cause);
		final LagEvent e = event(s, 0, 120, 125, Trigger.TICK_OFF, Trigger.NO_TICK);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals("six seconds: no support", 85, Rules.W1.score(ev));
		assertEquals(75, Rules.N6.score(ev));

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals(Cause.NOT_SURE, v.cause);
		assertEquals(Confidence.CANT_TELL, v.confidence);
		assertEquals("can't tell is never a red lag (the first live look)", Level.WARN, v.level);
		assertEquals("the lower rank first", Cause.SLOW_WORLD, v.alsoA);
		assertEquals(Cause.DELIVERY_GAP, v.alsoB);
		assertEquals("Can't tell yet", v.headline);
		assertEquals("It was the world or your line or the server.", v.proof);
		assertEquals("Wait for it to happen again.", v.fix);
		assertEquals(0, v.eventId);
		assertEquals(6, v.durationS);

		// Ten seconds of it: the support holds, 95 against 75, and W1 wins by 20.
		final Trace longer = Trace.steady(200).usual(USUAL).ticksEvery(120, 129, 900);
		final Session ls = longer.build();
		assertEquals(Cause.SLOW_WORLD, judge.judgeEvent(ls, event(ls, 1, 120, 129, Trigger.TICK_OFF),
			longer.settings()).cause);
	}

	/** C4: whatever else its span holds, an event that holds a disconnect is D1. */
	@Test
	public void eventHoldingADisconnectIsD1()
	{
		final Trace t = Trace.steady(200).usual(USUAL).frameGap(118, 600, 480).resent(119, 90).disconnect(120);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 118, 120, Trigger.FRAME_GAP, Trigger.RESENT, Trigger.DISCONNECT);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertTrue(ev.disconnect);
		assertEquals(120, ev.disconnectSec);
		assertEquals(200, Rules.D1.score(ev));
		assertEquals("excluded by the disconnect", 0, Rules.N3.score(ev));

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals(Cause.DISCONNECT, v.cause);
		assertEquals(Confidence.SURE, v.confidence);
		assertEquals("Connection lost at 20:54", v.headline);
	}

	/** D1 covers only the event whose SPAN holds the disconnect (6.3): an earlier event keeps its own verdict. */
	@Test
	public void eventThatClosedBeforeADisconnectKeepsItsVerdict()
	{
		final Trace stall = Trace.steady(200).usual(USUAL).frameGap(100, 600, 480);
		final Session before = stall.build();
		final Verdict alone = judge.judgeEvent(before, event(before, 0, 100, 100, Trigger.FRAME_GAP),
			stall.settings());
		assertEquals(Cause.CLIENT_BUSY, alone.cause);

		final Trace t = Trace.steady(200).usual(USUAL).frameGap(100, 600, 480).disconnect(110);
		final Session s = t.build();
		final LagEvent first = event(s, 0, 100, 100, Trigger.FRAME_GAP);
		final LagEvent second = event(s, 1, 110, 110, Trigger.DISCONNECT);
		final Verdict v = judge.judgeEvent(s, first, t.settings());
		assertEquals("the disconnect ten seconds later is not in its span", Cause.CLIENT_BUSY, v.cause);
		assertTrue(v.sameAs(alone));
		assertFalse(EvidenceBuilder.forEvent(s, first, t.settings()).disconnect);
		assertEquals(Cause.DISCONNECT, judge.judgeEvent(s, second, t.settings()).cause);

		// On the card: the stall shows when it closes and is not judged again. Its show (EVENT_SHOW_S 10 since
		// 2026-09-29) ends at 110, so the second of the lost connection finds the card Smooth when it leaves the
		// state, and leaving a state is a change: the hold keeps the card until 122, after the disconnect event's own
		// show has ended (110 + 10), so that event does not reach the card either.
		final VerdictEngine engine = new VerdictEngine();
		final LagEvent firstJudged = first.withVerdict(v);
		final LagEvent secondJudged = second.withVerdict(judge.judgeEvent(s, second, t.settings()));
		for (int now = 1; now <= 140; now++)
		{
			if (now == 106)
			{
				s.events.add(firstJudged);
			}
			if (now == 117)
			{
				s.events.add(secondJudged);
			}
			final Verdict shown = engine.current(s, now, s.wallMsOf(now), t.settings());
			if (now >= 106 && now <= 110)
			{
				assertEquals("at " + now, Cause.CLIENT_BUSY, shown.cause);
			}
			if (now == 111)
			{
				assertEquals("the second of the lost connection is not in-game", Answer.HEAD_NOT_LOGGED_IN,
					shown.headline);
			}
			if (now >= 112)
			{
				// Back at once, and the stall's show is over: Smooth. The card changed at 112 (it left "Not logged
				// in"), so the disconnect (in the log at 117) waits out a hold that outlasts its own show.
				assertEquals("at " + now, Cause.ALL_CLEAR, shown.cause);
			}
		}
		assertEquals(Cause.CLIENT_BUSY, s.events.byId(0).verdict.cause);
	}

	/** C9: under a cap of 4 frames a second a 250 ms frame is the cap, not a stall. */
	@Test
	public void capAtFourFpsIsF1NotAFreeze()
	{
		final SettingsView capped = VerdictCauseTest.fpsControl(4);
		final Trace t = Trace.steady(200).usual(USUAL).fps(100, 199, 4).settings(capped);
		final Session s = t.build();
		assertEquals(375, capped.frameGapLimitMs(true));

		final LagEvent e = event(s, 0, 150, 150, Trigger.FRAME_GAP);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, capped);
		assertEquals(250, ev.frameGapMs);
		assertEquals(375, ev.frameLimitMs);
		assertEquals("a 250 ms frame under the cap's limit is no freeze", 0, Rules.S3.score(ev));
		assertNotEquals(Cause.CLIENT_BUSY, judge.judgeEvent(s, e, capped).cause);

		final Verdict shown = card(s, capped, 200);
		assertEquals(Cause.FRAME_CAP, shown.cause);
		assertEquals("Frame rate is capped at 4", shown.headline);
		assertEquals(Confidence.SURE, shown.confidence);

		// The same frames with no cap set by the player are a stall of the client.
		final Session free = Trace.steady(200).usual(USUAL).fps(100, 199, 4).build();
		final SettingsView plain = Trace.steady(1).settings();
		assertEquals(Cause.CLIENT_BUSY, judge.judgeEvent(free, event(free, 0, 150, 150, Trigger.FRAME_GAP),
			plain).cause);
	}

	/** C21: a ping spike beside a re-send is lost packets, not an unsteady line. */
	@Test
	public void pingSpikeWithAResendIsN3NotN2()
	{
		final Trace t = VerdictCauseTest.n2Trace().resent(120, 90);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 120, 121, Trigger.TICK_OFF, Trigger.RTT_SPIKE, Trigger.RESENT);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals("a re-send excludes N2", 0, Rules.N2.score(ev));
		assertEquals("both supports", 110, Rules.N3.score(ev));
		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals(Cause.UPLOAD_LOSS, v.cause);
		assertEquals(Confidence.LIKELY, v.confidence);
	}

	/** C5: at a low frame rate the ticks' timing is the client's own pacing; N2 may not read it. */
	@Test
	public void lowFpsBlocksN2()
	{
		final Trace t = Trace.steady(200).usual(USUAL).fps(110, 130, 30).rtt(120, 120, 400).rtt(121, 121, 30)
			.tickLate(120, Thresholds.TICK_OFF_MS + 150, true);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 120, 121, Trigger.TICK_OFF, Trigger.RTT_SPIKE);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(30, ev.fps);
		assertEquals("ceil(1000 / 30), not under LOW_FPS_FRAME_MS", 34, ev.frameMedianMs);
		assertEquals(Evidence.YES, ev.rttSpike);
		assertEquals(0, Rules.N2.score(ev));
		assertNotEquals(Cause.PING_JUMPY, judge.judgeEvent(s, e, t.settings()).cause);

		// The N2 trace itself, at 50 frames a second, is N2.
		final VerdictCauseTest.Case n2 = VerdictCauseTest.n2();
		assertEquals(Cause.PING_JUMPY, n2.verdict().cause);
	}

	/**
	 * W1 needs a steady ping: a ping that doubled under the spike line is not the world's. It sent the trace to N6
	 * before the first live look; N6 needs a real stop (NO_TICK) since, so nothing answers and the judge can't tell.
	 */
	@Test
	public void pingRoseWithSlowTicksCannotBeTold()
	{
