	/** What happened AFTER the last tick is no evidence about the home line (6.4). */
	@Test
	public void resendsAfterTheLastTickDoNotBlameTheLine()
	{
		final Trace t = Trace.steady(200).usual(USUAL).noTicks(100, 110).resent(102, 400).resent(105, 400)
			.disconnect(110);
		final Session s = t.build();
		final LagEvent e = event(s, 0, 101, 110, Trigger.NO_TICK, Trigger.RESENT, Trigger.DISCONNECT);
		final Evidence ev = EvidenceBuilder.forEvent(s, e, t.settings());
		assertEquals(110, ev.disconnectSec);
		assertEquals("the tick at 99.6 s", 99, ev.lastTickSec);
		assertEquals("the span's own re-sends are bad", true, ev.resentPm >= Thresholds.RESENT_PER_MILLE);
		assertEquals("the ten seconds before the last tick are clean", 0, ev.beforeResentPm);
		assertEquals(Evidence.NO, ev.beforeRttSpike);

		final Verdict v = judge.judgeEvent(s, e, t.settings());
		assertEquals(Cause.DISCONNECT, v.cause);
		assertEquals("Ping and re-sends were fine just before.", v.proof);
		assertEquals("Wait a minute, then log in again.", v.fix);
	}

	/** X never says that nothing moved: with no candidate its proof names what the first trigger saw. */
	@Test
	public void xNamesWhatMoved()
	{
		// A 90 ms frame: no stall rule reaches the frame limit.
		final Trace freeze = Trace.steady(200).usual(USUAL).frameGap(120, 290, 90);
		final Session fs = freeze.build();
		final Verdict f = judge.judgeEvent(fs, event(fs, 0, 120, 120, Trigger.FRAME_GAP), freeze.settings());
		assertCantTellNamingNothing(f);
		assertEquals("A 90 ms freeze. Its cause was not measured.", f.proof);

		// The low-frame-rate trace of lowFpsBlocksN2: ticks off, no rule answers.
		final Trace ticks = Trace.steady(200).usual(USUAL).fps(110, 130, 30).rtt(120, 120, 400)
			.rtt(121, 121, 30).tickLate(120, 250, true);
		final Session ts = ticks.build();
		final Verdict k = judge.judgeEvent(ts, event(ts, 1, 120, 121, Trigger.TICK_OFF, Trigger.RTT_SPIKE),
			ticks.settings());
		assertCantTellNamingNothing(k);
		// The tick came 250 ms late: a stretch of 850 ms with no tick, 250 more than one tick (tickOffMs, 6.3).
		assertEquals("Ticks ran 250 ms off. Cause not measured.", k.proof);

		// A spike alone, as it would be with RTT_SPIKE_OPENS.
		final Trace spike = Trace.steady(200).usual(USUAL).rtt(120, 120, 400);
		final Session ss = spike.build();
		final Verdict p = judge.judgeEvent(ss, event(ss, 2, 120, 120, Trigger.RTT_SPIKE), spike.settings());
		assertCantTellNamingNothing(p);
		assertEquals("The connection wobbled. Cause not measured.", p.proof);

		// With no fresh RTT in the span the proof says so, because it fits.
		final Trace blind = Trace.steady(200).frameGap(120, 290, 90).rttNoData(0, 199, NoData.UNSUPPORTED);
		final Session bs = blind.build();
		final Verdict b = judge.judgeEvent(bs, event(bs, 3, 120, 120, Trigger.FRAME_GAP), blind.settings());
		assertCantTellNamingNothing(b);
		assertEquals("A 90 ms freeze. Its cause was not measured. No ping data.", b.proof);

		for (Trigger first : Trigger.values())
		{
			final Verdict any = judge.judgeEvent(fs, event(fs, 9, 150, 150, first), freeze.settings());
			assertFalse(first + ": " + any.proof, any.proof.contains("Nothing measured"));
			assertFalse(first + ": " + any.proof, any.proof.toLowerCase().contains("nothing moved"));
			assertFalse(any.proof.isEmpty());
		}
	}

	/** 3.7's case: alt-tabbed under FPS Control's unfocused limit of 10, its focused limit off, the CPU renderer. */
	@Test
	public void unfocusedUnderTheUnfocusedLimitIsF1()
	{
		final SettingsView settings = new SettingsView(Renderer.CPU, true, false, 0, true, 10, false, "", 0, 0, "",
			0, 60, Os.WINDOWS, "");
		final Trace t = Trace.steady(200).usual(USUAL).fps(100, 199, 10).unfocused(100, 199).settings(settings);
		final Session s = t.build();
		final VerdictEngine engine = new VerdictEngine();
		int firstF1 = -1;
		for (int now = 1; now <= 200; now++)
		{
			final Verdict v = engine.current(s, now, s.wallMsOf(now), settings);
			if (now >= 101)
			{
				assertNotEquals("never slow drawing, at " + now, Cause.SLOW_DRAWING, v.cause);
				final Verdict direct = new VerdictEngine().conditionNow(s, now, settings);
				assertTrue("no step's winner is F2, at " + now, direct == null || direct.cause != Cause.SLOW_DRAWING);
			}
			if (v.cause == Cause.FRAME_CAP && firstF1 < 0)
			{
				firstF1 = now;
			}
			if (now >= 121)
			{
				assertEquals("F1 from 121 at the latest, at " + now, Cause.FRAME_CAP, v.cause);
				assertEquals("Frame rate is capped at 10", v.headline);
				assertEquals("Set by FPS Control (unfocused). Not lag.", v.proof);
				assertEquals(Level.WARN, v.level);
			}
		}
		assertTrue("the cap must first hold CONDITION_HOLD_S, then win as long: " + firstF1, firstF1 > 110);

		// Read as focused the same seconds would be slow drawing: the focus of the second is what decides.
		final Session focused = Trace.steady(200).usual(USUAL).fps(100, 199, 10).build();
		assertEquals(Cause.SLOW_DRAWING, card(focused, settings, 200).cause);
	}

	/** F2 is judged on its run, not on the window's median (G3). */
	@Test
	public void slowDrawingPrintsTheRateOfItsRun()
	{
		final Trace t = Trace.steady(60).usual(USUAL).fps(45, 59, 24);
		final Session s = t.build();
		final Evidence ev = EvidenceBuilder.forCondition(s, 60, t.settings());
		assertEquals("the window's median is the fast rate", 50, ev.fps);
		assertEquals(15, ev.lowFpsS);
		assertEquals(24, ev.lowFps);

		final Verdict v = new VerdictEngine().conditionNow(s, 60, t.settings());
		assertNotNull(v);
		assertEquals(Cause.SLOW_DRAWING, v.cause);
		assertEquals("24 fps for 15 s.", v.proof);
		assertEquals(Confidence.LIKELY, v.confidence);

		// On the card, second by second over a longer slow stretch: F2, and never the window's 50.
		final Trace longer = Trace.steady(120).usual(USUAL).fps(45, 119, 24);
		final Session ls = longer.build();
		final VerdictEngine engine = new VerdictEngine();
		boolean shown = false;
		for (int now = 1; now <= 120; now++)
		{
			final Verdict c = engine.current(ls, now, ls.wallMsOf(now), longer.settings());
			assertFalse("at " + now + ": " + c.proof, c.proof.contains("50 fps"));
			if (c.cause == Cause.SLOW_DRAWING)
			{
				shown = true;
				assertTrue(c.proof, c.proof.startsWith("24 fps for "));
			}
		}
		assertTrue(shown);
	}

	/** A condition leaves out the seconds masked by their flags: a load is not slow drawing. */
	@Test
	public void aLongLoadIsNotSlowDrawing()
	{
		final Trace t = Trace.steady(100).usual(USUAL).fps(80, 91, 5);
		for (int sec = 80; sec <= 91; sec++)
		{
			t.loading(sec, 1000);
		}
		final Session s = t.build();
		final VerdictEngine engine = new VerdictEngine();
		for (int now = 1; now <= 100; now++)
		{
			final Verdict v = engine.current(s, now, s.wallMsOf(now), t.settings());
			assertEquals("at " + now, Cause.ALL_CLEAR, v.cause);
			assertNull("no condition scores, at " + now, new VerdictEngine().conditionNow(s, now, t.settings()));
		}

		// The same twelve seconds with no load are slow drawing: the mask is what saved them.
		final Session slow = Trace.steady(100).usual(USUAL).fps(80, 91, 5).build();
		final Verdict v = new VerdictEngine().conditionNow(slow, 92, t.settings());
		assertNotNull(v);
		assertEquals(Cause.SLOW_DRAWING, v.cause);
	}

	/**
	 * W1c needs "no event open or closed in the window" (6.3). The log keeps an open event as opened handed it in,
	 * with its end at its first trigger second (3.4, 3.6); while it stays open it still reaches the newest second, so
	 * a slow world is not a condition then, however long ago the event opened.
	 */
	@Test
	public void w1cNeverShowsWhileAnEventIsOpen()
	{
		final Trace t = Trace.steady(220).usual(USUAL).ticksEvery(100, 219, 750);

		// With no event the slow ticks are the condition W1c, on the card long before the trace ends.
		final Session free = t.build();
		final VerdictEngine freeCard = new VerdictEngine();
		int firstW1c = -1;
		for (int now = 1; now <= 220; now++)
		{
			final Verdict v = freeCard.current(free, now, free.wallMsOf(now), t.settings());
			if (v.cause == Cause.SLOW_WORLD && firstW1c < 0)
			{
				firstW1c = now;
				assertEquals("This world is running slow", v.headline);
				assertEquals(Level.WARN, v.level);
			}
		}
		assertTrue("W1c shows with no event", firstW1c > 0);

		// The same trace with an event that opened at 100 and never closed: never W1c.
		final Session s = t.build();
		final VerdictEngine engine = new VerdictEngine();
		for (int now = 1; now <= 220; now++)
		{
			if (now == 101)
			{
				s.events.add(new VerdictCauseTest.LagEventSpec(0, 100, 100, Trigger.TICK_OFF).open(true).on(s));
			}
			final Verdict v = engine.current(s, now, s.wallMsOf(now), t.settings());
			assertNotEquals("at " + now, Cause.SLOW_WORLD, v.cause);
			if (now >= 101)
			{
				final Evidence ev = EvidenceBuilder.forCondition(s, now, t.settings());
				assertTrue("the open event is in the window, at " + now, ev.eventInWindow);
				assertEquals("at " + now, 0, Rules.W1C.score(ev));
			}
		}
		assertEquals("an open event is not a closed one: the card has no event to show", "No lag this session.",
			engine.current(s, 220, s.wallMsOf(220), t.settings()).proof);
	}

	/** The judge never reads {@code LagEvent.open}: an open event is judged as if it closed now (3.6). */
	@Test
	public void anOpenEventIsJudgedAsIfItClosedNow()
	{
		final Trace t = VerdictCauseTest.w1Trace();
		final Session s = t.build();
		final LagEvent closed = new VerdictCauseTest.LagEventSpec(5, 120, 133, Trigger.TICK_OFF).on(s);
		final LagEvent open = new VerdictCauseTest.LagEventSpec(5, 120, 133, Trigger.TICK_OFF).open(true).on(s);
		assertTrue(open.open);
		final Verdict a = judge.judgeEvent(s, closed, t.settings());
		final Verdict b = judge.judgeEvent(s, open, t.settings());
		assertEquals(Cause.SLOW_WORLD, b.cause);
		assertTrue(a.sameAs(b));
		assertEquals(a.confidence, b.confidence);
		assertEquals(a.level, b.level);
		assertEquals(a.ruledOut, b.ruledOut);
		assertEquals(a.whenWallMs, b.whenWallMs);
		assertEquals(a.durationS, b.durationS);
		assertEquals(a.world, b.world);

		// Early in the lag the span is short, and the truth at that second is "Can't tell".
		final LagEvent early = new VerdictCauseTest.LagEventSpec(5, 120, 121, Trigger.TICK_OFF).open(true).on(s);
		final Verdict e = judge.judgeEvent(s, early, t.settings());
		assertNotEquals("W1 needs SLOW_WORLD_MIN_TICKS ticks", Cause.SLOW_WORLD, e.cause);

		// Judging an open event touches neither the log nor the card.
		final VerdictEngine engine = new VerdictEngine();
		final Verdict before = engine.current(s, 134, s.wallMsOf(134), t.settings());
		engine.judgeEvent(s, open, t.settings());
		assertEquals(0, s.events.size());
		assertTrue(before == engine.current(s, 134, s.wallMsOf(134), t.settings()));
	}

	private static void assertCantTellNamingNothing(Verdict v)
	{
		assertEquals(Cause.NOT_SURE, v.cause);
		assertEquals(Confidence.CANT_TELL, v.confidence);
		assertNull(v.alsoA);
		assertNull(v.alsoB);
		assertEquals("Can't tell yet", v.headline);
		assertEquals("Wait for it to happen again.", v.fix);
	}
}

package com.whylag.core;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static com.whylag.core.VerdictCauseTest.USUAL;
import static com.whylag.core.VerdictCauseTest.card;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * What the judge says when a signal cannot be read (contract 6.3, section 7 L4): no ping, no usual. A missing
 * signal costs reach or a step of confidence, never a wrong cause.
 */
public class VerdictNoDataTest
{
	private static final int NO_USUAL = -1;

	/** One judged event: the trace's session and settings, the event, and the verdict. */
	private static final class Judged
	{
		final String name;
		final Session s;
		final SettingsView settings;
		final LagEvent event;
		final Verdict verdict;
		final Evidence evidence;

		Judged(String name, Trace t, VerdictCauseTest.LagEventSpec spec)
		{
			this.name = name;
			s = t.build();
			settings = t.settings();
			event = spec.on(s);
			verdict = new VerdictEngine().judgeEvent(s, event, settings);
			evidence = EvidenceBuilder.forEvent(s, event, settings);
		}
	}

	private static VerdictCauseTest.LagEventSpec spec(int from, int to, Trigger first, Trigger... more)
	{
		return new VerdictCauseTest.LagEventSpec(0, from, to, first, more);
	}

	// ------------------------------------------------------------------ the traces

	private static Judged lossWithNoPing()
	{
		return new Judged("N3, no ping", VerdictCauseTest.n3Trace().rttNoData(0, 199, NoData.UNSUPPORTED),
			spec(120, 120, Trigger.RESENT));
	}

	private static Judged stallWithNoPing()
	{
		return new Judged("S3, no ping", VerdictCauseTest.s3Trace().rttNoData(0, 199, NoData.ERROR),
			spec(120, 120, Trigger.FRAME_GAP));
	}

	private static Judged slowWorldWithNoPing()
	{
		return new Judged("W1, no ping", VerdictCauseTest.w1Trace().rttNoData(0, 199, NoData.UNSUPPORTED),
			spec(120, 133, Trigger.TICK_OFF));
	}

	private static Judged slowWorldWithAStalePing()
	{
		return new Judged("W1, stale ping", VerdictCauseTest.w1Trace().rttStale(100, 199),
			spec(120, 133, Trigger.TICK_OFF));
	}

	private static Judged stallWithNoUsual()
	{
		return new Judged("S3, no usual", Trace.steady(200).frameGap(120, 600, 480),
			spec(120, 120, Trigger.FRAME_GAP).usual(NO_USUAL));
	}

	private static Judged slowWorldWithNoUsual()
	{
		return new Judged("W1, no usual", Trace.steady(200).ticksEvery(120, 133, 900),
			spec(120, 133, Trigger.TICK_OFF).usual(NO_USUAL));
	}

	/**
	 * Ticks stop for 3 s while a fresh RTT sits at 400 ms, before this world has a usual: the first quiet seconds of
	 * every world, a hop included, since the detector resets the usual when the world changes.
	 */
	private static Trace gapWithAHighPing()
	{
		return Trace.steady(200).noTicks(120, 121).rtt(120, 122, 400);
	}

	private static Judged gapWithAHighPingAndNoUsual()
	{
		return new Judged("N6, known ping, no usual", gapWithAHighPing(),
			spec(120, 122, Trigger.NO_TICK, Trigger.TICK_OFF, Trigger.RTT_SPIKE).usual(NO_USUAL));
	}

	private static List<Judged> everyTraceAbove()
	{
		final List<Judged> out = new ArrayList<>();
		out.add(lossWithNoPing());
		out.add(stallWithNoPing());
		out.add(slowWorldWithNoPing());
		out.add(slowWorldWithAStalePing());
		out.add(stallWithNoUsual());
		out.add(slowWorldWithNoUsual());
		out.add(gapWithAHighPingAndNoUsual());
		return out;
	}

	// ------------------------------------------------------------------ the tests

	@Test
	public void noPingLowersTheCeiling()
	{
		final Judged loss = lossWithNoPing();
		assertFalse(loss.evidence.rttKnown);
		assertEquals(Evidence.NO_DATA, loss.evidence.rttSpike);
		assertEquals("the spike support is skipped", 90, Rules.N3.score(loss.evidence));
		assertEquals(Cause.UPLOAD_LOSS, loss.verdict.cause);
		assertEquals("Likely, one step down", Confidence.HINT, loss.verdict.confidence);
		// With its ping the same trace answers at its full ceiling.
		assertEquals(Confidence.LIKELY, VerdictCauseTest.n3().verdict().confidence);

		final Judged stall = stallWithNoPing();
		assertEquals("the calm-ping support is skipped", 80, Rules.S3.score(stall.evidence));
		assertEquals(Cause.CLIENT_BUSY, stall.verdict.cause);
		assertEquals("Hint, one step down", Confidence.CANT_TELL, stall.verdict.confidence);
		assertEquals(Confidence.HINT, VerdictCauseTest.s3().verdict().confidence);
	}

	/**
	 * W1 needs a known ping. Before the first live look the slow ticks then fell to N6, "No ticks for 0.9 s": a 900 ms
	 * gap is no stop, and N6 needs the NO_TICK trigger since (2026-09-29), so the judge can't tell and names the ticks.
	 */
	@Test
	public void noPingFailsW1AndCannotTell()
	{
		for (Judged j : new Judged[] {slowWorldWithNoPing(), slowWorldWithAStalePing()})
		{
			assertFalse(j.name, j.evidence.rttKnown);
			assertEquals(j.name + ": W1 needs a known ping", 0, Rules.W1.score(j.evidence));
			assertEquals(j.name + ": N6 needs a real stop", 0, Rules.N6.score(j.evidence));
			assertEquals(j.name, Cause.NOT_SURE, j.verdict.cause);
			assertEquals(j.name, Confidence.CANT_TELL, j.verdict.confidence);
			assertTrue(j.name + ": " + j.verdict.proof,
				j.verdict.proof.startsWith("Ticks ran 300 ms off. Cause not measured."));
			assertFalse(j.name, j.verdict.proof.contains("No ticks"));
		}
		assertEquals(Cause.SLOW_WORLD, VerdictCauseTest.w1().verdict().cause);
	}

	@Test
	public void noUsualMakesTheSpikeNoData()
	{
		final Judged stall = stallWithNoUsual();
		assertTrue("the ping itself is there", stall.evidence.rttKnown);
		assertEquals(-1, stall.evidence.rttUsual);
		assertEquals(Evidence.NO_DATA, stall.evidence.rttSpike);
		assertEquals(Cause.CLIENT_BUSY, stall.verdict.cause);
		assertEquals("one step under its ceiling", Confidence.CANT_TELL, stall.verdict.confidence);
		assertEquals("Can't tell", stall.verdict.confidence.word());

		final Judged world = slowWorldWithNoUsual();
		assertEquals(Evidence.NO_DATA, world.evidence.rttSpike);
		assertEquals("a need on the spike fails", 0, Rules.W1.score(world.evidence));
		assertNotEquals(Cause.SLOW_WORLD, world.verdict.cause);
		assertNotEquals(Cause.SLOW_WORLD, world.verdict.alsoA);
		// N6 needs a real stop since the first live look: the 900 ms ticks are X's, not "No ticks for 0.9 s".
		assertEquals(Cause.NOT_SURE, world.verdict.cause);
		assertTrue("the ping itself is there", world.evidence.rttKnown);
		assertEquals("no usual: the ping was not judged, so the proof does not call it fine",
			"Ticks ran 300 ms off. Cause not measured.", world.verdict.proof);

		// The trigger bit does not make data: with no usual the spike has none, whatever the bit says.
		final Trace t = Trace.steady(200).rtt(120, 120, 400);
		final Session s = t.build();
		final LagEvent bit = spec(120, 120, Trigger.TICK_OFF, Trigger.RTT_SPIKE).usual(NO_USUAL).on(s);
		assertEquals(Evidence.NO_DATA, EvidenceBuilder.forEvent(s, bit, t.settings()).rttSpike);
		final LagEvent known = spec(120, 120, Trigger.TICK_OFF, Trigger.RTT_SPIKE).on(s);
		assertEquals(Evidence.YES, EvidenceBuilder.forEvent(s, known, t.settings()).rttSpike);

		// D1 with no usual and clean re-sends.
		final Trace d = Trace.steady(200).disconnect(120);
		final Session ds = d.build();
		final Verdict v = new VerdictEngine().judgeEvent(ds, spec(120, 120, Trigger.DISCONNECT).usual(NO_USUAL)
			.on(ds), d.settings());
		assertEquals(Cause.DISCONNECT, v.cause);
		assertEquals("No ping data just before.", v.proof);
		assertEquals("Log in again. Note if it repeats.", v.fix);
	}

	/**
	 * N6's ping part (6.4) is its "ping no data" form whenever the spike has no data, and with no usual it has none
	 * even though a fresh RTT exists (6.3). The proof then agrees with {@code ruledOut}, which leaves the ping out too.
	 */
	@Test
	public void aKnownPingWithNoUsualIsNotCalledFine()
	{
		final Judged j = gapWithAHighPingAndNoUsual();
		assertTrue("a fresh RTT", j.evidence.rttKnown);
		assertEquals(400, j.evidence.rttMax);
		assertEquals(-1, j.evidence.rttUsual);
		assertEquals("the trigger bit does not make data", Evidence.NO_DATA, j.evidence.rttSpike);
		assertEquals(3000, j.evidence.noTickMs);
		assertEquals("the exclude on the spike is skipped", 75, Rules.N6.score(j.evidence));
		assertEquals(Cause.DELIVERY_GAP, j.verdict.cause);
		assertEquals(Confidence.CANT_TELL, j.verdict.confidence);
		assertEquals("No ticks for 3.0 s. Frames were fine.", j.verdict.proof);
		assertEquals("Frames were fine.", j.verdict.ruledOut);
		assertFalse(j.verdict.proof, j.verdict.proof.contains("ping"));

		// With a usual of 40 the same 400 ms is a spike, which excludes N6: nothing answers, and X names the ticks.
		final Trace known = gapWithAHighPing().usual(USUAL);
		final Session s = known.build();
		final Verdict x = new VerdictEngine().judgeEvent(s,
			spec(120, 122, Trigger.NO_TICK, Trigger.TICK_OFF, Trigger.RTT_SPIKE).on(s), known.settings());
		assertEquals(Cause.NOT_SURE, x.cause);
		assertEquals("Ticks ran 2,400 ms off. Cause not measured.", x.proof);

		// And with the usual and a calm ping, N6 at its full ceiling calls the ping fine.
		final Trace calm = Trace.steady(200).usual(USUAL).noTicks(120, 121);
		final Session cs = calm.build();
		final Verdict n6 = new VerdictEngine().judgeEvent(cs, spec(120, 122, Trigger.NO_TICK, Trigger.TICK_OFF)
			.on(cs), calm.settings());
		assertEquals(Cause.DELIVERY_GAP, n6.cause);
		assertEquals("No ticks for 3.0 s. Frames and ping were fine.", n6.proof);
		assertEquals("Frames and ping were fine.", n6.ruledOut);
	}

	@Test
	public void aVerdictNeverExceedsItsCeiling()
	{
		int checked = 0;
		for (Judged j : everyTraceAbove())
		{
			assertWithinCeiling(j.name, j.verdict);
			checked++;
		}
		for (VerdictCauseTest.Case c : VerdictCauseTest.all())
		{
			assertWithinCeiling(c.id, c.verdict());
			checked++;
		}
		assertEquals(19, checked);
	}

	private static void assertWithinCeiling(String name, Verdict v)
	{
		Rule rule = null;
		for (Rule r : Rules.ALL)
		{
			final boolean condition = r.kind == Rule.Kind.CONDITION;
			if (r.cause == v.cause && (v.cause != Cause.SLOW_WORLD || condition == (v.level == Level.WARN)))
			{
				rule = r;
			}
		}
		assertTrue(name + ": a rule gives " + v.cause, rule != null);
		assertTrue(name + ": " + v.confidence + " is over the ceiling " + rule.ceiling + " of " + rule.id,
			v.confidence.ordinal() >= rule.ceiling.ordinal());
		assertFalse(name + " is a verdict, not a state", v.cause == Cause.WARMING_UP);
	}
}

package com.whylag.core;

import org.junit.Test;
import static com.whylag.core.VerdictCauseTest.USUAL;
import static com.whylag.core.VerdictCauseTest.event;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * What the card shows from second to second (contract 6.5): no flicker, the holds, the three states, the counting
 * texts, and what each kind of verdict carries (3.6). "Now" at the end of n seconds is {@code nowSec = n} (3.5).
 */
public class VerdictStabilityTest
{
	private static Verdict step(VerdictEngine engine, Session s, SettingsView settings, int nowSec)
	{
		return engine.current(s, nowSec, s.wallMsOf(nowSec), settings);
	}

	/** A closed one-second event at {@code sec} of a stall trace, judged, ready for the log. */
	private static LagEvent stallAt(Session s, SettingsView settings, long id, int sec)
	{
		return lagOver(s, settings, id, sec, sec);
	}

	/**
	 * A closed event over {@code from .. to}, judged, ready for the log. A span of several seconds tells the event's
	 * start from its end, which a one-second event cannot.
	 */
	private static LagEvent lagOver(Session s, SettingsView settings, long id, int from, int to)
	{
		final LagEvent e = event(s, id, from, to, Trigger.FRAME_GAP);
		return e.withVerdict(new VerdictEngine().judgeEvent(s, e, settings));
	}

	private static Trace stallTrace(int seconds, int... stallSeconds)
	{
		final Trace t = Trace.steady(seconds).usual(USUAL);
		for (int sec : stallSeconds)
		{
			t.frameGap(sec, 600, 480);
		}
		return t;
	}

	/**
	 * Ten minutes of a frame rate that hovers on the FPS_WARN line: 25 slow seconds, 5 fast ones, over and over. The
	 * slow-drawing condition comes and goes every 30 s; without the hold the card would drop it 6 s after showing it.
	 */
	@Test
	public void aTraceHoveringOnALineChangesTheCardAtMostOncePerTenSeconds()
	{
		final Trace t = Trace.steady(600).usual(USUAL);
		for (int from = 0; from < 600; from += 30)
		{
			t.fps(from, from + 24, 38);
		}
		final Session s = t.build();
		final VerdictEngine engine = new VerdictEngine();
		Verdict before = null;
		int lastChange = -1;
		int changes = 0;
		int causeChanges = 0;
		for (int now = 1; now <= 600; now++)
		{
			final Verdict v = step(engine, s, t.settings(), now);
			if (before != null && v != before)
			{
				assertTrue("changed at " + lastChange + " and again at " + now,
					lastChange < 0 || now - lastChange >= Thresholds.VERDICT_HOLD_S);
				lastChange = now;
				changes++;
				causeChanges += v.cause != before.cause ? 1 : 0;
			}
			before = v;
		}
		assertTrue("the trace must make the card move, or this test proves nothing: " + changes, changes >= 30);
		assertTrue("slow drawing came and went: " + causeChanges, causeChanges >= 30);
		assertTrue("at most once per VERDICT_HOLD_S", changes <= 600 / Thresholds.VERDICT_HOLD_S);
	}

	/**
	 * Rule 3: an event's verdict stays EVENT_SHOW_S (10 s since 2026-09-29) after the event's END, and rule 5's hold
	 * decides when the card may change. The lag lasts fourteen seconds, 100 to 113, so its start and its end tell
	 * apart. The card first names it at 119, when the detector's close is in the log; the show ended at 123, but the
	 * card stood only since 119 and changes once it has stood VERDICT_HOLD_S: the first V2 is at 129 and reads
	 * "No lag for 10 s.", counts from the END and carries the event's START (3.6).
	 */
	@Test
	public void anEventShowsForTenSecondsAndTheHoldAllowsTheChange()
	{
		final int start = 100;
		final int end = 113;
		final Trace t = stallTrace(400, start, end);
		final Session s = t.build();
		final LagEvent lag = lagOver(s, t.settings(), 0, start, end);
		assertEquals(14, lag.lengthS());
		final int closedAt = end + Thresholds.EVENT_QUIET_S + 1;
		final int firstV2 = Math.max(end + Thresholds.EVENT_SHOW_S, closedAt + Thresholds.VERDICT_HOLD_S);
		final VerdictEngine engine = new VerdictEngine();
		int lastShown = -1;
		int firstClearAt = -1;
		Verdict firstClear = null;
		for (int now = 1; now <= 400; now++)
		{
			if (now == closedAt)
			{
				// The detector closes it EVENT_QUIET_S quiet seconds after its last trigger second.
				s.events.add(lag);
			}
			final Verdict v = step(engine, s, t.settings(), now);
			if (now < closedAt)
			{
				assertEquals("at " + now, Cause.ALL_CLEAR, v.cause);
				assertEquals("No lag this session.", v.proof);
			}
			else if (now < firstV2)
			{
				assertSame("the event's own verdict, at " + now, lag.verdict, v);
				lastShown = now;
			}
			else
			{
				assertEquals("at " + now, Cause.ALL_CLEAR, v.cause);
				assertEquals("counted from the END, at " + now, allClearWords(now - end), v.proof);
				assertEquals("the START of the newest event, at " + now, s.wallMsOf(start), v.whenWallMs);
				if (firstClear == null)
				{
					firstClear = v;
					firstClearAt = now;
				}
			}
		}
		assertEquals("the last second it shows: the hold, not the show, keeps it", 128, lastShown);
		assertEquals("the first V2 is its end + 16", 129, firstClearAt);
		assertEquals("No lag for 10 s.", firstClear.proof);
		assertEquals(lag.startWallMs, firstClear.whenWallMs);
		assertNotEquals("not the end's clock", s.wallMsOf(end), firstClear.whenWallMs);
		assertEquals(416, firstClear.world);
		assertEquals(-1, firstClear.eventId);
		assertEquals(0, firstClear.durationS);
	}

	/**
	 * The card is Smooth 15 s after the last bad tick (addendum D, the user 2026-09-29): a lag whose last trigger
	 * second is T closes at T + EVENT_QUIET_S, the card names it from then through T + 14, and at T + 15 - the show
	 * (EVENT_SHOW_S 10) has ended and the hold (VERDICT_HOLD_S 10) allows the change - it reads ALL_CLEAR "No lag for
	 * 10 s.". The text then steps every ten seconds, "20 s." at T + 25, and counts minutes from "1 min." at T + 65;
	 * between steps it is the SAME object.
	 *
	 * <p>Choice: the plan's timeline counts from the last bad tick with the close at T + 5; the event is put in the
	 * log at that step. (The older tests here add it one step later, at end + EVENT_QUIET_S + 1, the detector's
	 * close as the sampler sees it, and read V2 one step later too.)
	 */
	@Test
	public void theCardIsSmoothFifteenSecondsAfterTheLastBadTick()
	{
		final int last = 100;
		final Trace t = stallTrace(300, 97, last);
		final Session s = t.build();
		final LagEvent lag = lagOver(s, t.settings(), 0, 97, last);
		assertEquals("the last bad tick is T", last, lag.endSec);
		final VerdictEngine engine = new VerdictEngine();
		Verdict smooth = null;
		Verdict before = null;
		Verdict minute = null;
		for (int now = 1; now <= 200; now++)
		{
			if (now == last + Thresholds.EVENT_QUIET_S)
			{
				s.events.add(lag);
			}
			final Verdict v = step(engine, s, t.settings(), now);
			final String at = "at T + " + (now - last);
			if (now < last + Thresholds.EVENT_QUIET_S)
			{
				assertEquals("nothing to name yet, " + at, "No lag this session.", v.proof);
			}
			else if (now <= last + 14)
			{
				assertSame("the card names the lag, " + at, lag.verdict, v);
				assertNotEquals(Cause.ALL_CLEAR, v.cause);
			}
			else
			{
				assertEquals("Smooth, " + at, Cause.ALL_CLEAR, v.cause);
				assertEquals("Smooth", v.headline);
				assertEquals(at, allClearWords(now - last), v.proof);
				if (now == last + 15)
				{
					assertEquals("No lag for 10 s.", v.proof);
					assertSame("the lag was on the card the second before", lag.verdict, before);
					smooth = v;
				}
				else if (now < last + 20)
				{
					assertSame("the same object between steps, " + at, smooth, v);
				}
				if (now == last + 25)
				{
					assertEquals("No lag for 20 s.", v.proof);
				}
				if (now == last + 65)
				{
					assertEquals("No lag for 1 min.", v.proof);
					minute = v;
				}
				else if (now > last + 65 && now < last + 120)
				{
					assertSame("the same object between steps, " + at, minute, v);
				}
			}
			before = v;
		}
		assertNotNull(smooth);
		assertNotNull(minute);
	}

	/** The words of V2's counting text, worked out here: steps of ten seconds under a minute, then whole minutes. */
	private static String allClearWords(long sinceEndS)
	{
		return sinceEndS < 60 ? "No lag for " + Math.max(10, sinceEndS / 10 * 10) + " s."
			: "No lag for " + sinceEndS / 60 + " min.";
	}

	/** Rule 2: inside the hold an event waits, and the newest waiting event wins. */
	@Test
	public void anEventWaitsOutTheHoldAndTheNewestWaitingOneWins()
	{
		final Trace t = stallTrace(400, 100, 108, 110);
		final Session s = t.build();
		final LagEvent first = stallAt(s, t.settings(), 0, 100);
		final LagEvent second = event(s, 1, 108, 108, Trigger.FRAME_GAP);
		final LagEvent third = stallAt(s, t.settings(), 2, 110);
		final VerdictEngine engine = new VerdictEngine();
		for (int now = 1; now <= 130; now++)
		{
			if (now == 106)
			{
				s.events.add(first);
			}
			if (now == 110)
			{
				// It came with no verdict: the judge makes one, once.
				s.events.add(second);
			}
			if (now == 114)
			{
				s.events.add(third);
			}
			final Verdict v = step(engine, s, t.settings(), now);
			if (now >= 106 && now <= 115)
			{
				assertSame("the card changed at 106 and holds, at " + now, first.verdict, v);
			}
			if (now >= 116 && now <= 125)
			{
				assertSame("the second event never showed; the newest did, at " + now, third.verdict, v);
			}
			if (now >= 126)
			{
				// The third one's show ended at 120 (110 + EVENT_SHOW_S), but the card changed at 116: the hold
				// lets it go at 126.
				assertEquals("at " + now, Cause.ALL_CLEAR, v.cause);
			}
		}

		// Alone, the event that came without a verdict is judged by the card, and the object is kept.
		final Session alone = t.build();
		final VerdictEngine other = new VerdictEngine();
		alone.events.add(event(alone, 1, 108, 108, Trigger.FRAME_GAP));
		final Verdict v = step(other, alone, t.settings(), 114);
		assertEquals(Cause.CLIENT_BUSY, v.cause);
		assertEquals(1, v.eventId);
		assertSame(v, step(other, alone, t.settings(), 115));
	}

