	/** T17: no StripChart and no EventList among the panel's components, and neither one's paintComponent runs. */
	@Test
	public void aFoldedBlockIsNotInTheLayout()
	{
		final WhyLagPanel folded = panel(PanelFixtures.lag(), false);
