	/** Open, hidden, shown again: still open. (A hide clears the selection, never the folds.) */
	@Test
	public void theStateOutlivesDeactivate()
	{
		final WhyLagPanel p = panel(PanelFixtures.lag(), true);
		edt(p::onDeactivate);
