	// ============================================================================ Swing

	interface EdtAction
	{
		void run() throws Exception;
	}

	/** Runs on the Swing thread and waits; a failure there is thrown here. */
	static void edt(EdtAction action)
	{
		onEdt(() ->
		{
			action.run();
			return null;
		});
	}

	/** Answers {@code call} run on the Swing thread; a failure there is thrown here. */
	static <T> T onEdt(Callable<T> call)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			return callNow(call);
		}
		final List<T> result = new ArrayList<>();
		final Throwable[] failure = new Throwable[1];
		try
		{
			SwingUtilities.invokeAndWait(() ->
			{
				try
				{
					result.add(call.call());
				}
				catch (Throwable t)
				{
					failure[0] = t;
				}
			});
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
		catch (Exception e)
		{
			// invokeAndWait wraps what the task threw; the task here catches its own, so this is the wrapper's cause
			throw new AssertionError(e.getCause() != null ? e.getCause() : e);
		}
		if (failure[0] instanceof Error)
		{
			throw (Error) failure[0];
		}
		if (failure[0] instanceof RuntimeException)
		{
			throw (RuntimeException) failure[0];
		}
		if (failure[0] != null)
		{
			throw new AssertionError(failure[0]);
		}
		return result.get(0);
	}

	private static <T> T callNow(Callable<T> call)
	{
		try
		{
			return call.call();
		}
		catch (RuntimeException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	/** A left-button press at (x, y) of a component, on the Swing thread. */
	static void press(Component c, int x, int y)
	{
		edt(() -> c.dispatchEvent(new MouseEvent(c, MouseEvent.MOUSE_PRESSED, System.currentTimeMillis(),
			InputEvent.BUTTON1_DOWN_MASK, x, y, 1, false, MouseEvent.BUTTON1)));
	}

	/** The tooltip a component gives at (x, y). */
	static String tip(JComponent c, int x, int y)
	{
		return onEdt(() -> c.getToolTipText(new MouseEvent(c, MouseEvent.MOUSE_MOVED, 0, 0, x, y, 0, false)));
	}

	// ============================================================================ painting

	/** A block painted as Swing paints it, at its preferred size. */
	static BufferedImage paint(JComponent c)
	{
		return onEdt(() ->
		{
			final Dimension d = c.getPreferredSize();
			c.setSize(d);
			final BufferedImage img = new BufferedImage(d.width, d.height, BufferedImage.TYPE_INT_ARGB);
			final Graphics2D g = img.createGraphics();
			try
			{
				c.paint(g);
			}
			finally
			{
				g.dispose();
			}
			return img;
		});
	}

	/** A whole panel painted as Swing paints it, blocks and all. */
	static BufferedImage paintPanel(WhyLagPanel p)
	{
		return onEdt(() ->
		{
			layOut(p);
			final BufferedImage img = new BufferedImage(p.getWidth(), p.getHeight(), BufferedImage.TYPE_INT_ARGB);
			final Graphics2D g = img.createGraphics();
			try
			{
				p.paint(g);
			}
			finally
			{
				g.dispose();
			}
			return img;
		});
	}

	/**
	 * A whole panel painted as Swing paints it, and, when the fixture has its gear menu open, the menu painted over it
	 * where it would stand: under the gear, its right edge at the gear's. The menu is the one the panel built at the
	 * press on the gear, laid out and painted without a window, so it wears the test's look and feel, not the
	 * client's.
	 */
	static BufferedImage paintPanel(Fixture f, WhyLagPanel p)
	{
		final BufferedImage img = paintPanel(p);
		if (f.menuOpen)
		{
			onEdt(() ->
			{
				final JPopupMenu menu = p.menu();
				final Dimension d = menu.getPreferredSize();
				menu.setSize(d);
				layOutTree(menu);
				final Rectangle gear = p.header().gearBounds();
				final Graphics2D g = img.createGraphics();
				try
				{
					g.translate(p.header().getX() + gear.x + gear.width - d.width,
						p.header().getY() + p.header().getHeight());
					menu.paint(g);
				}
				finally
				{
					g.dispose();
				}
				return null;
			});
		}
		return img;
	}

	/** Places the children of a container that was never shown, and theirs, each at its own preferred size. */
	static void layOutTree(java.awt.Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof java.awt.Container)
			{
				if (child.getWidth() == 0 && child.getHeight() == 0)
				{
					child.setSize(child.getPreferredSize());
				}
				layOutTree((java.awt.Container) child);
			}
		}
	}

	/**
	 * Sizes the panel to {@code width} and to its preferred height at that width, and places its blocks. The panel is
	 * sized twice: the first size makes the blocks measure at the new width, the second gives it the height they
	 * then need (a wrapping block may be shorter in a wider panel).
	 */
	static void layOutAt(WhyLagPanel p, int width)
	{
		p.setSize(width, 0);
		p.setSize(width, p.getPreferredSize().height);
		p.doLayout();
	}

	/** A whole panel {@code width} wide, painted as Swing paints it, blocks and all. */
	static BufferedImage paintPanelAt(WhyLagPanel p, int width)
	{
		return onEdt(() ->
		{
			layOutAt(p, width);
			final BufferedImage img = new BufferedImage(p.getWidth(), p.getHeight(), BufferedImage.TYPE_INT_ARGB);
			final Graphics2D g = img.createGraphics();
			try
			{
				p.paint(g);
			}
			finally
			{
				g.dispose();
			}
			return img;
		});
	}

	/**
	 * A block's own painting with NO clip, into an image {@code width} wide and 20 px taller than the block that
	 * starts as {@link #SENTINEL}: whatever the block paints past its bounds shows.
	 */
	static BufferedImage paintUnclipped(JComponent c, int width)
	{
		return onEdt(() ->
		{
			final Dimension d = c.getPreferredSize();
			c.setSize(d);
			final BufferedImage img = new BufferedImage(width, d.height + 20, BufferedImage.TYPE_INT_ARGB);
			final Graphics2D g = img.createGraphics();
			try
			{
				g.setColor(SENTINEL);
				g.fillRect(0, 0, img.getWidth(), img.getHeight());
				paintComponent(c, g);
			}
			finally
			{
				g.dispose();
			}
			return img;
		});
	}

	/** The strings a block draws, each with its font, colour and the ground under it, painted with no clip. */
	static List<Drawn> record(JComponent c)
	{
		return onEdt(() ->
		{
			final Dimension d = c.getPreferredSize();
			c.setSize(d);
			final BufferedImage img = new BufferedImage(Math.max(1, d.width + 40), Math.max(1, d.height + 20),
				BufferedImage.TYPE_INT_ARGB);
			final Recorder r = new Recorder(img);
			try
			{
				paintComponent(c, r);
			}
			finally
			{
				r.dispose();
			}
			return r.drawn;
		});
	}

	/**
	 * Calls the block's own {@code paintComponent}: protected, but this package holds every block that overrides it, so
	 * each is called by its own type. A block that is none of them has no override of its own to call.
	 */
	static void paintComponent(JComponent c, Graphics g)
	{
		if (c instanceof AnswerCard)
		{
			((AnswerCard) c).paintComponent(g);
		}
		else if (c instanceof CellStrip)
		{
			((CellStrip) c).paintComponent(g);
		}
		else if (c instanceof EventList)
		{
			((EventList) c).paintComponent(g);
		}
		else if (c instanceof FoldRow)
		{
			((FoldRow) c).paintComponent(g);
		}
		else if (c instanceof HeaderRow)
		{
			((HeaderRow) c).paintComponent(g);
		}
		else if (c instanceof RangeRow)
		{
			((RangeRow) c).paintComponent(g);
		}
		else if (c instanceof SessionCounts)
		{
			((SessionCounts) c).paintComponent(g);
		}
		else if (c instanceof SessionHeader)
		{
			((SessionHeader) c).paintComponent(g);
		}
		else if (c instanceof StripChart)
		{
			((StripChart) c).paintComponent(g);
		}
		else if (c instanceof WhyLagPanel.Footer)
		{
			((WhyLagPanel.Footer) c).paintComponent(g);
		}
		else
		{
			throw new AssertionError("no paintComponent of its own on " + label(c));
		}
	}

	/** The block's name for a failure message, from the same list of blocks {@link #paintComponent} knows. */
	static String label(java.awt.Component c)
	{
		if (c instanceof AnswerCard)
		{
			return "AnswerCard";
		}
		if (c instanceof CellStrip)
		{
			return "CellStrip";
		}
		if (c instanceof EventList)
