	// ------------------------------------------------------------------ helpers

	private static WhyLagPanel devPanel(Fixture f, boolean open)
	{
		final Fixture withFooter = new Fixture(f.name, PanelFixtures.withFooter(f.snapshot, FOOTER), f.selected);
		return PanelFixtures.panel(withFooter, open, open, true, new PanelFixtures.StubActions());
	}

	/**
	 * One block in every fixture and both fold states: 213 wide, its strings in their boxes, nothing painted past
	 * x 212. A foldable block is checked where it is in the layout, and must be absent where its row is folded.
	 */
	private static void eachBlock(Function<WhyLagPanel, JComponent> blockOf, Boxes boxes)
	{
		int checked = 0;
		for (Fixture f : PanelFixtures.all())
		{
			for (boolean open : new boolean[] {false, true})
			{
				final WhyLagPanel p = devPanel(f, open);
				final JComponent block = blockOf.apply(p);
				final String where = f + (open ? " open" : " folded");
				if (block.getParent() != p)
				{
					assertTrue(where + ": only a folded chart or list is out of the layout",
						!open && (block instanceof StripChart || block instanceof EventList));
					continue;
				}
				assertEquals(where, 213, block.getPreferredSize().width);
				assertEquals(where, 213, block.getWidth());
				final List<Drawn> drawn = record(block);
				for (Drawn d : drawn)
				{
					assertTrue(where + ": " + d + " starts at x 0 or more", d.x >= 0);
					assertTrue(where + ": " + d + " ends by x 213", d.right() <= 213);
				}
				boxes.check(where, drawn);
				final BufferedImage img = PanelFixtures.paintUnclipped(block, 260);
				for (int y = 0; y < img.getHeight(); y++)
				{
					for (int x = 213; x < 260; x++)
					{
						if (!is(img, x, y, SENTINEL))
						{
							throw new AssertionError(where + ": painted at " + x + "," + y);
						}
					}
				}
				checked++;
			}
		}
		assertTrue("the block was checked in many fixtures: " + checked, checked >= 20);
	}

	private static void inBox(String where, Drawn d, int from, int to)
	{
		assertTrue(where + ": " + d + " starts at " + from + " or later", d.x >= from);
		assertTrue(where + ": " + d + " (" + d.width + " px) ends by " + to, d.right() <= to);
	}
}

package com.whylag.ui;

import com.whylag.core.Group;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static com.whylag.ui.PanelFixtures.Drawn;
import static com.whylag.ui.PanelFixtures.counts;
import static com.whylag.ui.PanelFixtures.edt;
import static com.whylag.ui.PanelFixtures.record;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The session's counts (contract 5, block 8): the three counts on one line, 11 px apart; a fourth, "? n", only above
 * 0, with the tooltip "Can't tell"; "99+" over 99; items that do not fit go to a second line, and the block is then
 * 32 high; an item is never split and never clipped.
 */
public class SessionCountsTest
{
	@Test
	public void threeCountsAreOneLine()
	{
		final SessionCounts block = counted(counts(1, 1, 1, 0));
		assertEquals(Arrays.asList("Conn 1", "Frame 1", "World 1"), block.items());
		assertEquals(1, block.lines());
		assertEquals(16, block.getPreferredSize().height);
		final List<Drawn> drawn = record(block);
		assertEquals(3, drawn.size());
		int x = 0;
		for (Drawn d : drawn)
		{
			assertEquals(d.toString(), x, d.x);
			assertEquals(12, d.y);
			assertEquals(Ui.RSS, d.font);
			assertEquals(Ui.TEXT.getRGB(), d.colour.getRGB());
			x = d.right() + 11;
		}
		assertNull("no '?' item, no tooltip", PanelFixtures.tip(block, 5, 5));
	}

	/** Four items at "99+" are wider than the block: the ones that do not fit go to a second 16 px line. */
	@Test
	public void wideCountsWrapToASecondLine()
	{
		final SessionCounts block = counted(counts(120, 150, 999, 130));
		assertEquals(Arrays.asList("Conn 99+", "Frame 99+", "World 99+", "? 99+"), block.items());
		assertEquals(2, block.lines());
		assertEquals(32, block.getPreferredSize().height);
		final List<Drawn> drawn = record(block);
		assertEquals(4, drawn.size());
		int second = 0;
		for (Drawn d : drawn)
		{
			assertTrue(d.toString(), d.y == 12 || d.y == 28);
			second += d.y == 28 ? 1 : 0;
		}
		assertTrue(second >= 1);
		Drawn firstOfSecond = null;
		for (Drawn d : drawn)
		{
			if (d.y == 28)
			{
				firstOfSecond = d;
				break;
			}
		}
		assertEquals("a new line starts at x 0", 0, firstOfSecond.x);
		final int index = drawn.indexOf(firstOfSecond);
		assertTrue("it did not fit after the one before it", drawn.get(index - 1).right() + 11 + firstOfSecond.width
			> 213);
		assertEquals("Can't tell", tipOver(block, drawn.get(3)));
		assertNull(tipOver(block, drawn.get(0)));

		final SessionCounts twoDigits = counted(counts(99, 99, 99, 99));
		assertEquals("four two-digit items fit one line or do not: measured", 1, twoDigits.lines());
	}

	/** Every item is drawn whole and inside x 0 .. 213, whatever the counts. */
	@Test
	public void noItemIsSplitOrClipped()
	{
		final int[] samples = {0, 1, 9, 10, 99, 100, 1000};
		for (int a : samples)
		{
			for (int b : samples)
			{
				for (int u : new int[] {0, 1, 100})
				{
					final SessionCounts block = counted(counts(a, b, b, u));
					final List<Drawn> drawn = record(block);
					assertEquals(block.items().size(), drawn.size());
					for (int i = 0; i < drawn.size(); i++)
					{
						final Drawn d = drawn.get(i);
						assertEquals("drawn whole", block.items().get(i), d.text);
						assertTrue(d.toString(), d.x >= 0 && d.right() <= 213);
						assertTrue(d.toString(), d.y == 12 || d.y == 28);
					}
					for (int i = 1; i < drawn.size(); i++)
					{
						final Drawn before = drawn.get(i - 1);
						final Drawn d = drawn.get(i);
						if (d.y == before.y)
						{
							assertEquals("11 px between items", before.right() + 11, d.x);
						}
					}
					assertEquals(u > 0 ? 4 : 3, block.items().size());
					assertEquals(block.lines() * 16, block.getPreferredSize().height);
				}
			}
		}
		assertEquals("Conn 99", SessionCounts.item(Group.CONNECTION, 99));
		assertEquals("Conn 99+", SessionCounts.item(Group.CONNECTION, 100));
		assertEquals("? 3", SessionCounts.item(Group.UNSURE, 3));
		assertFalse(counted(null).items().contains("? 0"));
		assertEquals(Arrays.asList("Conn 0", "Frame 0", "World 0"), counted(null).items());
	}

	private static SessionCounts counted(int[] counts)
	{
		final SessionCounts block = PanelFixtures.onEdt(SessionCounts::new);
		edt(() -> block.set(counts));
		return block;
	}

	private static String tipOver(SessionCounts block, Drawn d)
	{
		return PanelFixtures.tip(block, d.x + 2, d.y - 4);
	}
}

package com.whylag.ui;

import com.whylag.core.Cell;
import com.whylag.core.LagEvent;
import com.whylag.core.Level;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static com.whylag.ui.PanelFixtures.Fixture;
import static com.whylag.ui.PanelFixtures.panel;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The status shapes (contract 5): each level has its own shape - circle, triangle, square, hollow ring - at the
 * three sizes the panel uses, 7, 8 and 14; and the card, the cells and the list rows never paint a level colour
 * without the shape of that level beside it. The strips are left out on purpose: their lines and bands use the
 * level colours by design.
 */
public class ShapeTest
{
	private static final int[] SIZES = {7, 8, 14};
	private static final Level[] LEVELS = {Level.OK, Level.WARN, Level.BAD, Level.NO_DATA};

	@Test
	public void everyLevelHasItsOwnShape()
	{
		for (int size : SIZES)
		{
			final boolean[][][] masks = new boolean[LEVELS.length][][];
			for (int i = 0; i < LEVELS.length; i++)
			{
				masks[i] = mask(LEVELS[i], size);
			}
			for (int i = 0; i < LEVELS.length; i++)
			{
				for (int j = i + 1; j < LEVELS.length; j++)
				{
					assertFalse(LEVELS[i] + " and " + LEVELS[j] + " at " + size, same(masks[i], masks[j]));
				}
			}
			final int last = size - 1;
			final int mid = size / 2;
			final boolean[][] ok = masks[0];
			final boolean[][] warn = masks[1];
			final boolean[][] bad = masks[2];
			final boolean[][] ring = masks[3];

			assertEquals("BAD fills the square", size * size, count(bad));

			assertTrue("OK: a filled middle", ok[mid][mid] && ok[mid][0] && ok[0][mid] && ok[mid][last]);
			assertFalse("OK: round corners", ok[0][0] || ok[0][last] || ok[last][0] || ok[last][last]);
			assertTrue("OK: symmetric", symmetric(ok));

			assertTrue("WARN: the whole base", row(warn, last) == size);
			assertTrue("WARN: a point at the top", row(warn, 0) >= 1 && row(warn, 0) <= 2);
			for (int y = 1; y < size; y++)
			{
				assertTrue("WARN widens downward, row " + y, row(warn, y) >= row(warn, y - 1));
			}
			assertTrue("WARN: symmetric left and right", mirrored(warn));

			assertFalse("the ring is hollow", ring[mid][mid]);
			assertFalse(ring[0][0]);
			assertTrue("the ring is round", ring[mid][0] && ring[0][mid] && ring[mid][last] && ring[last][mid]);
			final int thickness = Math.max(1, size / 7);
			int band = 0;
			for (int x = 0; x < mid && ring[mid][x]; x++)
			{
				band++;
			}
			assertEquals("the ring's line is max(1, size / 7) at " + size, thickness, band);
			assertTrue(symmetric(ring));
		}
		assertColour(Level.OK, new Color(55, 240, 70));
		assertColour(Level.WARN, new Color(230, 150, 30));
		assertColour(Level.BAD, new Color(230, 30, 30));
		assertColour(Level.NO_DATA, Ui.LABEL);
	}

	/** Over the card, the cells and the list rows of every fixture: a level colour stands only beside its shape. */
	@Test
	public void noLevelColourWithoutAShape()
	{
		int cards = 0;
		int cells = 0;
		int rows = 0;
		for (Fixture f : PanelFixtures.all())
		{
			final WhyLagPanel p = panel(f, true);

			final AnswerCard card = p.card();
			final BufferedImage cardImg = PanelFixtures.paint(card);
			assertOnlyItsLevel(f + " card", cardImg, 0, 0, 213, card.height(), card.level());
			assertShape(f + " card", cardImg, card.level(), 10, 16, 14);
			cards++;

			final BufferedImage cellImg = PanelFixtures.paint(p.cells());
			final Cell[] five = p.cells().cells();
			for (int i = 0; i < five.length; i++)
			{
				final int x = CellStrip.X[i];
				assertOnlyItsLevel(f + " cell " + five[i].name, cellImg, x, 0, CellStrip.W[i], 48, five[i].level);
				assertShape(f + " cell " + five[i].name, cellImg, five[i].level, x + 5, 7, 7);
				cells++;
			}

			final EventList list = p.eventList();
			final BufferedImage listImg = PanelFixtures.paint(list);
			final List<LagEvent> shown = list.rows();
			for (int i = 0; i < shown.size(); i++)
			{
				final LagEvent e = shown.get(i);
				final Level level = e.verdict == null ? Level.BAD : e.verdict.level;
				final int y = EventList.rowY(i);
				assertOnlyItsLevel(f + " row " + i, listImg, 0, y, 213, 24, level);
				assertShape(f + " row " + i, listImg, level, 9, y + 8, 8);
				rows++;
			}
		}
		assertTrue("the check ran over many cards, cells and rows", cards > 20 && cells > 100 && rows > 20);
	}

	/**
	 * The level colours found in a region - OK green, WARN amber, BAD red and its lighter text red - name one level
	 * at most, and it is the level whose shape is painted there. A NO_DATA region shows no level colour at all.
	 */
	private static void assertOnlyItsLevel(String where, BufferedImage img, int x0, int y0, int w, int h, Level level)
	{
		final Set<Level> seen = EnumSet.noneOf(Level.class);
		for (int y = y0; y < y0 + h; y++)
		{
			for (int x = x0; x < x0 + w; x++)
			{
				final int rgb = img.getRGB(x, y);
				if (rgb == Ui.OK.getRGB())
				{
					seen.add(Level.OK);
				}
				else if (rgb == Ui.WARN.getRGB())
				{
					seen.add(Level.WARN);
				}
				else if (rgb == Ui.BAD.getRGB() || rgb == Ui.BAD_TEXT.getRGB())
				{
					seen.add(Level.BAD);
				}
			}
		}
		if (level == Level.NO_DATA)
		{
			assertTrue(where + ": no level colour beside the ring: " + seen, seen.isEmpty());
		}
		else
		{
			assertEquals(where + ": the level colours", EnumSet.of(level), seen);
		}
	}

	/** The painted pixels at (x, y) are exactly the shape of that level: its mask in its colour, the rest not. */
	private static void assertShape(String where, BufferedImage img, Level level, int x, int y, int size)
	{
		final boolean[][] m = mask(level, size);
		final int colour = Ui.markColour(level).getRGB();
		for (int py = 0; py < size; py++)
		{
			for (int px = 0; px < size; px++)
			{
				final boolean painted = img.getRGB(x + px, y + py) == colour;
				assertEquals(where + ": the " + level + " shape at " + px + "," + py, m[py][px], painted);
			}
		}
	}

	private static void assertColour(Level level, Color expected)
	{
		final BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		Shape.paint(g, level, 0, 0, 14);
		g.dispose();
		// (7, 0), the top of the middle column, belongs to all four shapes at 14 px.
		assertEquals(level.toString(), expected.getRGB(), img.getRGB(7, 0));
		for (int y = 0; y < 14; y++)
		{
			for (int x = 0; x < 14; x++)
			{
				final int argb = img.getRGB(x, y);
				if ((argb >>> 24) != 0)
				{
					assertEquals(level + ": every pixel of the shape is its colour, at " + x + "," + y,
						expected.getRGB(), argb);
				}
			}
		}
	}

	/** The pixels a shape covers: [y][x]. */
	static boolean[][] mask(Level level, int size)
	{
		final BufferedImage img = new BufferedImage(size + 4, size + 4, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		Shape.paint(g, level, 2, 2, size);
		g.dispose();
		final boolean[][] m = new boolean[size][size];
		for (int y = 0; y < size + 4; y++)
		{
			for (int x = 0; x < size + 4; x++)
			{
				final boolean ink = (img.getRGB(x, y) >>> 24) != 0;
				if (x < 2 || y < 2 || x >= size + 2 || y >= size + 2)
				{
					assertFalse(level + " at " + size + " paints outside its square: " + x + "," + y, ink);
				}
				else
				{
					m[y - 2][x - 2] = ink;
				}
			}
		}
		return m;
	}

	private static boolean same(boolean[][] a, boolean[][] b)
	{
		for (int y = 0; y < a.length; y++)
		{
			for (int x = 0; x < a.length; x++)
			{
				if (a[y][x] != b[y][x])
				{
					return false;
				}
			}
		}
		return true;
	}

	private static int count(boolean[][] m)
	{
		int n = 0;
		for (boolean[] row : m)
		{
			for (boolean b : row)
			{
				n += b ? 1 : 0;
			}
		}
		return n;
	}

	private static int row(boolean[][] m, int y)
	{
		int n = 0;
		for (boolean b : m[y])
		{
			n += b ? 1 : 0;
		}
		return n;
	}

	private static boolean mirrored(boolean[][] m)
	{
		final int n = m.length;
		for (int y = 0; y < n; y++)
		{
			for (int x = 0; x < n; x++)
			{
				if (m[y][x] != m[y][n - 1 - x])
				{
					return false;
				}
			}
		}
		return true;
	}

	private static boolean symmetric(boolean[][] m)
	{
		final int n = m.length;
		for (int y = 0; y < n; y++)
		{
			for (int x = 0; x < n; x++)
			{
				if (m[y][x] != m[n - 1 - y][x] || m[y][x] != m[y][n - 1 - x])
				{
					return false;
				}
			}
		}
		return mirrored(m);
	}
}

package com.whylag.ui;

